INSERT INTO bookshelfapp.books (title, author, year, pages, genres, description) VALUES
('Война и мир', 'Лев Толстой', 1869, 1300, ARRAY['Классика', 'Художественная проза', 'Исторический роман', 'Драма', 'Военная проза'],
 'Эпопея охватывает полтора десятилетия жизни нескольких дворянских семей на фоне наполеоновских войн — от салонов Петербурга до Бородинского поля. Толстой показывает историю не через великих полководцев, а через частные судьбы, споры о смысле жизни и поиски счастья среди катастрофы.'),
('Преступление и наказание', 'Фёдор Достоевский', 1866, 672, ARRAY['Классика', 'Художественная проза', 'Психологическая проза', 'Детектив', 'Философия'],
 'Нищий студент Родион Раскольников убивает старуху-процентщицу, чтобы проверить собственную теорию о праве сильной личности преступать закон ради высшей цели. Но вместо ожидаемого освобождения его настигает мучительное раскаяние — один из самых пронзительных романов о вине и искуплении в мировой литературе.'),
('Мастер и Маргарита', 'Михаил Булгаков', 1967, 480, ARRAY['Классика', 'Художественная проза', 'Фэнтези', 'Мистика', 'Сатира'],
 'Таинственный консультант по имени Воланд со своей свитой устраивает в Москве 1930-х череду мистических происшествий, а в это же время разворачивается трагическая история Мастера, его возлюбленной Маргариты и романа о Понтии Пилате. Один из самых загадочных и многослойных романов русской литературы XX века.'),
('Евгений Онегин', 'Александр Пушкин', 1833, 240, ARRAY['Классика', 'Поэзия', 'Любовный роман', 'Драма'],
 'Скучающий петербургский денди Евгений Онегин отвергает искреннюю любовь провинциальной барышни Татьяны Лариной — а годы спустя, когда чувства меняются местами, платит за собственное равнодушие. Роман в стихах, названный «энциклопедией русской жизни», подарил русской литературе первый по-настоящему живой поэтический язык.'),
('Анна Каренина', 'Лев Толстой', 1878, 864, ARRAY['Классика', 'Художественная проза', 'Любовный роман', 'Психологическая проза', 'Драма'],
 'Замужняя петербургская дама Анна Каренина жертвует положением в обществе и семьёй ради страстной любви к офицеру Вронскому — и общество безжалостно её за это карает. Параллельно разворачивается история семейного счастья Левина и Кити, по контрасту оттеняющая трагедию главной героини.'),
('Мёртвые души', 'Николай Гоголь', 1842, 352, ARRAY['Классика', 'Художественная проза', 'Сатира', 'Юмор'],
 'Авантюрист Чичиков разъезжает по российской провинции, скупая у помещиков «мёртвые души» — крестьян, числящихся живыми по последней ревизии, — чтобы провернуть хитроумную финансовую махинацию. Галерея гротескных помещичьих типов сделала поэму одной из самых точных сатир на российские нравы.'),
('Отцы и дети', 'Иван Тургенев', 1862, 288, ARRAY['Классика', 'Художественная проза', 'Психологическая проза', 'Драма'],
 'Молодой нигилист Базаров, отрицающий искусство, любовь и авторитеты, приезжает погостить в дворянское имение друга — и сталкивается там и со спором поколений, и с неожиданной для себя самого любовью. Роман, давший языку слово «нигилист», стал одним из главных текстов о конфликте старого и нового мировоззрения.'),
('1984', 'Джордж Оруэлл', 1949, 328, ARRAY['Классика', 'Научная фантастика', 'Антиутопия', 'Политическая проза'],
 'В тоталитарном государстве будущего, где Большой Брат следит за каждым шагом граждан, а Министерство правды переписывает историю, мелкий чиновник Уинстон Смит осмеливается на крошечный акт бунта — личные чувства и собственные мысли. Главный роман-предупреждение XX века подарил языку термины «новояз», «двоемыслие» и «Большой Брат».'),
('Дюна', 'Фрэнк Герберт', 1965, 704, ARRAY['Научная фантастика', 'Приключения', 'Фэнтези', 'Философия'],
 'Юный Пол Атрейдес оказывается на пустынной планете Арракис — единственном источнике драгоценной Пряности во Вселенной — и становится центром древнего пророчества, политических интриг Домов и восстания коренных жителей пустыни фрименов. Один из самых масштабных и влиятельных романов в истории научной фантастики, соединивший экологию, религию и политику.'),
('Властелин колец', 'Дж. Р. Р. Толкин', 1954, 1216, ARRAY['Фэнтези', 'Классика', 'Приключения', 'Эпос'],
 'Хоббит Фродо Бэггинс получает в наследство Кольцо Всевластья и вместе с Братством отправляется через Средиземье, чтобы уничтожить его в огне Роковой горы, пока оно не вернулось к своему создателю — тёмному властелину Саурону. Эпопея, заложившая основы современного фэнтези как жанра.'),
('Гарри Поттер и философский камень', 'Дж. К. Роулинг', 1997, 432, ARRAY['Фэнтези', 'Детская литература', 'Приключения', 'Школьная проза'],
 'Мальчик-сирота Гарри Поттер узнаёт в свой одиннадцатый день рождения, что он волшебник, и поступает в школу чародейства и волшебства Хогвартс, где его ждут новые друзья, говорящая шляпа и тайна, связанная с гибелью его родителей. Первая книга серии, с которой началась одна из самых успешных книжных франшиз в истории.'),
('Убийство в «Восточном экспрессе»', 'Агата Кристи', 1934, 256, ARRAY['Детектив', 'Классика', 'Триллер'],
 'Застрявший в снегах на Балканах «Восточный экспресс» становится местом убийства одного из пассажиров — и знаменитому сыщику Эркюлю Пуаро предстоит разгадать загадку, в которой подозреваемым оказывается буквально каждый в вагоне. Одна из самых изобретательных детективных головоломок золотого века жанра.'),
('Собака Баскервилей', 'Артур Конан Дойл', 1902, 256, ARRAY['Детектив', 'Классика', 'Мистика', 'Приключения'],
 'Шерлок Холмс и доктор Ватсон расследуют смерть сэра Чарльза Баскервиля, якобы растерзанного легендарной призрачной собакой, преследующей род уже не первое столетие. Самая атмосферная и мистическая из повестей о великом сыщике, балансирующая на грани детектива и готического ужаса.'),
('Сияние', 'Стивен Кинг', 1977, 688, ARRAY['Ужасы', 'Триллер', 'Мистика', 'Психологическая проза'],
 'Семья нанятого на зиму смотрителя отеля «Оверлук» остаётся в полной изоляции среди снегов Колорадо — а сам отель, хранящий тёмное прошлое, начинает медленно сводить отца семейства с ума. Один из главных романов ужасов XX века о распаде личности и насилии внутри семьи.'),
('Гордость и предубеждение', 'Джейн Остин', 1813, 432, ARRAY['Классика', 'Любовный роман', 'Художественная проза', 'Юмор'],
 'Острая на язык Элизабет Беннет и гордый аристократ мистер Дарси вынуждены преодолеть собственные предрассудки и уязвлённую гордость, прежде чем признать взаимные чувства. Один из самых обаятельных и остроумных романов о любви в английской литературе.'),
('Маленький принц', 'Антуан де Сент-Экзюпери', 1943, 96, ARRAY['Детская литература', 'Классика', 'Сказка', 'Философия'],
 'Лётчик, потерпевший крушение в пустыне, встречает странного мальчика с далёкой крошечной планеты, который рассказывает о своей розе, лисе и взрослых, разучившихся видеть главное. Философская сказка-притча о дружбе, ответственности и утраченной способности удивляться стала одной из самых переводимых книг в мире.'),
('Sapiens. Краткая история человечества', 'Юваль Ной Харари', 2011, 512, ARRAY['Нон-фикшн', 'История', 'Научно-популярная'],
 'От кочевых охотников-собирателей до покорителей атома — книга прослеживает, как вид Homo sapiens сумел обойти всех конкурентов благодаря умению сообща верить в общие вымыслы: деньги, государства, религии. Один из самых обсуждаемых научно-популярных бестселлеров последнего десятилетия.'),
('Краткая история времени', 'Стивен Хокинг', 1988, 256, ARRAY['Научно-популярная', 'Нон-фикшн', 'Физика'],
 'Один из величайших физиков современности доступным языком объясняет устройство Вселенной: Большой взрыв, чёрные дыры, природу пространства и времени — почти без сложных формул. Книга стала одним из самых продаваемых научно-популярных изданий в истории.'),
('Стив Джобс', 'Уолтер Айзексон', 2011, 704, ARRAY['Биография', 'Нон-фикшн', 'Бизнес', 'История'],
 'Единственная официальная биография основателя Apple, написанная на основе десятков часов личных интервью с самим Джобсом, его семьёй, друзьями и соперниками. Откровенный портрет гения, перфекциониста и тирана, изменившего несколько отраслей одновременно.'),
('Пикник на обочине', 'Аркадий и Борис Стругацкие', 1972, 256, ARRAY['Научная фантастика', 'Философия', 'Триллер'],
 'После визита инопланетян на Земле остаются загадочные Зоны, полные смертельных аномалий и бесценных артефактов, — и сталкер Рэдрик Шухарт раз за разом рискует жизнью, пробираясь туда за добычей. Философская фантастика о непостижимом Чужом легла в основу фильма Андрея Тарковского «Сталкер».'),
('Девушка с татуировкой дракона', 'Стиг Ларссон', 2005, 640, ARRAY['Триллер', 'Детектив', 'Криминальная проза'],
 'Опальный журналист Микаэль Блумквист и хакер с татуировкой дракона Лисбет Саландер расследуют исчезновение молодой женщины из влиятельной шведской семьи сорокалетней давности, раскрывая по пути куда более мрачные тайны. Первая книга трилогии «Миллениум» стала одним из главных скандинавских триллеров XXI века.'),
('Майнкрафт', 'Австрийский художник', 1925, 700, ARRAY['Политика', 'Автобиография'], 
'Майнкрафт. Полное и исчерпывающее руководство» — это настольная книга и незаменимый путеводитель для каждого игрока, желающего освоить пиксельную вселенную. Книга содержит пошаговые инструкции, профессиональные лайфхаки и секреты выживания от разработчиков.'),
('Скотный двор', 'Джордж Оруэлл', 1945, 128, ARRAY['Классика', 'Сатира', 'Антиутопия', 'Притча'],
 'Животные фермы изгоняют хозяина и строят собственное справедливое общество — но очень скоро новые вожаки оказываются не лучше прежних. Короткая сатирическая притча о том, как революция вырождается в тиранию, стала одной из самых цитируемых политических аллегорий XX века.'),
('Убить пересмешника', 'Харпер Ли', 1960, 384, ARRAY['Классика', 'Художественная проза', 'Драма', 'Социальная проза'],
 'Маленький городок на юге США потрясён судебным процессом: чернокожего мужчину обвиняют в преступлении, которого он не совершал. Глазами девочки Глазастика читатель видит, как предрассудки и мужество соседствуют в одном обществе — и как редко встречается настоящая справедливость.'),
('Джейн Эйр', 'Шарлотта Бронте', 1847, 512, ARRAY['Классика', 'Художественная проза', 'Любовный роман', 'Готика'],
 'Сирота, выросшая в суровом пансионе, поступает гувернанткой в мрачный особняк Торнфилд — и влюбляется в его хозяина, скрывающего страшную тайну. История о достоинстве, независимости и праве любить вопреки обстоятельствам стала одним из первых феминистских романов английской литературы.'),
('Франкенштейн, или Современный Прометей', 'Мэри Шелли', 1818, 280, ARRAY['Классика', 'Готика', 'Научная фантастика', 'Ужасы'],
 'Молодой учёный Виктор Франкенштейн создаёт живое существо из частей мёртвых тел — и в ужасе отворачивается от собственного творения. Отвергнутое чудовище мстит своему создателю, а роман задаёт вопрос, актуальный и двести лет спустя: кто на самом деле чудовище — тварь или тот, кто её породил?'),
('Хитроумный идальго Дон Кихот Ламанчский', 'Мигель де Сервантес', 1605, 992, ARRAY['Классика', 'Приключения', 'Сатира', 'Пародия'],
 'Начитавшись рыцарских романов, обедневший дворянин Алонсо Кихано решает сам стать странствующим рыцарем и отправляется в путь на тощей кляче вместе с верным оруженосцем Санчо Пансой. Пародия на рыцарский эпос превратилась в один из первых и величайших романов европейской литературы.'),
('О дивный новый мир', 'Олдос Хаксли', 1932, 288, ARRAY['Классика', 'Научная фантастика', 'Антиутопия'],
 'В будущем мире людей выращивают на конвейере и с детства программируют на счастье, устраняя боль, страдание и свободу выбора. Антиутопия, в которой тирания не пытает, а убаюкивает удовольствиями, — один из самых пророческих романов XX века.'),
('Гамлет, принц датский', 'Уильям Шекспир', 1600, 224, ARRAY['Классика', 'Драма', 'Трагедия', 'Пьесы'],
 'Принц Гамлет узнаёт от призрака отца, что тот был убит собственным братом, занявшим трон и женившимся на королеве. Пьеса о мести, безумии и цене промедления — источник бессчётных цитат и, пожалуй, самая исследуемая трагедия в истории театра.'),
('Братья Карамазовы', 'Фёдор Достоевский', 1880, 824, ARRAY['Классика', 'Художественная проза', 'Психологическая проза', 'Философия'],
 'После убийства старика Карамазова подозрение падает на всех троих его сыновей — страстного Дмитрия, рассудочного Ивана и кроткого Алёшу. Последний роман Достоевского соединяет детективный сюжет с глубочайшими размышлениями о вере, свободе и природе зла.'),
('Грозовой перевал', 'Эмили Бронте', 1847, 352, ARRAY['Классика', 'Художественная проза', 'Любовный роман', 'Готика'],
 'Найдёныш Хитклиф вырастает рядом с Кэтрин Эрншо на вересковых пустошах Йоркшира, и их разрушительная любовь аукается в судьбах уже следующего поколения. Один из самых мрачных и страстных романов английской литературы, где любовь неотделима от мести.'),
('Отверженные', 'Виктор Гюго', 1862, 1440, ARRAY['Классика', 'Художественная проза', 'Исторический роман', 'Драма'],
 'Бывший каторжник Жан Вальжан пытается начать новую жизнь, но прошлое не отпускает его: по пятам идёт неумолимый инспектор Жавер. На фоне французских революционных потрясений разворачивается история падения и искупления, ставшая символом веры в человеческое благородство.'),
('Гроздья гнева', 'Джон Стейнбек', 1939, 464, ARRAY['Классика', 'Художественная проза', 'Социальная проза', 'Драма'],
 'Во времена Великой депрессии семья Джоудов теряет ферму в Оклахоме и отправляется в Калифорнию в поисках лучшей жизни. Эпическая хроника о нищете, достоинстве и солидарности бедняков принесла Стейнбеку Пулитцеровскую премию и статус голоса целого поколения.'),
('Над пропастью во ржи', 'Джером Сэлинджер', 1951, 288, ARRAY['Классика', 'Художественная проза', 'Психологическая проза'],
 'Шестнадцатилетний Холден Колфилд сбегает из закрытой школы и несколько дней бродит по Нью-Йорку, пытаясь понять мир взрослых, который кажется ему насквозь фальшивым. Исповедь бунтующего подростка стала культовой книгой нескольких поколений читателей.'),
('Бойня номер пять', 'Курт Воннегут', 1969, 288, ARRAY['Классика', 'Научная фантастика', 'Сатира', 'Антивоенная проза'],
 'Пережив бомбардировку Дрездена, Билли Пилигрим теряет связь с линейным временем и постоянно переносится между эпизодами собственной жизни — включая плен у инопланетян тральфамадорцев. Абсурдистский антивоенный роман соединяет чёрный юмор с одной из самых пронзительных военных трагедий XX века.'),
('Превращение', 'Франц Кафка', 1915, 96, ARRAY['Классика', 'Психологическая проза', 'Абсурдизм'],
 'Коммивояжёр Грегор Замза просыпается однажды утром и обнаруживает, что превратился в огромное насекомое. Короткая повесть об отчуждении, вине и равнодушии близких стала одним из самых разбираемых текстов XX века и дала имя целому литературному явлению — кафкианству.'),
('Великий Гэтсби', 'Фрэнсис Скотт Фицджеральд', 1925, 224, ARRAY['Классика', 'Художественная проза', 'Любовный роман', 'Драма'],
 'Таинственный миллионер Джей Гэтсби закатывает роскошные вечеринки в надежде вернуть любовь юности — замужнюю Дэйзи Бьюкенен. За блеском эпохи джаза роман разглядел пустоту американской мечты и стал одним из главных романов XX века.'),
('Снежная королева', 'Ганс Христиан Андерсен', 1844, 96, ARRAY['Сказка', 'Детская литература', 'Классика', 'Фэнтези'],
 'Осколок волшебного зеркала попадает в глаз и сердце мальчика Кая, и тот уходит со Снежной королевой в ледяной дворец. Его подруга Герда отправляется на край света, чтобы спасти друга, — одна из самых трогательных сказок о силе дружбы и верности.'),
('Сто лет одиночества', 'Габриэль Гарсиа Маркес', 1967, 448, ARRAY['Классика', 'Магический реализм', 'Семейная сага'],
 'История рода Буэндиа разворачивается на протяжении ста лет в вымышленном городке Макондо, где обыденное соседствует с чудесным: дожди из цветов, вечное одиночество и повторяющиеся имена. Роман, подаривший миру магический реализм и принёсший автору Нобелевскую премию.'),
('Приключения Гекльберри Финна', 'Марк Твен', 1884, 366, ARRAY['Классика', 'Приключения', 'Детская литература', 'Сатира'],
 'Сбежав от жестокого отца, мальчишка Гек Финн отправляется в плавание по Миссисипи на плоту вместе с беглым рабом Джимом. Под видом приключенческой истории скрывается едкая сатира на рабовладельческий Юг и один из первых романов, написанных живым разговорным языком.'),
('Алиса в Стране чудес', 'Льюис Кэрролл', 1865, 200, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Классика'],
 'Провалившись за Белым Кроликом в нору, девочка Алиса попадает в абсурдный мир говорящих зверей, безумных чаепитий и капризной Червонной Королевы. Остроумная логическая сказка стала источником бесчисленных отсылок в культуре и до сих пор обожается и детьми, и взрослыми.'),
('Миссис Дэллоуэй', 'Вирджиния Вулф', 1925, 192, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Один июньский день лондонской дамы Клариссы Дэллоуэй, готовящейся к вечернему приёму, превращается в поток воспоминаний о юности, несбывшейся любви и быстротечности жизни. Роман, написанный техникой потока сознания, — одна из вершин литературного модернизма.'),
('Большие надежды', 'Чарльз Диккенс', 1861, 544, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'Сирота Пип неожиданно получает деньги от таинственного благодетеля и отправляется в Лондон превращаться в джентльмена — но успех оказывается куда сложнее и горче, чем он представлял. Один из самых психологически тонких романов Диккенса о взрослении, стыде и подлинной доброте.'),
('Сердце тьмы', 'Джозеф Конрад', 1899, 128, ARRAY['Классика', 'Приключения', 'Психологическая проза'],
 'Капитан Марлоу поднимается вверх по африканской реке на поиски загадочного торговца слоновой костью Куртца и всё глубже погружается не только в джунгли, но и в тёмные глубины человеческой природы. Короткая повесть о колониализме и безумии вдохновила, среди прочего, фильм «Апокалипсис сегодня».'),
('Паутина Шарлотты', 'Элвин Брукс Уайт', 1952, 192, ARRAY['Детская литература', 'Сказка', 'Классика'],
 'Поросёнку Уилберу грозит участь всех поросят на ферме, пока паучиха Шарлотта не начинает плести над его загоном слова, убеждающие хозяев в его исключительности. Трогательная история о дружбе и самопожертвовании стала одной из самых любимых детских книг Америки.'),
('Уловка-22', 'Джозеф Хеллер', 1961, 544, ARRAY['Классика', 'Сатира', 'Антивоенная проза', 'Чёрный юмор'],
 'Военный лётчик Йоссариан пытается любой ценой избежать боевых вылетов, но сталкивается с абсурдным правилом: признать себя сумасшедшим может только тот, кто в здравом уме, а значит — годен к службе. Роман подарил языку выражение «уловка-22» для обозначения неразрешимого парадокса.'),
('Золотой жук', 'Эдгар Аллан По', 1843, 320, ARRAY['Классика', 'Мистика', 'Детектив', 'Ужасы'],
 'Найдя на берегу странного золотого жука и обрывок пергамента, Уильям Легран разгадывает зашифрованное послание, ведущее к пиратскому кладу капитана Кидда. Сборник рассказов отца детектива и мастера готической прозы соединяет логическую головоломку с атмосферой тревожного ожидания.'),
('Повелитель мух', 'Уильям Голдинг', 1954, 224, ARRAY['Классика', 'Антиутопия', 'Драма', 'Приключения'],
 'Группа английских школьников оказывается одна на необитаемом острове после авиакатастрофы и пытается построить собственное общество — но очень быстро скатывается к жестокости и культу силы. Притча о тонкой грани между цивилизацией и варварством принесла автору Нобелевскую премию.'),
('Божественная комедия', 'Данте Алигьери', 1320, 640, ARRAY['Классика', 'Поэзия', 'Философия'],
 'Проведённый тенью поэта Вергилия, Данте спускается через девять кругов Ада, поднимается на гору Чистилища и достигает сияющего Рая. Грандиозная поэма о странствии души к спасению заложила основы итальянского литературного языка и повлияла на всю западную культуру.'),
('Миддлмарч', 'Джордж Элиот', 1871, 880, ARRAY['Классика', 'Художественная проза', 'Социальная проза'],
 'В провинциальном английском городке переплетаются судьбы идеалистки Доротеи Брук, честолюбивого врача Лидгейта и десятков других персонажей, пытающихся найти своё место в меняющемся мире. Один из самых масштабных и психологически точных романов викторианской эпохи.'),
('Лолита', 'Владимир Набоков', 1955, 368, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Литературовед средних лет Гумберт Гумберт одержим двенадцатилетней падчерицей Долорес Гейз и описывает свою одержимость языком утончённого эстета. Скандальный при выходе роман о власти, манипуляции и ненадёжном рассказчике остаётся одним из самых стилистически виртуозных текстов XX века.'),
('На маяк', 'Вирджиния Вулф', 1927, 209, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Семья Рэмзи проводит лето на шотландском острове, откуда виден маяк, к которому так и не удаётся доплыть, — а десять лет спустя оставшиеся в живых всё же совершают это путешествие. Роман о времени, утрате и мимолётной красоте жизни написан виртуозной техникой потока сознания.'),
('Процесс', 'Франц Кафка', 1925, 256, ARRAY['Классика', 'Абсурдизм', 'Психологическая проза', 'Антиутопия'],
 'Служащего банка Йозефа К. в день тридцатилетия арестовывают по обвинению, которое ему так никогда и не называют, — и втягивают в бесконечный, абсурдный судебный процесс. Роман о безликой бюрократической машине стал одной из главных книг XX века о человеке перед лицом непостижимой власти.'),
('Листья травы', 'Уолт Уитмен', 1855, 624, ARRAY['Поэзия', 'Классика'],
 'Сборник свободного стиха воспевает тело и душу, демократию и природу Америки голосом, не знавшим прежде рифмы и размера. Уитмен переиздавал и дополнял книгу всю жизнь, превратив её в главный памятник американской поэзии XIX века.'),
('Невидимка', 'Ральф Эллисон', 1952, 581, ARRAY['Классика', 'Социальная проза', 'Психологическая проза'],
 'Безымянный чернокожий рассказчик проходит путь от южного колледжа до подпольных политических кружков Гарлема, всюду оставаясь невидимым для общества, которое отказывается видеть в нём личность. Один из самых важных американских романов о расе и идентичности XX века.'),
('И пришло разрушение', 'Чинуа Ачебе', 1958, 224, ARRAY['Классика', 'Художественная проза', 'Социальная проза'],
 'Воин и фермер Оконкво — уважаемый человек в своей нигерийской деревне, пока приход европейских колонизаторов и миссионеров не переворачивает привычный мир с ног на голову. Один из первых африканских романов, получивших мировое признание, и обязательное чтение для понимания колониализма изнутри.'),
('Фауст', 'Иоганн Вольфганг фон Гёте', 1808, 512, ARRAY['Классика', 'Драма', 'Поэзия', 'Философия'],
 'Разочаровавшийся в науке доктор Фауст заключает сделку с дьяволом Мефистофелем в обмен на знание, молодость и земные удовольствия. Философская драма в стихах о вечной жажде познания — главное произведение немецкой литературы и один из величайших текстов европейской культуры.'),
('Эмма', 'Джейн Остин', 1815, 474, ARRAY['Классика', 'Любовный роман', 'Художественная проза'],
 'Красивая, умная и слегка избалованная Эмма Вудхаус обожает устраивать судьбы окружающих — но её сватовские интриги то и дело оборачиваются неожиданными последствиями, в том числе для её собственного сердца. Один из самых остроумных романов Остин о самопознании через собственные ошибки.'),
('Прощай, оружие!', 'Эрнест Хемингуэй', 1929, 332, ARRAY['Классика', 'Военная проза', 'Любовный роман', 'Драма'],
 'Американский лейтенант, служащий в санитарных частях итальянской армии во время Первой мировой, влюбляется в английскую медсестру — но война не щадит ни чувств, ни планов на будущее. Полуавтобиографический роман Хемингуэя о любви на фоне бессмысленной бойни написан его фирменным скупым, точным языком.'),
('В ожидании Годо', 'Сэмюэл Беккет', 1953, 112, ARRAY['Классика', 'Абсурдизм', 'Пьесы'],
 'Два бродяги, Владимир и Эстрагон, день за днём ждут у дороги некоего Годо, который так и не появляется, заполняя ожидание бессмысленными разговорами и играми. Пьеса, в которой «ничего не происходит, причём дважды», стала манифестом театра абсурда.'),
('Граф Монте-Кристо', 'Александр Дюма', 1844, 1276, ARRAY['Классика', 'Приключения', 'Исторический роман', 'Детектив'],
 'Молодой моряк Эдмон Дантес по ложному доносу попадает в тюрьму замка Иф, откуда бежит спустя четырнадцать лет — уже несметно богатым и одержимым идеей изощрённой мести всем, кто его предал. Один из самых увлекательных авантюрных романов, когда-либо написанных.'),
('Алая буква', 'Натаниель Готорн', 1850, 288, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'В пуританском Бостоне XVII века Эстер Принн приговаривают всю жизнь носить на груди алую букву «А» — знак её греха, — пока имя настоящего отца её ребёнка остаётся тайной. Роман о публичном позоре, тайной вине и ханжестве общества, которое карает иначе, чем прощает.'),
('Улисс', 'Джеймс Джойс', 1922, 730, ARRAY['Классика', 'Модернизм', 'Психологическая проза'],
 'Один день из жизни дублинца Леопольда Блума, перекликающийся эпизод за эпизодом с гомеровской «Одиссеей», превращён в грандиозный эксперимент над языком и формой романа. Одна из самых влиятельных и самых сложных книг XX века, навсегда изменившая представление о том, каким может быть роман.'),
('Моби Дик, или Белый Кит', 'Герман Мелвилл', 1851, 720, ARRAY['Классика', 'Приключения', 'Философия'],
 'Капитан Ахав одержим местью белому киту, откусившему ему ногу в прошлом плавании, и готов утащить за собой на дно весь экипаж китобойного судна «Пекод». Под слоем приключенческого сюжета роман скрывает философское размышление о природе, судьбе и разрушительной одержимости.'),
('Шум и ярость', 'Уильям Фолкнер', 1929, 326, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'История упадка южного аристократического рода Компсонов рассказана четырежды — голосами разных братьев, включая умственно отсталого Бенджи, чьё восприятие времени полностью спутано. Один из самых формально смелых романов американской литературы, написанный техникой множественного потока сознания.'),
('Авессалом, Авессалом!', 'Уильям Фолкнер', 1936, 313, ARRAY['Классика', 'Исторический роман', 'Психологическая проза'],
 'История плантатора Томаса Сатпена, пытавшегося любой ценой основать династию на Юге, реконструируется несколькими рассказчиками из противоречивых обрывков памяти и слухов. Один из самых сложных романов Фолкнера о проклятии рабовладельческого прошлого американского Юга.'),
('Кентерберийские рассказы', 'Джеффри Чосер', 1400, 504, ARRAY['Классика', 'Поэзия', 'Сатира'],
 'Группа паломников разных сословий — от рыцаря до мельника — коротает дорогу в Кентербери, рассказывая друг другу истории на любой вкус: от благочестивых притч до озорных анекдотов. Памятник средневековой английской литературы, подаривший живой и ироничный портрет целой эпохи.'),
('Путешествия Гулливера', 'Джонатан Свифт', 1726, 320, ARRAY['Классика', 'Сатира', 'Приключения', 'Фэнтези'],
 'Корабельный врач Лемюэль Гулливер попадает то к крошечным лилипутам, то к великанам Бробдингнега, то к разумным лошадям гуигнгнмам, всякий раз видя человечество в кривом зеркале. Едкая сатира на политику и нравы своего времени давно пережила свою эпоху и читается как увлекательная фантастика.'),
('Возлюбленная', 'Тони Моррисон', 1987, 324, ARRAY['Классика', 'Исторический роман', 'Драма'],
 'Бывшая рабыня Сэти живёт в доме, который преследует призрак её умершей дочери, — расплата за отчаянный поступок, совершённый ради того, чтобы спасти ребёнка от рабства. Пронзительный роман о травме памяти принёс Моррисон Пулитцеровскую премию и Нобелевскую премию по литературе.'),
('Посторонний', 'Альбер Камю', 1942, 123, ARRAY['Классика', 'Философия', 'Психологическая проза', 'Экзистенциализм'],
 'Мерсо равнодушно хоронит мать, бесцельно убивает человека на пляже и так же равнодушно идёт на суд, отказываясь изображать раскаяние, которого не чувствует. Короткий роман стал манифестом философии абсурда и одной из главных книг экзистенциализма.'),
('Фиеста. И восходит солнце', 'Эрнест Хемингуэй', 1926, 251, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'Компания американских и британских экспатриантов перемещается из богемного Парижа на праздник корриды в Памплону, пытаясь заглушить весельем и алкоголем разъедающую их внутреннюю пустоту «потерянного поколения». Первый роман Хемингуэя задал тон целой литературной эпохе.'),
('Волшебная гора', 'Томас Манн', 1924, 706, ARRAY['Классика', 'Философия', 'Психологическая проза'],
 'Приехав навестить больного кузена в швейцарский санаторий на три недели, молодой инженер Ганс Касторп застревает там на семь лет, погружаясь в бесконечные философские споры пациентов. Монументальный роман-воспитание о времени, болезни и европейской цивилизации накануне Первой мировой.'),
('Кандид, или Оптимизм', 'Вольтер', 1759, 144, ARRAY['Классика', 'Сатира', 'Философия', 'Приключения'],
 'Наивный юноша Кандид, воспитанный в убеждении, что «всё к лучшему в этом лучшем из миров», отправляется в путешествие, полное войн, землетрясений и предательств, последовательно опровергающих эту философию. Едкая сатирическая повесть Вольтера — один из главных текстов эпохи Просвещения.'),
('Тэсс из рода д’Эрбервиллей', 'Томас Харди', 1891, 508, ARRAY['Классика', 'Художественная проза', 'Драма', 'Любовный роман'],
 'Бедная крестьянская девушка Тэсс узнаёт, что принадлежит к обедневшему аристократическому роду, — и это открытие запускает цепь событий, которые общество использует, чтобы раз за разом её осуждать. Один из самых трагических романов о двойных стандартах викторианской морали.'),
('Портрет художника в юности', 'Джеймс Джойс', 1916, 320, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Становление будущего писателя Стивена Дедала прослеживается от детских впечатлений до юношеского бунта против церкви, семьи и родины ради искусства. Автобиографический роман Джойса о рождении художника экспериментирует со стилем, меняющимся вместе со взрослением героя.'),
('Старик и море', 'Эрнест Хемингуэй', 1952, 128, ARRAY['Классика', 'Приключения', 'Философия'],
 'Старый кубинский рыбак Сантьяго после долгой полосы неудач выходит в море в одиночку и вступает в изматывающую схватку с огромным марлином. Лаконичная притча о достоинстве, упорстве и неизбежном поражении принесла Хемингуэю Пулитцеровскую и Нобелевскую премии.'),
('Солдат всегда солдат', 'Форд Мэдокс Форд', 1915, 256, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Рассказчик по кусочкам, то и дело сбиваясь и противореча сам себе, восстанавливает историю двух благополучных на вид семейных пар, скрывавших десятилетие тайных измен и лжи. Один из самых виртуозных примеров романа с ненадёжным рассказчиком в английской литературе.'),
('Унесённые ветром', 'Маргарет Митчелл', 1936, 1037, ARRAY['Классика', 'Исторический роман', 'Любовный роман', 'Драма'],
 'Своенравная южная красавица Скарлетт О’Хара переживает Гражданскую войну и крушение старого уклада Юга, борясь за собственное выживание и за любовь циничного Ретта Батлера. Эпическая сага о Юге довоенной и послевоенной эпохи остаётся одним из самых продаваемых романов в истории.'),
('Вымышленные истории', 'Хорхе Луис Борхес', 1944, 192, ARRAY['Классика', 'Фантастика', 'Философия', 'Магический реализм'],
 'Библиотека, содержащая все возможные книги, сад расходящихся тропок, человек, вознамерившийся заново написать «Дон Кихота» слово в слово, — сборник интеллектуальных новелл Борхеса стирает границы между философским трактатом, детективом и фантастикой.'),
('Путешествие на край ночи', 'Луи-Фердинанд Селин', 1932, 448, ARRAY['Классика', 'Военная проза', 'Сатира', 'Психологическая проза'],
 'Циничный и беспощадный к себе и миру Фердинанд Бардамю проходит через ужасы Первой мировой, колониальную Африку, нищету американского завода и парижские трущобы. Один из самых яростных антивоенных и антибуржуазных романов XX века, написанный взрывным разговорным языком.'),
('Идиот', 'Фёдор Достоевский', 1869, 608, ARRAY['Классика', 'Художественная проза', 'Психологическая проза', 'Драма'],
 'Князь Мышкин, человек почти евангельской доброты и честности, возвращается в Петербург из швейцарской клиники и тут же оказывается в центре страстей, интриг и трагедии, которые его чистота не в силах предотвратить. Попытка Достоевского изобразить «положительно прекрасного человека» в испорченном мире.'),
('Замок', 'Франц Кафка', 1926, 328, ARRAY['Классика', 'Абсурдизм', 'Психологическая проза'],
 'Землемер К. приезжает в деревню, подчинённую таинственному Замку, и безуспешно пытается добиться официального подтверждения своих полномочий, застревая в лабиринте бюрократических проволочек. Неоконченный роман о недостижимой власти стал ещё одним воплощением кафкианского абсурда.'),
('По направлению к Свану', 'Марсель Пруст', 1913, 528, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Вкус бисквита «мадлен», размоченного в чае, пробуждает в рассказчике лавину воспоминаний детства в Комбре и истории любви Шарля Свана к куртизанке Одетте. Первый том эпопеи «В поисках утраченного времени» исследует природу памяти с невиданной прежде подробностью.'),
('Потерянный рай', 'Джон Мильтон', 1667, 453, ARRAY['Классика', 'Поэзия', 'Философия', 'Религия'],
 'Эпическая поэма рассказывает о восстании и падении Сатаны, искушении Адама и Евы и их изгнании из рая — и делает это языком, по мощи сравнимым с Гомером и Вергилием. Одно из величайших произведений английской поэзии, переосмыслившее библейский сюжет для нового времени.'),
('Госпожа Бовари', 'Гюстав Флобер', 1856, 384, ARRAY['Классика', 'Художественная проза', 'Любовный роман', 'Драма'],
 'Эмма Бовари, выросшая на романтических романах, задыхается в скучном браке с провинциальным врачом и ищет страсти в адюльтерах и роскоши, которую не может себе позволить. Флобер довёл реалистическую прозу до совершенства — и сам едва не попал под суд за безнравственность романа.'),
('Робинзон Крузо', 'Даниэль Дефо', 1719, 320, ARRAY['Классика', 'Приключения'],
 'Потерпев кораблекрушение, моряк Робинзон Крузо проводит почти три десятилетия на необитаемом острове, выстраивая быт заново и в одиночку, пока не встречает туземца, которого называет Пятницей. Один из первых и самых влиятельных романов о выживании положил начало целому жанру.'),
('Гаргантюа и Пантагрюэль', 'Франсуа Рабле', 1534, 880, ARRAY['Классика', 'Сатира', 'Приключения'],
 'Похождения великанов — отца и сына, Гаргантюа и Пантагрюэля, — полны обжорства, похабных шуток и неудержимого веселья и одновременно скрывают глубокую гуманистическую философию эпохи Возрождения. Один из самых озорных и языково изобретательных романов европейской литературы.'),
('Цветы зла', 'Шарль Бодлер', 1857, 288, ARRAY['Поэзия', 'Классика'],
 'Сборник стихов, воспевающий красоту в пороке, город как источник вдохновения и скуку как болезнь века, потряс современников настолько, что автор был осуждён судом за оскорбление нравственности. Бодлер заложил основы символизма и всей современной поэзии.'),
('Тысяча и одна ночь', 'Автор неизвестен', 1450, 992, ARRAY['Сказка', 'Классика', 'Приключения', 'Фэнтези'],
 'Чтобы отсрочить собственную казнь, Шахерезада каждую ночь рассказывает жестокому султану новую сказку, обрывая её на самом интересном месте, — и так продолжается тысячу и одну ночь. Сборник арабских, персидских и индийских сказок подарил миру Синдбада, Аладдина и Али-Бабу.'),
('Дети полуночи', 'Салман Рушди', 1981, 448, ARRAY['Классика', 'Магический реализм', 'Исторический роман'],
 'Рождённый ровно в полночь на миг обретения Индией независимости, Салем Синай обнаруживает, что обладает телепатической связью со всеми детьми, родившимися в тот же час по всей стране. Роман, соединивший магический реализм с историей новой Индии, принёс Рушди «Букера Букеров».'),
('Палата № 6', 'Антон Чехов', 1892, 64, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Доктор Рагин годами равнодушно управляет захолустной больницей, пока разговоры с умным пациентом психиатрического отделения не заставляют его усомниться в собственном здравомыслии — с пугающими последствиями. Одна из самых мрачных повестей Чехова о равнодушии и цене отстранённости от зла.'),
('Красное и чёрное', 'Стендаль', 1830, 576, ARRAY['Классика', 'Художественная проза', 'Драма', 'Любовный роман'],
 'Честолюбивый сын плотника Жюльен Сорель пытается любой ценой подняться по социальной лестнице послереволюционной Франции — через лицемерие, соблазнение и в конце концов преступление. Один из первых и лучших психологических романов о цене амбиций в обществе, где нет места таланту без происхождения.'),
('Жизнь Дэвида Копперфилда', 'Чарльз Диккенс', 1850, 882, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'От тяжёлого детства с жестоким отчимом до писательской карьеры и зрелой любви — роман прослеживает всю жизнь Дэвида Копперфилда, во многом списанную с биографии самого Диккенса. Сам автор называл эту книгу своим любимым детищем.'),
('Женский портрет', 'Генри Джеймс', 1881, 656, ARRAY['Классика', 'Психологическая проза', 'Любовный роман'],
 'Независимая и любознательная американка Изабель Арчер, неожиданно унаследовав состояние, отправляется в Европу за новыми впечатлениями — и становится жертвой расчётливого брака. Тонкий психологический роман о цене личной свободы в мире, где за каждым поступком стоит интерес.'),
('Кузина Бетта', 'Оноре де Бальзак', 1846, 544, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'Обделённая красотой и удачей Бетта Фишер годами копит тихую ненависть к успешным родственникам и наконец находит способ методично разрушить благополучие всей семьи. Один из самых мрачных романов бальзаковской «Человеческой комедии» о зависти как разрушительной силе.'),
('Воспитание чувств', 'Гюстав Флобер', 1869, 528, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Молодой провинциал Фредерик Моро приезжает в Париж, переживает революцию 1848 года и всю жизнь безуспешно добивается любви замужней женщины, так и не найдя себе места ни в любви, ни в карьере. Флобер назвал роман историей «нравственного воспитания» целого поколения — и его собственного разочарования.'),
('Бесы', 'Фёдор Достоевский', 1872, 768, ARRAY['Классика', 'Психологическая проза', 'Политическая проза', 'Драма'],
 'В провинциальном городе кучка революционеров-нигилистов во главе с харизматичным и беспринципным Петром Верховенским сеет хаос, манипуляции и в итоге доводит дело до убийства. Пророческий роман-предупреждение о природе политического радикализма, написанный по следам реального дела нечаевцев.'),
('Декамерон', 'Джованни Боккаччо', 1353, 720, ARRAY['Классика', 'Сатира', 'Новеллы'],
 'Спасаясь от чумы во Флоренции, десять молодых людей удаляются на загородную виллу и в течение десяти дней рассказывают друг другу по новелле — сто историй о любви, хитрости, пороке и удаче. Один из первых памятников европейской прозы Нового времени.'),
('Ярмарка тщеславия', 'Уильям Теккерей', 1848, 912, ARRAY['Классика', 'Сатира', 'Художественная проза'],
 'Ловкая и беспринципная авантюристка Бекки Шарп и добродетельная, но наивная Эмилия Седли идут по жизни совершенно разными путями сквозь светское общество, одержимое деньгами, титулами и репутацией. Роман «без героя», как назвал его сам автор, — едкая сатира на викторианское тщеславие.'),
('Бледный огонь', 'Владимир Набоков', 1962, 246, ARRAY['Классика', 'Постмодернизм', 'Сатира'],
 'Поэма покойного поэта Джона Шейда в 999 строк сопровождается длиннейшим комментарием его соседа — эмигранта из вымышленной страны Зембла, который постепенно превращает скромные построчные примечания в собственный безумный роман. Один из самых изобретательных постмодернистских текстов XX века.'),
('По ком звонит колокол', 'Эрнест Хемингуэй', 1940, 480, ARRAY['Классика', 'Военная проза', 'Любовный роман', 'Драма'],
 'Американец Роберт Джордан, воюющий на стороне республиканцев в Испании, получает задание взорвать мост и за три дня успевает пережить целую жизнь — включая короткую, но всепоглощающую любовь к Марии. Один из главных романов о гражданской войне в Испании и цене, которую платят идеалисты.'),
('У подножия вулкана', 'Малькольм Лаури', 1947, 448, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'В последний День мёртвых перед войной бывший британский консул Джеффри Фирмин медленно убивает себя алкоголем в мексиканском городке, пока бывшая жена пытается вернуть его к жизни. Плотный, галлюцинаторный роман о саморазрушении считается одним из сложнейших и важнейших текстов XX века.'),
('История Тома Джонса, найдёныша', 'Генри Филдинг', 1749, 900, ARRAY['Классика', 'Сатира', 'Приключения', 'Юмор'],
 'Подброшенный младенцем в богатый дом, Том Джонс вырастает добрым, но безрассудным молодым человеком, чьи похождения и любовные приключения проводят его через всю Англию XVIII века. Один из первых больших английских романов и образец плутовского юмора эпохи Просвещения.'),
('Когда я умирала', 'Уильям Фолкнер', 1930, 267, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'После смерти матери семья Бандренов отправляется в долгий и полный злоключений путь, чтобы похоронить её согласно последней воле — в родном городе, за много миль от дома. Роман, рассказанный пятнадцатью разными голосами, — один из самых формально дерзких экспериментов Фолкнера.'),
('Доктор Живаго', 'Борис Пастернак', 1957, 592, ARRAY['Классика', 'Исторический роман', 'Любовный роман', 'Драма'],
 'Врач и поэт Юрий Живаго проходит через революцию, Гражданскую войну и годы советской власти, пытаясь сохранить верность собственному голосу и любви к Ларе среди эпохи, не оставляющей места частной жизни. Роман был запрещён в СССР и принёс автору Нобелевскую премию, от которой его вынудили отказаться.'),
('Жизнь и мнения Тристрама Шенди, джентльмена', 'Лоренс Стерн', 1759, 660, ARRAY['Классика', 'Сатира', 'Юмор'],
 'Рассказчик берётся поведать историю собственной жизни, но постоянно отвлекается на отступления, анекдоты и рассуждения — и к концу книги успевает рассказать разве что о собственном рождении. Эксцентричный роман, опередивший своё время и предвосхитивший литературу потока сознания на полтора века.'),
('Поездка в Индию', 'Эдвард Морган Форстер', 1924, 322, ARRAY['Классика', 'Художественная проза', 'Драма', 'Колониальная проза'],
 'Поездка английской гостьи Аделы Куестед в пещеры Марабар вместе с индийским врачом доктором Азизом заканчивается обвинением, которое взрывает и без того хрупкие отношения между колонизаторами и колонизированными. Один из самых проницательных романов о несовместимости культур под властью империи.'),
('Король Лир', 'Уильям Шекспир', 1606, 224, ARRAY['Классика', 'Драма', 'Трагедия', 'Пьесы'],
 'Старый король Лир делит королевство между дочерьми по тому, кто красивее выразит свою любовь к нему, — и жестоко расплачивается за эту ошибку, лишаясь всего и теряя рассудок на пустоши под грозой. Одна из самых беспощадных трагедий Шекспира о власти, старости и предательстве.'),
('Отелло', 'Уильям Шекспир', 1603, 192, ARRAY['Классика', 'Драма', 'Трагедия', 'Пьесы'],
 'Благородный венецианский полководец Отелло становится жертвой изощрённых интриг своего знаменосца Яго, который медленно и методично убеждает его в неверности жены Дездемоны. Трагедия о ревности, манипуляции и разрушительной силе сомнения.'),
('Любовь во время чумы', 'Габриэль Гарсиа Маркес', 1985, 464, ARRAY['Классика', 'Любовный роман', 'Магический реализм'],
 'Флорентино Ариса ждёт свою первую любовь Фермину Дасу больше полувека, пока её муж не умирает, — и тогда он вновь признаётся ей в чувствах, не угасших за все эти годы. Один из самых красивых романов о любви, которая не боится ни времени, ни старости.'),
('Кукольный дом', 'Генрик Ибсен', 1879, 112, ARRAY['Классика', 'Драма', 'Пьесы', 'Социальная проза'],
 'Нора Хельмер, образцовая жена и мать, годами скрывавшая давний подлог ради спасения мужа, в финале совершает немыслимый по меркам своего времени поступок — уходит из дома, хлопнув дверью. Пьеса, взорвавшая европейское общество XIX века разговором о праве женщины на собственную жизнь.'),
('Грек Зорба', 'Никос Казандзакис', 1946, 320, ARRAY['Классика', 'Философия', 'Приключения', 'Юмор'],
 'Интеллигентный критянин, отправившийся разрабатывать угольную шахту, встречает неукротимого и жизнелюбивого Алексиса Зорбу, который учит его танцевать, любить и не бояться жизни. Роман-гимн свободе и чувственной радости бытия вопреки всем бедам.'),
('Пеппи Длинныйчулок', 'Астрид Линдгрен', 1945, 160, ARRAY['Детская литература', 'Сказка', 'Классика', 'Юмор'],
 'Рыжая девочка с неимоверной силой живёт одна в вилле «Курица», воспитывает лошадь и обезьянку и переворачивает скучную жизнь соседских детей Томми и Анники вверх дном. Самая знаменитая непослушная героиня детской литературы, обожающая приключения и презирающая правила.'),
('Будденброки', 'Томас Манн', 1901, 736, ARRAY['Классика', 'Семейная сага', 'Художественная проза'],
 'На протяжении четырёх поколений богатая купеческая семья Будденброков из Любека медленно теряет деловую хватку, здоровье и волю к жизни, уступая место более практичным и менее утончённым конкурентам. Дебютный роман Томаса Манна о закате бюргерской культуры принёс автору Нобелевскую премию.'),
('Ностромо', 'Джозеф Конрад', 1904, 512, ARRAY['Классика', 'Приключения', 'Политическая проза'],
 'В вымышленной латиноамериканской стране Костагуане революция угрожает серебряному руднику, и единственный, кому доверяют спасти сокровище, — обаятельный и беспринципный портовый вожак по прозвищу Ностромо. Роман о коррупции, идеализме и власти денег в неспокойной молодой республике.'),
('Отец Горио', 'Оноре де Бальзак', 1835, 448, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'Бывший торговец вермишелью папаша Горио тратит последние гроши на дочерей, вышедших замуж за аристократов и стыдящихся отца, пока в том же пансионе молодой честолюбец Растиньяк постигает жестокие законы парижского света. Одна из ключевых книг «Человеческой комедии» о родительской любви и цинизме большого города.'),
('Сыновья и любовники', 'Дэвид Герберт Лоуренс', 1913, 480, ARRAY['Классика', 'Психологическая проза', 'Любовный роман'],
 'Пол Морел, сын шахтёра и властной, не отпускающей его матери, пытается вырваться из-под её эмоциональной власти через отношения с двумя непохожими женщинами. Полуавтобиографический роман Лоуренса стал одним из первых глубоких психологических исследований материнской любви, перерастающей в зависимость.'),
('Жестяной барабан', 'Гюнтер Грасс', 1959, 608, ARRAY['Классика', 'Магический реализм', 'Исторический роман', 'Сатира'],
 'В три года Оскар Мацерат решает больше никогда не расти и наблюдает за безумием нацистской Германии с высоты роста трёхлетнего ребёнка, колотя в жестяной барабан и разбивая стёкла пронзительным криком. Гротескный и беспощадный роман о немецкой истории XX века, написанный одним из самых дерзких голосов послевоенной литературы.'),
('Золотая тетрадь', 'Дорис Лессинг', 1962, 688, ARRAY['Классика', 'Психологическая проза', 'Феминистская проза'],
 'Писательница Анна Вулф ведёт сразу четыре дневника — чёрный, красный, жёлтый и синий, — пытаясь разложить по полочкам политику, творчество, любовь и собственное душевное здоровье, прежде чем свести их в единую золотую тетрадь. Один из главных романов второй волны феминизма и один из первых глубоких портретов женского творческого сознания.'),
('Ромео и Джульетта', 'Уильям Шекспир', 1597, 176, ARRAY['Классика', 'Драма', 'Трагедия', 'Любовный роман', 'Пьесы'],
 'Дети двух враждующих веронских семей, Монтекки и Капулетти, влюбляются друг в друга с первого взгляда и пытаются быть вместе вопреки ненависти родных — ценой собственных жизней. Самая знаменитая история любви в истории театра, давно ставшая нарицательной.'),
('Макбет', 'Уильям Шекспир', 1606, 160, ARRAY['Классика', 'Драма', 'Трагедия', 'Пьесы', 'Мистика'],
 'Подстрекаемый пророчеством трёх ведьм и честолюбивой женой, шотландский полководец Макбет убивает короля, чтобы занять трон, — и тонет во всё новых убийствах, пытаясь удержать захваченную власть. Самая короткая и, пожалуй, самая мрачная трагедия Шекспира о природе зла и разрушительной силе амбиций.'),
('Приключения Тома Сойера', 'Марк Твен', 1876, 320, ARRAY['Классика', 'Приключения', 'Детская литература', 'Юмор'],
 'Озорной мальчишка из городка на Миссисипи красит забор чужими руками, ищет клад в пещере с настоящим убийцей и присутствует на собственных похоронах, спрятавшись на хорах церкви. Солнечная и остроумная повесть о детстве стала одной из самых любимых книг о мальчишеских приключениях.'),
('Хоббит, или Туда и обратно', 'Дж. Р. Р. Толкин', 1937, 320, ARRAY['Фэнтези', 'Классика', 'Приключения', 'Детская литература'],
 'Домовитый хоббит Бильбо Бэггинс неожиданно для себя отправляется в поход с отрядом гномов и волшебником Гэндальфом, чтобы отвоевать у дракона Смауга украденное сокровище. Лёгкая и остроумная детская сказка, предшествующая «Властелину колец», в которой впервые появляется Кольцо Всевластья.'),
('Лев, Колдунья и Платяной Шкаф', 'Клайв Стейплз Льюис', 1950, 224, ARRAY['Фэнтези', 'Детская литература', 'Сказка', 'Классика'],
 'Четверо детей попадают через старый платяной шкаф в волшебную страну Нарнию, скованную вечной зимой по воле злой Белой Колдуньи, — и оказываются втянуты в пророчество о свержении её власти. Первая и самая известная книга цикла «Хроники Нарнии», ставшая классикой детской фантастики.'),
('Принц Каспиан', 'Клайв Стейплз Льюис', 1951, 224, ARRAY['Фэнтези', 'Детская литература', 'Сказка', 'Приключения'],
 'Дети Певенси вновь возвращаются в Нарнию, где с момента их прошлого визита прошли столетия, и помогают законному наследнику трона принцу Каспиану вернуть королевство, захваченное узурпаторами. Второй роман цикла «Хроники Нарнии» о борьбе за справедливость и вере в чудеса.'),
('Волшебник Земноморья', 'Урсула Ле Гуин', 1968, 256, ARRAY['Фэнтези', 'Классика', 'Приключения'],
 'Юный волшебник Гед, одержимый жаждой власти, по неосторожности выпускает на волю тёмную тень, которая начинает его преследовать по всему архипелагу Земноморья. Одна из первых фэнтези-историй о взрослении и цене гордыни, написанная скупым и поэтичным языком.'),
('Игра престолов', 'Джордж Р. Р. Мартин', 1996, 800, ARRAY['Фэнтези', 'Классика', 'Драма', 'Политическая проза'],
 'Семь королевств Вестероса балансируют на грани войны, пока благородный лорд Эддард Старк пытается раскрыть заговор при королевском дворе, а за Стеной на севере пробуждается древняя угроза. Первая книга эпопеи «Песнь льда и пламени» перевернула представления о жанре фэнтези своей политической жестокостью и непредсказуемостью.'),
('Имя ветра', 'Патрик Ротфусс', 2007, 736, ARRAY['Фэнтези', 'Приключения', 'Драма'],
 'Легендарный герой, скрывающийся под именем простого трактирщика, соглашается рассказать летописцу правдивую историю своей юности — обучения в магическом Университете, нищеты, мести и первой любви. Первая часть «Хроники убийцы короля» прославилась виртуозным языком и погружением в мастерство рассказчика.'),
('Благие знамения', 'Терри Пратчетт и Нил Гейман', 1990, 416, ARRAY['Фэнтези', 'Сатира', 'Юмор', 'Мистика'],
 'Ангел и демон, сдружившиеся за тысячелетия совместной жизни на Земле, пытаются предотвратить грядущий Апокалипсис, который едва не срывается из-за потерянного младенца-Антихриста. Остроумный и абсурдистский роман о дружбе поперёк всех границ добра и зла стал культовой классикой комедийного фэнтези.'),
('Американские боги', 'Нил Гейман', 2001, 635, ARRAY['Фэнтези', 'Мистика', 'Магический реализм'],
 'Вышедший из тюрьмы Тень поступает на службу к загадочному мистеру Среде и оказывается втянут в назревающую войну между старыми богами, привезёнными в Америку иммигрантами, и новыми божествами — техникой, медиа и деньгами. Масштабный роман-путешествие по американской мифологии и дорогам.'),
('Звёздная пыль', 'Нил Гейман', 1999, 256, ARRAY['Фэнтези', 'Сказка', 'Любовный роман', 'Приключения'],
 'Юноша из английской деревушки на границе с волшебной страной отправляется за упавшей звездой, чтобы завоевать сердце возлюбленной, — и обнаруживает, что звезда оказывается живой девушкой, за которой охотятся ведьмы и принцы. Изящная взрослая сказка в духе викторианского фэнтези.'),
('Коралина', 'Нил Гейман', 2002, 192, ARRAY['Фэнтези', 'Детская литература', 'Мистика', 'Ужасы'],
 'Переехав в новую квартиру, девочка Коралина находит потайную дверь в параллельный мир, где живут её «другие» родители — такие же на вид, но с пуговицами вместо глаз и пугающими намерениями. Тревожная детская сказка-ужастик о доме, одиночестве и опасности слишком идеальных обещаний.'),
('Последнее желание', 'Анджей Сапковский', 1993, 384, ARRAY['Фэнтези', 'Приключения', 'Мистика'],
 'Ведьмак Геральт из Ривии, профессиональный охотник на чудовищ, выполняет один заказ за другим, сталкиваясь с моралью куда более запутанной, чем простое деление на монстров и людей. Сборник рассказов, открывающий знаменитый цикл о Ведьмаке, переосмысляет классические сказочные сюжеты в мрачных и циничных тонах.'),
('Обитатели холмов', 'Ричард Адамс', 1972, 480, ARRAY['Фэнтези', 'Приключения', 'Классика'],
 'Стая кроликов, спасаясь от гибели родной норы, отправляется в опасное странствие по английским холмам в поисках нового дома, преодолевая хищников, враждебные колонии и собственные страхи. Эпическая история о дружбе и выживании, рассказанная от лица животных, стала одной из самых почитаемых книг английской литературы XX века.'),
('Принцесса-невеста', 'Уильям Голдман', 1973, 320, ARRAY['Фэнтези', 'Приключения', 'Любовный роман', 'Юмор'],
 'Прекрасная Баттеркап и благородный пират Уэстли преодолевают великанов, фехтовальщиков, болото Безумия и собственную мнимую смерть ради того, чтобы снова быть вместе. Пародийная сказка о настоящей любви и настоящих приключениях, рассказанная с неизменной иронией.'),
('Марсианские хроники', 'Рэй Брэдбери', 1950, 256, ARRAY['Научная фантастика', 'Классика', 'Философия'],
 'Серия взаимосвязанных новелл рассказывает о колонизации Марса людьми, которые привозят с собой на чужую планету и свои мечты, и все свои земные пороки. Поэтичный и тревожный цикл Брэдбери — скорее философская притча о человечестве, чем классическая научная фантастика.'),
('451 градус по Фаренгейту', 'Рэй Брэдбери', 1953, 256, ARRAY['Классика', 'Научная фантастика', 'Антиутопия'],
 'В обществе будущего, где хранить книги запрещено, а пожарные их не тушат, а сжигают, один из таких пожарных по имени Гай Монтэг начинает сомневаться в справедливости своей работы. Один из главных романов-предупреждений о цене общества, добровольно отказавшегося думать.'),
('Вино из одуванчиков', 'Рэй Брэдбери', 1957, 240, ARRAY['Классика', 'Художественная проза', 'Философия'],
 'Двенадцатилетний Дуглас Сполдинг проживает одно лето в маленьком городке американского Среднего Запада, впервые по-настоящему осознавая, что он живой, — и одновременно узнавая о старости и смерти. Лирический, почти бессюжетный роман-воспоминание о счастье простых вещей.'),
('Я, робот', 'Айзек Азимов', 1950, 288, ARRAY['Научная фантастика', 'Классика', 'Философия'],
 'Сборник взаимосвязанных рассказов исследует Три закона роботехники через серию логических и этических головоломок, в которые попадают роботы и люди, пытающиеся с ними ужиться. Книга, сформировавшая само представление массовой культуры о роботах на десятилетия вперёд.'),
('Основание', 'Айзек Азимов', 1951, 320, ARRAY['Научная фантастика', 'Классика', 'Философия'],
 'Математик Гэри Селдон предсказывает неизбежный крах галактической империи и создаёт Фонд, призванный сократить грядущие тёмные века с тридцати тысяч лет до одной тысячи. Одна из самых влиятельных саг в истории научной фантастики, построенная на идее, что историю можно предсказывать статистически.'),
('Автостопом по галактике', 'Дуглас Адамс', 1979, 224, ARRAY['Научная фантастика', 'Юмор', 'Сатира', 'Приключения'],
 'За несколько секунд до сноса Земли ради строительства гиперпространственной магистрали землянин Артур Дент спасается автостопом на борту инопланетного корабля — и узнаёт, что ответ на главный вопрос жизни, вселенной и всего такого прочего равен 42. Одна из самых смешных книг в истории фантастики.'),
('Игра Эндера', 'Орсон Скотт Кард', 1985, 352, ARRAY['Научная фантастика', 'Приключения', 'Философия'],
 'Шестилетнего гения Эндера Виггина забирают в военную академию, чтобы с помощью серии всё более жестоких игр подготовить его к решающей битве с инопланетной расой жукеров. Одна из самых популярных книг о детстве, манипуляции и цене победы в научной фантастике.'),
('Заводной апельсин', 'Энтони Бёрджесс', 1962, 240, ARRAY['Классика', 'Антиутопия', 'Психологическая проза'],
 'Юный бандит Алекс со своей шайкой упивается насилием на улицах мрачного будущего, пока государство не решает «исправить» его экспериментальной методикой, лишающей способности выбирать между добром и злом. Роман о природе свободы воли написан на изобретённом автором сленге надсат.'),
('Мы', 'Евгений Замятин', 1924, 224, ARRAY['Классика', 'Научная фантастика', 'Антиутопия'],
 'В Едином Государстве будущего люди живут по номерам, а не именам, за стеклянными стенами, под постоянным наблюдением, и мечтают построить космический корабль, чтобы принести этот идеальный порядок другим планетам. Первый классический роман-антиутопия XX века, вдохновивший и Оруэлла, и Хаксли.'),
('Левая рука Тьмы', 'Урсула Ле Гуин', 1969, 320, ARRAY['Научная фантастика', 'Философия'],
 'Землянин-посланник прибывает на планету Гетен, населённую людьми без постоянного пола, и вынужден пересмотреть собственные представления о гендере, дружбе и верности посреди политических интриг и ледяной пустыни. Одна из самых значимых феминистских научно-фантастических книг.'),
('Обделённые', 'Урсула Ле Гуин', 1974, 400, ARRAY['Научная фантастика', 'Философия', 'Политическая проза'],
 'Физик Шевек покидает анархическую колонию на бедной луне Анаррес и отправляется на богатую капиталистическую планету-метрополию Уррас, чтобы завершить научную теорию, — и сравнивает две противоположные общественные системы изнутри. Философский роман об утопии без прикрас.'),
('Нейромант', 'Уильям Гибсон', 1984, 320, ARRAY['Научная фантастика', 'Триллер'],
 'Бывший хакер Кейс, лишённый способности подключаться к киберпространству, получает шанс на исцеление в обмен на опасную кражу данных у искусственного интеллекта. Роман, придумавший термин «киберпространство» и заложивший основы жанра киберпанк.'),
('Цветы для Элджернона', 'Дэниел Киз', 1966, 320, ARRAY['Классика', 'Научная фантастика', 'Психологическая проза', 'Драма'],
 'Умственно отсталый Чарли Гордон соглашается на экспериментальную операцию, резко повышающую интеллект, — такую же, что уже провели лабораторной мыши Элджернону, — и постепенно превращается в гения, который начинает видеть мир совсем иначе. Один из самых пронзительных романов о цене и хрупкости разума.'),
('Мечтают ли андроиды об электроовцах?', 'Филип К. Дик', 1968, 256, ARRAY['Научная фантастика', 'Философия', 'Нуар'],
 'Охотник за головами Рик Декард выслеживает сбежавших андроидов в постапокалиптическом Сан-Франциско, одновременно всё меньше понимая, чем на самом деле отличается искусственная жизнь от настоящей. Роман, легший в основу фильма «Бегущий по лезвию», ставит вопрос об эмпатии как главном признаке человечности.'),
('Человек в высоком замке', 'Филип К. Дик', 1962, 288, ARRAY['Научная фантастика', 'Альтернативная история', 'Философия'],
 'В мире, где во Второй мировой войне победили страны Оси, Америка поделена между Японией и Германией, а подпольная книга описывает альтернативную реальность, подозрительно похожую на нашу. Один из первых и самых изощрённых романов жанра альтернативной истории.'),
('Солярис', 'Станислав Лем', 1961, 288, ARRAY['Научная фантастика', 'Философия', 'Психологическая проза'],
 'Психолог Крис Кельвин прибывает на орбитальную станцию над планетой-океаном Солярис и обнаруживает, что разумный океан материализует живые образы из самых тяжёлых воспоминаний экипажа. Философский роман о пределах человеческого познания и невозможности понять по-настоящему чуждый разум.'),
('Война миров', 'Герберт Уэллс', 1898, 240, ARRAY['Классика', 'Научная фантастика', 'Приключения'],
 'Марсиане высаживаются в сельской Англии на боевых треножниках и методично уничтожают всё на своём пути, пока безымянный рассказчик пытается выжить среди хаоса вторжения. Один из первых и самых влиятельных романов об инопланетном вторжении, заложивший каноны жанра.'),
('Машина времени', 'Герберт Уэллс', 1895, 160, ARRAY['Классика', 'Научная фантастика', 'Философия'],
 'Изобретатель отправляется на созданной им машине в далёкое будущее и обнаруживает человечество, разделившееся на два вида — изнеженных элоев и чудовищных морлоков. Роман, подаривший жанру само понятие путешествия во времени на машине.'),
('Трудно быть богом', 'Аркадий и Борис Стругацкие', 1964, 256, ARRAY['Научная фантастика', 'Философия', 'Приключения'],
 'Земной историк под видом благородного дона Руматы работает под прикрытием на отсталой планете, застрявшей в своём средневековье, — и день за днём мучается невозможностью вмешаться и остановить творящееся вокруг него зло. Одна из самых философски глубоких книг Стругацких о пределах благих намерений.'),
('Марсианин', 'Энди Вейер', 2011, 384, ARRAY['Научная фантастика', 'Приключения', 'Юмор'],
 'Астронавт Марк Уотни, по ошибке оставленный командой на Марсе, использует всю свою инженерную изобретательность и чёрный юмор, чтобы выжить в одиночку на безжизненной планете. Технически достоверный и невероятно увлекательный роман о выживании лёг в основу одноимённого фильма.'),
('Задача трёх тел', 'Лю Цысинь', 2008, 400, ARRAY['Научная фантастика', 'Философия', 'Триллер'],
 'Учёные по всему миру начинают один за другим сводить счёты с жизнью после загадочного контакта, связанного с секретным китайским проектом времён культурной революции и сигналом из далёкой звёздной системы. Первый роман трилогии, познакомивший мир с масштабной китайской научной фантастикой.'),
('Голодные игры', 'Сьюзен Коллинз', 2008, 384, ARRAY['Фэнтези', 'Антиутопия', 'Приключения', 'Драма'],
 'В тоталитарном государстве Панем дети из бедных округов ежегодно сражаются друг с другом на арене в прямом эфире в наказание за давнее восстание — и Китнисс Эвердин вызывается добровольцем вместо младшей сестры. Роман, запустивший волну молодёжных антиутопий XXI века.'),
('Дивергент', 'Вероника Рот', 2011, 487, ARRAY['Фэнтези', 'Антиутопия', 'Приключения'],
 'В будущем Чикаго общество поделено на пять фракций по доминирующей черте характера, а шестнадцатилетняя Трис обнаруживает, что не вписывается ни в одну из них — и это делает её опасной для системы. Ещё одна культовая young-adult антиутопия о выборе собственной идентичности.'),
('Бегущий в лабиринте', 'Джеймс Дэшнер', 2009, 384, ARRAY['Фэнтези', 'Антиутопия', 'Приключения', 'Триллер'],
 'Подросток Томас просыпается в лифте без памяти посреди загадочной поляны, окружённой гигантским постоянно меняющимся лабиринтом, полным смертельных механических существ. Напряжённый антиутопический триллер о группе детей, пытающихся выбраться из ловушки.'),
('Сумерки', 'Стефани Майер', 2005, 498, ARRAY['Фэнтези', 'Любовный роман', 'Мистика'],
 'Переехав в дождливый городок Форкс, школьница Белла Свон влюбляется в загадочного одноклассника Эдварда Каллена, который оказывается вампиром, веками борющимся с собственной природой. Роман, подаривший жанру подростковой паранормальной романтики мировую популярность.'),
('Дракула', 'Брэм Стокер', 1897, 418, ARRAY['Классика', 'Ужасы', 'Готика', 'Мистика'],
 'Молодой юрист отправляется в трансильванский замок к загадочному графу Дракуле и становится первой жертвой его зловещего плана по переезду в Лондон. Роман в письмах и дневниках, собравший в себе весь европейский фольклор о вампирах, стал главным каноном жанра на столетия вперёд.'),
('Экзорцист', 'Уильям Питер Блэтти', 1971, 340, ARRAY['Ужасы', 'Мистика', 'Триллер'],
 'Актриса в отчаянии наблюдает, как её двенадцатилетняя дочь на глазах превращается в кого-то чудовищного, и обращается за помощью к двум католическим священникам, готовым провести древний обряд изгнания беса. Один из самых страшных романов XX века, основанный на реальном случае.'),
('Интервью с вампиром', 'Энн Райс', 1976, 346, ARRAY['Ужасы', 'Готика', 'Мистика', 'Драма'],
 'Вампир Луи рассказывает молодому журналисту историю своих двух веков бессмертия — одиночество, вину, запретную дружбу с демоническим Лестатом и приёмную дочь, навсегда застрявшую в теле ребёнка. Роман, превративший вампира из чудовища в трагического романтического героя.'),
('Ребёнок Розмари', 'Айра Левин', 1967, 256, ARRAY['Ужасы', 'Мистика', 'Психологическая проза', 'Триллер'],
 'Молодая женщина переезжает с мужем в старый нью-йоркский дом и постепенно начинает подозревать, что её соседи-старики и собственный супруг вовлечены в сатанинский заговор вокруг её будущего ребёнка. Один из самых тревожных психологических триллеров о паранойе и недоверии к самым близким людям.'),
('Призрак дома на холме', 'Ширли Джексон', 1959, 246, ARRAY['Ужасы', 'Мистика', 'Психологическая проза', 'Готика'],
 'Четверо участников экспериментального исследования паранормальных явлений проводят лето в печально известном особняке Хилл-Хаус, который словно начинает приспосабливаться к самому уязвимому из гостей. Один из важнейших романов в истории литературы ужасов о доме, который, возможно, по-настоящему жив.'),
('Мы всегда жили в замке', 'Ширли Джексон', 1962, 214, ARRAY['Мистика', 'Психологическая проза', 'Готика', 'Триллер'],
 'Две сестры живут в фамильном поместье в полной изоляции от враждебно настроенной деревни после загадочного отравления, унёсшего жизни остальной семьи. Тревожный и странно уютный роман о замкнутости, вине и хрупкой границе между жертвой и преступником.'),
('Оно', 'Стивен Кинг', 1986, 1138, ARRAY['Ужасы', 'Мистика', 'Триллер'],
 'Семеро детей из городка Дерри сталкиваются с древним злом, принимающим облик клоуна Пеннивайза, а спустя почти тридцать лет, уже взрослыми, вынуждены вернуться, чтобы покончить с ним раз и навсегда. Один из самых масштабных и знаменитых романов Стивена Кинга.'),
('Кладбище домашних животных', 'Стивен Кинг', 1983, 374, ARRAY['Ужасы', 'Мистика', 'Психологическая проза'],
 'Переехав в новый дом рядом с таинственным индейским кладбищем, способным возвращать мёртвых к жизни, врач Луис Крид поддаётся искушению испытать это на себе, несмотря на все предупреждения. Один из самых мрачных романов Кинга о горе, которое толкает людей на немыслимые поступки.'),
('Мизери', 'Стивен Кинг', 1987, 320, ARRAY['Триллер', 'Психологическая проза', 'Ужасы'],
 'Популярный писатель, попавший в автокатастрофу, оказывается в плену у своей «самой преданной поклонницы» — бывшей медсестры, которая не позволит ему убить любимую героиню её романов. Клаустрофобный триллер о власти читателя над автором и цене творческой свободы.'),
('Кэрри', 'Стивен Кинг', 1974, 245, ARRAY['Ужасы', 'Психологическая проза', 'Мистика'],
 'Застенчивая школьница, подвергающаяся травле и деспотичному религиозному воспитанию матери, обнаруживает в себе телекинетические способности — и выпускной бал превращается в акт разрушительной мести. Дебютный роман Стивена Кинга о школьной жестокости и цене унижения.'),
('Жребий', 'Стивен Кинг', 1975, 439, ARRAY['Ужасы', 'Мистика', 'Триллер'],
 'Писатель возвращается в маленький городок своего детства как раз в тот момент, когда там поселяется загадочный антиквар, а жители один за другим начинают исчезать по ночам. Один из первых романов Кинга переносит классическую историю о вампирах в декорации американской провинции.'),
('Зелёная миля', 'Стивен Кинг', 1996, 400, ARRAY['Драма', 'Мистика', 'Классика'],
 'Надзиратель блока смертников в тюрьме 1930-х годов сталкивается с заключённым огромного роста, обвинённым в чудовищном преступлении, но обладающим даром исцеления и душой ребёнка. Трогательный роман о вере, несправедливости и цене молчаливого соучастия.'),
('Мальтийский сокол', 'Дэшил Хэммет', 1930, 217, ARRAY['Детектив', 'Классика', 'Нуар', 'Триллер'],
 'Частный детектив Сэм Спейд берётся за дело об убийстве партнёра и оказывается втянут в охоту нескольких авантюристов за бесценной статуэткой сокола. Роман, заложивший канон жанра нуар и подаривший литературе образ циничного крутого детектива.'),
('Имя розы', 'Умберто Эко', 1980, 672, ARRAY['Детектив', 'Исторический роман', 'Философия'],
 'Монах-францисканец Вильгельм Баскервильский расследует серию загадочных смертей в средневековом монастыре, библиотека которого скрывает запретную книгу. Интеллектуальный детектив, соединивший средневековую философию, семиотику и классическую загадку запертой комнаты.'),
('Ребекка', 'Дафна дю Морье', 1938, 400, ARRAY['Классика', 'Готика', 'Психологическая проза', 'Триллер'],
 'Молодая безымянная рассказчица выходит замуж за богатого вдовца и переезжает в его родовое поместье Мэндерли, где тень его первой жены Ребекки, кажется, присутствует в каждой комнате. Один из главных образцов готического романтического саспенса XX века.'),
('И никого не стало', 'Агата Кристи', 1939, 272, ARRAY['Детектив', 'Триллер', 'Классика'],
 'Десять незнакомцев получают приглашение на уединённый остров — и один за другим начинают погибать в точности так, как описано в детской считалочке, развешанной по всему дому. Самый продаваемый детективный роман в истории, построенный на идеальной логической головоломке без единого лишнего свидетеля.'),
('Убийство Роджера Экройда', 'Агата Кристи', 1926, 312, ARRAY['Детектив', 'Классика'],
 'Эркюль Пуаро расследует убийство состоятельного помещика в тихой английской деревне, где у каждого домочадца находится свой мотив и своя тайна. Роман знаменит одним из самых дерзких сюжетных поворотов в истории детективного жанра.'),
('Долгое прощание', 'Реймонд Чандлер', 1953, 379, ARRAY['Детектив', 'Нуар', 'Классика'],
 'Частный сыщик Филип Марлоу помогает загадочному знакомому бежать из страны, а затем оказывается втянут в расследование убийства, которое приводит его в мир богатства, лжи и моральной коррозии Лос-Анджелеса. Один из вершинных романов детективного нуара.'),
('Шпион, пришедший с холода', 'Джон ле Карре', 1963, 256, ARRAY['Детектив', 'Триллер', 'Политическая проза'],
 'Разочаровавшийся британский разведчик соглашается на последнюю, самую циничную операцию против восточногерманской разведки, в которой трудно отличить истинную миссию от собственной подставы. Один из самых мрачных и правдоподобных шпионских романов холодной войны.'),
('Казино Рояль', 'Ян Флеминг', 1953, 208, ARRAY['Детектив', 'Триллер', 'Приключения'],
 'Агент 007 Джеймс Бонд получает задание разорить за карточным столом французского казино советского агента, финансирующего профсоюз. Роман, впервые представивший миру самого знаменитого шпиона в истории массовой культуры.'),
('Молчание ягнят', 'Томас Харрис', 1988, 352, ARRAY['Триллер', 'Детектив', 'Психологическая проза', 'Ужасы'],
 'Молодая стажёрка ФБР Кларис Старлинг обращается за помощью к заключённому психиатру-каннибалу Ганнибалу Лектеру, чтобы выйти на след другого серийного убийцы. Один из самых известных триллеров о психологическом поединке между охотником и чудовищем.'),
('Исчезнувшая', 'Гиллиан Флинн', 2012, 419, ARRAY['Триллер', 'Детектив', 'Психологическая проза'],
 'В день пятой годовщины свадьбы жена главного героя бесследно исчезает, а улики одна за другой начинают указывать на него самого как на убийцу. Роман о распаде брака держит читателя в напряжении до самого неожиданного финала и построен на смене ненадёжных рассказчиков.'),
('Тайная история', 'Донна Тартт', 1992, 629, ARRAY['Триллер', 'Психологическая проза', 'Драма'],
 'Группа элитных студентов-классиков тайно совершает убийство одного из своих — и весь оставшийся роман посвящён тому, как чувство вины медленно разрушает их изнутри. Необычный триллер, в котором читатель с первой страницы знает, кто виновен, и следит не за разгадкой, а за распадом.'),
('Щегол', 'Донна Тартт', 2013, 864, ARRAY['Драма', 'Психологическая проза', 'Художественная проза'],
 'После теракта в музее, в котором гибнет его мать, подросток Тео Декер выносит с места трагедии маленькую картину голландского мастера — и эта кража определяет всю его последующую жизнь, полную горя, искусства и преступлений. Масштабный роман о травме и красоте принёс Тартт Пулитцеровскую премию.'),
('Талантливый мистер Рипли', 'Патриция Хайсмит', 1955, 290, ARRAY['Детектив', 'Триллер', 'Психологическая проза'],
 'Обаятельный мошенник Том Рипли отправляется в Италию, чтобы вернуть на родину богатого бездельника, — но вместо этого присваивает себе не только его образ жизни, но и в буквальном смысле его личность. Один из самых обаятельных литературных злодеев и образец психологического триллера без традиционного морального финала.'),
('Незнакомцы в поезде', 'Патриция Хайсмит', 1950, 276, ARRAY['Детектив', 'Триллер', 'Психологическая проза'],
 'Случайный попутчик предлагает архитектору Гаю Хейнсу идеальное преступление: каждый убивает человека, мешающего другому, и ни у кого не будет мотива. Дебютный роман Хайсмит о том, как легко моральный порог размывается простой логической игрой.'),
('Девушка в поезде', 'Пола Хокинс', 2015, 336, ARRAY['Триллер', 'Детектив', 'Психологическая проза'],
 'Разведённая алкоголичка Рейчел каждый день из окна пригородной электрички наблюдает за парой, чья жизнь кажется ей идеальной, — а когда женщина из этой пары пропадает, Рейчел понимает, что располагает важными, но крайне ненадёжными воспоминаниями. Триллер о памяти, зависимости и опасности чужих секретов.'),
('Большая маленькая ложь', 'Лиана Мориарти', 2014, 460, ARRAY['Драма', 'Детектив', 'Психологическая проза', 'Юмор'],
 'Жизни трёх матерей из благополучного австралийского городка переплетаются вокруг школьного родительского собрания, которое заканчивается смертью одного из участников. Остроумный и тревожный роман о домашнем насилии, материнстве и лжи, которую мы рассказываем даже самым близким.'),
('Охота за «Красным Октябрём»', 'Том Клэнси', 1984, 480, ARRAY['Триллер', 'Приключения', 'Военная проза'],
 'Советская подводная лодка с экспериментальным бесшумным двигателем отправляется в сторону американских берегов, и аналитик ЦРУ Джек Райан пытается понять, бегство это или начало войны. Технически достоверный военный триллер холодной войны, сделавший жанр техно-триллера массовым.'),
('Код да Винчи', 'Дэн Браун', 2003, 489, ARRAY['Триллер', 'Детектив', 'Приключения'],
 'Профессор символогии Роберт Лэнгдон расследует убийство в Лувре и обнаруживает цепочку зашифрованных подсказок, ведущих к древней тайне, которую Церковь скрывала веками. Один из самых продаваемых триллеров XXI века, соединивший детектив с искусствоведческим квестом.'),
('Парк Юрского периода', 'Майкл Крайтон', 1990, 448, ARRAY['Научная фантастика', 'Триллер', 'Приключения'],
 'Эксцентричный миллиардер открывает тематический парк с живыми динозаврами, воссозданными из древней ДНК, — и система безопасности, разумеется, даёт сбой в самый неподходящий момент. Технотриллер о гордыне науки лёг в основу одного из самых успешных фильмов в истории кино.'),
('Хладнокровное убийство', 'Трумен Капоте', 1966, 343, ARRAY['Нон-фикшн', 'Детектив', 'Психологическая проза'],
 'Документальный роман реконструирует реальное жестокое убийство семьи фермеров в Канзасе и психологию двух преступников, его совершивших, на основе многолетних интервью самого автора. Книга, фактически создавшая жанр документального романа.'),
('Думай медленно… решай быстро', 'Даниэль Канеман', 2011, 653, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология'],
 'Нобелевский лауреат по экономике объясняет, как в человеческом мышлении уживаются две системы — быстрая интуитивная и медленная рациональная — и почему первая постоянно подсовывает нам предсказуемые ошибки и когнитивные искажения. Одна из самых влиятельных научно-популярных книг о природе принятия решений.'),
('Эгоистичный ген', 'Ричард Докинз', 1976, 384, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биология'],
 'Книга предлагает смотреть на эволюцию не с точки зрения отдельных организмов, а с точки зрения генов, которые используют тела своих носителей как временные машины выживания. Один из самых влиятельных и спорных научно-популярных текстов о биологии XX века.'),
('Краткая история почти всего на свете', 'Билл Брайсон', 2003, 544, ARRAY['Нон-фикшн', 'Научно-популярная', 'История'],
 'Писатель-непрофессионал берётся объяснить читателю устройство Вселенной, Земли и жизни на ней — от Большого взрыва до эволюции человека — лёгким и увлекательным языком, достойным лучшего научпопа. Книга стала одним из самых успешных способов полюбить науку, не будучи учёным.'),
('Алхимик', 'Пауло Коэльо', 1988, 208, ARRAY['Философия', 'Притча', 'Приключения'],
 'Андалузский пастух Сантьяго отправляется в Египет на поиски клада, который видел во сне, и в пути узнаёт, что путешествие к своей мечте важнее самого сокровища. Один из самых переводимых романов современности — притча о следовании собственному предназначению.'),
('Над кукушкиным гнездом', 'Кен Кизи', 1962, 325, ARRAY['Классика', 'Психологическая проза', 'Драма', 'Сатира'],
 'Симулянт Рэндл Макмёрфи попадает в психиатрическую лечебницу и бросает вызов деспотичному порядку, установленному старшей медсестрой Рэтчед, вдохновляя остальных пациентов на бунт против системы. Один из главных романов о свободе личности против обезличивающего института.'),
('Атлант расправил плечи', 'Айн Рэнд', 1957, 1168, ARRAY['Философия', 'Художественная проза', 'Антиутопия'],
 'В недалёком будущем, где государство душит частную инициативу, лучшие промышленники и изобретатели один за другим таинственно исчезают, оставляя страну разваливаться без них. Масштабный и крайне спорный роман-манифест об индивидуализме и капитализме, вызывающий горячие споры по сей день.'),
('Дневник памяти', 'Николас Спаркс', 1996, 214, ARRAY['Любовный роман', 'Драма'],
 'Пожилой мужчина читает прикованной к постели женщине, страдающей от потери памяти, историю любви двух юных героев из довоенной Южной Каролины, разлучённых войной и классовыми предрассудками. Один из самых известных современных романов о любви, которая переживает даже забвение.'),
('Три товарища', 'Эрих Мария Ремарк', 1936, 448, ARRAY['Классика', 'Художественная проза', 'Драма', 'Любовный роман'],
 'Трое фронтовых друзей пытаются наладить мирную жизнь в Германии между двумя войнами, зарабатывая ремонтом машин, — пока один из них не влюбляется в смертельно больную девушку. Один из самых проникновенных романов о мужской дружбе и хрупком счастье на фоне надвигающейся катастрофы.'),
('На Западном фронте без перемен', 'Эрих Мария Ремарк', 1929, 296, ARRAY['Классика', 'Военная проза', 'Антивоенная проза'],
 'Молодой немецкий солдат Пауль Боймер и его школьные товарищи, отправленные со школьной скамьи прямо в окопы Первой мировой, теряют одну за другой все иллюзии о героизме войны. Один из самых известных антивоенных романов в истории литературы.'),
('Степной волк', 'Герман Гессе', 1927, 256, ARRAY['Классика', 'Психологическая проза', 'Философия'],
 'Немолодой интеллектуал Гарри Галлер ощущает себя раздираемым между буржуазной тягой к комфорту и волчьей тягой к одиночеству и бунту — пока таинственный Магический театр не предлагает ему взглянуть на собственную душу со стороны. Один из главных романов о внутреннем кризисе современного человека.'),
('Игра в бисер', 'Герман Гессе', 1943, 496, ARRAY['Классика', 'Философия', 'Антиутопия'],
 'В далёком будущем элитная интеллектуальная провинция Касталия посвящает себя абстрактной Игре в бисер, синтезирующей все достижения человеческой культуры, — а её лучший игрок начинает сомневаться в смысле жизни, оторванной от реального мира. Философский роман, принёсший Гессе Нобелевскую премию.'),
('Сиддхартха', 'Герман Гессе', 1922, 152, ARRAY['Классика', 'Философия', 'Притча'],
 'Сын брахмана Сиддхартха покидает дом в поисках духовного просветления, проходя через аскезу, мирские удовольствия, богатство и в итоге — тихую жизнь перевозчика у реки. Короткая философская притча о пути к собственной, а не заимствованной мудрости.'),
('Шантарам', 'Грегори Дэвид Робертс', 2003, 936, ARRAY['Приключения', 'Драма', 'Криминальная проза'],
 'Беглый австралийский заключённый находит укрытие в трущобах Бомбея, где открывает бесплатную клинику, вступает в местную мафию и постепенно обретает новую, куда более сложную версию себя. Полуавтобиографический роман о поиске искупления в самом хаотичном городе мира.'),
('Парфюмер. История одного убийцы', 'Патрик Зюскинд', 1985, 288, ARRAY['Классика', 'Триллер', 'Мистика', 'Исторический роман'],
 'Рождённый без запаха, но наделённый сверхъестественным обонянием, Жан-Батист Гренуй одержим созданием идеального аромата — и ради него готов на серию убийств юных девушек. Один из самых необычных и чувственных триллеров, разворачивающихся во Франции XVIII века.'),
('Коллекционер', 'Джон Фаулз', 1963, 320, ARRAY['Триллер', 'Психологическая проза', 'Драма'],
 'Одинокий клерк, выигравший в лотерею, похищает девушку, в которую давно и безответно влюблён, и держит её в подвале загородного дома, искренне считая, что однажды она сможет его полюбить. Один из самых тревожных психологических романов о границе между одержимостью и любовью.'),
('Чайка по имени Джонатан Ливингстон', 'Ричард Бах', 1970, 112, ARRAY['Притча', 'Философия'],
 'Чайка по имени Джонатан не желает довольствоваться простым поиском еды и посвящает жизнь оттачиванию полёта ради самого полёта, за что изгоняется собственной стаей. Короткая философская притча о самосовершенствовании и верности собственному призванию стала одной из самых популярных духовных книг XX века.'),
('Маленькая жизнь', 'Ханья Янагихара', 2015, 720, ARRAY['Драма', 'Психологическая проза'],
 'Четверо друзей, встретившихся в колледже, строят жизнь в Нью-Йорке, но тень тяжёлого детства одного из них, Джуда, постепенно становится центром всего повествования. Один из самых эмоционально тяжёлых и обсуждаемых романов XXI века о травме, дружбе и границах того, сколько боли способна вынести любовь.'),
('Книжный вор', 'Маркус Зусак', 2005, 552, ARRAY['Исторический роман', 'Драма', 'Военная проза'],
 'Приёмная дочь немецкой семьи в нацистской Германии находит утешение в украденных книгах, пока семья прячет в подвале еврейского беженца, — а рассказчиком этой истории выступает сама Смерть. Необычный роман о силе слов в самые тёмные времена истории.'),
('Жизнь Пи', 'Янн Мартел', 2001, 460, ARRAY['Приключения', 'Философия', 'Магический реализм'],
 'После кораблекрушения индийский подросток Пи оказывается один в спасательной шлюпке посреди Тихого океана — в компании бенгальского тигра. Роман о выживании, вере и силе историй, которые мы рассказываем, чтобы пережить невыносимое, принёс автору Букеровскую премию.'),
('Облачный атлас', 'Дэвид Митчелл', 2004, 528, ARRAY['Фантастика', 'Исторический роман', 'Философия'],
 'Шесть переплетённых историй, разделённых столетиями — от тихоокеанского плавания XIX века до постапокалиптического будущего, — складываются в размышление о том, как поступки одного человека эхом отзываются через века. Один из самых структурно изобретательных романов начала XXI века.'),
('Нормальные люди', 'Салли Руни', 2018, 288, ARRAY['Драма', 'Любовный роман', 'Психологическая проза'],
 'Коннелл и Марианна то сходятся, то расходятся на протяжении школьных и студенческих лет, снова и снова не умея сказать друг другу вслух то, что на самом деле чувствуют. Тонкий роман о классовых различиях, неуверенности в себе и несовершенной коммуникации в отношениях сделал Руни голосом нового поколения.'),
('Милые кости', 'Элис Сиболд', 2002, 328, ARRAY['Драма', 'Детектив', 'Мистика'],
 'Четырнадцатилетняя Сюзи Сэлмон, убитая соседом, наблюдает с небес за тем, как её семья и убийца продолжают жить дальше после трагедии. Необычный роман о горе и постепенном исцелении, рассказанный от лица самой жертвы.'),
('Выбор Софи', 'Уильям Стайрон', 1979, 562, ARRAY['Драма', 'Исторический роман', 'Психологическая проза'],
 'Молодой писатель на юге сближается с польской беженкой Софи, пережившей Освенцим, и постепенно узнаёт о невыносимом выборе, который ей когда-то пришлось сделать. Один из самых мощных романов о травме Холокоста и грузе памяти, который невозможно разделить с другими.'),
('Ночь', 'Эли Визель', 1960, 120, ARRAY['Нон-фикшн', 'Военная проза', 'Биография'],
 'Автобиографические воспоминания подростка, пережившего Освенцим и Бухенвальд вместе с отцом, который умирает у него на глазах незадолго до освобождения. Одно из самых важных свидетельств о Холокосте, написанных непосредственным очевидцем.'),
('Дневник Анны Франк', 'Анна Франк', 1947, 283, ARRAY['Нон-фикшн', 'Биография', 'История'],
 'Еврейская девочка-подросток ведёт дневник, скрываясь вместе с семьёй от нацистов в тайном убежище амстердамского дома в течение двух лет, записывая страхи, мечты и взросление в условиях постоянной смертельной опасности. Одно из самых читаемых документальных свидетельств о Второй мировой войне в мире.'),
('Три мушкетёра', 'Александр Дюма', 1844, 700, ARRAY['Классика', 'Приключения', 'Исторический роман'],
 'Молодой гасконец д’Артаньян приезжает в Париж, чтобы стать мушкетёром короля, и заводит дружбу с тремя бесстрашными товарищами — Атосом, Портосом и Арамисом, — вместе с которыми ввязывается в придворные интриги и спасает честь королевы. Самый знаменитый плащ-и-шпага роман в истории литературы.'),
('Этюд в багровых тонах', 'Артур Конан Дойл', 1887, 192, ARRAY['Детектив', 'Классика', 'Приключения'],
 'Вернувшийся с афганской войны доктор Ватсон знакомится с эксцентричным сыщиком Шерлоком Холмсом и становится свидетелем его первого громкого расследования — загадочного убийства в пустующем лондонском доме. Первая повесть, представившая миру самого знаменитого детектива в истории литературы.'),
('Таинственный остров', 'Жюль Верн', 1875, 580, ARRAY['Приключения', 'Научная фантастика', 'Классика'],
 'Пятеро пленников, сбежавших на воздушном шаре во время Гражданской войны в США, оказываются на необитаемом острове и шаг за шагом, с помощью одной лишь инженерной смекалки, превращают его в маленькую цивилизацию. Приключенческий роман-энциклопедия о силе человеческого разума и труда.'),
('Двадцать тысяч льё под водой', 'Жюль Верн', 1870, 444, ARRAY['Приключения', 'Научная фантастика', 'Классика'],
 'Профессор Аронакс попадает в плен к таинственному капитану Немо на борту революционного подводного корабля «Наутилус» и вместе с ним исследует подводные глубины всех океанов мира. Один из первых и самых влиятельных романов об исследовании подводного мира в научной фантастике.'),
('Вокруг света за восемьдесят дней', 'Жюль Верн', 1873, 275, ARRAY['Приключения', 'Классика', 'Юмор'],
 'Эксцентричный британский джентльмен Филеас Фогг заключает пари, что сумеет обогнуть земной шар всего за восемьдесят дней, и отправляется в путь вместе со своим слугой Паспарту, сталкиваясь с бесконечной чередой препятствий. Один из самых весёлых и стремительных приключенческих романов XIX века.'),
('Гарри Поттер и Тайная комната', 'Дж. К. Роулинг', 1998, 368, ARRAY['Фэнтези', 'Детская литература', 'Приключения', 'Школьная проза'],
 'На втором курсе Хогвартса Гарри сталкивается с голосами в стенах, окаменевшими учениками и легендой о Тайной комнате, которую, по слухам, однажды уже открывал сам Волан-де-Морт. Вторая книга серии о юном волшебнике разворачивает интригу вокруг чистоты крови и первого хоркрукса.'),
('Гарри Поттер и узник Азкабана', 'Дж. К. Роулинг', 1999, 448, ARRAY['Фэнтези', 'Детская литература', 'Приключения', 'Триллер'],
 'В Хогвартс пробирается слух о побеге опасного убийцы Сириуса Блэка, а школу патрулируют жуткие дементоры, высасывающие из людей счастливые воспоминания. Третья книга серии впервые раскрывает тайны прошлого родителей Гарри и вводит путешествия во времени.'),
('Гарри Поттер и Кубок огня', 'Дж. К. Роулинг', 2000, 640, ARRAY['Фэнтези', 'Детская литература', 'Приключения', 'Драма'],
 'Гарри неожиданно для себя становится четвёртым участником смертельно опасного Турнира Трёх Волшебников, а в финале книги Волан-де-Морт открыто возвращается к полной силе. Переломная часть серии, где детская сказка начинает превращаться в полноценную войну добра со злом.'),
('Гарри Поттер и Орден Феникса', 'Дж. К. Роулинг', 2003, 870, ARRAY['Фэнтези', 'Детская литература', 'Драма', 'Политическая проза'],
 'Министерство магии отказывается верить в возвращение Волан-де-Морта и объявляет Гарри лжецом, пока тайный Орден Феникса готовится к войне в тени. Самая длинная книга серии о давлении, одиночестве подростка и зарождающемся сопротивлении.'),
('Гарри Поттер и Принц-полукровка', 'Дж. К. Роулинг', 2005, 608, ARRAY['Фэнтези', 'Детская литература', 'Драма', 'Мистика'],
 'Дамблдор посвящает Гарри в прошлое Волан-де-Морта и тайну хоркруксов, пока в самом Хогвартсе зреет предательство. Предпоследняя книга серии заканчивается одной из самых трагических сцен во всём цикле.'),
('Гарри Поттер и Дары Смерти', 'Дж. К. Роулинг', 2007, 640, ARRAY['Фэнтези', 'Детская литература', 'Приключения', 'Военная проза'],
 'Гарри, Рон и Гермиона бросают школу и отправляются в бега, чтобы найти и уничтожить последние хоркруксы Волан-де-Морта, пока магический мир скатывается в открытую войну. Финальная книга серии завершает историю эпической битвой за Хогвартс.'),
('Покоритель зари, или Плавание «Утреннего путника»', 'Клайв Стейплз Льюис', 1952, 240, ARRAY['Фэнтези', 'Детская литература', 'Сказка', 'Приключения'],
 'Дети Певенси вместе с несносным кузеном Юстасом отправляются в морское путешествие на корабле короля Каспиана к краю света, на поиски семи пропавших лордов Нарнии. Третья книга цикла — самая приключенческая и исследовательская часть «Хроник Нарнии».'),
('Племянник чародея', 'Клайв Стейплз Льюис', 1955, 224, ARRAY['Фэнтези', 'Детская литература', 'Сказка', 'Приключения'],
 'Два лондонских ребёнка случайно попадают в мир между мирами и становятся свидетелями самого рождения Нарнии, которую лев Аслан создаёт из песни. Приквел цикла объясняет, откуда в нашем мире взялся волшебный платяной шкаф.'),
('Конь и его мальчик', 'Клайв Стейплз Льюис', 1954, 224, ARRAY['Фэнтези', 'Детская литература', 'Сказка', 'Приключения'],
 'Мальчик-раб Шаста бежит из южного королевства Калормен на говорящем коне Игого, направляясь в свободную Нарнию, и по пути раскрывает заговор против соседнего королевства. Самостоятельная приключенческая история, разворачивающаяся во времена золотого века Нарнии.'),
('Серебряное кресло', 'Клайв Стейплз Льюис', 1953, 224, ARRAY['Фэнтези', 'Детская литература', 'Сказка', 'Приключения'],
 'Юстас и его одноклассница Джил отправляются на поиски пропавшего принца Нарнии в компании меланхоличного болотного существа Хмуроу. Одна из самых мрачных и атмосферных книг цикла о Нарнии.'),
('Последняя битва', 'Клайв Стейплз Льюис', 1956, 192, ARRAY['Фэнтези', 'Детская литература', 'Сказка', 'Философия'],
 'Лжец в костюме льва вводит жителей Нарнии в заблуждение, выдавая себя за Аслана, что приводит к последней войне и концу света Нарнии. Финальная книга «Хроник Нарнии» подводит философский итог всему циклу.'),
('Чарли и шоколадная фабрика', 'Роальд Даль', 1964, 192, ARRAY['Детская литература', 'Сказка', 'Фэнтези', 'Юмор'],
 'Бедный мальчик Чарли Бакет выигрывает один из пяти золотых билетов на экскурсию по таинственной фабрике эксцентричного кондитера Вилли Вонки. Яркая и местами мрачная сказка о жадности, воспитании и вознаграждённой доброте.'),
('Матильда', 'Роальд Даль', 1988, 256, ARRAY['Детская литература', 'Сказка', 'Юмор', 'Фэнтези'],
 'Девочка-вундеркинд из равнодушной к ней семьи находит отдушину в книгах и обнаруживает у себя телекинетические способности, которые помогают ей противостоять деспотичной директрисе школы. Одна из самых любимых детских книг Роальда Даля о силе ума против грубой силы.'),
('Джеймс и гигантский персик', 'Роальд Даль', 1961, 176, ARRAY['Детская литература', 'Сказка', 'Фэнтези', 'Приключения'],
 'Осиротевший мальчик Джеймс попадает внутрь выросшего до гигантских размеров персика и вместе с компанией говорящих насекомых отправляется в путешествие через океан. Эксцентричная сказка Роальда Даля о побеге от жестоких опекунов к настоящей семье.'),
('Волшебник страны Оз', 'Лаймен Фрэнк Баум', 1900, 192, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Классика'],
 'Ураган уносит девочку Дороти из Канзаса в волшебную страну Оз, где она вместе со Страшилой, Железным Дровосеком и Трусливым Львом отправляется по дороге из жёлтого кирпича в поисках способа вернуться домой. Одна из самых известных американских сказок, заложившая основы жанра литературного фэнтези.'),
('Приключения Пиноккио', 'Карло Коллоди', 1883, 224, ARRAY['Сказка', 'Детская литература', 'Классика'],
 'Деревянная кукла, вырезанная старым столяром Джеппетто, оживает и мечтает стать настоящим мальчиком, но раз за разом поддаётся лени, лжи и дурным компаниям. Итальянская сказка о совести и взрослении, у носа героя которой есть особое свойство — расти от каждой лжи.'),
('Питер Пэн', 'Джеймс Барри', 1911, 192, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Классика'],
 'Мальчик, который никогда не взрослеет, уводит лондонскую девочку Венди и её братьев в Нетландию, где их ждут феи, пираты и капитан Крюк. Сказка о нежелании расставаться с детством подарила культуре архетип вечного ребёнка.'),
('Винни-Пух', 'Алан Александр Милн', 1926, 176, ARRAY['Сказка', 'Детская литература', 'Юмор', 'Классика'],
 'Плюшевый медвежонок с опилками в голове бродит по Стоакровому лесу вместе с Пятачком, Иа-Иа и остальными друзьями в поисках мёда и несложных житейских приключений. Одна из самых тепло и нежно написанных детских книг в истории английской литературы.'),
('Чиполлино', 'Джанни Родари', 1951, 192, ARRAY['Сказка', 'Детская литература', 'Сатира'],
 'Весёлый луковый мальчик Чиполлино вступает в борьбу с жестоким принцем Лимоном и его приспешниками-фруктами за справедливость для бедных овощей-крестьян. Итальянская сказка с отчётливым социальным подтекстом стала одной из самых любимых переводных детских книг в России.'),
('Малыш и Карлсон, который живёт на крыше', 'Астрид Линдгрен', 1955, 192, ARRAY['Сказка', 'Детская литература', 'Юмор'],
 'Одинокий стокгольмский мальчик заводит дружбу с толстым и в меру упитанным мужчиной с пропеллером на спине, который живёт на крыше и обожает варенье и розыгрыши. Шведская сказка о дружбе и воображаемом друге, ставшая особенно любимой в русскоязычных странах.'),
('Записки из подполья', 'Фёдор Достоевский', 1864, 176, ARRAY['Классика', 'Психологическая проза', 'Философия'],
 'Безымянный озлобленный чиновник из подполья язвительно разоблачает собственные слабости, рациональность и саму идею человеческого прогресса. Короткая повесть Достоевского считается одним из первых экзистенциалистских текстов мировой литературы.'),
('Смерть Ивана Ильича', 'Лев Толстой', 1886, 96, ARRAY['Классика', 'Психологическая проза', 'Философия'],
 'Успешный и внешне благополучный чиновник Иван Ильич, узнав о смертельной болезни, впервые по-настоящему задумывается, была ли прожитая им жизнь настоящей. Одна из самых пронзительных повестей Толстого о страхе смерти и фальши светской жизни.'),
('Собачье сердце', 'Михаил Булгаков', 1925, 192, ARRAY['Классика', 'Сатира', 'Научная фантастика'],
 'Профессор Преображенский пересаживает собаке Шарику человеческий гипофиз — и получившееся существо, Полиграф Полиграфович Шариков, превращается в едкую сатиру на нового советского человека. Одна из самых острых и запрещённых в своё время повестей Булгакова.'),
('Капитанская дочка', 'Александр Пушкин', 1836, 176, ARRAY['Классика', 'Исторический роман', 'Любовный роман', 'Приключения'],
 'Молодой офицер Пётр Гринёв оказывается втянут в Пугачёвское восстание и вынужден выбирать между долгом, честью и спасением возлюбленной. Исторический роман Пушкина о милосердии и верности слову на фоне одного из самых кровавых восстаний в русской истории.'),
('Шинель', 'Николай Гоголь', 1842, 64, ARRAY['Классика', 'Сатира', 'Психологическая проза'],
 'Мелкий петербургский чиновник Акакий Акакиевич копит деньги на новую шинель всю свою скромную жизнь — а потеряв её в первую же ночь, буквально сходит с ума от горя. Повесть, о которой принято говорить, что из неё «вышла вся русская литература».'),
('Разум и чувства', 'Джейн Остин', 1811, 416, ARRAY['Классика', 'Любовный роман', 'Художественная проза'],
 'Сёстры Дэшвуд, рассудительная Элинор и порывистая Марианна, по-разному переживают разочарования в любви после того, как их семья теряет состояние. Дебютный роман Джейн Остин противопоставляет холодный рассудок и бурные чувства на пути к счастью.'),
('Оливер Твист', 'Чарльз Диккенс', 1838, 544, ARRAY['Классика', 'Художественная проза', 'Драма', 'Криминальная проза'],
 'Сирота из работного дома сбегает в Лондон и попадает в банду карманников под началом коварного старика Феджина, пока добрые незнакомцы не пытаются вытащить его на честный путь. Один из первых социальных романов Диккенса, обнажающий нищету викторианского Лондона.'),
('Рождественская история', 'Чарльз Диккенс', 1843, 128, ARRAY['Классика', 'Сказка', 'Драма', 'Философия'],
 'Скупой и чёрствый делец Эбенезер Скрудж в канун Рождества встречает трёх духов, показывающих ему его прошлое, настоящее и возможное будущее. Короткая повесть Диккенса подарила культуре саму идею рождественского перерождения.'),
('Чума', 'Альбер Камю', 1947, 320, ARRAY['Классика', 'Философия', 'Драма'],
 'Эпидемия чумы запирает алжирский город Оран на карантин, и доктор Риё вместе с горожанами борется с болезнью, не имея ни лекарства, ни надежды на скорое избавление. Философская притча Камю об абсурде, солидарности и достоинстве перед лицом бедствия.'),
('Смерть на Ниле', 'Агата Кристи', 1937, 288, ARRAY['Детектив', 'Классика', 'Приключения'],
 'Во время круиза по Нилу убивают молодую богатую наследницу, и Эркюлю Пуаро предстоит разобраться в клубке мотивов среди ограниченного круга пассажиров теплохода. Один из самых атмосферных и изобретательных романов Агаты Кристи.'),
('Загадочное происшествие в Стайлзе', 'Агата Кристи', 1920, 256, ARRAY['Детектив', 'Классика'],
 'В богатом поместье при загадочных обстоятельствах отравлена пожилая хозяйка дома, и бельгийский сыщик-эмигрант Эркюль Пуаро берётся за своё самое первое крупное расследование. Дебютный роман Агаты Кристи, представивший миру одного из самых знаменитых детективов в истории жанра.'),
('Знак четырёх', 'Артур Конан Дойл', 1890, 160, ARRAY['Детектив', 'Классика', 'Приключения'],
 'К Шерлоку Холмсу обращается молодая девушка, которая много лет подряд анонимно получает по одной жемчужине, а затем получает приглашение на встречу, связанную со старым индийским кладом и давним предательством. Вторая повесть о Холмсе, где доктор Ватсон впервые встречает свою будущую жену.'),
('Долина страха', 'Артур Конан Дойл', 1915, 224, ARRAY['Детектив', 'Классика', 'Триллер'],
 'Шерлок Холмс расшифровывает тревожное зашифрованное письмо и приезжает в загородное поместье, где обнаруживает тело хозяина дома, — а вторая часть повести уводит читателя на десятилетия назад, в мир тайного общества американских шахтёров. Одна из самых структурно необычных повестей о великом сыщике.'),
('Человек в поисках смысла', 'Виктор Франкл', 1946, 192, ARRAY['Нон-фикшн', 'Биография', 'Философия', 'Психология'],
 'Психиатр и узник нацистских концлагерей описывает пережитый опыт и выведенную из него терапевтическую систему логотерапии, согласно которой главная движущая сила человека — поиск смысла даже в самых невыносимых обстоятельствах. Одна из самых влиятельных книг о человеческой стойкости XX века.'),
('Государь', 'Никколо Макиавелли', 1532, 176, ARRAY['Нон-фикшн', 'Философия', 'История', 'Политическая проза'],
 'Трактат итальянского дипломата описывает практические, часто безжалостные методы завоевания и удержания власти правителем, вне зависимости от общепринятой морали. Одна из самых влиятельных и спорных книг о политике в истории мировой мысли.'),
('Семь навыков высокоэффективных людей', 'Стивен Кови', 1989, 464, ARRAY['Нон-фикшн', 'Бизнес', 'Психология'],
 'Книга предлагает систему из семи принципов личной и профессиональной эффективности — от проактивности до умения сначала понять, а потом быть понятым. Один из самых продаваемых бизнес-бестселлеров в истории, ставший настольной книгой для нескольких поколений руководителей.'),
('Богатый папа, бедный папа', 'Роберт Кийосаки', 1997, 336, ARRAY['Нон-фикшн', 'Бизнес', 'Финансы'],
 'Автор сравнивает финансовые взгляды двух своих отцов — родного, с традиционным подходом к карьере, и отца друга, предпринимателя, — чтобы объяснить разницу между активами и пассивами. Одна из самых известных и спорных книг по личным финансам в мире.'),
('Как завоёвывать друзей и оказывать влияние на людей', 'Дейл Карнеги', 1936, 320, ARRAY['Нон-фикшн', 'Бизнес', 'Психология'],
 'Классическое руководство по общению объясняет простые принципы: искренне интересоваться людьми, избегать критики и уметь видеть ситуацию с чужой точки зрения. Одна из первых и самых влиятельных книг жанра self-help, не теряющая актуальности почти век.'),
('Думай и богатей', 'Наполеон Хилл', 1937, 368, ARRAY['Нон-фикшн', 'Бизнес', 'Психология'],
 'На основе интервью с десятками успешных промышленников и предпринимателей своего времени автор выводит тринадцать принципов достижения успеха, начиная с силы желания и веры. Одна из самых переиздаваемых книг жанра личной эффективности XX века.'),
('Становление', 'Мишель Обама', 2018, 448, ARRAY['Нон-фикшн', 'Биография', 'История'],
 'Бывшая первая леди США рассказывает о детстве на юге Чикаго, карьере юриста, материнстве и восьми годах в Белом доме. Один из самых продаваемых мемуаров последнего десятилетия о пути от обычной семьи до мировой узнаваемости.'),
('Образование', 'Тара Уэстовер', 2018, 400, ARRAY['Нон-фикшн', 'Биография', 'Психология'],
 'Девочка, выросшая в изолированной от общества семье сторонников выживания без документов, школы и врачей, в семнадцать лет впервые переступает порог класса — и это становится началом пути к университетскому образованию и разрыву с прошлым. Один из самых обсуждаемых мемуаров о силе знания освобождать.'),
('21 урок для XXI века', 'Юваль Ной Харари', 2018, 416, ARRAY['Нон-фикшн', 'Научно-популярная', 'Философия'],
 'Автор «Sapiens» обращается от прошлого человечества к его тревожному настоящему: искусственному интеллекту, фейковым новостям, терроризму и кризису смысла в эпоху, когда старые идеологии больше не дают ответов. Третья книга трилогии Харари о человечестве и его будущем.'),
('Homo Deus. Краткая история будущего', 'Юваль Ной Харари', 2015, 496, ARRAY['Нон-фикшн', 'Научно-популярная', 'Философия'],
 'Продолжение «Sapiens» задаётся вопросом, чем займётся человечество, однажды победив голод, болезни и войну, — и приходит к тревожным прогнозам о биотехнологиях, искусственном интеллекте и возможном появлении нового, божественного класса людей. Одна из самых обсуждаемых футурологических книг последнего десятилетия.'),
('Оружие, микробы и сталь', 'Джаред Даймонд', 1997, 576, ARRAY['Нон-фикшн', 'Научно-популярная', 'История'],
 'Автор объясняет, почему именно европейские цивилизации, а не какие-либо другие, в итоге колонизировали остальной мир, — через географию, доступность одомашниваемых растений и животных и случайное распределение природных ресурсов. Влиятельная попытка объяснить ход мировой истории без расовых теорий.'),
('Происхождение видов', 'Чарльз Дарвин', 1859, 528, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биология', 'История'],
 'Фундаментальный научный труд впервые систематически излагает теорию эволюции путём естественного отбора, навсегда изменив представление человечества о собственном происхождении. Одна из самых влиятельных научных книг когда-либо написанных.'),
('Дом, в котором...', 'Мариам Петросян', 2009, 960, ARRAY['Художественная проза', 'Магический реализм', 'Драма'],
 'Интернат для детей-инвалидов на окраине города живёт по собственным легендам, кличкам и негласным законам, недоступным взрослому миру снаружи. Масштабный магреалистический роман о детстве, инаковости и прощании с домом, ставший культовым в современной русской литературе.'),
('Тошнота', 'Жан-Поль Сартр', 1938, 288, ARRAY['Классика', 'Философия', 'Психологическая проза'],
 'Историк Антуан Рокантен начинает испытывать необъяснимые приступы тошноты при столкновении с самим фактом существования окружающих предметов. Философский роман-дневник Сартра — одно из программных произведений экзистенциализма.'),
('Жутко громко и запредельно близко', 'Джонатан Сафран Фоер', 2005, 368, ARRAY['Драма', 'Психологическая проза'],
 'Девятилетний мальчик, потерявший отца в теракте 11 сентября, находит в его вещах загадочный ключ и отправляется по Нью-Йорку на поиски замка, который он открывает. Трогательный роман о горе, памяти и попытке ребёнка найти смысл в немыслимой трагедии.'),
('Дневник Бриджит Джонс', 'Хелен Филдинг', 1996, 320, ARRAY['Юмор', 'Любовный роман', 'Драма'],
 'Незадачливая лондонская одиночка Бриджит Джонс ведёт дневник собственных диет, сигарет, отношений и бесконечных попыток привести жизнь в порядок. Остроумный роман о тридцатилетнем кризисе стал одной из самых узнаваемых книг о современной женщине.'),
('Жизнь и судьба', 'Василий Гроссман', 1980, 896, ARRAY['Классика', 'Военная проза', 'Исторический роман', 'Философия'],
 'Эпический роман о Сталинградской битве через судьбы десятков персонажей сравнивает советский тоталитаризм с нацизмом, за что книга была конфискована КГБ и впервые опубликована только на Западе. Одно из самых масштабных и бескомпромиссных произведений о войне и тоталитаризме XX века.'),
('Один день Ивана Денисовича', 'Александр Солженицын', 1962, 160, ARRAY['Классика', 'Исторический роман', 'Драма'],
 'Один обычный день заключённого советского лагеря Ивана Шухова, от подъёма до отбоя, показывает всю механику выживания в системе ГУЛАГа через мелкие бытовые детали. Повесть, впервые открыто рассказавшая советским читателям о лагерях.'),
('Архипелаг ГУЛАГ', 'Александр Солженицын', 1973, 672, ARRAY['Нон-фикшн', 'История', 'Биография'],
 'Документальное исследование системы советских лагерей, основанное на сотнях свидетельств бывших заключённых и личном опыте автора. Один из самых значимых и разрушительных для советской идеологии текстов XX века.'),
('Белая гвардия', 'Михаил Булгаков', 1925, 320, ARRAY['Классика', 'Военная проза', 'Исторический роман', 'Драма'],
 'Семья Турбиных пытается сохранить достоинство и дом в охваченном Гражданской войной Киеве, за который поочерёдно сражаются петлюровцы, большевики и белогвардейцы. Один из первых романов Булгакова, пронизанный тоской по уходящему миру.'),
('Тихий Дон', 'Михаил Шолохов', 1940, 1600, ARRAY['Классика', 'Исторический роман', 'Военная проза', 'Драма'],
 'Донской казак Григорий Мелехов мечется между красными и белыми, между двумя женщинами и собственными представлениями о правде на фоне революции и Гражданской войны. Монументальная казачья эпопея принесла Шолохову Нобелевскую премию.'),
('Приглашение на казнь', 'Владимир Набоков', 1938, 224, ARRAY['Классика', 'Антиутопия', 'Философия'],
 'Приговорённый к смерти за «гносеологическую гнусность» — непохожесть на остальных — Цинциннат Ц. ждёт казни в абсурдной тюрьме, где реальность вокруг него кажется бутафорской декорацией. Один из самых загадочных романов Набокова о тоталитарной пошлости и внутренней свободе.'),
('Норвежский лес', 'Харуки Мураками', 1987, 400, ARRAY['Драма', 'Любовный роман', 'Психологическая проза'],
 'Студент токийского университета вспоминает свою юность конца 1960-х — дружбу, первую любовь и потерю близкого человека, определившую всю его дальнейшую жизнь. Самый реалистичный и самый известный роман Харуки Мураками на Западе.'),
('Кафка на пляже', 'Харуки Мураками', 2002, 656, ARRAY['Магический реализм', 'Драма', 'Мистика'],
 'Пятнадцатилетний беглец Кафка Тамура и пожилой простодушный Наката, умеющий разговаривать с кошками, движутся навстречу друг другу по параллельным сюжетным линиям японского магического реализма. Один из самых известных романов Мураками, соединяющий греческий миф, джаз и сверхъестественное.'),
('1Q84', 'Харуки Мураками', 2009, 944, ARRAY['Магический реализм', 'Драма', 'Мистика'],
 'Инструктор по фитнесу Аомамэ и писатель Тэнго незаметно для себя оказываются в параллельном 1984 году с двумя лунами на небе, где реальность подчиняется собственным, не до конца понятным законам. Масштабный магреалистический роман Мураками о судьбе, сектах и параллельных мирах.'),
('Тысяча сияющих солнц', 'Халед Хоссейни', 2007, 384, ARRAY['Драма', 'Исторический роман', 'Военная проза'],
 'Две афганские женщины разных поколений, выданные замуж за одного и того же жестокого мужчину, находят друг в друге единственную опору на фоне десятилетий войны и репрессий против женщин. Пронзительный роман о женской дружбе и выживании в современном Афганистане.'),
('Бегущий за ветром', 'Халед Хоссейни', 2003, 384, ARRAY['Драма', 'Исторический роман', 'Психологическая проза'],
 'Мальчик из обеспеченной кабульской семьи предаёт своего лучшего друга и слугу — а много лет спустя, уже в эмиграции, получает шанс искупить этот детский грех. Дебютный роман Халеда Хоссейни о вине, дружбе и Афганистане до и после советского вторжения.'),
('Девушка, которая играла с огнём', 'Стиг Ларссон', 2006, 608, ARRAY['Триллер', 'Детектив', 'Криминальная проза'],
 'Хакер Лисбет Саландер сама становится главной подозреваемой в тройном убийстве, связанном с расследованием торговли людьми, которое она вела вместе с журналистом Микаэлем Блумквистом. Вторая часть трилогии «Миллениум» раскрывает тёмное прошлое самой Лисбет.'),
('Девушка, которая взрывала воздушные замки', 'Стиг Ларссон', 2007, 752, ARRAY['Триллер', 'Детектив', 'Криминальная проза'],
 'Тяжело раненная Лисбет Саландер оказывается под охраной полиции и под судом, пока Микаэль Блумквист пытается разоблачить государственный заговор, который десятилетиями скрывал правду о её прошлом. Заключительная часть трилогии «Миллениум».'),
('Чёрный лебедь', 'Нассим Николас Талеб', 2007, 528, ARRAY['Нон-фикшн', 'Научно-популярная', 'Философия'],
 'Книга исследует природу редких, непредсказуемых и имеющих огромные последствия событий — «чёрных лебедей» — и то, как человеческий разум склонен задним числом находить им рациональное объяснение. Одна из самых влиятельных книг о риске и неопределённости начала XXI века.'),
('Поющие в терновнике', 'Колин Маккалоу', 1977, 692, ARRAY['Драма', 'Любовный роман', 'Семейная сага'],
 'Несколько поколений семьи Клири живут на бескрайнем австралийском ранчо, а в центре истории — запретная многолетняя любовь Мэгги к католическому священнику Ральфу де Брикассару. Один из самых известных семейных саг-бестселлеров XX века.'),
('Жена путешественника во времени', 'Одри Ниффенеггер', 2003, 560, ARRAY['Драма', 'Любовный роман', 'Фантастика'],
 'Генри страдает редким генетическим расстройством, из-за которого непроизвольно перемещается во времени, а его жена Клэр годами ждёт его то в прошлом, то в настоящем, то в будущем. Необычный роман о любви, не подчиняющейся линейному времени.'),
('Виноваты звёзды', 'Джон Грин', 2012, 288, ARRAY['Драма', 'Любовный роман', 'Психологическая проза'],
 'Две больные раком подростка, Хейзел и Огастус, знакомятся в группе поддержки и переживают короткую, но насыщенную историю первой любви на фоне неизбежности. Один из самых популярных young-adult романов о жизни, юморе и смерти.'),
('Загадочная история Бенджамина Баттона', 'Фрэнсис Скотт Фицджеральд', 1922, 64, ARRAY['Классика', 'Фантастика', 'Философия'],
 'Мужчина рождается глубоким стариком и на протяжении жизни становится всё моложе, в то время как окружающий мир неумолимо стареет вокруг него. Короткая философская притча Фицджеральда о времени и неизбежности, легшая в основу известного фильма.'),
('Психология влияния', 'Роберт Чалдини', 1984, 416, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология', 'Бизнес'],
 'Книга систематизирует шесть универсальных принципов убеждения — взаимность, обязательство, социальное доказательство, авторитет, симпатию и дефицит, — которыми пользуются продавцы, маркетологи и манипуляторы. Одна из самых влиятельных научно-популярных книг о психологии убеждения.'),
('Атомные привычки', 'Джеймс Клир', 2018, 320, ARRAY['Нон-фикшн', 'Бизнес', 'Психология'],
 'Автор объясняет, как крошечные ежедневные улучшения на один процент со временем складываются в огромные перемены, и предлагает практическую систему формирования полезных привычек и избавления от вредных. Один из самых популярных нон-фикшн бестселлеров о личной эффективности последних лет.'),
('Магия утра', 'Хэл Элрод', 2012, 224, ARRAY['Нон-фикшн', 'Бизнес', 'Психология'],
 'Книга предлагает систему утренних ритуалов — от медитации до чтения и физических упражнений, — которая, по утверждению автора, способна радикально изменить продуктивность и качество жизни. Популярный бестселлер жанра личной эффективности.'),
('Сила привычки', 'Чарльз Дахигг', 2012, 400, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология', 'Бизнес'],
 'Книга исследует нейробиологию формирования привычек на примере отдельных людей, компаний и целых обществ, объясняя петлю «сигнал — действие — награда», лежащую в основе любого автоматизма. Один из самых известных научно-популярных бестселлеров о механике человеческого поведения.'),
('Тонкое искусство пофигизма', 'Марк Мэнсон', 2016, 224, ARRAY['Нон-фикшн', 'Психология', 'Юмор'],
 'Вопреки традиционным советам мотивационной литературы автор утверждает, что путь к счастливой жизни лежит не через стремление к большему, а через осознанный выбор того немногого, что действительно важно. Нестандартный и ироничный бестселлер жанра self-help.'),
('Остров сокровищ', 'Роберт Льюис Стивенсон', 1883, 320, ARRAY['Классика', 'Приключения', 'Детская литература'],
 'Юный Джим Хокинс находит карту сокровищ пирата капитана Флинта и отправляется в опасное плавание, на борту которого скрывается бывший член банды — одноногий Джон Сильвер. Один из самых знаменитых приключенческих романов о пиратах в истории литературы.'),
('Алиса в Зазеркалье', 'Льюис Кэрролл', 1871, 160, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Классика'],
 'Алиса проходит сквозь зеркало в страну, устроенную по правилам шахматной партии, где встречает Белого Рыцаря, Траляля и Труляля и становится королевой в финале собственной игры. Продолжение «Алисы в Стране чудес» построено как логическая шахматная головоломка.'),
('Таинственный сад', 'Фрэнсис Ходжсон Бёрнетт', 1911, 288, ARRAY['Детская литература', 'Классика', 'Драма'],
 'Угрюмая осиротевшая девочка Мэри переезжает в мрачное английское поместье дяди, находит заброшенный запертый сад и постепенно возвращает к жизни и его, и своего больного кузена. Классическая детская повесть о целительной силе природы и дружбы.'),
('Маленькие женщины', 'Луиза Мэй Олкотт', 1868, 448, ARRAY['Классика', 'Драма', 'Семейная сага'],
 'Четыре сестры семьи Марч взрослеют в Новой Англии времён Гражданской войны, каждая по-своему справляясь с бедностью, мечтами и первой любовью. Один из самых любимых американских романов о взрослении и женской самостоятельности XIX века.'),
('Приключения Незнайки и его друзей', 'Николай Носов', 1954, 480, ARRAY['Детская литература', 'Сказка', 'Юмор'],
 'Коротышка-хвастунишка Незнайка живёт в Цветочном городе вместе с другими малышами-коротышками и то и дело попадает в неприятности из-за собственного невежества и самоуверенности. Одна из самых любимых советских детских книг о дружбе и взрослении через собственные ошибки.'),
('Понедельник начинается в субботу', 'Аркадий и Борис Стругацкие', 1965, 224, ARRAY['Фэнтези', 'Научная фантастика', 'Сатира', 'Юмор'],
 'Молодой программист случайно устраивается на работу в Научно-исследовательский институт чародейства и волшебства, где маги, учёные и бюрократы сосуществуют в абсурдном симбиозе. Одна из самых остроумных советских фантастических повестей о науке, магии и бюрократии.'),
('Трое в лодке, не считая собаки', 'Джером К. Джером', 1889, 224, ARRAY['Юмор', 'Приключения', 'Классика'],
 'Трое ипохондричных приятелей и фокстерьер Монморенси отправляются в лодочное путешествие по Темзе, которое оборачивается бесконечной чередой нелепых недоразумений. Одна из самых смешных книг английской литературы, до сих пор остающаяся образцом тонкого британского юмора.'),
('Любовник леди Чаттерли', 'Дэвид Герберт Лоуренс', 1928, 368, ARRAY['Классика', 'Любовный роман', 'Драма'],
 'Аристократка Констанс Чаттерли, разочаровавшаяся в парализованном после войны муже, заводит страстный роман с его егерем Оливером Меллорсом. Скандальный при публикации роман о телесной и эмоциональной близости был запрещён цензурой на десятилетия.'),
('Тропик Рака', 'Генри Миллер', 1934, 320, ARRAY['Классика', 'Психологическая проза', 'Художественная проза'],
 'Нищий американский писатель в межвоенном Париже описывает богемную, полную секса, голода и творческого отчаяния жизнь эмигрантского дна. Скандальный автобиографический роман Генри Миллера годами был запрещён в США за непристойность.'),
('Дом духов', 'Изабель Альенде', 1982, 448, ARRAY['Магический реализм', 'Семейная сага', 'Исторический роман'],
 'Несколько поколений семьи Труэба проживают историю Чили XX века — от спиритических сеансов до военного переворота — глазами женщин семьи, наделённых даром предвидения. Дебютный роман Альенде, написанный в традиции магического реализма Маркеса.'),
('Волхв', 'Джон Фаулз', 1965, 656, ARRAY['Психологическая проза', 'Мистика', 'Драма'],
 'Молодой англичанин, устроившийся учителем на греческом острове, попадает под влияние загадочного богача, устраивающего для него череду всё более причудливых и жестоких психологических игр. Один из самых загадочных и многослойных романов Джона Фаулза.'),
('Женщина французского лейтенанта', 'Джон Фаулз', 1969, 384, ARRAY['Классика', 'Исторический роман', 'Любовный роман', 'Постмодернизм'],
 'Викторианский джентльмен влюбляется в загадочную женщину с сомнительной репутацией, в то время как сам автор то и дело вмешивается в повествование и предлагает читателю на выбор несколько разных финалов. Постмодернистский роман, играющий с условностями викторианской прозы.'),
('Моя семья и другие звери', 'Джеральд Даррелл', 1956, 304, ARRAY['Нон-фикшн', 'Юмор', 'Биография'],
 'Английская семья переезжает на греческий остров Корфу, где маленький Джеральд увлечённо коллекционирует скорпионов, черепах и прочую живность к ужасу и веселью всей семьи. Тёплые и невероятно смешные мемуары будущего знаменитого зоолога о детстве среди природы.'),
('Дорога', 'Кормак Маккарти', 2006, 256, ARRAY['Научная фантастика', 'Драма', 'Художественная проза'],
 'Отец и сын бредут через выжженную постапокалиптическую Америку, где почти не осталось ни еды, ни надежды, ни других людей, которым можно доверять. Мрачный и минималистичный роман о любви и выживании принёс Маккарти Пулитцеровскую премию.'),
('Старикам тут не место', 'Кормак Маккарти', 2005, 320, ARRAY['Триллер', 'Криминальная проза', 'Драма'],
 'Случайно наткнувшись на место неудачной наркосделки, техасский сварщик забирает чемодан с деньгами — и за ним начинает охоту хладнокровный наёмный убийца. Жёсткий неонуарный роман о насилии, судьбе и бессилии закона лёг в основу одноимённого фильма братьев Коэн.'),
('Кровавый меридиан', 'Кормак Маккарти', 1985, 352, ARRAY['Исторический роман', 'Триллер', 'Драма'],
 'Безымянный подросток присоединяется к банде охотников за скальпами, бесчинствующей на американо-мексиканской границе XIX века, во главе с демонически жестоким судьёй Холденом. Один из самых насильственных и философски тяжёлых романов в истории американской литературы.'),
('Generation «П»', 'Виктор Пелевин', 1999, 336, ARRAY['Классика', 'Сатира', 'Постмодернизм'],
 'Бывший поэт Вавилен Татарский устраивается копирайтером в рекламное агентство постсоветской Москвы и постепенно поднимается по лестнице манипуляции массовым сознанием вплоть до самых вершин тайной власти. Культовый сатирический роман Пелевина о рекламе, деньгах и симулякрах девяностых.'),
('Чапаев и Пустота', 'Виктор Пелевин', 1996, 416, ARRAY['Постмодернизм', 'Философия', 'Сатира'],
 'Поэт Пётр Пустота оказывается то комиссаром при легендарном Чапаеве времён Гражданской войны, то пациентом психиатрической больницы 1990-х, и граница между этими реальностями становится всё более зыбкой. Философский постмодернистский роман Пелевина о природе иллюзии и пустоты.'),
('Географ глобус пропил', 'Алексей Иванов', 2003, 480, ARRAY['Драма', 'Юмор', 'Художественная проза'],
 'Непутёвый школьный учитель географии Виктор Служкин, сам не определившийся в жизни, пытается найти общий язык с трудными подростками во время похода по уральской реке. Тёплый и горький роман о провинциальной российской жизни девяностых.'),
('Текст', 'Дмитрий Глуховский', 2017, 416, ARRAY['Триллер', 'Драма', 'Криминальная проза'],
 'Выйдя из тюрьмы по ложному обвинению, молодой человек крадёт телефон полицейского, который его подставил, и получает доступ ко всей его цифровой жизни, что толкает его на опасную месть. Остросюжетный роман о цене чужой цифровой идентичности в современной России.'),
('Метро 2033', 'Дмитрий Глуховский', 2005, 480, ARRAY['Научная фантастика', 'Приключения', 'Драма'],
 'После ядерной войны уцелевшие жители Москвы живут в тоннелях метро, разделённых на враждующие станции-государства, а юный житель ВДНХ отправляется через весь метрополитен с опасной миссией спасти свою станцию. Один из самых известных российских постапокалиптических романов, выросший в целую медиафраншизу.'),
('Ночной дозор', 'Сергей Лукьяненко', 1998, 380, ARRAY['Фэнтези', 'Мистика', 'Городское фэнтези'],
 'В современной Москве параллельно существуют Светлые и Тёмные волшебники, связанные договором о вечном равновесии, а рядовой сотрудник Ночного дозора оказывается в центре интриги, угрожающей нарушить этот хрупкий баланс. Один из самых известных образцов российского городского фэнтези.'),
('Дневной дозор', 'Сергей Лукьяненко и Владимир Васильев', 2000, 432, ARRAY['Фэнтези', 'Мистика', 'Городское фэнтези'],
 'История конфликта Светлых и Тёмных продолжается с другой стороны баррикад — глазами тёмной волшебницы, вынужденной разбираться в интригах внутри собственного лагеря. Второй роман цикла о Дозорах, написанный в соавторстве с Владимиром Васильевым.'),
('Обитаемый остров', 'Аркадий и Борис Стругацкие', 1971, 400, ARRAY['Научная фантастика', 'Приключения', 'Политическая проза'],
 'Земной космонавт Максим Каммерер терпит крушение на отсталой планете, охваченной войной и тотальной пропагандой через скрытые излучатели, и пытается понять, можно ли изменить общество, не разрушив его. Одна из самых политически острых повестей Стругацких о манипуляции массовым сознанием.'),
('Волкодав', 'Мария Семёнова', 1995, 480, ARRAY['Фэнтези', 'Приключения', 'Исторический роман'],
 'Последний воин истреблённого рода Серых Псов отправляется мстить работорговцам, уничтожившим его племя, странствуя по миру, пропитанному славянским и скандинавским фольклором. Один из самых известных романов русского героического фэнтези.'),
('Таня Гроттер и волшебный контрабас', 'Дмитрий Емец', 2002, 416, ARRAY['Фэнтези', 'Детская литература', 'Приключения', 'Юмор'],
 'Девочка-сирота с огромным волшебным контрабасом вместо привычной метлы поступает в школу магии и колдовства Тибидохс, где её ждут новые друзья и опасные интриги. Популярная русская фэнтези-серия, написанная под явным влиянием «Гарри Поттера», но с собственным фольклорным колоритом.'),
('Волшебник Изумрудного города', 'Александр Волков', 1939, 192, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Классика'],
 'Девочку Элли ураган уносит из Канзаса в волшебную страну, где она вместе со Страшилой, Железным Дровосеком и Трусливым Львом идёт по дороге из жёлтого кирпича к Изумрудному городу. Вольный русский пересказ «Волшебника страны Оз», ставший самостоятельной классикой советской детской литературы.'),
('Приключения капитана Врунгеля', 'Андрей Некрасов', 1937, 224, ARRAY['Детская литература', 'Приключения', 'Юмор'],
 'Незадачливый, но находчивый капитан Врунгель отправляется в кругосветную яхтенную регату на судне с «говорящим» названием, то и дело попадая в нелепейшие передряги по всему миру. Одна из самых весёлых советских приключенческих книг, построенная на каламбурах и морских байках.'),
('Битва королей', 'Джордж Р. Р. Мартин', 1998, 784, ARRAY['Фэнтези', 'Драма', 'Политическая проза', 'Военная проза'],
 'Семь королевств окончательно погружаются в гражданскую войну, когда сразу несколько претендентов объявляют себя королём Вестероса. Второй том «Песни льда и пламени» расширяет мир саги и впервые по-настоящему показывает масштаб грядущей катастрофы.'),
('Буря мечей', 'Джордж Р. Р. Мартин', 2000, 992, ARRAY['Фэнтези', 'Драма', 'Политическая проза', 'Военная проза'],
 'Война пяти королей достигает кровавой кульминации, а за Стеной надвигается угроза, куда более страшная, чем борьба за Железный трон. Третий том саги знаменит одними из самых шокирующих сюжетных поворотов во всём жанре фэнтези.'),
('Пир стервятников', 'Джордж Р. Р. Мартин', 2005, 753, ARRAY['Фэнтези', 'Драма', 'Политическая проза'],
 'После разрушительной войны уцелевшие дома Вестероса делят власть над обескровленным королевством, пока в Дорне и на Железных островах назревают собственные интриги. Четвёртый том саги фокусируется на южных и западных землях Вестероса.'),
('Танец с драконами', 'Джордж Р. Р. Мартин', 2011, 1056, ARRAY['Фэнтези', 'Драма', 'Политическая проза', 'Военная проза'],
 'Дейенерис пытается удержать власть над чужим городом за морем, а на Севере зима и армия мёртвых подступают всё ближе к Стене. Пятый, пока последний опубликованный том саги параллельно развивает сразу несколько сюжетных линий по всему известному миру.'),
('Основание и Империя', 'Айзек Азимов', 1952, 272, ARRAY['Научная фантастика', 'Классика', 'Философия'],
 'Фонд, созданный Гэри Селдоном для сокращения тёмных веков, выдерживает первое по-настоящему серьёзное испытание — военную экспансию остатков рушащейся Империи, а затем и внезапного мутанта, которого никакая статистика предсказать не могла. Второй роман трилогии «Основание».'),
('Второе основание', 'Айзек Азимов', 1953, 288, ARRAY['Научная фантастика', 'Классика', 'Философия'],
 'Уцелевшие после вторжения мутанта-Мула ищут таинственное Второе Основание, якобы спрятанное на другом конце Галактики и способное исправить сбившийся план Селдона. Завершающий роман оригинальной трилогии «Основание».'),
('Гиперион', 'Дэн Симмонс', 1989, 512, ARRAY['Научная фантастика', 'Философия', 'Приключения'],
 'Семеро паломников отправляются к загадочным Гробницам Времени на планете Гиперион, где обитает механическое чудовище Шрайк, и по дороге рассказывают друг другу истории своей жизни. Многослойный роман, вдохновлённый структурой «Кентерберийских рассказов», стал одной из самых почитаемых книг научной фантастики.'),
('Падение Гипериона', 'Дэн Симмонс', 1990, 576, ARRAY['Научная фантастика', 'Философия', 'Военная проза'],
 'Паломники, добравшиеся до Гробниц Времени, оказываются в центре межзвёздной войны и заговора искусственных интеллектов, определяющего судьбу всего человечества. Прямое продолжение «Гипериона» связывает воедино все истории, рассказанные в первой книге.'),
('Девять принцев Амбера', 'Роджер Желязны', 1970, 192, ARRAY['Фэнтези', 'Приключения', 'Мистика'],
 'Очнувшись в земной больнице без памяти, Корвин постепенно вспоминает, что он один из бессмертных принцев Амбера — единственного истинного мира, тенью которого являются все остальные вселенные, включая Землю. Первая книга цикла «Хроники Амбера» о борьбе за трон между братьями-полубогами.'),
('Ружья Авалона', 'Роджер Желязны', 1972, 188, ARRAY['Фэнтези', 'Приключения', 'Мистика'],
 'Корвин, временно потерпевший поражение в борьбе за трон Амбера, собирает армию в тени-мире Авалон и возвращается, чтобы продолжить войну с братом Эриком. Прямое продолжение «Девяти принцев Амбера» расширяет космологию бесконечных параллельных миров.'),
('Двенадцать стульев', 'Илья Ильф и Евгений Петров', 1928, 432, ARRAY['Сатира', 'Приключения', 'Юмор', 'Классика'],
 'Бывший предводитель дворянства Ипполит Воробьянинов и ловкий авантюрист Остап Бендер гоняются по всему Советскому Союзу за фамильными бриллиантами, зашитыми в один из двенадцати стульев гарнитура. Одна из самых цитируемых сатирических книг русской литературы XX века.'),
('Золотой телёнок', 'Илья Ильф и Евгений Петров', 1931, 464, ARRAY['Сатира', 'Приключения', 'Юмор', 'Классика'],
 'Остап Бендер объявляет охоту на подпольного советского миллионера Корейко, пытаясь легально вытрясти из него состояние в стране, где частным капиталом быть попросту нельзя. Продолжение «Двенадцати стульев» не уступает первой книге в остроумии и афористичности.'),
('Обломов', 'Иван Гончаров', 1859, 480, ARRAY['Классика', 'Художественная проза', 'Психологическая проза'],
 'Помещик Илья Обломов проводит дни напролёт на диване, не в силах заставить себя заняться ни имением, ни карьерой, ни даже взаимностью влюблённой в него Ольги Ильинской. Роман подарил русскому языку слово «обломовщина» — для обозначения всепоглощающей апатии и бездействия.'),
('Левша', 'Николай Лесков', 1881, 64, ARRAY['Классика', 'Сатира', 'Приключения'],
 'Тульский мастер-левша без микроскопа подковывает механическую блоху, подаренную англичанами русскому императору, доказывая превосходство русской смекалки над иностранной техникой. Сказовая повесть Лескова стала символом одновременно гениальности и трагической недооценённости русского умельца.'),
('История одного города', 'Михаил Салтыков-Щедрин', 1870, 272, ARRAY['Классика', 'Сатира', 'Политическая проза'],
 'Вымышленный город Глупов на протяжении столетия переживает чреду градоначальников один нелепее другого — от набитого опилками до буквально пожирающего собственных подданных. Едкая сатира на российскую государственную систему остаётся удивительно актуальной спустя полтора века.'),
('Так говорил Заратустра', 'Фридрих Ницше', 1883, 352, ARRAY['Нон-фикшн', 'Философия', 'Поэзия'],
 'Пророк Заратустра спускается с гор, чтобы возвестить людям учение о сверхчеловеке, вечном возвращении и смерти Бога, облекая философские идеи в форму притч и афоризмов. Одно из самых влиятельных и поэтичных философских сочинений в истории западной мысли.'),
('По ту сторону добра и зла', 'Фридрих Ницше', 1886, 272, ARRAY['Нон-фикшн', 'Философия'],
 'Трактат подвергает резкой критике традиционную мораль, религию и философию предшественников, предлагая взглянуть на ценности добра и зла как на исторически обусловленные конструкции, а не абсолютные истины. Одно из ключевых произведений зрелого Ницше.'),
('Критика чистого разума', 'Иммануил Кант', 1781, 608, ARRAY['Нон-фикшн', 'Философия'],
 'Фундаментальный труд исследует границы и возможности человеческого разума в познании мира, разделяя действительность на познаваемые явления и непознаваемую «вещь в себе». Один из самых влиятельных и сложных философских текстов в истории, заложивший основы немецкой классической философии.'),
('Муми-тролль и комета', 'Туве Янссон', 1946, 176, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Юмор'],
 'Жители Муми-дола готовятся к столкновению с кометой, которая, по предсказаниям учёных, может столкнуться с Землёй, — и Муми-тролль с друзьями отправляются в обсерваторию, чтобы разузнать правду. Одна из первых книг цикла о добродушных существах из скандинавской сказочной долины.'),
('Шляпа волшебника', 'Туве Янссон', 1948, 176, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Юмор'],
 'Муми-тролль и его друзья находят в горах волшебную шляпу, которая превращает всё, что в неё кладут, в нечто совершенно иное, — с самыми неожиданными и забавными последствиями. Одна из самых любимых и известных книг цикла о муми-троллях.'),
('Айвенго', 'Вальтер Скотт', 1819, 496, ARRAY['Классика', 'Исторический роман', 'Приключения', 'Любовный роман'],
 'Саксонский рыцарь Айвенго возвращается из Крестового похода в Англию, раздираемую враждой саксов и норманнов, и инкогнито участвует в рыцарском турнире, попутно спасая прекрасную еврейку Ревекку от несправедливого обвинения в колдовстве. Один из первых и самых влиятельных исторических романов в европейской литературе.'),
('Копи царя Соломона', 'Генри Райдер Хаггард', 1885, 304, ARRAY['Приключения', 'Классика', 'Фэнтези'],
 'Охотник Аллан Квотермейн ведёт экспедицию вглубь неисследованной Африки на поиски пропавшего без вести человека и легендарных алмазных копей царя Соломона. Один из первых романов жанра «затерянного мира», заложивший каноны приключенческой литературы.'),
('Собор Парижской Богоматери', 'Виктор Гюго', 1831, 576, ARRAY['Классика', 'Исторический роман', 'Драма', 'Любовный роман'],
 'Уродливый звонарь Собора Парижской Богоматери Квазимодо безнадёжно влюблён в цыганку Эсмеральду, которую преследует одержимый ею архидьякон Фролло. Готический роман Гюго прославил собор как архитектурный памятник и спас его от сноса, вызвав волну общественного интереса к реставрации.'),
('Крёстный отец', 'Марио Пьюзо', 1969, 448, ARRAY['Криминальная проза', 'Драма', 'Триллер'],
 'Глава сицилийской мафиозной семьи Дон Корлеоне передаёт власть над кланом младшему сыну Майклу, который, вопреки собственным клятвам держаться подальше от семейного бизнеса, становится самым безжалостным из донов. Роман, определивший жанр криминальной саги об американской мафии на десятилетия вперёд.'),
('О мышах и людях', 'Джон Стейнбек', 1937, 112, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Двое бродячих батраков, сообразительный Джордж и умственно отсталый силач Ленни, мечтают о собственном клочке земли, путешествуя от фермы к ферме во времена Великой депрессии. Короткая и беспощадно трагическая повесть Стейнбека о дружбе, мечте и её неизбежном крушении.'),
('Своя комната', 'Вирджиния Вулф', 1929, 172, ARRAY['Нон-фикшн', 'Философия', 'Феминистская проза'],
 'Эссе исследует, почему в литературе так мало женщин-классиков, и приходит к выводу, что для творчества женщине нужны лишь собственная комната и независимый доход. Одно из основополагающих произведений феминистской литературной критики XX века.'),
('Дающий', 'Лоис Лоури', 1993, 208, ARRAY['Фэнтези', 'Антиутопия', 'Детская литература'],
 'В идеально устроенном обществе без боли, войн и выбора двенадцатилетний Джонас назначается Хранителем Памяти и постепенно узнаёт, какой страшной ценой куплено это спокойствие. Одна из первых и самых влиятельных young-adult антиутопий, открывшая жанр для целого поколения читателей.'),
('Пятьдесят оттенков серого', 'Э. Л. Джеймс', 2011, 514, ARRAY['Любовный роман', 'Драма'],
 'Скромная студентка Анастейша Стил знакомится с молодым миллиардером Кристианом Греем, чьи романтические предпочтения оказываются куда более нетрадиционными, чем она могла представить. Один из самых продаваемых романов XXI века, вызвавший огромный резонанс и волну подражаний в жанре.'),
('Пять поросят', 'Агата Кристи', 1942, 256, ARRAY['Детектив', 'Классика', 'Психологическая проза'],
 'Шестнадцать лет спустя после казни своей матери за убийство отца дочь просит Эркюля Пуаро заново расследовать старое дело, собирая показания пятерых свидетелей, каждый из которых помнит события совершенно по-разному. Один из самых психологически тонких романов Агаты Кристи, построенный целиком на противоречивых воспоминаниях.'),
('Убийство в доме викария', 'Агата Кристи', 1930, 288, ARRAY['Детектив', 'Классика'],
 'Непопулярного в деревне полковника находят застреленным в кабинете викария, а расследование берёт в свои руки проницательная пожилая дама мисс Марпл. Роман, впервые представивший миру одну из самых знаменитых сыщиц в истории детективного жанра.'),
('Эмоциональный интеллект', 'Дэниел Гоулман', 1995, 480, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология'],
 'Книга доказывает, что способность понимать и управлять собственными и чужими эмоциями значит для жизненного успеха не меньше, а порой и больше, чем классический IQ. Одна из самых влиятельных научно-популярных книг по психологии конца XX века, подарившая массовой культуре сам термин «эмоциональный интеллект».'),
('Поток. Психология оптимального переживания', 'Михай Чиксентмихайи', 1990, 464, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология'],
 'Книга исследует состояние полной поглощённости деятельностью — «поток», — в котором люди ощущают себя наиболее счастливыми, продуктивными и живыми. Одна из основополагающих работ позитивной психологии о природе удовлетворённости и вовлечённости.'),
('От хорошего к великому', 'Джим Коллинз', 2001, 320, ARRAY['Нон-фикшн', 'Бизнес'],
 'На основе многолетнего исследования компаний, сумевших перейти от хороших результатов к выдающимся, автор выводит общие принципы такого перехода — от скромного лидерства до железной дисциплины. Один из самых влиятельных бизнес-бестселлеров о корпоративном величии.'),
('Стратегия голубого океана', 'Чан Ким и Рене Моборн', 2005, 320, ARRAY['Нон-фикшн', 'Бизнес'],
 'Книга предлагает компаниям вместо конкуренции в переполненных «алых океанах» существующих рынков создавать собственные, свободные от соперников «голубые океаны» новых рыночных пространств. Одна из самых известных концепций стратегического менеджмента XXI века.'),
('Деньги. Мастер игры', 'Тони Роббинс', 2014, 688, ARRAY['Нон-фикшн', 'Бизнес', 'Финансы'],
 'Известный коуч по личностному росту берёт интервью у десятков крупнейших инвесторов мира и превращает их советы в пошаговый план финансовой свободы для обычного читателя. Один из самых объёмных и подробных бестселлеров по личным финансам.'),
('Богатство народов', 'Адам Смит', 1776, 1152, ARRAY['Нон-фикшн', 'Бизнес', 'История', 'Философия'],
 'Фундаментальный трактат описывает принципы свободного рынка, разделение труда и роль «невидимой руки» в саморегуляции экономики без вмешательства государства. Книга, заложившая основы современной экономической науки.'),
('Капитал', 'Карл Маркс', 1867, 784, ARRAY['Нон-фикшн', 'Философия', 'История', 'Политическая проза'],
 'Фундаментальный экономический труд анализирует механизмы капиталистического производства, прибавочной стоимости и эксплуатации наёмного труда. Одна из самых влиятельных и спорных книг в истории экономической и политической мысли.'),
('Тонкая красная линия', 'Джеймс Джонс', 1962, 496, ARRAY['Военная проза', 'Драма', 'Исторический роман'],
 'Рота американских солдат сражается за стратегическую высоту на острове Гуадалканал во время Второй мировой войны, а автор показывает войну не через героизм, а через страх, усталость и хрупкость психики обычных людей. Один из самых реалистичных романов о боевых действиях на Тихом океане.'),
('Мессия Дюны', 'Фрэнк Герберт', 1969, 256, ARRAY['Научная фантастика', 'Философия', 'Политическая проза'],
 'Двенадцать лет спустя после событий «Дюны» Пол Атрейдес правит галактической империей как мессия-тиран, развязавший священную войну, унёсшую миллиарды жизней, — и пытается найти выход из ловушки собственного пророческого дара. Прямое продолжение «Дюны» ставит под сомнение героизм главного героя первой книги.'),
('Дети Дюны', 'Фрэнк Герберт', 1976, 384, ARRAY['Научная фантастика', 'Философия', 'Политическая проза'],
 'Дети Пола Атрейдеса, близнецы Лето и Ганима, наследуют не только трон, но и генетическую память бесчисленных предков, пытаясь найти собственный путь, отличный от пути отца-мессии. Третий роман цикла «Дюна» продолжает исследовать цену власти и пророчества.'),
('Гордость и предубеждение и зомби', 'Сет Грэм-Смит', 2009, 320, ARRAY['Сатира', 'Ужасы', 'Любовный роман', 'Юмор'],
 'Элизабет Беннет и её сёстры не только ищут выгодных женихов в провинциальной Англии, но и профессионально истребляют орды зомби, наводнивших сельскую местность. Пародийный мэшап, вплетающий классический текст Джейн Остин в декорации зомби-апокалипсиса.'),
('Милый друг', 'Ги де Мопассан', 1885, 352, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'Обаятельный и беспринципный Жорж Дюруа поднимается из нищеты к вершинам парижского общества, цинично используя женщин и газетные интриги. Один из самых едких романов французской литературы о цене успеха в журналистике и свете.'),
('Триумфальная арка', 'Эрих Мария Ремарк', 1945, 454, ARRAY['Классика', 'Драма', 'Любовный роман', 'Военная проза'],
 'Немецкий хирург-эмигрант без документов работает нелегально в довоенном Париже, вынашивая план мести нацистскому палачу, пока случайная встреча с актрисой Жоан не дарит ему короткое, обречённое на разлуку счастье. Один из самых проникновенных романов Ремарка об изгнании и любви накануне катастрофы.'),
('Мартин Иден', 'Джек Лондон', 1909, 480, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Простой моряк Мартин Иден влюбляется в девушку из состоятельной семьи и решает стать писателем, чтобы быть её достойным, — а добившись наконец успеха и признания, обнаруживает, что мечта обернулась внутренней пустотой. Один из самых известных романов о цене успеха и разочаровании в собственной мечте.'),
('Белый Клык', 'Джек Лондон', 1906, 320, ARRAY['Классика', 'Приключения', 'Художественная проза'],
 'Полуволк-полупёс по кличке Белый Клык проходит путь от жестокого собачьего бойца до верного друга человека в суровых условиях Клондайка. Приключенческий роман Джека Лондона о силе и доверии, написанный с точки зрения самого животного.'),
('Зов предков', 'Джек Лондон', 1903, 160, ARRAY['Классика', 'Приключения', 'Художественная проза'],
 'Домашний пёс Бэк, украденный и проданный на золотые прииски Клондайка, постепенно сбрасывает цивилизованные привычки и возвращается к зову диких предков. Короткая и мощная повесть о природе и инстинкте против воспитания.'),
('Моя гениальная подруга', 'Элена Ферранте', 2011, 384, ARRAY['Драма', 'Семейная сага', 'Психологическая проза'],
 'Две девочки из бедного неаполитанского квартала, умная и своевольная Лила и прилежная рассказчица Элена, строят дружбу длиной в жизнь, полную соперничества, восхищения и зависти. Первая книга «неаполитанского квартета» стала мировым литературным феноменом.'),
('Повесть о настоящем человеке', 'Борис Полевой', 1946, 288, ARRAY['Военная проза', 'Драма', 'Исторический роман'],
 'Советский лётчик Алексей Мересьев, потерявший обе ноги после авиакатастрофы, превозмогает боль и отчаяние, чтобы снова подняться в небо и вернуться к боевым вылетам. Документальный по духу роман о силе воли, основанный на реальной судьбе лётчика Алексея Маресьева.'),
('А зори здесь тихие...', 'Борис Васильев', 1969, 192, ARRAY['Военная проза', 'Драма', 'Исторический роман'],
 'Пятеро девушек-зенитчиц вместе со старшиной вступают в неравный бой с отрядом немецких диверсантов в карельских лесах. Одна из самых пронзительных советских повестей о войне, где на передний план выходит именно женский опыт фронта.'),
('В списках не значился', 'Борис Васильев', 1974, 256, ARRAY['Военная проза', 'Драма', 'Исторический роман'],
 'Молодой лейтенант прибывает в Брестскую крепость буквально накануне немецкого вторжения и, формально не числясь ни в одном списке личного состава, продолжает в одиночку сражаться в руинах крепости почти десять месяцев. Одна из самых трагических и героических повестей о первых днях Великой Отечественной войны.'),
('Молодая гвардия', 'Александр Фадеев', 1946, 544, ARRAY['Военная проза', 'Драма', 'Исторический роман'],
 'Группа советских школьников-подпольщиков организует сопротивление немецкой оккупации в шахтёрском городе Краснодоне. Роман, основанный на реальной истории подпольной организации, стал одной из самых известных книг о молодёжном сопротивлении во время войны.'),
('Как закалялась сталь', 'Николай Островский', 1934, 464, ARRAY['Классика', 'Исторический роман', 'Драма'],
 'Павел Корчагин проходит путь от бедного подростка до красноармейца Гражданской войны и несгибаемого коммуниста, теряющего здоровье и зрение, но не веру в дело революции. Полуавтобиографический роман стал одной из самых известных книг о поколении, сформированном революцией и войной.'),
('Судьба человека', 'Михаил Шолохов', 1957, 48, ARRAY['Военная проза', 'Драма', 'Классика'],
 'Бывший военнопленный Андрей Соколов, потерявший на войне всю семью, усыновляет такого же осиротевшего мальчишку и находит в этом последний смысл дальнейшей жизни. Короткий, но один из самых эмоционально сильных рассказов о войне в русской литературе.'),
('Старик Хоттабыч', 'Лазарь Лагин', 1938, 224, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Юмор'],
 'Пионер Волька выпускает из старинного кувшина могучего, но безнадёжно отставшего от современности джинна Хоттабыча, который начинает щедро одаривать своего спасителя совершенно неуместными в советской действительности чудесами. Одна из самых любимых советских детских сказок о дружбе и столкновении эпох.'),
('Трое из Простоквашино', 'Эдуард Успенский', 1973, 128, ARRAY['Детская литература', 'Сказка', 'Юмор'],
 'Мальчик Дядя Фёдор вместе с говорящим котом Матроскиным и бестолковым псом Шариком поселяется в деревенском доме Простоквашино, заводит корову и то и дело разбирается с деревенским почтальоном Печкиным. Одна из самых любимых советских детских повестей о самостоятельности и дружбе.'),
('Приключения Буратино, или Золотой ключик', 'Алексей Толстой', 1936, 128, ARRAY['Сказка', 'Детская литература', 'Юмор'],
 'Деревянный мальчишка Буратино сбегает от злого кукольника Карабаса-Барабаса и ищет потайную дверцу, которую открывает золотой ключик. Русская переработка истории о Пиноккио стала самостоятельной и не менее любимой классикой детской литературы.'),
('Урфин Джюс и его деревянные солдаты', 'Александр Волков', 1963, 256, ARRAY['Сказка', 'Детская литература', 'Фэнтези'],
 'Амбициозный столяр Урфин Джюс оживляет целую армию деревянных солдат с помощью волшебного порошка и захватывает власть над Изумрудным городом. Второй роман цикла об Изумрудном городе, куда более приключенческий и мрачный, чем первый.'),
('Семь подземных королей', 'Александр Волков', 1964, 240, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Приключения'],
 'Элли вновь попадает в Волшебную страну и вместе с друзьями спускается в подземное царство семи братьев-королей-коротышек, чтобы предотвратить новый заговор против Изумрудного города. Третья книга цикла продолжает приключения героев в придуманном Волковым мире.'),
('Гадкий утёнок', 'Ганс Христиан Андерсен', 1843, 32, ARRAY['Сказка', 'Детская литература', 'Классика'],
 'Нескладного птенца, не похожего на остальных утят, травят и изгоняют всей птичьей компанией, пока он не вырастает в прекрасного лебедя. Одна из самых известных сказок-притч о непохожести и обретении собственного места в мире.'),
('Русалочка', 'Ганс Христиан Андерсен', 1837, 48, ARRAY['Сказка', 'Детская литература', 'Классика', 'Драма'],
 'Морская русалочка отдаёт голос ведьме в обмен на человеческие ноги, чтобы быть рядом с полюбившимся ей принцем, — но, в отличие от позднейших экранизаций, оригинальная сказка Андерсена заканчивается совсем не счастливо. Одна из самых трогательных и печальных сказок о безответной любви и самопожертвовании.'),
('Дикие лебеди', 'Ганс Христиан Андерсен', 1838, 48, ARRAY['Сказка', 'Детская литература', 'Классика'],
 'Одиннадцать братьев принцессы Элизы превращены злой мачехой в диких лебедей, и единственный способ расколдовать их — сплести одиннадцать рубашек из крапивы, храня полное молчание. Сказка о сестринской преданности и силе немого, но упорного труда.'),
('Руслан и Людмила', 'Александр Пушкин', 1820, 160, ARRAY['Классика', 'Поэзия', 'Сказка', 'Фэнтези'],
 'В ночь свадьбы злой колдун-карлик Черномор похищает невесту киевского князя Людмилу, и богатырь Руслан вместе с соперниками отправляется её спасать, сражаясь с великанской говорящей головой и коварными волшебниками. Поэма-сказка молодого Пушкина соединила русский фольклор с духом рыцарского романа.'),
('Сказка о царе Салтане', 'Александр Пушкин', 1831, 32, ARRAY['Сказка', 'Поэзия', 'Детская литература', 'Классика'],
 'Оклеветанную царицу с маленьким сыном заточают в бочку и бросают в море, но чудом спасшийся царевич Гвидон вырастает правителем волшебного острова, где ему помогает заколдованная Царевна Лебедь. Одна из самых музыкальных и любимых сказок Пушкина в стихах.'),
('Сказка о рыбаке и рыбке', 'Александр Пушкин', 1833, 16, ARRAY['Сказка', 'Поэзия', 'Детская литература', 'Классика'],
 'Старик отпускает пойманную золотую рыбку в обмен на исполнение желаний, а его жадная старуха требует всё больше и больше, пока не теряет всё и не остаётся у разбитого корыта. Короткая стихотворная притча о жадности, ставшая крылатым выражением в русском языке.'),
('Конёк-Горбунок', 'Пётр Ершов', 1834, 128, ARRAY['Сказка', 'Поэзия', 'Детская литература', 'Классика'],
 'Крестьянский сын Иванушка-дурачок с помощью волшебного маленького конька с двумя горбами проходит через царские поручения — от поимки Жар-птицы до купания в кипящем молоке — и в итоге сам становится царём. Одна из самых любимых и часто цитируемых русских литературных сказок в стихах.'),
('Братья Львиное Сердце', 'Астрид Линдгрен', 1973, 208, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Драма'],
 'Смертельно больной мальчик умирает и попадает в волшебную страну Нангиялу, где воссоединяется со старшим братом, — но и там приходится сражаться со злом, угрожающим этому новому миру. Одна из самых серьёзных и философских сказок Астрид Линдгрен, открыто говорящая с детьми о смерти.'),
('Эмиль из Лённеберги', 'Астрид Линдгрен', 1963, 224, ARRAY['Детская литература', 'Юмор', 'Сказка'],
 'Неугомонный шведский мальчишка Эмиль вечно попадает в нелепые передряги на семейном хуторе и в наказание отсиживает время в сарае, где от скуки вырезает деревянные фигурки. Весёлая и тёплая повесть о детских шалостях в сельской Швеции начала XX века.'),
('Рони, дочь разбойника', 'Астрид Линдгрен', 1981, 208, ARRAY['Фэнтези', 'Детская литература', 'Приключения'],
 'Дочь предводителя разбойничьей шайки Рони заводит дружбу с сыном враждебного клана Биргитом, бросая вызов многолетней вражде двух семей. Одна из последних и самых атмосферных сказочных повестей Астрид Линдгрен о дружбе, независимости и взрослении.'),
('Мэри Поппинс', 'Памела Трэверс', 1934, 224, ARRAY['Сказка', 'Детская литература', 'Фэнтези', 'Юмор'],
 'Строгая и загадочная няня с волшебным зонтиком появляется в лондонской семье Бэнксов буквально с порывом восточного ветра и превращает скучные детские будни в череду необъяснимых чудес. Один из самых знаменитых образов британской детской литературы XX века.'),
('Приключения Электроника', 'Евгений Велтистов', 1964, 224, ARRAY['Научная фантастика', 'Детская литература', 'Приключения'],
 'Учёный создаёт робота-мальчика Электроника, точную копию школьника Сыроежкина, который сбегает из лаборатории и пытается понять, каково это — быть настоящим человеком. Одна из самых известных советских детских научно-фантастических повестей о дружбе человека и машины.'),
('Королевство кривых зеркал', 'Виталий Губарев', 1951, 128, ARRAY['Сказка', 'Детская литература', 'Фэнтези'],
 'Непослушная девочка Оля попадает сквозь зеркало в королевство, где всё отражено наоборот, и встречает там собственное зазеркальное отражение по имени Яло. Советская сказочная повесть о дружбе и взрослении через волшебное зазеркалье.'),
('Тимур и его команда', 'Аркадий Гайдар', 1940, 128, ARRAY['Детская литература', 'Приключения', 'Драма'],
 'Подросток Тимур тайно организует отряд ребят, которые без лишней огласки помогают семьям красноармейцев, одновременно воюя с местной хулиганской шайкой. Повесть подарила советской культуре само понятие «тимуровское движение» как символ бескорыстной помощи.'),
('Судьба барабанщика', 'Аркадий Гайдар', 1939, 160, ARRAY['Приключения', 'Детская литература', 'Драма'],
 'Подросток, оставшийся без присмотра после ареста отца, попадает в сети шпионской группы, маскирующейся под добрых знакомых. Напряжённая приключенческая повесть Гайдара о взрослении, доверии и бдительности.'),
('Два капитана', 'Вениамин Каверин', 1944, 768, ARRAY['Приключения', 'Драма', 'Исторический роман'],
 'Немой мальчик из глухого городка вырастает лётчиком, одержимым разгадкой тайны пропавшей полярной экспедиции, случайно связанной с его собственным прошлым. Девиз героя «Бороться и искать, найти и не сдаваться» стал одной из самых известных цитат советской литературы.'),
('Разгром', 'Александр Фадеев', 1927, 192, ARRAY['Военная проза', 'Драма', 'Исторический роман'],
 'Партизанский отряд на Дальнем Востоке во время Гражданской войны терпит сокрушительное поражение, и автор исследует, кто из бойцов и командиров оказался по-настоящему способен выдержать это испытание. Один из первых и самых известных советских романов о Гражданской войне.'),
('Женщина в белом', 'Уилки Коллинз', 1859, 624, ARRAY['Детектив', 'Классика', 'Триллер', 'Готика'],
 'Учитель рисования встречает на ночной дороге загадочную женщину в белом, сбежавшую из психиатрической лечебницы, — а вскоре обнаруживает, что её судьба зловеще переплетена с судьбой его собственной ученицы. Один из первых и самых влиятельных романов в жанре сенсационной литературы и детектива.'),
('Лунный камень', 'Уилки Коллинз', 1868, 528, ARRAY['Детектив', 'Классика', 'Приключения'],
 'Бесценный индийский алмаз, подаренный девушке на день рождения, исчезает из её комнаты в ту же ночь, а расследование, рассказанное несколькими разными свидетелями, раз за разом заходит в тупик. Один из первых классических детективных романов английской литературы.'),
('Дети капитана Гранта', 'Жюль Верн', 1868, 576, ARRAY['Приключения', 'Классика', 'Научная фантастика'],
 'По найденной в бутылке записке дети пропавшего без вести капитана Гранта вместе с эксцентричным географом Паганелем отправляются на поиски отца вдоль тридцать седьмой параллели через три континента. Один из самых масштабных приключенческих романов Жюля Верна.'),
('Пять недель на воздушном шаре', 'Жюль Верн', 1863, 320, ARRAY['Приключения', 'Научная фантастика', 'Классика'],
 'Трое англичан пересекают неисследованную Африку на воздушном шаре, становясь свидетелями и участниками череды опасных приключений. Дебютный роман Жюля Верна, с которого началась серия «Необыкновенные путешествия».'),
('С Земли на Луну', 'Жюль Верн', 1865, 240, ARRAY['Научная фантастика', 'Приключения', 'Классика'],
 'Американский артиллерийский клуб после окончания Гражданской войны от скуки решает построить гигантскую пушку и запустить экипаж на Луну. Один из первых и самых пророческих романов о космических полётах в истории научной фантастики.'),
('Повесть о двух городах', 'Чарльз Диккенс', 1859, 480, ARRAY['Классика', 'Исторический роман', 'Драма'],
 'Судьбы английского и французского семейства переплетаются на фоне Великой французской революции, а один из героев в финале жертвует собой ради спасения человека, которого когда-то презирал. Один из самых продаваемых романов в истории литературы, с одной из самых знаменитых первых строк.'),
('Лавка древностей', 'Чарльз Диккенс', 1841, 560, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'Маленькая Нелл и её дед, одержимый азартными играми владелец лавки антиквариата, бегут от кредиторов и зловещего ростовщика через всю Англию в поисках спасения и покоя. Один из самых сентиментальных и трагических романов раннего Диккенса.'),
('Холодный дом', 'Чарльз Диккенс', 1853, 928, ARRAY['Классика', 'Детектив', 'Сатира', 'Драма'],
 'Бесконечная судебная тяжба о наследстве медленно разрушает жизни всех, кто имел несчастье оказаться в неё вовлечён, пока на фоне этого абсурдного процесса разворачивается детективная история о тайном материнстве и убийстве. Один из самых сложных и социально острых романов Диккенса, высмеивающий английскую судебную систему.'),
('Агнес Грей', 'Энн Бронте', 1847, 240, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'Дочь бедного священника поступает гувернанткой в богатые семьи, сталкиваясь с избалованными воспитанниками и унизительным положением прислуги высшего порядка. Полуавтобиографический роман младшей из сестёр Бронте — один из первых честных портретов профессии гувернантки в английской литературе.'),
('Незнакомка из Уайлдфелл-Холла', 'Энн Бронте', 1848, 448, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Загадочная молодая вдова поселяется в уединённом поместье, скрывая от соседей темные обстоятельства бегства от собственного мужа-алкоголика. Один из первых феминистских романов английской литературы, откровенно говорящий о домашнем насилии и праве женщины на развод.'),
('Крошка Доррит', 'Чарльз Диккенс', 1857, 896, ARRAY['Классика', 'Художественная проза', 'Драма', 'Сатира'],
 'Девушка, выросшая в долговой тюрьме, где содержится её отец, неожиданно для себя становится наследницей состояния, в то время как её покровитель переживает крах всей своей прежней жизни. Один из самых мрачных поздних романов Диккенса о деньгах, бюрократии и тюрьмах — настоящих и метафорических.'),
('Домби и сын', 'Чарльз Диккенс', 1848, 912, ARRAY['Классика', 'Художественная проза', 'Драма'],
 'Холодный и гордый торговец Домби мечтает о сыне-наследнике для фамильной фирмы, но судьба ребёнка и позже дочери, которую отец долгие годы отвергал, оборачивается совсем не так, как он планировал. Один из первых романов Диккенса, подробно исследующих тему семейных отношений и родительской слепоты.'),
('Записки Пиквикского клуба', 'Чарльз Диккенс', 1837, 896, ARRAY['Классика', 'Юмор', 'Приключения'],
 'Эксцентричный мистер Пиквик и трое его друзей по клубу отправляются путешествовать по Англии, попадая в череду комических недоразумений, судебных тяжб и нелепых ухаживаний. Дебютный роман Диккенса, принёсший ему мгновенную славу благодаря неудержимому юмору.'),
('Джуд Незаметный', 'Томас Харди', 1895, 512, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Бедный каменотёс Джуд мечтает об университетском образовании, недоступном человеку его происхождения, а его запретная любовь к свободолюбивой кузине Сью становится источником общественного осуждения и личной трагедии. Один из самых мрачных и социально резких романов Томаса Харди.'),
('Вдали от обезумевшей толпы', 'Томас Харди', 1874, 464, ARRAY['Классика', 'Любовный роман', 'Драма'],
 'Независимая фермерша Батшеба Эвердин выбирает между тремя совершенно разными поклонниками, пытаясь при этом удержать под контролем собственное хозяйство в сельской Англии. Один из первых романов, принёсших Харди известность, с одной из самых сильных героинь викторианской литературы.'),
('Мэр Кэстербриджа', 'Томас Харди', 1886, 384, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Подвыпивший работник продаёт на ярмарке жену и дочь случайному моряку, а годы спустя, уже став уважаемым городским мэром, вынужден столкнуться с последствиями этого давнего и постыдного поступка. Один из самых беспощадных романов Харди о неизбежности расплаты за прошлые грехи.'),
('Крошка Цахес по прозванию Циннобер', 'Эрнст Теодор Амадей Гофман', 1819, 160, ARRAY['Фэнтези', 'Сатира', 'Мистика'],
 'Уродливый карлик получает от доброй феи три волшебных золотых волоса, благодаря которым все окружающие приписывают ему чужие таланты и заслуги, пока он поднимается до самых высоких постов в маленьком немецком княжестве. Едкая сказочная сатира Гофмана на тщеславие и слепоту общества.'),
('Щелкунчик и Мышиный король', 'Эрнст Теодор Амадей Гофман', 1816, 96, ARRAY['Сказка', 'Детская литература', 'Фэнтези'],
 'В рождественскую ночь деревянный Щелкунчик, подаренный девочке Мари, оживает и вступает в сражение с семиглавым Мышиным королём, а затем уносит её в волшебное кукольное царство. Сказка Гофмана легла в основу знаменитого балета Чайковского.'),
('Приключения барона Мюнхгаузена', 'Рудольф Эрих Распе', 1785, 176, ARRAY['Сказка', 'Приключения', 'Юмор', 'Фэнтези'],
 'Барон Мюнхгаузен рассказывает собутыльникам невероятные, заведомо невозможные истории о собственных похождениях — от полёта на пушечном ядре до вытаскивания самого себя за волосы из болота. Сборник небылиц, собранных по мотивам рассказов реального немецкого барона, стал синонимом весёлого и безобидного враньё.'),
('Дон Жуан', 'Джордж Гордон Байрон', 1824, 512, ARRAY['Поэзия', 'Классика', 'Сатира', 'Юмор'],
 'Незавершённая поэма в стихах иронично переосмысляет легенду о знаменитом соблазнителе, превращая его в скорее жертву обстоятельств и женского напора, чем в хищного покорителя сердец. Одно из самых остроумных и масштабных произведений Байрона.'),
('Паломничество Чайльд-Гарольда', 'Джордж Гордон Байрон', 1818, 256, ARRAY['Поэзия', 'Классика', 'Философия'],
 'Разочарованный в светской жизни молодой аристократ отправляется в путешествие по охваченной наполеоновскими войнами Европе, размышляя о свободе, истории и собственном одиночестве. Поэма подарила европейской культуре архетип байронического героя — гордого, разочарованного скитальца.'),
('Таис Афинская', 'Иван Ефремов', 1972, 416, ARRAY['Исторический роман', 'Приключения', 'Философия'],
 'Афинская гетера Таис сопровождает войско Александра Македонского в его восточном походе, становясь свидетельницей и участницей крушения древних цивилизаций. Исторический роман Ефремова соединяет приключенческий сюжет с размышлениями о красоте, свободе и судьбе женщины в античном мире.'),
('Туманность Андромеды', 'Иван Ефремов', 1957, 336, ARRAY['Научная фантастика', 'Философия', 'Приключения'],
 'Далёкое коммунистическое будущее человечества объединено в единое общество, устремлённое к звёздам, науке и гармоничному развитию личности. Одна из самых значимых советских утопий, оказавшая огромное влияние на всю последующую отечественную научную фантастику.'),
('Час Быка', 'Иван Ефремов', 1968, 448, ARRAY['Научная фантастика', 'Философия', 'Антиутопия'],
 'Экипаж звездолёта с Земли прибывает на планету Торманс, где человеческая цивилизация скатилась к жестокой тоталитарной антиутопии, и пытается понять, можно ли ей помочь, не разрушив при этом её хрупкое равновесие. Одна из самых философски смелых советских научно-фантастических книг, подвергшаяся цензурным гонениям.'),
('Путешествие к центру Земли', 'Жюль Верн', 1864, 320, ARRAY['Научная фантастика', 'Приключения', 'Классика'],
 'Профессор минералогии со своим племянником и исландским проводником спускаются в кратер потухшего вулкана, чтобы по зашифрованной рукописи старинного алхимика добраться до самого центра Земли. Один из самых увлекательных приключенческих романов Жюля Верна о подземном мире, сохранившем доисторических чудовищ.'),
('Реквием', 'Анна Ахматова', 1963, 32, ARRAY['Поэзия', 'Классика', 'Исторический роман'],
 'Поэтический цикл написан в годы сталинских репрессий как отклик на арест сына и бесконечные тюремные очереди в Ленинграде, но долгие годы существовал лишь в памяти близких и не мог быть записан на бумаге. Одно из самых сильных поэтических свидетельств о терроре сталинской эпохи.'),
('Вечер', 'Анна Ахматова', 1912, 96, ARRAY['Поэзия', 'Классика', 'Любовный роман'],
 'Дебютный сборник молодой поэтессы сразу принёс ей известность благодаря интимной, почти разговорной интонации и психологической точности любовной лирики. Книга, с которой начался акмеизм как отдельное направление русской поэзии.'),
('После России', 'Марина Цветаева', 1928, 224, ARRAY['Поэзия', 'Классика'],
 'Сборник объединяет стихи, написанные уже в эмиграции, — о тоске по родине, бедности, материнстве и неутолимой поэтической страсти. Один из самых зрелых и виртуозных по технике поэтических сборников Цветаевой.'),
('Персидские мотивы', 'Сергей Есенин', 1925, 64, ARRAY['Поэзия', 'Классика', 'Любовный роман'],
 'Цикл стихов, вдохновлённый поездкой поэта в Закавказье, воспевает восточную экзотику, любовь и тоску по далёкой русской земле сквозь образы розы, соловья и шафрановой страны. Один из самых светлых и мелодичных поэтических циклов Есенина.'),
('Облако в штанах', 'Владимир Маяковский', 1915, 48, ARRAY['Поэзия', 'Классика'],
 'Поэма о несчастной любви перерастает в бунтарский манифест против буржуазного искусства, религии и общественного строя, выраженный предельно дерзким и новаторским поэтическим языком. Одно из программных произведений русского футуризма.'),
('Двенадцать', 'Александр Блок', 1918, 48, ARRAY['Поэзия', 'Классика', 'Исторический роман'],
 'Поэма изображает отряд из двенадцати красногвардейцев, патрулирующих заснеженный революционный Петроград, — а в финале среди метели перед ними неожиданно возникает фигура Христа. Одно из самых противоречивых и обсуждаемых поэтических откликов на Октябрьскую революцию.'),
('Стихи о Прекрасной Даме', 'Александр Блок', 1904, 160, ARRAY['Поэзия', 'Классика', 'Любовный роман'],
 'Ранний сборник Блока воспевает мистический образ Вечной Женственности, в котором земная возлюбленная поэта сливается с философским идеалом в духе учения Владимира Соловьёва. Сборник, обозначивший Блока как ведущего поэта русского символизма.'),
('Часть речи', 'Иосиф Бродский', 1977, 128, ARRAY['Поэзия', 'Классика', 'Философия'],
 'Сборник, написанный уже в эмиграции, размышляет об изгнании, языке как единственной родине поэта и неумолимом течении времени. Одна из ключевых книг Бродского, во многом определившая присуждение ему Нобелевской премии.'),
('Вишнёвый сад', 'Антон Чехов', 1904, 96, ARRAY['Драма', 'Классика', 'Пьесы'],
 'Разорившаяся помещица возвращается в родовое имение, которое вот-вот будет продано за долги вместе с любимым вишнёвым садом, — а единственный, кто предлагает практичный выход, оказывается сыном бывшего крепостного. Последняя пьеса Чехова о смене эпох и неспособности старого мира приспособиться к новому.'),
('Три сестры', 'Антон Чехов', 1901, 96, ARRAY['Драма', 'Классика', 'Пьесы'],
 'Три сестры из провинциального города мечтают вернуться в Москву своего детства, но год за годом упускают любую возможность что-либо изменить в собственной жизни. Одна из самых тонких пьес Чехова о несбывшихся мечтах и инерции привычного существования.'),
('Дядя Ваня', 'Антон Чехов', 1898, 80, ARRAY['Драма', 'Классика', 'Пьесы'],
 'Приезд профессора с молодой женой в тихое провинциальное имение переворачивает жизнь всех его обитателей, заставляя их осознать, насколько бездарно были потрачены годы. Одна из самых психологически точных пьес Чехова о тихом отчаянии обыденной жизни.'),
('Гроза', 'Александр Островский', 1859, 96, ARRAY['Драма', 'Классика', 'Пьесы'],
 'Молодая купеческая жена Катерина задыхается под гнётом деспотичной свекрови и патриархальных нравов провинциального города и решается на отчаянный шаг во имя короткой, но настоящей любви. Пьеса, давшая критику Добролюбову повод назвать героиню «лучом света в тёмном царстве».'),
('Горе от ума', 'Александр Грибоедов', 1825, 128, ARRAY['Драма', 'Классика', 'Сатира', 'Пьесы'],
 'Вернувшийся из заграницы Чацкий обрушивается на лицемерие и косность московского дворянского общества и в итоге оказывается объявлен сумасшедшим за собственное свободомыслие. Пьеса в стихах, разошедшаяся на пословицы и поговорки едва ли не больше любого другого произведения русской литературы.'),
('Ревизор', 'Николай Гоголь', 1836, 128, ARRAY['Драма', 'Классика', 'Сатира', 'Пьесы'],
 'Мелкого петербургского чиновника по ошибке принимают за грозного столичного ревизора, и чиновники уездного города наперебой пытаются дать ему взятку, лишь бы скрыть собственные злоупотребления. Одна из самых злободневных сатирических комедий русской литературы.'),
('Тарас Бульба', 'Николай Гоголь', 1835, 160, ARRAY['Классика', 'Исторический роман', 'Военная проза'],
 'Старый казачий полковник Тарас Бульба отправляется в поход против поляков вместе с двумя сыновьями, один из которых ради любви предаёт товарищество и отца. Героическая и трагическая повесть о казачьей вольнице и цене предательства.'),
('Вий', 'Николай Гоголь', 1835, 64, ARRAY['Мистика', 'Ужасы', 'Классика'],
 'Семинарист Хома Брут три ночи подряд отчитывает в церкви гроб с телом панночки-ведьмы, с каждой ночью сталкиваясь со всё более жуткой нечистью. Одна из самых страшных повестей русской литературы, завершающаяся появлением легендарного монстра Вия.'),
('Ночь перед Рождеством', 'Николай Гоголь', 1832, 96, ARRAY['Сказка', 'Мистика', 'Юмор', 'Классика'],
 'Кузнец Вакула в сочельник летит верхом на чёрте в Петербург за черевичками для капризной красавицы Оксаны. Весёлая и мистическая святочная повесть из цикла «Вечера на хуторе близ Диканьки».'),
('На дне', 'Максим Горький', 1902, 96, ARRAY['Драма', 'Классика', 'Социальная проза', 'Пьесы'],
 'Обитатели ночлежки для бедноты — бывший актёр, вор, умирающая от чахотки женщина и странник-утешитель Лука — спорят о правде, лжи во спасение и возможности вырваться со дна жизни. Одна из самых мрачных и социально острых пьес русской драматургии.'),
('Пигмалион', 'Бернард Шоу', 1913, 160, ARRAY['Драма', 'Сатира', 'Пьесы', 'Юмор'],
 'Профессор фонетики Хиггинс заключает пари, что за несколько месяцев превратит уличную цветочницу с чудовищным произношением в даму, неотличимую от аристократки. Остроумная пьеса о социальных масках легла в основу мюзикла и фильма «Моя прекрасная леди».'),
('Игра в классики', 'Хулио Кортасар', 1963, 480, ARRAY['Постмодернизм', 'Философия', 'Художественная проза'],
 'Роман можно читать и подряд, и по особой схеме, прыгая между главами, как в детской игре в классики, следуя за аргентинским эмигрантом Орасио Оливейрой по богемному Парижу и ностальгическому Буэнос-Айресу. Одно из самых структурно экспериментальных произведений латиноамериканской литературы.'),
('Город и псы', 'Марио Варгас Льоса', 1963, 432, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Курсанты перуанского военного училища живут по жестоким негласным законам, где слабость карается травлей, а донос считается единственным непростительным грехом. Дебютный роман будущего нобелевского лауреата, основанный на собственном опыте автора в военной школе.'),
('Смерть Артемио Круса', 'Карлос Фуэнтес', 1962, 320, ARRAY['Классика', 'Исторический роман', 'Психологическая проза'],
 'Умирающий магнат Артемио Крус перебирает в памяти ключевые моменты собственной жизни — от участия в Мексиканской революции до циничного обогащения на её итогах. Один из главных романов мексиканской литературы о продажности революционных идеалов.'),
('Педро Парамо', 'Хуан Рульфо', 1955, 160, ARRAY['Магический реализм', 'Классика', 'Мистика'],
 'Юноша приезжает в родную деревню отца в поисках самого Педро Парамо и постепенно понимает, что говорит с призраками в городе, где давно уже нет ни одного живого человека. Короткий, но невероятно влиятельный роман, заложивший основы латиноамериканского магического реализма.'),
('Бог мелочей', 'Арундати Рой', 1997, 384, ARRAY['Драма', 'Семейная сага', 'Психологическая проза'],
 'Разнояйцевые близнецы из касты высокообразованных, но обедневших сирийских христиан южной Индии вспоминают трагическое лето, разрушившее их семью и разделившее их самих на долгие годы. Дебютный роман Арундати Рой принёс ей Букеровскую премию.'),
('Песнь Соломона', 'Тони Моррисон', 1977, 384, ARRAY['Классика', 'Магический реализм', 'Семейная сага'],
 'Молодой афроамериканец по прозвищу Молочник отправляется на юг США в поисках семейного золота, а находит вместо этого собственную родовую историю, уходящую корнями в легенду о летающих африканцах. Один из главных романов Тони Моррисон о поиске идентичности через память предков.'),
('Пурпурный цвет', 'Элис Уокер', 1982, 320, ARRAY['Классика', 'Драма', 'Исторический роман'],
 'Чернокожая девушка на американском Юге начала XX века переписывается с Богом в дневниковых письмах, переживая насилие, разлуку с сестрой и постепенное обретение собственного голоса. Роман в письмах принёс Элис Уокер Пулитцеровскую премию.'),
('Американха', 'Чимаманда Нгози Адичи', 2013, 480, ARRAY['Драма', 'Любовный роман', 'Социальная проза'],
 'Нигерийская девушка эмигрирует в США ради образования и впервые по-настоящему сталкивается с понятием расы, в то время как её школьная любовь остаётся в Лондоне без документов. Один из самых обсуждаемых романов о миграции, идентичности и расе в современном мире.'),
('Половина жёлтого солнца', 'Чимаманда Нгози Адичи', 2006, 448, ARRAY['Исторический роман', 'Военная проза', 'Драма'],
 'Судьбы нескольких нигерийцев переплетаются на фоне кровопролитной гражданской войны за независимость Биафры в конце 1960-х годов. Один из самых известных романов о колониальном наследии и трагедии постколониальной Африки.'),
('Снеговик', 'Ю Несбё', 2007, 544, ARRAY['Триллер', 'Детектив', 'Криминальная проза'],
 'Детектив Харри Холе расследует исчезновение женщины, единственной уликой по делу которой остаётся зловещий снеговик, построенный прямо под её окнами. Один из самых известных романов норвежского нуара о серийном убийце.'),
('Девушка с жемчужной серёжкой', 'Трейси Шевалье', 1999, 272, ARRAY['Исторический роман', 'Драма', 'Художественная проза'],
 'Молодая служанка в доме художника Яна Вермеера становится его музой и натурщицей для одной из самых загадочных картин в истории живописи. Исторический роман, вдохновлённый реальной картиной «Девушка с жемчужной серёжкой».'),
('Смилла и её чувство снега', 'Питер Хёг', 1992, 448, ARRAY['Триллер', 'Детектив', 'Драма'],
 'Полудатчанка-полугренландка Смилла Ясперсен, знающая о снеге и льде больше любого эксперта, по следам на крыше дома понимает, что падение соседского мальчика не было несчастным случаем. Один из самых атмосферных скандинавских триллеров о расследовании и культурной принадлежности.'),
('Элегантная вселенная', 'Брайан Грин', 1999, 448, ARRAY['Нон-фикшн', 'Научно-популярная', 'Физика'],
 'Книга доступно объясняет теорию струн — одну из самых амбициозных попыток физики объединить квантовую механику и общую теорию относительности в единую теорию всего. Один из самых известных научно-популярных бестселлеров о современной физике.'),
('Хаос. Создание новой науки', 'Джеймс Глейк', 1987, 384, ARRAY['Нон-фикшн', 'Научно-популярная', 'Физика'],
 'Книга рассказывает историю зарождения теории хаоса — науки о непредсказуемом поведении сложных систем, от турбулентности до эффекта бабочки в прогнозе погоды. Одна из самых влиятельных научно-популярных книг о рождении новой научной дисциплины.'),
('Бог как иллюзия', 'Ричард Докинз', 2006, 464, ARRAY['Нон-фикшн', 'Научно-популярная', 'Философия'],
 'Биолог-эволюционист последовательно разбирает традиционные аргументы в пользу существования Бога и отстаивает атеизм как рациональную и этически состоятельную позицию. Одна из самых спорных и обсуждаемых научно-популярных книг XXI века.'),
('Физика невозможного', 'Митио Каку', 2008, 352, ARRAY['Нон-фикшн', 'Научно-популярная', 'Физика'],
 'Физик-теоретик разбирает классические сюжеты научной фантастики — телепортацию, невидимость, путешествия во времени — и оценивает, какие из них когда-нибудь действительно могут стать реальностью. Увлекательный научпоп на стыке физики и фантастики.'),
('Воспоминания гейши', 'Артур Голден', 1997, 512, ARRAY['Исторический роман', 'Драма', 'Художественная проза'],
 'Проданная в раннем детстве в гейшинский дом девочка проходит путь от бедной рыбацкой дочери до одной из самых знаменитых гейш довоенного Киото. Роман, рассказанный от первого лица, подробно воссоздаёт закрытый мир японских гейш XX века.'),
('Тайпан', 'Джеймс Клавелл', 1966, 736, ARRAY['Исторический роман', 'Приключения', 'Драма'],
 'Основатель торговой империи на только что захваченном британцами Гонконге ведёт жестокую борьбу за власть над колонией с конкурентами, пиратами и собственным прошлым. Первый роман азиатской саги Клавелла о столкновении Запада и Востока.'),
('Сёгун', 'Джеймс Клавелл', 1975, 1152, ARRAY['Исторический роман', 'Приключения', 'Драма'],
 'Английский штурман, потерпевший кораблекрушение у берегов средневековой Японии, оказывается втянут в смертельно опасные политические интриги накануне решающей битвы за власть над страной. Один из самых масштабных исторических романов о культурном столкновении Запада и феодальной Японии.'),
('Вся королевская рать', 'Роберт Пенн Уоррен', 1946, 464, ARRAY['Классика', 'Политическая проза', 'Драма'],
 'Циничный журналист становится правой рукой харизматичного южного политика-популиста, наблюдая, как благие намерения постепенно превращаются в откровенную коррупцию власти. Один из главных американских романов о природе политической власти и моральном компромиссе.'),
('Дорога перемен', 'Ричард Йейтс', 1961, 384, ARRAY['Драма', 'Психологическая проза', 'Семейная сага'],
 'Молодая пара из пригорода 1950-х годов мечтает вырваться из душной конформистской рутины и переехать в Париж, но мечта медленно разбивается о собственную нерешительность и несовместимость желаний. Один из самых проницательных романов о разочаровании в американской мечте.'),
('Жареные зелёные помидоры в кафе «Полустанок»', 'Фэнни Флэгг', 1987, 416, ARRAY['Драма', 'Юмор', 'Семейная сага'],
 'Пожилая женщина в доме престарелых рассказывает скучающей домохозяйке истории из прошлого маленького городка на американском Юге — о дружбе, убийстве и легендарном кафе, прославившемся на весь округ жареными зелёными помидорами. Тёплый роман о женской дружбе и силе историй, которые мы рассказываем.'),
('Доводы рассудка', 'Джейн Остин', 1817, 272, ARRAY['Классика', 'Любовный роман', 'Драма'],
 'Энн Эллиот много лет назад отказала от любви из-за доводов благоразумных советчиков — а теперь, когда её бывший жених вновь появляется в её жизни уже состоятельным и уважаемым человеком, у неё остаётся последний шанс исправить ошибку молодости. Последний завершённый роман Остин, самый зрелый по тону среди всех её книг.'),
('Нортенгерское аббатство', 'Джейн Остин', 1817, 256, ARRAY['Классика', 'Сатира', 'Любовный роман', 'Готика'],
 'Начитавшаяся готических романов провинциальная барышня Кэтрин Морланд приезжает в старинное аббатство и повсюду мерещатся ей зловещие тайны, которых на самом деле попросту нет. Ироничная пародия Остин на моду готических романов её эпохи.'),
('Мэнсфилд-парк', 'Джейн Остин', 1814, 448, ARRAY['Классика', 'Любовный роман', 'Художественная проза'],
 'Бедная родственница Фанни Прайс растёт в богатом поместье дяди на правах почти прислуги, незаметно и терпеливо влюбляясь в кузена, которого куда больше привлекает яркая столичная гостья. Один из самых моралистических и недооценённых романов Джейн Остин.'),
('Вторая жизнь Уве', 'Фредрик Бакман', 2012, 320, ARRAY['Драма', 'Юмор', 'Психологическая проза'],
 'Угрюмый и педантичный вдовец Уве, разочаровавшийся в жизни после смерти жены, неохотно сближается с шумной семьёй новых соседей, которая переворачивает его тщательно выстроенное одиночество. Тёплая шведская история о горе, дружбе и втором шансе.'),
('Медвежий угол', 'Фредрик Бакман', 2016, 432, ARRAY['Драма', 'Семейная сага', 'Социальная проза'],
 'Маленький шведский городок, живущий хоккеем как единственной надеждой на будущее, оказывается расколот скандалом, связанным со звездой местной юниорской команды. Роман о сообществе, молчании и цене, которую платят самые уязвимые ради общего благополучия.'),
('Элеанор Олифант в полном порядке', 'Гейл Ханимен', 2017, 400, ARRAY['Драма', 'Юмор', 'Психологическая проза'],
 'Социально неловкая одиночка Элеанор Олифант живёт по строгому расписанию и уверяет себя, что у неё всё в полном порядке, — пока случайное знакомство не начинает медленно вскрывать травматичное прошлое, которое она так старательно прячет. Тёплый и трогательный роман о одиночестве и исцелении.'),
('Семь мужей Эвелин Хьюго', 'Тейлор Дженкинс Рид', 2017, 400, ARRAY['Драма', 'Исторический роман', 'Любовный роман'],
 'Стареющая голливудская звезда впервые решается рассказать правду о своих семи браках никому не известной журналистке — и история оказывается далеко не такой, какой её знала публика. Один из самых популярных романов о цене славы и скрытой любви в золотую эпоху Голливуда.'),
('Где раки поют', 'Делия Оуэнс', 2018, 448, ARRAY['Драма', 'Детектив', 'Художественная проза'],
 'Девочка, брошенная семьёй и выросшая в одиночестве среди болот Северной Каролины, становится главной подозреваемой в убийстве местного парня спустя годы. Роман соединяет детективную интригу с лирическим повествованием о дикой природе и человеческом одиночестве.'),
('Полночная библиотека', 'Мэтт Хейг', 2020, 304, ARRAY['Фэнтези', 'Философия', 'Драма'],
 'Между жизнью и смертью разочаровавшаяся в собственной жизни женщина попадает в бесконечную библиотеку, где каждая книга — это версия её жизни, сложившаяся из другого выбора. Философский роман-притча о сожалениях и бесчисленных дорогах, которые мы не выбрали.'),
('Проект «Аве Мария»', 'Энди Вейер', 2021, 476, ARRAY['Научная фантастика', 'Приключения', 'Юмор'],
 'Очнувшись на борту космического корабля без памяти, единственный выживший член экипажа постепенно вспоминает, что отправлен спасти Солнечную систему от вымирания, — и находит неожиданного союзника среди звёзд. Увлекательный научно-фантастический роман от автора «Марсианина».'),
('Витязь в тигровой шкуре', 'Шота Руставели', 1200, 320, ARRAY['Поэзия', 'Классика', 'Приключения', 'Любовный роман'],
 'Грузинский рыцарь Автандил отправляется на поиски таинственного витязя в тигровой шкуре, чтобы помочь другу в поисках его возлюбленной, похищенной злыми силами. Национальный эпос Грузии в стихах — одно из величайших произведений средневековой восточной поэзии.'),
('Слово о полку Игореве', 'Автор неизвестен', 1187, 48, ARRAY['Поэзия', 'Классика', 'Исторический роман', 'Военная проза'],
 'Поэма рассказывает о неудачном походе князя Игоря против половцев, его пленении и побеге, а также о горестном плаче его жены Ярославны. Древнейший из сохранившихся памятников русской литературы, написанный вскоре после описанных в нём событий.'),
('Исповедь', 'Августин Блаженный', 400, 400, ARRAY['Нон-фикшн', 'Философия', 'Биография', 'Религия'],
 'Христианский мыслитель описывает собственный путь от беспечной языческой юности через духовные метания к обращению в христианство, одновременно размышляя о природе времени, памяти и воли. Одна из первых автобиографий в западной литературе и ключевой текст христианской философии.'),
('Структура научных революций', 'Томас Кун', 1962, 264, ARRAY['Нон-фикшн', 'Научно-популярная', 'Философия'],
 'Книга вводит понятие «парадигмы» и описывает, как наука развивается не плавно, а скачкообразно — через революционную смену устоявшихся картин мира, когда накопленные аномалии больше не укладываются в старую теорию. Одна из самых влиятельных книг философии науки XX века.'),
('Реквием по мечте', 'Хьюберт Селби-младший', 1978, 288, ARRAY['Драма', 'Психологическая проза'],
 'Четверо жителей Кони-Айленда — одинокая вдова, её сын и двое его друзей — медленно и неотвратимо катятся к краху через зависимости: от героина до амфетаминов для похудения и телевизионных шоу. Беспощадный роман о зависимости любого рода, легший в основу одноимённого культового фильма.'),
('Медный всадник', 'Александр Пушкин', 1833, 48, ARRAY['Поэзия', 'Классика', 'Мистика'],
 'Мелкий чиновник Евгений теряет возлюбленную в петербургском наводнении и в отчаянии бросает вызов памятнику Петру Великому, виновному, по его мнению, в основании города на столь гибельном месте, — а каменный всадник оживает и начинает его преследовать. Одна из самых мистических и философских поэм Пушкина о человеке перед лицом государственной машины.'),
('Мцыри', 'Михаил Лермонтов', 1840, 48, ARRAY['Поэзия', 'Классика', 'Приключения'],
 'Юный горец, с детства заточённый в монастыре, совершает побег на три дня, чтобы хоть недолго вкусить настоящей свободы, прежде чем вернуться туда умирать. Романтическая поэма о тоске по воле и недостижимой полноте жизни.'),
('Герой нашего времени', 'Михаил Лермонтов', 1840, 224, ARRAY['Классика', 'Психологическая проза', 'Приключения'],
 'Циничный и скучающий офицер Печорин разрушает судьбы окружающих его людей на Кавказе, не находя применения собственным незаурядным способностям в обществе, которое ему чуждо. Один из первых психологических романов русской литературы, предвосхитивший героев Достоевского.'),
('Демон', 'Михаил Лермонтов', 1839, 64, ARRAY['Поэзия', 'Классика', 'Мистика', 'Любовный роман'],
 'Падший ангел, уставший от вечного одиночества и зла, влюбляется в земную грузинскую княжну Тамару и пытается через эту любовь обрести утраченную гармонию с миром. Одна из самых романтических и мистических поэм русской литературы.'),
('Кому на Руси жить хорошо', 'Николай Некрасов', 1877, 240, ARRAY['Поэзия', 'Классика', 'Социальная проза'],
 'Семеро крестьян отправляются странствовать по пореформенной России в поисках ответа на вопрос, кому на Руси живётся вольготно и счастливо. Масштабная народная поэма-эпопея о жизни русского крестьянства после отмены крепостного права.'),
('Гобсек', 'Оноре де Бальзак', 1830, 96, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Старый парижский ростовщик Гобсек, накопивший огромное состояние ценой полного отказа от человеческих привязанностей, становится свидетелем и невольным судьёй чужих семейных драм, построенных на деньгах. Короткая и беспощадная повесть о власти золота над человеческой душой.'),
('Евгения Гранде', 'Оноре де Бальзак', 1833, 256, ARRAY['Классика', 'Драма', 'Любовный роман'],
 'Дочь скупого провинциального богача влюбляется в обедневшего столичного кузена и тратит на него тайные сбережения, за что расплачивается годами одинокой и несчастливой жизни. Один из самых психологически точных романов Бальзака о скупости, самопожертвовании и несбывшейся любви.'),
('Шагреневая кожа', 'Оноре де Бальзак', 1831, 304, ARRAY['Классика', 'Мистика', 'Философия'],
 'Разорившийся юноша получает волшебный кусок кожи, исполняющий любое желание, — но с каждым исполненным желанием кожа сжимается, а вместе с ней сокращается и жизнь владельца. Философская притча о цене исполненных желаний и неизбежности смерти.'),
('Пена дней', 'Борис Виан', 1947, 192, ARRAY['Магический реализм', 'Любовный роман', 'Сатира'],
 'В причудливом мире, где коктейли готовит рояль, а мышь живёт в каждой квартире, молодой человек женится на девушке, в чьих лёгких постепенно вырастает цветок, медленно убивающий её. Сюрреалистический роман о любви, болезни и абсурдности мира, полный изобретательной игры слов.'),
('Школа для дураков', 'Саша Соколов', 1976, 192, ARRAY['Постмодернизм', 'Психологическая проза', 'Поэзия'],
 'Ученик спецшколы для умственно отсталых детей, страдающий раздвоением личности, ведёт прихотливое, нелинейное повествование, в котором время течёт одновременно в нескольких направлениях. Один из первых и самых значительных образцов русского литературного постмодернизма.'),
('Москва — Петушки', 'Венедикт Ерофеев', 1970, 160, ARRAY['Постмодернизм', 'Сатира', 'Юмор', 'Философия'],
 'Пьющий интеллигент Веничка едет на электричке из Москвы в Петушки к любимой женщине, философствуя, цитируя классиков и смешивая немыслимые коктейли, — а маршрут раз за разом оборачивается чем-то совсем иным, чем кажется. Культовая поэма в прозе, ставшая одним из главных текстов позднесоветского андеграунда.'),
('Повести Белкина', 'Александр Пушкин', 1831, 128, ARRAY['Классика', 'Художественная проза', 'Юмор'],
 'Пять самостоятельных новелл — о выстреле, метели, гробовщике, станционном смотрителе и барышне-крестьянке — объединены фигурой вымышленного рассказчика Ивана Белкина. Первый законченный прозаический цикл Пушкина заложил основы русской классической прозы.'),
('Пиковая дама', 'Александр Пушкин', 1834, 64, ARRAY['Классика', 'Мистика', 'Психологическая проза'],
 'Военный инженер Германн узнаёт тайну трёх карт, способных сделать его сказочно богатым, и из жажды разбогатеть доводит пожилую графиню-хранительницу тайны до смерти, — а затем расплачивается за это собственным рассудком. Одна из самых мистических и психологически точных повестей Пушкина об одержимости и возмездии.'),
('Дубровский', 'Александр Пушкин', 1841, 160, ARRAY['Классика', 'Приключения', 'Любовный роман'],
 'Молодой офицер Владимир Дубровский, разорённый и доведённый до отчаяния несправедливым соседом-помещиком, становится благородным разбойником и влюбляется в дочь своего врага. Неоконченный роман Пушкина о мести, чести и запретной любви.'),
('Дом на краю света', 'Майкл Каннингем', 1990, 352, ARRAY['Драма', 'Семейная сага', 'Психологическая проза'],
 'Двое друзей детства, выросшая вместе с ними девушка и её будущий ребёнок создают нетрадиционную семью втроём, бросающую вызов общепринятым представлениям о доме и родстве. Роман о поиске собственной формы семьи вне привычных рамок.'),
('Часы', 'Майкл Каннингем', 1998, 240, ARRAY['Драма', 'Психологическая проза', 'Исторический роман'],
 'Один день из жизни трёх женщин разных эпох — самой Вирджинии Вулф, работающей над романом «Миссис Дэллоуэй», читательницы этого романа в 1950-х и современной нью-йоркской издательницы — переплетается в структуре, вдохновлённой самим произведением Вулф. Роман принёс Каннингему Пулитцеровскую премию.'),
('Любовник', 'Маргерит Дюрас', 1984, 128, ARRAY['Классика', 'Любовный роман', 'Драма'],
 'Пятнадцатилетняя французская девочка из бедной колониальной семьи вступает в тайную любовную связь с состоятельным китайцем во Вьетнаме 1930-х годов. Автобиографичный роман Дюрас о запретной любви, нищете и колониальном Индокитае принёс ей Гонкуровскую премию.'),
('Мандолина капитана Корелли', 'Луи де Берньер', 1994, 544, ARRAY['Исторический роман', 'Любовный роман', 'Военная проза'],
 'Итальянский офицер-музыкант, расквартированный на греческом острове во время Второй мировой войны, влюбляется в дочь местного врача, несмотря на то что их страны находятся по разные стороны фронта. Роман о любви, войне и оккупации на фоне идиллической греческой природы.'),
('Остров', 'Олдос Хаксли', 1962, 336, ARRAY['Научная фантастика', 'Философия', 'Утопия'],
 'Потерпевший кораблекрушение журналист попадает на утопический остров Пала, где местные жители сумели совместить западную науку с восточной духовностью и построить по-настоящему гармоничное общество. Последний роман Хаксли представляет собой позитивную утопию в противовес его же антиутопии «О дивный новый мир».'),
('Контрапункт', 'Олдос Хаксли', 1928, 480, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Жизни нескольких лондонских интеллектуалов и богемных персонажей переплетаются и комментируют друг друга, подобно голосам в музыкальном контрапункте. Один из самых известных романов межвоенного Хаксли, построенный по музыкальному принципу композиции.'),
('Слепота', 'Жозе Сарамаго', 1995, 352, ARRAY['Классика', 'Драма', 'Антиутопия'],
 'Необъяснимая эпидемия белой слепоты поочерёдно поражает жителей безымянного города, и общество стремительно скатывается в варварство, пока единственный зрячий человек пытается сохранить хоть каплю человечности. Мощная притча нобелевского лауреата о цивилизации, держащейся на тонкой плёнке приличий.'),
('Евангелие от Иисуса', 'Жозе Сарамаго', 1991, 448, ARRAY['Классика', 'Философия', 'Исторический роман'],
 'Роман переосмысляет жизнь Иисуса Христа как человека, мучительно пытающегося понять собственное предназначение и цену, которую придётся заплатить за спасение человечества. Одно из самых спорных произведений Сарамаго, вызвавшее острую полемику с католической церковью.'),
('Безмолвный пациент', 'Алекс Михаэлидес', 2019, 352, ARRAY['Триллер', 'Детектив', 'Психологическая проза'],
 'Успешная художница стреляет в мужа пять раз подряд, а затем полностью замолкает и не произносит ни слова — и психотерапевт, одержимый её молчанием, пытается во что бы то ни стало разгадать причину немыслимого преступления. Один из самых успешных психологических триллеров конца 2010-х годов.'),
('Дом странных детей', 'Ренсом Риггз', 2011, 352, ARRAY['Фэнтези', 'Мистика', 'Приключения'],
 'После смерти деда подросток отправляется на уединённый валлийский остров, где находит сиротский приют, застывший в одном и том же дне 1940 года и населённый детьми с необычными способностями. Роман, иллюстрированный подлинными старинными фотографиями, стал основой популярной young-adult серии.'),
('Белый отряд', 'Артур Конан Дойл', 1891, 384, ARRAY['Исторический роман', 'Приключения', 'Военная проза'],
 'Молодой послушник покидает монастырь и присоединяется к отряду английских лучников, отправляющихся воевать во Францию и Испанию времён Столетней войны. Любимый самим автором исторический роман о рыцарстве, куда менее известный, чем его детективы о Шерлоке Холмсе.'),
('Затерянный мир', 'Артур Конан Дойл', 1912, 288, ARRAY['Научная фантастика', 'Приключения', 'Классика'],
 'Эксцентричный профессор Челленджер организует экспедицию на отдалённое южноамериканское плато, где, по его утверждению, всё ещё обитают доисторические динозавры. Один из первых и самых влиятельных романов жанра «затерянного мира», вдохновивший бесчисленных последователей от «Парка Юрского периода» до «Кинг-Конга».'),
('Собака на сене', 'Лопе де Вега', 1618, 160, ARRAY['Драма', 'Юмор', 'Любовный роман', 'Пьесы'],
 'Знатная неаполитанская графиня не может позволить себе выйти замуж за собственного секретаря из-за разницы в положении, но и не в силах смотреть, как он достаётся другой. Одна из самых популярных комедий испанского золотого века о любви, гордости и сословных предрассудках.'),
('Жизнь есть сон', 'Педро Кальдерон де ла Барка', 1635, 160, ARRAY['Драма', 'Философия', 'Пьесы'],
 'Польского принца, заключённого отцом в башню из страха перед пророчеством, на один день освобождают и возвращают во дворец, чтобы проверить его нрав, — а затем вновь погружают в сон, заставляя усомниться, где явь, а где видение. Философская драма золотого века испанской литературы о свободе воли и природе реальности.'),
('Фуэнте Овехуна', 'Лопе де Вега', 1619, 128, ARRAY['Драма', 'Исторический роман', 'Пьесы'],
 'Жители испанской деревни коллективно убивают жестокого командора, творившего произвол над местными жителями, а на королевском допросе все как один твердят, что виновна вся деревня сразу. Пьеса о коллективном сопротивлении тирании, основанная на реальных исторических событиях.'),
('Севильский озорник, или Каменный гость', 'Тирсо де Молина', 1630, 128, ARRAY['Драма', 'Пьесы', 'Мистика'],
 'Легендарный соблазнитель дон Хуан обманывает и бросает одну женщину за другой, пока в финале не получает возмездие от ожившей каменной статуи убитого им командора. Пьеса, впервые представившая миру легенду о Дон Жуане, вдохновившая бесчисленные последующие версии сюжета.'),
('Дон Карлос', 'Фридрих Шиллер', 1787, 224, ARRAY['Драма', 'Исторический роман', 'Пьесы'],
 'Инфант испанского короля Филиппа II влюблён в собственную мачеху и мечтает о свободе для угнетённых испанцами Нидерландов, вступая в неизбежный конфликт с деспотичным отцом. Историческая драма Шиллера о свободе, власти и невозможности примирить личное счастье с политическим идеализмом.'),
('Разбойники', 'Фридрих Шиллер', 1781, 192, ARRAY['Драма', 'Пьесы', 'Криминальная проза'],
 'Обманутый коварным братом и лишённый отцовского наследства юноша возглавляет шайку благородных разбойников, мстящих продажному обществу, — пока сам не осознаёт, что встал на путь, не менее кровавый, чем тот, против которого восстал. Дебютная пьеса молодого Шиллера потрясла современников своей бунтарской энергией.'),
('Коварство и любовь', 'Фридрих Шиллер', 1784, 160, ARRAY['Драма', 'Любовный роман', 'Пьесы'],
 'Сын придворного министра влюбляется в дочь бедного музыканта, а придворные интриги отца оборачиваются для влюблённых трагедией, которую не могла предотвратить никакая искренность чувств. Одна из самых известных мещанских трагедий немецкой драматургии.'),
('Мария Стюарт', 'Фридрих Шиллер', 1800, 192, ARRAY['Драма', 'Исторический роман', 'Пьесы'],
 'Заключённая в английскую тюрьму шотландская королева Мария Стюарт ожидает решения своей участи от соперницы и кузины Елизаветы I, пока придворные обеих сторон плетут интриги вокруг их единственной личной встречи. Историческая трагедия о противостоянии двух великих королев.'),
('Минна фон Барнхельм', 'Готхольд Эфраим Лессинг', 1767, 144, ARRAY['Драма', 'Юмор', 'Любовный роман', 'Пьесы'],
 'Прусский офицер, несправедливо обвинённый и лишившийся состояния после войны, из гордости отказывается от брака с богатой невестой, пока та сама не находит способ обойти его упрямство. Одна из первых немецких комедий нравов, до сих пор остающаяся в репертуаре немецких театров.'),
('Эмилия Галотти', 'Готхольд Эфраим Лессинг', 1772, 112, ARRAY['Драма', 'Пьесы'],
 'Добродетельная девушка становится объектом похоти местного принца накануне собственной свадьбы, а отец, не видя иного способа защитить её честь, идёт на крайние меры. Мещанская трагедия Лессинга, обличающая произвол и безнравственность аристократии.'),
('Натан Мудрый', 'Готхольд Эфраим Лессинг', 1779, 176, ARRAY['Драма', 'Философия', 'Пьесы'],
 'Мудрый еврейский купец во времена Крестовых походов рассказывает притчу о трёх кольцах, чтобы примирить представителей иудаизма, христианства и ислама и доказать равную ценность всех религий. Одна из первых европейских пьес, открыто проповедующих религиозную терпимость.'),
('Слуга двух господ', 'Карло Гольдони', 1746, 160, ARRAY['Драма', 'Юмор', 'Пьесы'],
 'Находчивый слуга Труффальдино устраивается работать сразу на двух хозяев одновременно, стараясь, чтобы ни один из них не узнал о существовании другого, — и, конечно же, запутывается в собственной хитрости. Одна из самых весёлых комедий итальянского театра, выросшая из традиций комедии дель арте.'),
('Мещанин во дворянстве', 'Жан-Батист Мольер', 1670, 144, ARRAY['Драма', 'Сатира', 'Юмор', 'Пьесы'],
 'Разбогатевший торговец мечтает во что бы то ни стало стать похожим на дворянина и нанимает учителей музыки, танцев и философии, становясь при этом лёгкой добычей для аферистов всех мастей. Одна из самых смешных комедий Мольера о тщеславии и социальном снобизме.'),
('Тартюф', 'Жан-Батист Мольер', 1664, 128, ARRAY['Драма', 'Сатира', 'Пьесы'],
 'Лицемерный святоша Тартюф втирается в доверие к наивному главе семейства и чуть было не лишает его и состояния, и чести собственной жены. Комедия Мольера о религиозном лицемерии была запрещена церковью сразу после первой постановки.'),
('Мизантроп', 'Жан-Батист Мольер', 1666, 128, ARRAY['Драма', 'Сатира', 'Пьесы'],
 'Альсест, ненавидящий светское лицемерие и фальшь парижского общества, влюблён в кокетливую и насквозь светскую даму, что ставит его перед невозможным выбором между принципами и чувствами. Одна из самых философски глубоких комедий Мольера о конфликте искренности и социальных условностей.'),
('Скупой', 'Жан-Батист Мольер', 1668, 128, ARRAY['Драма', 'Сатира', 'Юмор', 'Пьесы'],
 'Богатый, но патологически скупой Гарпагон мечтает одновременно выгодно женить своих детей и жениться самому, при этом не потратив ни одного лишнего су. Одна из самых известных комедий Мольера о разрушительной власти алчности над человеческой душой.'),
('Дон Жуан, или Каменный гость', 'Жан-Батист Мольер', 1665, 144, ARRAY['Драма', 'Сатира', 'Мистика', 'Пьесы'],
 'Легендарный соблазнитель дон Жуан насмехается над моралью, религией и браком, пока не получает возмездие от ожившей каменной статуи убитого им командора. Версия Мольера придаёт классическому испанскому сюжету острую философскую и религиозную полемику.'),
('Женитьба Фигаро', 'Пьер Бомарше', 1784, 192, ARRAY['Драма', 'Сатира', 'Юмор', 'Пьесы'],
 'Находчивый слуга Фигаро пытается жениться на горничной Сюзанне, расстраивая план собственного графа воспользоваться правом первой ночи. Дерзкая комедия, высмеивающая аристократические привилегии накануне Французской революции, легла в основу знаменитой оперы Моцарта.'),
('Двенадцатая ночь', 'Уильям Шекспир', 1602, 160, ARRAY['Драма', 'Юмор', 'Пьесы', 'Любовный роман'],
 'Виола, потерпевшая кораблекрушение и переодетая в мужское платье, поступает на службу к герцогу Орсино и невольно становится участницей запутанного любовного четырёхугольника. Одна из самых весёлых и изящных комедий Шекспира о любви и спутанных личностях.'),
('Как вам это понравится', 'Уильям Шекспир', 1599, 160, ARRAY['Драма', 'Юмор', 'Пьесы', 'Любовный роман'],
 'Изгнанная из дворца Розалинда скрывается в Арденнском лесу под видом юноши и наблюдает, как её возлюбленный Орландо развешивает по деревьям неуклюжие любовные стихи в её честь. Пасторальная комедия Шекспира о любви, переодеваниях и жизни на лоне природы.'),
('Много шума из ничего', 'Уильям Шекспир', 1599, 160, ARRAY['Драма', 'Юмор', 'Пьесы', 'Любовный роман'],
 'Остроумцы Беатриче и Бенедикт клянутся никогда не вступать в брак, но друзья устраивают заговор, чтобы влюбить их друг в друга, пока параллельно разворачивается куда более мрачная интрига с ложным обвинением невесты в измене. Одна из самых остроумных комедий Шекспира о войне полов.'),
('Венецианский купец', 'Уильям Шекспир', 1596, 160, ARRAY['Драма', 'Пьесы', 'Сатира'],
 'Купец Антонио занимает деньги у ростовщика Шейлока под условием фунта собственной плоти в случае просрочки, а его друг тем временем добивается руки богатой наследницы Порции. Одна из самых спорных пьес Шекспира, сочетающая комедию с острой драмой о мести и милосердии.'),
('Сон в летнюю ночь', 'Уильям Шекспир', 1596, 128, ARRAY['Драма', 'Фэнтези', 'Юмор', 'Пьесы'],
 'В волшебном лесу близ Афин феи, влюблённые пары и труппа ремесленников-актёров путаются в чарах эльфа Пака, превращающего простое недоразумение в ночь абсолютного безумия. Одна из самых сказочных и празднично-ярких комедий Шекспира.'),
('Юлий Цезарь', 'Уильям Шекспир', 1599, 160, ARRAY['Драма', 'Исторический роман', 'Трагедия', 'Пьесы'],
 'Группа римских сенаторов во главе с Брутом убивает Юлия Цезаря ради спасения республики от тирании — но смерть диктатора лишь развязывает ещё более кровавую гражданскую войну. Политическая трагедия Шекспира о цене идеализма и опасности политического насилия.'),
('Буря', 'Уильям Шекспир', 1611, 128, ARRAY['Драма', 'Фэнтези', 'Пьесы'],
 'Свергнутый герцог-волшебник Просперо, заброшенный штормом на уединённый остров вместе с дочерью, устраивает кораблекрушение своим обидчикам, чтобы наконец вершить над ними правосудие. Последняя пьеса, написанная Шекспиром в одиночку, о прощении и отречении от власти.'),
('Генрих IV', 'Уильям Шекспир', 1597, 192, ARRAY['Драма', 'Исторический роман', 'Пьесы'],
 'Принц Хэл проводит юность в тавернах в компании толстяка-гуляки Фальстафа, пока отец-король сражается с мятежниками, — но взросление заставляет наследника выбрать между дружбой и короной. Одна из самых человечных исторических хроник Шекспира, подарившая литературе образ Фальстафа.'),
('Ричард III', 'Уильям Шекспир', 1593, 192, ARRAY['Драма', 'Исторический роман', 'Трагедия', 'Пьесы'],
 'Коварный и уродливый герцог Глостер методично устраняет всех, кто стоит между ним и английским престолом, обращаясь к зрителю с циничными монологами о собственных злодеяниях. Одна из самых ярких галерей злодеев в истории драматургии.'),
('Снежная страна', 'Ясунари Кавабата', 1948, 192, ARRAY['Классика', 'Любовный роман', 'Психологическая проза'],
 'Состоятельный токиец заводит отношения с гейшей в отдалённом горячем источнике на заснеженном севере Японии, зная заранее, что эта связь обречена остаться лишь мимолётным эпизодом. Лирический роман Кавабаты, принёсший ему Нобелевскую премию, построен на недосказанности и тонких деталях.'),
('Тысячекрылый журавль', 'Ясунари Кавабата', 1952, 160, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Молодой человек, запутавшийся в отношениях с любовницей покойного отца и её дочерью, пытается разобраться в собственных чувствах сквозь ритуал японской чайной церемонии. Один из самых тонких психологических романов Кавабаты о вине, памяти и красоте.'),
('Золотой храм', 'Юкио Мисима', 1956, 288, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Заикающийся и одержимый красотой монах-послушник, одновременно восхищённый и мучимый совершенством древнего храма, в итоге решает его уничтожить. Роман, основанный на реальном поджоге знаменитого киотского храма, исследует природу одержимости прекрасным.'),
('Исповедь маски', 'Юкио Мисима', 1949, 256, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Молодой японец с раннего детства осознаёт, что его истинные влечения не соответствуют ожиданиям общества, и всю жизнь учится носить маску нормальности. Полуавтобиографический дебютный роман Мисимы о скрытой идентичности и саморазрушительном самоконтроле.'),
('Ваш покорный слуга кот', 'Нацумэ Сосэки', 1905, 400, ARRAY['Сатира', 'Юмор', 'Классика'],
 'Безымянный домашний кот с высокомерной иронией наблюдает за нелепыми привычками и мелочными заботами японской интеллигенции эпохи Мэйдзи, в доме которой он поселился. Сатирический роман, принёсший Сосэки известность как одному из главных писателей современной Японии.'),
('Ворота', 'Нацумэ Сосэки', 1910, 240, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Тихая супружеская пара живёт в стороне от общества, отягощённая давней виной за обстоятельства, при которых когда-то поженились, а муж в поисках покоя отправляется в буддийский монастырь, так и не находя за его воротами настоящего умиротворения. Один из самых меланхоличных романов Сосэки о невозможности убежать от собственного прошлого.'),
('Расёмон и другие рассказы', 'Рюноскэ Акутагава', 1915, 224, ARRAY['Классика', 'Психологическая проза', 'Мистика'],
 'Сборник коротких новелл исследует относительность истины и тёмные стороны человеческой натуры через истории вроде спора нескольких свидетелей одного и того же убийства в чаще. Рассказы Акутагавы легли в основу знаменитого фильма Акиры Куросавы «Расёмон».'),
('Барон на дереве', 'Итало Кальвино', 1957, 256, ARRAY['Сказка', 'Философия', 'Приключения', 'Сатира'],
 'Юный итальянский аристократ XVIII века в приступе детского упрямства забирается на дерево и клянётся никогда больше не спускаться на землю — и действительно проводит там всю оставшуюся жизнь. Философская притча Кальвино о независимости и жизни по собственным правилам.'),
('Незримые города', 'Итало Кальвино', 1972, 192, ARRAY['Философия', 'Фантастика', 'Поэзия'],
 'Путешественник Марко Поло рассказывает императору Хубилай-хану о десятках фантастических городов, каждый из которых на самом деле является гранью одного и того же города — Венеции. Поэтичная и фрагментарная книга-калейдоскоп о природе памяти, желания и воображения.'),
('Если однажды зимней ночью путник', 'Итало Кальвино', 1979, 288, ARRAY['Постмодернизм', 'Философия', 'Сатира'],
 'Читатель, купивший новый роман, обнаруживает дефектный экземпляр и отправляется на поиски правильной копии, раз за разом натыкаясь на начало совсем другой книги. Постмодернистский роман-лабиринт о самом процессе чтения, обращённый ко второму лицу.'),
('Равнодушные', 'Альберто Моравиа', 1929, 320, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Обедневшая буржуазная семья в Риме погрязла во взаимном равнодушии, лжи и мелочных компромиссах с совестью, не находя сил ни на подлинное чувство, ни на открытый бунт. Дебютный роман Моравиа, написанный в двадцать один год, стал одним из первых образцов итальянского экзистенциализма в прозе.'),
('История', 'Эльза Моранте', 1974, 736, ARRAY['Исторический роман', 'Военная проза', 'Драма'],
 'Полуеврейская школьная учительница и её незаконнорождённый сын пытаются выжить в оккупированном Риме времён Второй мировой войны среди бомбёжек, голода и постоянной угрозы депортации. Один из самых масштабных итальянских романов о войне глазами простых людей, оставшихся на обочине большой истории.'),
('История нового имени', 'Элена Ферранте', 2012, 480, ARRAY['Драма', 'Семейная сага', 'Психологическая проза'],
 'Лила выходит замуж совсем юной и пытается вырваться из нищеты квартала через удачный брак, пока Элена продолжает учиться и постепенно отдаляется от подруги детства. Второй роман «неаполитанского квартета» продолжает историю соперничества и преданности длиной в жизнь.'),
('Те, кто уходит, и те, кто остаётся', 'Элена Ферранте', 2013, 464, ARRAY['Драма', 'Семейная сага', 'Политическая проза'],
 'Элена уезжает из Неаполя учиться и постепенно входит в интеллектуальную среду, пока Лила остаётся в родном квартале и ввязывается в рабочее движение на фабрике. Третий роман квартета исследует, как по-разному складываются судьбы двух подруг, выбравших разные пути.'),
('История о пропавшем ребёнке', 'Элена Ферранте', 2014, 528, ARRAY['Драма', 'Семейная сага', 'Психологическая проза'],
 'Уже взрослые Элена и Лила возвращаются в родной неаполитанский квартал, где застарелые обиды, материнство и личная трагедия подводят итог их полувековой дружбе-соперничеству. Заключительный роман «неаполитанского квартета» завершает одну из самых значимых литературных саг XXI века.'),
('Сон в красном тереме', 'Цао Сюэцинь', 1791, 800, ARRAY['Классика', 'Семейная сага', 'Любовный роман'],
 'Упадок богатого аристократического клана прослеживается через судьбу юноши Цзя Баоюя, разрывающегося между несколькими кузинами и собственным нежеланием взрослеть в мире, обречённом на крушение. Один из четырёх классических романов китайской литературы и вершина её психологической прозы.'),
('Речные заводи', 'Ши Найань', 1589, 800, ARRAY['Классика', 'Приключения', 'Военная проза'],
 'Сто восемь благородных разбойников, изгнанных продажными чиновниками из общества, собираются в неприступных болотах горы Ляншань и создают собственное братство справедливости. Один из четырёх классических романов китайской литературы о народных героях, восставших против коррумпированной власти.'),
('Путешествие на Запад', 'У Чэнъэнь', 1592, 800, ARRAY['Фэнтези', 'Приключения', 'Мистика', 'Классика'],
 'Буддийский монах в сопровождении царя обезьян Сунь Укуна, свиньи-оборотня Чжу Бацзе и других спутников отправляется в опасное паломничество в Индию за священными текстами. Один из четырёх классических романов китайской литературы, подаривший миру одного из самых любимых трикстеров в восточной мифологии.'),
('Ночь нежна', 'Фрэнсис Скотт Фицджеральд', 1934, 352, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Блестящий молодой психиатр женится на богатой и психически нестабильной пациентке, а годы спустя на французской Ривьере их брак медленно, но неотвратимо разрушается под тяжестью денег, зависти и утраченных иллюзий. Самый личный и автобиографичный роман Фицджеральда о крушении американской мечты изнутри.'),
('По эту сторону рая', 'Фрэнсис Скотт Фицджеральд', 1920, 288, ARRAY['Классика', 'Драма', 'Любовный роман'],
 'Амбициозный студент Принстона Эмори Блейн проходит через войну, несколько романов и разочарование в собственном поколении, пытаясь найти смысл в послевоенном мире, лишённом прежних ориентиров. Дебютный роман мгновенно сделал двадцатитрёхлетнего Фицджеральда голосом «потерянного поколения».'),
('Иметь и не иметь', 'Эрнест Хемингуэй', 1937, 256, ARRAY['Классика', 'Приключения', 'Криминальная проза'],
 'Владелец рыболовецкой лодки на Кубе времён Великой депрессии постепенно скатывается от законного чартера к контрабанде, пытаясь прокормить семью любой ценой. Единственный роман Хемингуэя, действие которого разворачивается в Америке, о выживании во времена экономического отчаяния.'),
('Острова в океане', 'Эрнест Хемингуэй', 1970, 480, ARRAY['Классика', 'Драма', 'Военная проза'],
 'Художник, живущий на Кубе и постепенно теряющий связь с собственными сыновьями и прошлым, в финале вступает в охоту за немецкой подводной лодкой во время Второй мировой войны. Неоконченный роман, опубликованный посмертно, — один из самых личных и меланхоличных текстов Хемингуэя.'),
('Уолден, или Жизнь в лесу', 'Генри Дэвид Торо', 1854, 352, ARRAY['Нон-фикшн', 'Философия', 'Природа'],
 'Автор описывает два года, проведённые в одиночестве в хижине на берегу пруда Уолден, где он сознательно упростил жизнь до самого необходимого, чтобы разобраться в подлинных, а не навязанных обществом ценностях. Одна из основополагающих книг американского трансцендентализма и экологической мысли.'),
('Билли Бадд', 'Герман Мелвилл', 1924, 128, ARRAY['Классика', 'Военная проза', 'Драма'],
 'Простодушный и всеми любимый молодой матрос по злому навету оказывается обвинён офицером во вражеском заговоре на борту военного корабля — и в порыве гнева убивает обвинителя, после чего капитан вынужден выбирать между буквой закона и собственной совестью. Последнее произведение Мелвилла, опубликованное лишь спустя треть века после его смерти.'),
('Жизнь на Миссисипи', 'Марк Твен', 1883, 400, ARRAY['Нон-фикшн', 'Биография', 'Юмор', 'Приключения'],
 'Марк Твен вспоминает годы, проведённые лоцманом на пароходах по реке Миссисипи, прежде чем стать писателем, перемежая личные воспоминания с историей и байками речной жизни американского Юга. Полудокументальная книга, давшая писателю и его псевдоним.'),
('Янки из Коннектикута при дворе короля Артура', 'Марк Твен', 1889, 384, ARRAY['Научная фантастика', 'Сатира', 'Приключения', 'Юмор'],
 'Инженер из XIX века после удара по голове переносится в средневековую Англию времён короля Артура и пытается модернизировать рыцарское общество с помощью технологий и здравого смысла. Один из первых романов о путешествии во времени, одновременно сатира на феодализм и на наивную веру в технический прогресс.'),
('Доктор Фаустус', 'Томас Манн', 1947, 528, ARRAY['Классика', 'Философия', 'Психологическая проза'],
 'Биография вымышленного немецкого композитора, заключившего сделку с дьяволом ради гениальности, рассказанная другом детства на фоне краха Германии во Второй мировой войне. Поздний и самый мрачный роман Манна переосмысляет легенду о Фаусте как метафору национальной катастрофы.'),
('Смерть в Венеции', 'Томас Манн', 1912, 96, ARRAY['Классика', 'Психологическая проза', 'Философия'],
 'Пожилой респектабельный писатель, отдыхающий в охваченной эпидемией холеры Венеции, оказывается одержим созерцанием красоты юного польского мальчика, что постепенно разрушает всю прежнюю дисциплину его жизни. Одна из самых известных повестей о красоте, одержимости и разрушении.'),
('Письмо к отцу', 'Франц Кафка', 1919, 64, ARRAY['Нон-фикшн', 'Биография', 'Психологическая проза'],
 'Неотправленное письмо, в котором писатель пытается объяснить отцу, как его авторитарность и холодность искалечили всю его последующую жизнь и творчество. Один из самых откровенных автобиографических текстов Кафки, многое объясняющий в его художественной прозе.'),
('Бильярд в половине десятого', 'Генрих Бёлль', 1959, 288, ARRAY['Классика', 'Психологическая проза', 'Исторический роман'],
 'Три поколения семьи немецких архитекторов встречаются в день юбилея, и сквозь их воспоминания постепенно проступает история страны от кайзеровской Германии через нацизм к послевоенному благополучию. Один из ключевых романов о немецкой коллективной памяти и вине.'),
('Глазами клоуна', 'Генрих Бёлль', 1963, 288, ARRAY['Классика', 'Драма', 'Сатира'],
 'Профессиональный клоун, брошенный возлюбленной, уходящей в монастырь, спивается и обзванивает старых знакомых в поисках денег и сочувствия, попутно едко высмеивая лицемерие послевоенного католического общества ФРГ. Один из самых известных романов Бёлля о совести и приспособленчестве.'),
('Чтец', 'Бернхард Шлинк', 1995, 208, ARRAY['Драма', 'Исторический роман', 'Психологическая проза'],
 'Подросток в послевоенной Германии заводит роман со значительно старшей женщиной, а годы спустя, уже будучи студентом юридического факультета, узнаёт о её темном нацистском прошлом на судебном процессе. Роман о вине поколений и невозможности простого морального суждения о сложном прошлом.'),
('Семья Паскуаля Дуарте', 'Камило Хосе Села', 1942, 192, ARRAY['Классика', 'Психологическая проза', 'Криминальная проза'],
 'Осуждённый на казнь крестьянин пишет исповедь о жестоком детстве, беспросветной нищете и череде убийств, к которым его привела собственная ярость. Жёсткий роман будущего нобелевского лауреата считается одним из первых образцов испанского «тремендизма» — литературы крайнего натурализма.'),
('Станция одиннадцать', 'Эмили Сент-Джон Мандел', 2014, 384, ARRAY['Научная фантастика', 'Драма', 'Приключения'],
 'После стремительной пандемии, уничтожившей почти всё человечество, бродячая труппа актёров и музыкантов странствует по опустевшим землям Великих озёр, играя Шекспира для уцелевших поселений. Элегичный постапокалиптический роман о том, что именно искусство делает выживание осмысленным.'),
('Не отпускай меня', 'Кадзуо Исигуро', 2005, 352, ARRAY['Научная фантастика', 'Драма', 'Психологическая проза'],
 'Воспитанники элитного английского интерната постепенно узнают истинное предназначение, для которого их растили, — быть донорами органов для остального общества. Пронзительный антиутопический роман о смирении, дружбе и короткой жизни, прожитой без права на бунт.'),
('Остаток дня', 'Кадзуо Исигуро', 1989, 256, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Пожилой английский дворецкий отправляется в короткое путешествие по стране и, перебирая воспоминания о десятилетиях безупречной службы, впервые осознаёт, сколько личного счастья он принёс в жертву долгу и профессиональной сдержанности. Роман, принёсший Исигуро Букеровскую премию, — один из самых тонких портретов подавленных чувств в литературе.'),
('Погребённый великан', 'Кадзуо Исигуро', 2015, 352, ARRAY['Фэнтези', 'Драма', 'Мистика'],
 'Пожилая британская пара в легендарной Англии после ухода короля Артура отправляется на поиски сына сквозь землю, окутанную волшебным туманом забвения, стирающим из памяти людей и старые обиды, и старую любовь. Притча Исигуро о памяти, прощении и цене забытых преступлений.'),
('Клара и Солнце', 'Кадзуо Исигуро', 2021, 320, ARRAY['Научная фантастика', 'Драма', 'Философия'],
 'Робот-компаньон по имени Клара, созданная для компании больному ребёнку, с наивной преданностью наблюдает за человеческим миром и молится Солнцу о выздоровлении своей хозяйки. Философский роман о любви, вере и границах искусственного сознания.'),
('Человек, который принял жену за шляпу', 'Оливер Сакс', 1985, 288, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биография', 'Психология'],
 'Невролог описывает серию клинических случаев пациентов с необычными неврологическими расстройствами — от человека, принимающего части тела жены за шляпу, до художника, навсегда потерявшего цветовое зрение. Одна из самых человечных и увлекательных книг о работе и поломках человеческого мозга.'),
('Искусство любить', 'Эрих Фромм', 1956, 160, ARRAY['Нон-фикшн', 'Философия', 'Психология'],
 'Психоаналитик утверждает, что любовь — это не случайное чувство, а навык, требующий дисциплины, терпения и зрелости, который можно и нужно развивать, как любое другое искусство. Один из самых известных философско-психологических бестселлеров XX века о природе человеческой близости.'),
('Бегство от свободы', 'Эрих Фромм', 1941, 320, ARRAY['Нон-фикшн', 'Философия', 'Психология', 'Политическая проза'],
 'Книга исследует, почему свобода, завоёванная современным человеком, парадоксальным образом вызывает у него тревогу и толкает к добровольному подчинению авторитарным режимам. Один из первых психологических анализов природы тоталитаризма, написанный накануне и во время Второй мировой войны.'),
('Истоки тоталитаризма', 'Ханна Арендт', 1951, 576, ARRAY['Нон-фикшн', 'Философия', 'История', 'Политическая проза'],
 'Философ прослеживает исторические корни нацизма и сталинизма через антисемитизм, империализм и распад традиционных классовых структур, приведший к появлению атомизированных масс, восприимчивых к тоталитарной пропаганде. Одна из самых фундаментальных работ политической философии XX века.'),
('Эйхман в Иерусалиме. Банальность зла', 'Ханна Арендт', 1963, 336, ARRAY['Нон-фикшн', 'История', 'Философия'],
 'Репортаж с суда над нацистским чиновником Адольфом Эйхманом приводит философа к выводу, что чудовищные преступления часто совершаются не монстрами, а обычными, скучными бюрократами, бездумно исполняющими приказы. Книга ввела в обиход понятие «банальность зла», ставшее одним из ключевых терминов философии XX века.'),
('Книга джунглей', 'Редьярд Киплинг', 1894, 256, ARRAY['Сказка', 'Детская литература', 'Приключения', 'Классика'],
 'Человеческий детёныш Маугли вырастает среди волчьей стаи в индийских джунглях под присмотром медведя Балу и пантеры Багиры, училась законам джунглей и противостоя тигру-людоеду Шер-Хану. Сборник рассказов о воспитании вне человеческого общества стал одной из самых известных детских книг в истории.'),
('Ким', 'Редьярд Киплинг', 1901, 352, ARRAY['Приключения', 'Классика', 'Исторический роман'],
 'Ирландский сирота, выросший на улицах колониальной Индии, становится участником тайной разведывательной игры между Британской и Российской империями, попутно сопровождая старого тибетского ламу в его духовных странствиях. Один из самых известных романов о «Большой игре» и колониальной Индии.'),
('Женщина в песках', 'Кобо Абэ', 1962, 256, ARRAY['Классика', 'Философия', 'Психологическая проза'],
 'Энтомолог-любитель, застрявший на ночь в деревне среди песчаных дюн, обнаруживает, что местные жители заперли его в яме вместе с местной женщиной, откуда выбраться без посторонней помощи невозможно. Философская притча об абсурде, свободе и неожиданном смысле, который можно найти даже в заточении.'),
('Благоволительницы', 'Джонатан Литтелл', 2006, 928, ARRAY['Исторический роман', 'Военная проза', 'Психологическая проза'],
 'Бывший офицер СС вспоминает собственное участие в массовых убийствах на Восточном фронте, пытаясь объяснить читателю — и самому себе, — как обычный образованный человек становится соучастником геноцида. Один из самых мрачных и спорных романов о Холокосте, рассказанных от лица палача.'),
('Угрюм-река', 'Вячеслав Шишков', 1933, 896, ARRAY['Исторический роман', 'Драма', 'Семейная сага'],
 'Три поколения сибирской купеческой семьи Громовых строят состояние на золотых приисках, эксплуатации и преступлениях, пока груз накопленных грехов не начинает настигать уже внуков первых хозяев тайги. Масштабная сибирская сага о цене богатства и расплате за него.'),
('Третий человек', 'Грэм Грин', 1949, 160, ARRAY['Детектив', 'Триллер', 'Драма'],
 'Американский писатель приезжает в послевоенную оккупированную Вену на похороны друга и начинает подозревать, что его смерть была не случайной, а сам покойный, возможно, жив и причастен к мрачным делам чёрного рынка. Атмосферный нуар-триллер, положенный в основу одноимённого классического фильма.'),
('Тихий американец', 'Грэм Грин', 1955, 256, ARRAY['Драма', 'Политическая проза', 'Триллер'],
 'Циничный британский журналист во Вьетнаме времён французской колониальной войны наблюдает за наивным американским идеалистом, чьё желание принести демократию неизбежно оборачивается трагедией. Пророческий роман, предсказавший американское вмешательство во Вьетнаме за десятилетие до его начала.'),
('Власть и слава', 'Грэм Грин', 1940, 256, ARRAY['Драма', 'Религия', 'Триллер'],
 'Последний не отрёкшийся от сана католический священник скрывается от властей в охваченной антирелигиозными репрессиями мексиканской провинции, будучи при этом слабым, пьющим и далёким от святости человеком. Один из главных романов Грина о вере, грехе и благодати, которая настигает недостойных.'),
('Вампир', 'Джон Полидори', 1819, 64, ARRAY['Ужасы', 'Готика', 'Мистика', 'Классика'],
 'Молодой англичанин заводит дружбу с аристократичным и загадочным лордом Рутвеном, постепенно понимая, что его спутник — не человек, а кровожадный вампир. Повесть, написанная в ту же знаменитую грозовую ночь, что и «Франкенштейн», заложила канон аристократичного вампира задолго до «Дракулы».'),
('Кармилла', 'Джозеф Шеридан Ле Фаню', 1872, 96, ARRAY['Ужасы', 'Готика', 'Мистика'],
 'Одинокая девушка из уединённого замка заводит тесную дружбу с загадочной гостьей Кармиллой, которая оказывается вампиршей, преследующей её род уже не одно столетие. Повесть, опередившая «Дракулу» на четверть века, заложила основы жанра женской вампирской готики.'),
('Орля', 'Ги де Мопассан', 1887, 64, ARRAY['Ужасы', 'Мистика', 'Психологическая проза'],
 'Рассказчик ведёт дневник собственного постепенного схождения с ума — или, возможно, встречи с невидимым сверхъестественным существом, захватывающим контроль над его разумом и домом. Одна из самых тревожных повестей о безумии в истории литературы ужасов.'),
('Белоснежка', 'Братья Гримм', 1812, 32, ARRAY['Сказка', 'Детская литература', 'Классика'],
 'Прекрасную падчерицу королевы изгоняют из дома завистливой мачехой, желающей быть «всех милее», и девушка находит приют у семи гномов в лесной избушке. Одна из самых известных сказок братьев Гримм, собранная из немецкого фольклора.'),
('Золушка', 'Шарль Перро', 1697, 32, ARRAY['Сказка', 'Детская литература', 'Классика', 'Любовный роман'],
 'Добрая, но затюканная мачехой и сёстрами девушка попадает на королевский бал благодаря волшебству крёстной феи, а хрустальная туфелька, оставленная ею на ступенях дворца, становится ключом к счастливому финалу. Самая знаменитая версия сказки о Золушке, закрепившая канонические детали сюжета — тыкву-карету и полночный час.'),
('Красная Шапочка', 'Шарль Перро', 1697, 16, ARRAY['Сказка', 'Детская литература', 'Классика'],
 'Девочка в красной шапочке отправляется через лес к больной бабушке с пирожками и маслом, не подозревая, что хитрый волк уже опередил её и поджидает в бабушкином доме. Одна из самых известных и часто пересказываемых европейских сказок-предостережений.'),
('Кот в сапогах', 'Шарль Перро', 1697, 24, ARRAY['Сказка', 'Детская литература', 'Классика', 'Юмор'],
 'Смышлёный кот, доставшийся в наследство младшему из трёх братьев, хитростью добывает для бедного хозяина богатство, титул и руку принцессы. Одна из самых весёлых и находчивых сказок о плутовском уме, побеждающем бедность и обстоятельства.'),
('Спящая красавица', 'Шарль Перро', 1697, 24, ARRAY['Сказка', 'Детская литература', 'Классика', 'Любовный роман'],
 'Проклятая злой феей принцесса засыпает на сто лет вместе со всем своим замком, пока поцелуй принца не разрушает чары. Одна из самых известных европейских сказок о проклятии, пророчестве и неотвратимости судьбы.'),
('Фрикономика', 'Стивен Левитт и Стивен Дабнер', 2005, 320, ARRAY['Нон-фикшн', 'Научно-популярная', 'Экономика'],
 'Экономист применяет статистические методы к совершенно неожиданным темам — от жульничества учителей до причин падения преступности, — доказывая, что экономика может объяснить куда больше, чем принято думать. Один из самых увлекательных научпоп-бестселлеров о скрытой стороне повседневных явлений.'),
('Капитал в XXI веке', 'Тома Пикетти', 2013, 696, ARRAY['Нон-фикшн', 'Экономика', 'История'],
 'На основе масштабного анализа исторических данных о доходах и богатстве за три столетия экономист доказывает, что при капитализме неравенство имеет тенденцию только нарастать, если ему не противостоять сознательной политикой. Одна из самых влиятельных и обсуждаемых экономических книг XXI века.'),
('Происхождение человека', 'Чарльз Дарвин', 1871, 448, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биология'],
 'Продолжая идеи «Происхождения видов», Дарвин впервые прямо и подробно применяет теорию естественного и полового отбора к происхождению самого человека. Книга, распространившая эволюционную теорию на самый спорный и болезненный её объект.'),
('Удивительная жизнь', 'Стивен Джей Гулд', 1989, 352, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биология', 'История'],
 'На примере уникальных окаменелостей сланцев Бёрджес палеонтолог размышляет о роли случайности в эволюции и о том, насколько иначе могла бы выглядеть жизнь на Земле, если бы историю можно было прокрутить заново. Одна из самых влиятельных научно-популярных книг о природе эволюционного процесса.'),
('Ген. Очень личная история', 'Сиддхартха Мукерджи', 2016, 592, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биология', 'Биография'],
 'Онколог рассказывает историю открытия гена — от первых опытов Менделя с горохом до современной генной инженерии — переплетая её с историей наследственных психических заболеваний в собственной семье. Масштабная и личная научно-популярная книга о генетике, принёсшая автору Пулитцеровскую премию.'),
('Императрица всех болезней', 'Сиддхартха Мукерджи', 2010, 608, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биография', 'История'],
 'Онколог прослеживает историю рака — от первых древних описаний болезни до современной иммунотерапии — как своеобразную биографию одной из самых грозных болезней человечества. Книга, принёсшая автору Пулитцеровскую премию, остаётся одним из самых доступных и полных введений в онкологию для непрофессионалов.'),
('В Патагонии', 'Брюс Чатвин', 1977, 240, ARRAY['Нон-фикшн', 'Приключения', 'Природа'],
 'В поисках куска кожи доисторического ленивца, хранившегося в семье с детства, автор отправляется автостопом через всю Патагонию, попутно собирая истории эмигрантов, ковбоев и чудаков, осевших на краю света. Книга, фактически определившая жанр современной литературы о путешествиях.'),
('Маленькая принцесса', 'Фрэнсис Ходжсон Бёрнетт', 1905, 240, ARRAY['Детская литература', 'Классика', 'Драма'],
 'Богатая девочка из элитного пансиона внезапно теряет отца и состояние и из любимицы превращается в бесправную служанку — но не теряет внутреннего достоинства и воображения, продолжая вести себя как настоящая принцесса. Одна из самых трогательных детских повестей о достоинстве перед лицом нищеты.'),
('Поллианна', 'Элинор Портер', 1913, 256, ARRAY['Детская литература', 'Классика', 'Драма'],
 'Осиротевшая девочка переезжает к суровой тётке и заражает весь городок своей «игрой в радость» — умением находить повод для благодарности в самых тяжёлых обстоятельствах. Книга подарила английскому языку слово «поллианна» для неисправимого оптимиста.'),
('Хайди, или Волшебная долина', 'Иоганна Спири', 1881, 256, ARRAY['Детская литература', 'Классика', 'Природа'],
 'Маленькая сирота переезжает жить к нелюдимому деду-отшельнику в швейцарские Альпы и постепенно своей бесхитростной добротой растапливает его суровость, прежде чем её насильно увозят в город компаньонкой к больной девочке. Одна из самых любимых и издаваемых детских книг о горах, дружбе и тоске по дому.'),
('Остров Голубых дельфинов', 'Скотт О’Делл', 1960, 192, ARRAY['Детская литература', 'Приключения', 'Драма'],
 'Девочка из индейского племени остаётся совсем одна на тихоокеанском острове после того, как всё её племя эвакуируют, а корабль забывает забрать её вместе с потерявшимся братом. Основанная на реальной истории повесть о выживании и независимости в полном одиночестве.'),
('Хроники заводной птицы', 'Харуки Мураками', 1994, 768, ARRAY['Магический реализм', 'Мистика', 'Драма'],
 'Безработный токиец ищет пропавшую кошку, а затем и пропавшую жену, спускаясь по пути на дно пересохшего колодца и в самые тёмные уголки собственной психики и японской военной истории. Один из самых масштабных и загадочных романов Мураками, соединяющий бытовую реальность с глубоко мистическим подтекстом.'),
('Охота на овец', 'Харуки Мураками', 1982, 320, ARRAY['Магический реализм', 'Детектив', 'Мистика'],
 'Токийский рекламщик получает задание найти редкую овцу со звездой на спине, обладающую сверхъестественной властью над людьми, и отправляется на поиски на далёкий остров Хоккайдо. Ранний роман Мураками соединяет детективный сюжет с фирменной атмосферой необъяснимого.'),
('P.S. Я люблю тебя', 'Сесилия Ахерн', 2004, 400, ARRAY['Любовный роман', 'Драма', 'Юмор'],
 'Молодая вдова получает от покойного мужа серию писем, написанных им перед смертью, — каждое с новым маленьким заданием, которое должно помочь ей заново научиться жить и любить. Дебютный роман Ахерн, написанный в двадцать один год, стал мировым бестселлером о горе и надежде.'),
('Ешь, молись, люби', 'Элизабет Гилберт', 2006, 384, ARRAY['Нон-фикшн', 'Биография', 'Путешествия'],
 'После тяжёлого развода журналистка отправляется в годовое путешествие по Италии, Индии и Индонезии в поисках удовольствия, духовности и внутреннего равновесия. Один из самых популярных мемуаров о самопознании через путешествие, вдохновивший целое поколение читательниц.'),
('Старосветские помещики', 'Николай Гоголь', 1835, 48, ARRAY['Классика', 'Художественная проза', 'Юмор'],
 'Пожилая супружеская пара украинских помещиков проживает тихую, почти растительную жизнь, целиком состоящую из взаимной нежности и бесконечных трапез, — пока смерть одного из них не разрушает этот маленький уютный мир. Одна из самых трогательных и ироничных повестей цикла «Миргород».'),
('Портрет', 'Николай Гоголь', 1835, 96, ARRAY['Мистика', 'Классика', 'Философия'],
 'Бедный художник покупает на последние деньги таинственный портрет старика с пронзительными глазами, который приносит ему богатство, но губит его талант и душу. Мистическая повесть Гоголя о цене продажного искусства и дьявольском соблазне лёгкого успеха.'),
('Записки сумасшедшего', 'Николай Гоголь', 1835, 48, ARRAY['Психологическая проза', 'Сатира', 'Классика'],
 'Мелкий петербургский чиновник, униженный и не замеченный никем на службе, постепенно скатывается в безумие, вообразив себя испанским королём. Одна из самых пронзительных повестей о «маленьком человеке», доведённом до сумасшествия равнодушием общества.'),
('Нос', 'Николай Гоголь', 1836, 48, ARRAY['Сатира', 'Мистика', 'Юмор', 'Классика'],
 'Петербургский чиновник однажды утром обнаруживает, что его собственный нос исчез с лица и разгуливает по городу в мундире, с чином значительно выше хозяйского. Абсурдистская сатирическая повесть Гоголя на чинопочитание и общественный статус.'),
('Житие протопопа Аввакума', 'Протопоп Аввакум', 1675, 160, ARRAY['Нон-фикшн', 'Биография', 'Религия', 'История'],
 'Лидер старообрядческого раскола описывает собственную жизнь, преследования за веру и многолетнюю ссылку в Сибирь ярким, почти разговорным языком, резко отличающимся от книжной традиции своего времени. Первая подробная автобиография в русской литературе и один из важнейших памятников допетровской словесности.'),
('Слепой музыкант', 'Владимир Короленко', 1886, 128, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Слепой от рождения мальчик из дворянской семьи постепенно открывает в себе редкий музыкальный талант, помогающий ему найти собственный путь восприятия мира, недоступного зрячим. Одна из самых светлых повестей русской классики о преодолении физического недуга через искусство.'),
('Муму', 'Иван Тургенев', 1852, 48, ARRAY['Классика', 'Драма', 'Социальная проза'],
 'Глухонемой крепостной дворник Герасим находит единственную привязанность в маленькой собачке Муму — пока капризная барыня не приказывает от неё избавиться. Одна из самых пронзительных и часто экранизируемых повестей о крепостном праве и немом отчаянии бесправного человека.'),
('Дворянское гнездо', 'Иван Тургенев', 1859, 192, ARRAY['Классика', 'Драма', 'Любовный роман'],
 'Разочаровавшийся в неудачном браке помещик Лаврецкий возвращается в родовое имение и влюбляется в тихую и глубоко верующую Лизу Калитину — но судьба и долг не оставляют их счастью ни единого шанса. Один из самых лиричных романов Тургенева о несбывшейся любви и тихом достоинстве жертвы.'),
('Рудин', 'Иван Тургенев', 1856, 160, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Блестящий оратор и идеалист Рудин покоряет провинциальное общество красноречием о высоких материях, но на поверку оказывается неспособен ни на одно по-настоящему решительное действие в собственной жизни. Первый роман Тургенева ввёл в русскую литературу тип «лишнего человека», красивого на словах и бессильного на деле.'),
('Накануне', 'Иван Тургенев', 1860, 192, ARRAY['Классика', 'Драма', 'Любовный роман', 'Политическая проза'],
 'Русская девушка влюбляется не в кого-то из вялых и рефлексирующих соотечественников, а в болгарского революционера, готового отдать жизнь за свободу своей родины. Роман Тургенева о поиске деятельного героя в русском обществе предвосхитил вопрос «Что делать?», ставший центральным для следующего поколения писателей.'),
('Записки охотника', 'Иван Тургенев', 1852, 480, ARRAY['Классика', 'Художественная проза', 'Социальная проза'],
 'Сборник очерков о жизни крепостных крестьян, увиденной глазами охотника-помещика, показал российскому обществу полноценных, умных и достойных людей там, где привыкли видеть лишь бесправную собственность. Книга, которую сам Александр II называл одной из причин отмены крепостного права.'),
('Детство', 'Лев Толстой', 1852, 160, ARRAY['Классика', 'Психологическая проза', 'Семейная сага'],
 'Десятилетний дворянский мальчик Николенька Иртеньев переживает первые уроки, первую смерть близкого человека и первое осознание сложности взрослого мира. Дебютная повесть молодого Толстого открывает автобиографическую трилогию о взрослении.'),
('Отрочество', 'Лев Толстой', 1854, 144, ARRAY['Классика', 'Психологическая проза', 'Семейная сага'],
 'Подросток Николенька переживает первые сомнения в авторитете взрослых, первую дружбу на равных и мучительную неуверенность переходного возраста. Вторая часть автобиографической трилогии Толстого о взрослении.'),
('Юность', 'Лев Толстой', 1857, 224, ARRAY['Классика', 'Психологическая проза', 'Семейная сага'],
 'Повзрослевший Николенька поступает в университет, переживает первую влюблённость и мучительно пытается нравственно самосовершенствоваться, то и дело срываясь в юношеское тщеславие и самообман. Заключительная часть трилогии Толстого о пути от детства к зрелости.'),
('Крейцерова соната', 'Лев Толстой', 1889, 112, ARRAY['Классика', 'Психологическая проза', 'Философия'],
 'Пассажир поезда исповедуется случайному попутчику в убийстве собственной жены из ревности, обрушиваясь попутно на институт брака, плотскую любовь и лицемерие семейной жизни в целом. Одна из самых мрачных и спорных поздних повестей Толстого, запрещённая цензурой сразу после публикации.'),
('Хаджи-Мурат', 'Лев Толстой', 1912, 160, ARRAY['Классика', 'Исторический роман', 'Военная проза'],
 'Легендарный кавказский горец Хаджи-Мурат переходит на сторону русских войск в войне против имама Шамиля, пытаясь спасти собственную семью, — но оказывается чужим и недоверенным по обе стороны фронта. Последняя крупная повесть Толстого, опубликованная посмертно, о цене войны и личном достоинстве перед лицом двух враждующих империй.'),
('Казаки', 'Лев Толстой', 1863, 192, ARRAY['Классика', 'Художественная проза', 'Военная проза'],
 'Разочарованный столичной жизнью молодой дворянин отправляется служить на Кавказ и оказывается покорён простой, близкой к природе жизнью казачьей станицы, разительно отличающейся от фальши света. Ранняя повесть Толстого о поиске подлинности вдали от цивилизации.'),
('Зов Ктулху', 'Говард Филлипс Лавкрафт', 1928, 64, ARRAY['Ужасы', 'Мистика', 'Научная фантастика'],
 'Расследуя бумаги покойного дяди, молодой человек по крупицам восстанавливает историю культа, поклоняющегося древнему космическому божеству Ктулху, спящему на дне океана в ожидании часа пробуждения. Рассказ, давший имя целой мифологии Лавкрафта о безразличных к человеку космических ужасах.'),
('Хребты безумия', 'Говард Филлипс Лавкрафт', 1936, 128, ARRAY['Ужасы', 'Научная фантастика', 'Мистика'],
 'Антарктическая экспедиция обнаруживает во льдах руины чудовищно древнего города, построенного расой, существовавшей на Земле задолго до человека, — и находит там нечто, что лучше было бы не находить. Одна из самых масштабных повестей мифологии Ктулху о ничтожности человека перед лицом глубокой древности космоса.'),
('Тень над Иннсмутом', 'Говард Филлипс Лавкрафт', 1936, 96, ARRAY['Ужасы', 'Мистика'],
 'Турист, оказавшийся проездом в обветшалом рыбацком городке Иннсмут, замечает странную, почти рыбью внешность местных жителей и постепенно узнаёт о тёмном договоре, который город заключил с морскими глубинами поколения назад. Одна из самых атмосферных повестей Лавкрафта о вырождении и наследственном проклятии.'),
('Данвичский кошмар', 'Говард Филлипс Лавкрафт', 1929, 64, ARRAY['Ужасы', 'Мистика'],
 'В глухой новоанглийской деревне рождается странный ребёнок, растущий с пугающей быстротой, — а учёные из соседнего университета слишком поздно понимают, какую опасность несёт его истинное происхождение. Одна из самых известных повестей о вторжении потустороннего зла в тихую сельскую Америку.'),
('Фирма', 'Джон Гришэм', 1991, 480, ARRAY['Триллер', 'Криминальная проза', 'Детектив'],
 'Молодой блестящий юрист получает заманчивое предложение от небольшой, но очень щедрой мемфисской фирмы — и слишком поздно понимает, что покинуть её можно только одним способом. Роман, сделавший Гришэма королём юридического триллера.'),
('Дело о пеликанах', 'Джон Гришэм', 1992, 448, ARRAY['Триллер', 'Детектив', 'Политическая проза'],
 'Студентка юридического факультета случайно пишет курсовую работу, в которой точно угадывает заказчика убийства двух судей Верховного суда, — и эта догадка делает её главной целью настоящих убийц. Один из самых динамичных юридических триллеров Гришэма.'),
('Время убивать', 'Джон Гришэм', 1989, 512, ARRAY['Триллер', 'Криминальная проза', 'Драма'],
 'Чернокожий отец мстит насильникам своей маленькой дочери прямо в здании суда, а молодой адвокат берётся его защищать в городе, расколотом по расовому признаку. Дебютный роман Гришэма, поднимающий вопросы расизма, мести и справедливости на американском Юге.'),
('День Шакала', 'Фредерик Форсайт', 1971, 448, ARRAY['Триллер', 'Детектив', 'Исторический роман'],
 'Безымянный профессиональный убийца по прозвищу Шакал нанят тайной организацией для устранения президента Франции де Голля, а полиция по крупицам улик пытается вычислить его личность прежде, чем он нанесёт удар. Технически безупречный триллер, ставший эталоном жанра политического убийства.'),
('Досье «Одесса»', 'Фредерик Форсайт', 1972, 352, ARRAY['Триллер', 'Детектив', 'Исторический роман'],
 'Немецкий журналист по дневнику умершего еврея выходит на след тайной организации бывших офицеров СС, годами укрывающих друг друга и готовящих новый виток нацистской угрозы. Один из самых известных триллеров о послевоенной охоте на нацистских преступников.'),
('Шпион, выйди вон!', 'Джон ле Карре', 1974, 384, ARRAY['Детектив', 'Триллер', 'Политическая проза'],
 'Отставной разведчик Джордж Смайли вызван обратно на службу, чтобы вычислить советского «крота», годами действующего в самом сердце британской разведки. Один из самых интеллектуальных и мрачных шпионских романов, построенный на кропотливом расследовании, а не на экшене.'),
('Идеальный шпион', 'Джон ле Карре', 1986, 480, ARRAY['Детектив', 'Триллер', 'Психологическая проза'],
 'Британский разведчик внезапно исчезает после похорон отца, а расследование его прошлого постепенно раскрывает, что всю жизнь он вёл двойную, если не тройную игру. Один из самых личных романов ле Карре, во многом основанный на отношениях автора с собственным отцом-авантюристом.'),
('Русский Дом', 'Джон ле Карре', 1989, 400, ARRAY['Детектив', 'Триллер', 'Любовный роман'],
 'Британский издатель, случайно получивший секретную советскую рукопись о состоянии ядерной программы СССР, оказывается втянут в шпионскую операцию на закате холодной войны. Один из первых крупных западных романов, действие которого разворачивается в перестроечной Москве.'),
('Бесплодная земля', 'Томас Стернз Элиот', 1922, 64, ARRAY['Поэзия', 'Классика', 'Философия'],
 'Фрагментарная поэма сплетает голоса, культурные и мифологические отсылки и мёртвые языки в единое полотно духовного опустошения послевоенной Европы. Одно из самых влиятельных и сложных поэтических произведений модернизма XX века.'),
('Полые люди', 'Томас Стернз Элиот', 1925, 32, ARRAY['Поэзия', 'Классика', 'Философия'],
 'Короткая поэма изображает голоса безжизненных, лишённых подлинной веры людей, бредущих к концу света «не с грохотом, а со всхлипом». Одно из самых цитируемых произведений Элиота о духовной пустоте современного человека.'),
('Нью-Гэмпшир', 'Роберт Фрост', 1923, 112, ARRAY['Поэзия', 'Классика', 'Природа'],
 'Сборник воспевает сельскую Новую Англию простым, разговорным языком, за внешней безыскусностью которого скрываются глубокие размышления о человеке, природе и одиночестве. Книга принесла Фросту первую из четырёх Пулитцеровских премий.'),
('Лирические баллады', 'Уильям Вордсворт и Сэмюэл Тейлор Кольридж', 1798, 224, ARRAY['Поэзия', 'Классика'],
 'Совместный сборник двух поэтов, написанный простым разговорным языком о природе и простых людях, считается манифестом, с которого официально начался английский романтизм в поэзии. Издание включает знаменитую балладу Кольриджа «Сказание о старом мореходе».'),
('Прометей освобождённый', 'Перси Биши Шелли', 1820, 160, ARRAY['Поэзия', 'Классика', 'Философия'],
 'Лирическая драма в стихах переосмысляет древний миф о Прометее как аллегорию освобождения человечества от тирании через любовь и внутреннее преображение, а не через месть. Одно из самых философски насыщенных произведений английского романтизма.'),
('Рассуждение о методе', 'Рене Декарт', 1637, 96, ARRAY['Нон-фикшн', 'Философия'],
 'Философ излагает метод систематического сомнения во всём, что можно подвергнуть сомнению, приходя в итоге к единственной несомненной истине — «я мыслю, следовательно, существую». Одна из основополагающих работ философии Нового времени и рационализма.'),
('Левиафан', 'Томас Гоббс', 1651, 544, ARRAY['Нон-фикшн', 'Философия', 'Политическая проза'],
 'Философ обосновывает необходимость сильной абсолютной государственной власти как единственной альтернативы «войне всех против всех», присущей естественному состоянию человека. Одно из самых влиятельных произведений политической философии Нового времени.'),
('Два трактата о правлении', 'Джон Локк', 1689, 320, ARRAY['Нон-фикшн', 'Философия', 'Политическая проза'],
 'Философ обосновывает естественные права человека на жизнь, свободу и собственность и право народа на восстание против тиранической власти, нарушающей общественный договор. Трактат заложил философские основы либеральной демократии и позднее вдохновил авторов американской Декларации независимости.'),
('Исследование о человеческом разумении', 'Дэвид Юм', 1748, 256, ARRAY['Нон-фикшн', 'Философия'],
 'Философ подвергает скептическому анализу природу человеческого познания, причинности и веры, утверждая, что многие наши убеждения основаны не на разуме, а на привычке. Одна из ключевых работ британского эмпиризма, оказавшая огромное влияние на последующую философию.'),
('Об общественном договоре', 'Жан-Жак Руссо', 1762, 224, ARRAY['Нон-фикшн', 'Философия', 'Политическая проза'],
 'Философ утверждает, что легитимная политическая власть может проистекать только из добровольного общественного договора свободных и равных граждан, выражающих общую волю. Один из самых влиятельных политических трактатов, вдохновивших Французскую революцию.'),
('Этика', 'Бенедикт Спиноза', 1677, 320, ARRAY['Нон-фикшн', 'Философия'],
 'Философский трактат, построенный по образцу геометрических доказательств Евклида, выводит учение о Боге, природе человека и пути к подлинной свободе и счастью через рациональное познание. Одно из самых строгих и систематических произведений западной философии.'),
('Феноменология духа', 'Георг Вильгельм Фридрих Гегель', 1807, 448, ARRAY['Нон-фикшн', 'Философия'],
 'Философ прослеживает развитие человеческого сознания от простейших чувственных восприятий до абсолютного знания через последовательность диалектических противоречий и их снятий. Одно из самых сложных и влиятельных произведений немецкой классической философии.'),
('Мир как воля и представление', 'Артур Шопенгауэр', 1818, 640, ARRAY['Нон-фикшн', 'Философия'],
 'Философ утверждает, что в основе всего сущего лежит слепая, иррациональная воля к жизни, порождающая бесконечное страдание, а единственное спасение от него — в искусстве, сострадании и аскезе. Одна из самых мрачных и влиятельных философских систем XIX века, повлиявшая на Ницше и Фрейда.'),
('Камень', 'Осип Мандельштам', 1913, 96, ARRAY['Поэзия', 'Классика'],
 'Дебютный сборник молодого поэта воспевает архитектуру, культуру и «тоску по мировой культуре» через предельно точный, почти осязаемый поэтический образ. Сборник, обозначивший Мандельштама как одного из ведущих поэтов акмеизма.'),
('Сестра моя — жизнь', 'Борис Пастернак', 1922, 128, ARRAY['Поэзия', 'Классика', 'Любовный роман'],
 'Сборник, написанный одним летом революционного 1917 года, передаёт восторженное, почти стихийное ощущение жизни, любви и природы через смелые и неожиданные образы. Книга, с которой началась слава Пастернака как одного из главных поэтов своего поколения.'),
('Пророк', 'Халиль Джебран', 1923, 128, ARRAY['Философия', 'Притча', 'Поэзия'],
 'Мудрец перед отплытием с чужбины на родину отвечает жителям города на вопросы о любви, браке, детях, труде и смерти серией поэтических притч. Одна из самых переводимых и издаваемых духовных книг XX века.'),
('Дети нашей улицы', 'Нагиб Махфуз', 1959, 480, ARRAY['Классика', 'Философия', 'Притча'],
 'Аллегорический роман прослеживает историю одной каирской улицы через поколения, чьи персонажи символически перекликаются с библейскими и кораническими пророками. Роман нобелевского лауреата был запрещён в нескольких странах за религиозную дерзость и едва не стоил автору жизни.'),
('Илон Маск', 'Уолтер Айзексон', 2023, 688, ARRAY['Нон-фикшн', 'Биография', 'Бизнес'],
 'Авторизованная биография одного из самых противоречивых предпринимателей современности написана на основе двух лет непосредственного наблюдения за его жизнью и работой в Tesla, SpaceX, X и других компаниях. Подробный и неоднозначный портрет гения, визионера и источника бесконечных скандалов.'),
('Сделано в Японии', 'Акио Морита', 1986, 352, ARRAY['Нон-фикшн', 'Биография', 'Бизнес'],
 'Основатель компании Sony рассказывает историю превращения послевоенной маленькой мастерской в одну из крупнейших технологических корпораций мира. Одна из первых и самых известных автобиографий японского бизнес-лидера, переведённых на Запад.'),
('Жизнь без границ', 'Ник Вуйчич', 2010, 208, ARRAY['Нон-фикшн', 'Биография', 'Психология'],
 'Родившийся без рук и ног австралиец рассказывает, как преодолел отчаяние юности и превратил собственное тело, которое он когда-то ненавидел, в источник вдохновения для миллионов людей по всему миру. Один из самых известных мотивационных мемуаров о принятии себя.'),
('Шахматная новелла', 'Стефан Цвейг', 1942, 96, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'На борту океанского лайнера скромный пассажир неожиданно обыгрывает чемпиона мира по шахматам, а его собственная история оказывается связана с месяцами одиночного заключения у нацистов, где шахматы стали единственным спасением от безумия. Последнее произведение Цвейга, законченное незадолго до самоубийства автора.'),
('Письмо незнакомки', 'Стефан Цвейг', 1922, 64, ARRAY['Классика', 'Психологическая проза', 'Любовный роман'],
 'Умирающая женщина пишет известному писателю прощальное письмо, впервые открывая всю правду о своей всепоглощающей и так и не замеченной им любви, длившейся целую жизнь. Одна из самых пронзительных новелл о безответной, но несокрушимой любви.'),
('Вчерашний мир', 'Стефан Цвейг', 1942, 480, ARRAY['Нон-фикшн', 'Биография', 'История'],
 'Писатель вспоминает блестящую довоенную Европу своей юности и прослеживает её постепенный распад через две мировые войны и приход нацизма. Одни из самых проникновенных мемуаров о гибели целой цивилизации, написанные незадолго до самоубийства автора в эмиграции.'),
('Нетерпение сердца', 'Стефан Цвейг', 1939, 352, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Молодой офицер из жалости ухаживает за парализованной дочерью богатого помещика, а та принимает сочувствие за настоящую любовь — с трагическими последствиями для них обоих. Единственный законченный роман Цвейга исследует разрушительную силу жалости, выдаваемой за чувство.'),
('Амок', 'Стефан Цвейг', 1922, 64, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Врач, добровольно сославший себя в тропическую глушь после скандала на родине, впадает в одержимость единственной европейской пациенткой, обратившейся к нему за помощью, — одержимость, которая приводит обоих к катастрофе. Психологическая новелла о внезапном приступе неконтролируемой страсти, давшая название малайскому понятию «амок».'),
('Виргинец', 'Оуэн Уистер', 1902, 384, ARRAY['Приключения', 'Классика', 'Любовный роман'],
 'Молчаливый и благородный ковбой с юга по прозвищу Виргинец добивается руки школьной учительницы с востока, попутно сталкиваясь с конокрадами и защищая собственную честь на дуэли. Роман, фактически заложивший все основные каноны классического американского вестерна.'),
('Нежность волков', 'Стеф Пенни', 2006, 480, ARRAY['Детектив', 'Исторический роман', 'Приключения'],
 'В канадской глуши XIX века женщина отправляется на поиски пропавшего сына, подозреваемого в убийстве местного зверолова, через заснеженную тайгу и индейские поселения. Атмосферный исторический детектив, принёсший автору престижную британскую литературную премию.'),
('Карты на столе', 'Агата Кристи', 1936, 288, ARRAY['Детектив', 'Классика'],
 'На ужине у эксцентричного коллекционера четверо гостей, каждый из которых подозревается в прошлом убийстве, садятся играть в бридж, а хозяин вечера оказывается заколот прямо посреди партии. Один из самых необычных романов Кристи, где убийцей может быть только один из четырёх игроков за столом.'),
('Зло под солнцем', 'Агата Кристи', 1941, 256, ARRAY['Детектив', 'Классика'],
 'На фешенебельном курорте находят задушенной красавицу-актрису, у которой, казалось, был мотив убить едва ли не каждый отдыхающий, — и Эркюль Пуаро распутывает клубок алиби и обманчивой внешности. Один из самых изящных детективов Агаты Кристи с курортной атмосферой.'),
('Свидетель обвинения', 'Агата Кристи', 1933, 64, ARRAY['Детектив', 'Триллер', 'Классика'],
 'Адвокат берётся защищать обвиняемого в убийстве состоятельной пожилой знакомой, а главным свидетелем обвинения неожиданно выступает собственная жена подсудимого. Короткая, но безупречно выстроенная история с одним из самых знаменитых финальных поворотов в творчестве Агаты Кристи.'),
('Отель «Бертрам»', 'Агата Кристи', 1965, 256, ARRAY['Детектив', 'Классика'],
 'Пожилая мисс Марпл приезжает отдохнуть в фешенебельный лондонский отель, хранящий атмосферу довоенной Англии, — и обнаруживает, что идиллический фасад скрывает хорошо организованную преступную схему. Один из поздних романов о мисс Марпл, полный ностальгии по уходящей эпохе.'),
('Скарамуш', 'Рафаэль Сабатини', 1921, 352, ARRAY['Приключения', 'Исторический роман', 'Драма'],
 'Молодой адвокат, чей друг убит аристократом на дуэли, вступает в революционную политику, а затем становится бродячим актёром и знаменитым фехтовальщиком, чтобы однажды отомстить убийце. Один из самых известных романов плаща и шпаги на фоне Французской революции.'),
('Одиссея капитана Блада', 'Рафаэль Сабатини', 1922, 320, ARRAY['Приключения', 'Исторический роман'],
 'Ирландский врач, несправедливо осуждённый на рабство в колониях за помощь раненому повстанцу, поднимает бунт и становится одним из самых удачливых пиратских капитанов Карибского моря. Классический приключенческий роман о благородном пирате, оправданном обстоятельствами, а не злой волей.'),
('Голод', 'Кнут Гамсун', 1890, 240, ARRAY['Классика', 'Психологическая проза'],
 'Безымянный молодой писатель бродит по улицам Осло, медленно умирая от голода и гордости, слишком упрямый, чтобы просить милостыню, и слишком безденежный, чтобы её не желать. Роман-исповедь, предвосхитивший модернистскую прозу потока сознания задолго до Джойса и Вулф.'),
('Пан', 'Кнут Гамсун', 1894, 192, ARRAY['Классика', 'Любовный роман', 'Природа'],
 'Отставной лейтенант проводит лето в охотничьей хижине на севере Норвегии, переживая мучительный роман с местной девушкой на фоне дикой северной природы. Один из самых лиричных романов Гамсуна о любви, свободе и невозможности удержать ускользающее счастье.'),
('Виктория', 'Кнут Гамсун', 1898, 160, ARRAY['Классика', 'Любовный роман', 'Драма'],
 'Сын мельника и дочь помещика любят друг друга с детства, но классовые различия раз за разом не дают их чувству осуществиться на протяжении всей жизни. Короткий и пронзительный роман Гамсуна о любви, которую разделяет не время, а сословная пропасть.'),
('Прислуга', 'Кэтрин Стокетт', 2009, 464, ARRAY['Драма', 'Исторический роман', 'Социальная проза'],
 'Молодая белая журналистка на американском Юге 1960-х тайно собирает истории чернокожих горничных о работе в домах их белых хозяек, рискуя безопасностью всех участниц проекта. Роман о расовой сегрегации и женской солидарности, рассказанный от нескольких лиц сразу.'),
('Поправки', 'Джонатан Франзен', 2001, 568, ARRAY['Драма', 'Семейная сага', 'Сатира'],
 'Пожилые родители из американского Среднего Запада пытаются в последний раз собрать на одно общее Рождество троих взрослых детей, каждый из которых несёт собственный груз разочарований и семейных травм. Роман, во многом определивший жанр большого американского семейного романа начала XXI века.'),
('Свобода', 'Джонатан Франзен', 2010, 640, ARRAY['Драма', 'Семейная сага', 'Психологическая проза'],
 'Благополучная на вид семья из миннесотского пригорода медленно распадается под грузом нереализованных амбиций, супружеской неверности и политических разногласий. Ещё один масштабный роман Франзена о свободе выбора, которая оборачивается не счастьем, а одиночеством.'),
('Квентин Дорвард', 'Вальтер Скотт', 1823, 416, ARRAY['Классика', 'Исторический роман', 'Приключения'],
 'Молодой шотландский стрелок поступает на службу к французскому королю Людовику XI и оказывается втянут в придворные интриги на фоне войны с бургундским герцогом. Один из самых популярных исторических романов Скотта о средневековой Франции.'),
('Роб Рой', 'Вальтер Скотт', 1817, 448, ARRAY['Классика', 'Исторический роман', 'Приключения'],
 'Молодой англичанин отправляется в горную Шотландию по торговым делам отца и оказывается втянут в якобитское восстание и дела легендарного горского разбойника Роб Роя. Один из самых динамичных исторических романов Вальтера Скотта о шотландском нагорье.'),
('Мифы', 'Стивен Фрай', 2017, 448, ARRAY['Мифология', 'Юмор', 'Классика'],
 'Актёр и писатель Стивен Фрай остроумно и с огромной любовью к материалу пересказывает древнегреческие мифы о сотворении мира и олимпийских богах современным, ироничным языком. Один из самых увлекательных и смешных пересказов греческой мифологии для взрослого читателя.'),
('Герои', 'Стивен Фрай', 2018, 448, ARRAY['Мифология', 'Юмор', 'Приключения'],
 'Продолжение «Мифов» переходит от богов к смертным героям древнегреческих легенд — Персею, Гераклу, Тесею и Беллерофонту — и их невероятным подвигам. Стивен Фрай вновь пересказывает классические сюжеты с фирменным остроумием и эрудицией.'),
('Великая теорема Ферма', 'Саймон Сингх', 1997, 320, ARRAY['Нон-фикшн', 'Научно-популярная', 'Математика'],
 'Книга рассказывает историю трёхвековых попыток доказать одну из самых знаменитых нерешённых задач математики и о математике Эндрю Уайлсе, посвятившем доказательству теоремы Ферма семь лет тайной работы. Один из самых увлекательных научпоп-бестселлеров о математике, написанных для неспециалистов.'),
('Под сенью девушек в цвету', 'Марсель Пруст', 1919, 480, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Рассказчик проводит лето на нормандском курорте, влюбляется поочерёдно в нескольких девушек из компании подруг и наблюдает закат художника Эльстира и писателя Берготта, некогда боготворимых им в детстве. Второй том эпопеи «В поисках утраченного времени» принёс Прусту Гонкуровскую премию.'),
('У Германтов', 'Марсель Пруст', 1920, 480, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Рассказчик проникает в аристократический салон герцогини Германтской, наблюдая изнутри снобизм, остроумие и пустоту высшего парижского света. Третий том эпопеи Пруста о неумолимом течении социального времени и крушении детских иллюзий.'),
('Содом и Гоморра', 'Марсель Пруст', 1921, 480, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Рассказчик постепенно осознаёт скрытую гомосексуальность барона де Шарлю и других персонажей парижского света, а его собственная ревнивая и мучительная любовь к Альбертине выходит на первый план повествования. Четвёртый том эпопеи Пруста об изнанке светских приличий.'),
('Пленница', 'Марсель Пруст', 1923, 480, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Рассказчик поселяет возлюбленную Альбертину у себя дома, пытаясь полностью контролировать её жизнь из болезненной ревности, — но чем крепче эта клетка, тем очевиднее, что подлинной близости она не приносит. Пятый том эпопеи Пруста о собственничестве, выдаваемом за любовь.'),
('Беглянка', 'Марсель Пруст', 1925, 320, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Альбертина неожиданно покидает рассказчика, и его прежняя мучительная ревность сменяется ещё более мучительным горем и попытками понять, что он на самом деле к ней чувствовал. Шестой том эпопеи Пруста о природе любви, которая осознаётся в полной мере лишь после утраты.'),
('Обретённое время', 'Марсель Пруст', 1927, 480, ARRAY['Классика', 'Психологическая проза', 'Модернизм', 'Философия'],
 'Спустя годы рассказчик возвращается в парижское общество, постаревшее и изменившееся до неузнаваемости, и неожиданно, через цепь непроизвольных воспоминаний, осознаёт своё истинное призвание — написать роман о времени, которое, казалось, было безвозвратно утрачено. Заключительный том эпопеи «В поисках утраченного времени» замыкает цикл на самом себе.'),
('Клуб любителей книг и пирогов из картофельных очистков', 'Мэри Энн Шеффер и Энни Бэрроуз', 2008, 320, ARRAY['Драма', 'Исторический роман', 'Юмор'],
 'Лондонская писательница переписывается с жителями острова Гернси, во время немецкой оккупации случайно создавшими литературный клуб с эксцентричным названием в качестве алиби для комендантского часа. Роман в письмах о книгах, дружбе и выживании под оккупацией.'),
('Последнее письмо от твоего любимого', 'Джоджо Мойес', 2010, 480, ARRAY['Драма', 'Любовный роман', 'Детектив'],
 'Журналистка с потерей памяти после аварии случайно находит старое любовное письмо, адресованное незнакомке, и пытается разгадать историю чужой запретной любви полувековой давности. Роман Мойес переплетает две временные линии в истории о письмах, которые меняют судьбы.'),
('До встречи с тобой', 'Джоджо Мойес', 2012, 480, ARRAY['Драма', 'Любовный роман'],
 'Простодушная провинциальная девушка устраивается сиделкой к богатому молодому человеку, парализованному после аварии и решившему добровольно уйти из жизни, — и пытается за полгода убедить его передумать. Один из самых обсуждаемых и трогательных современных романов о любви и праве на собственный выбор.'),
('После тебя', 'Джоджо Мойес', 2015, 400, ARRAY['Драма', 'Любовный роман', 'Юмор'],
 'Спустя полтора года после трагических событий героиня «До встречи с тобой» пытается заново научиться жить, пока в её жизни неожиданно не появляется человек из прошлого её возлюбленного. Продолжение одного из самых популярных современных романов о горе и движении дальше.'),
('Переломный момент', 'Малкольм Гладуэлл', 2000, 304, ARRAY['Нон-фикшн', 'Научно-популярная', 'Социология'],
 'Книга исследует, как незначительные на первый взгляд изменения способны достичь «точки перелома» и вызвать масштабную социальную эпидемию — от моды до преступности. Дебютный бестселлер Гладуэлла, подаривший языку само выражение «точка перелома».'),
('Гении и аутсайдеры', 'Малкольм Гладуэлл', 2008, 320, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология'],
 'Автор доказывает, что выдающийся успех объясняется не только врождённым талантом, но и стечением обстоятельств, культурным наследием и, что особенно важно, десятью тысячами часов упорной практики. Один из самых известных научпоп-бестселлеров о природе успеха.'),
('Озарение', 'Малкольм Гладуэлл', 2005, 288, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология'],
 'Книга исследует природу мгновенных интуитивных суждений, которые мы выносим за доли секунды, — и то, когда таким быстрым решениям стоит доверять, а когда они опасно обманчивы. Один из самых обсуждаемых бестселлеров Гладуэлла о скрытой силе первого впечатления.'),
('Голая экономика', 'Чарльз Уилан', 2002, 400, ARRAY['Нон-фикшн', 'Научно-популярная', 'Экономика'],
 'Книга объясняет базовые принципы экономики простым и остроумным языком, без сложных формул и графиков, на понятных повседневных примерах. Один из самых доступных и популярных вводных курсов в экономику для неспециалистов.'),
('Принц и нищий', 'Марк Твен', 1881, 288, ARRAY['Классика', 'Приключения', 'Сатира', 'Детская литература'],
 'Юный английский принц и уличный нищий мальчик, поразительно похожие друг на друга, случайно меняются местами и обнаруживают, насколько по-разному устроена жизнь богатых и бедных. Сатирическая повесть Марка Твена о случайности социального положения и природе королевской власти.'),
('Двадцать лет спустя', 'Александр Дюма', 1845, 704, ARRAY['Классика', 'Приключения', 'Исторический роман'],
 'Постаревшие мушкетёры д’Артаньян, Атос, Портос и Арамис, давно разошедшиеся по разным сторонам политических баррикад, вновь объединяются ради спасения английского короля и собственной родины. Прямое продолжение «Трёх мушкетёров» о верности дружбе спустя десятилетия.'),
('Виконт де Бражелон', 'Александр Дюма', 1850, 1600, ARRAY['Классика', 'Приключения', 'Исторический роман'],
 'Постаревшие мушкетёры в последний раз объединяются на фоне интриг молодого Людовика XIV, тайны Железной маски и трагической судьбы следующего поколения героев. Заключительный, самый объёмный роман трилогии о мушкетёрах завершает историю гибелью почти всех главных героев.'),
('Королева Марго', 'Александр Дюма', 1845, 704, ARRAY['Классика', 'Исторический роман', 'Приключения'],
 'На фоне кровавой Варфоломеевской ночи королева Наваррская Маргарита Валуа балансирует между долгом, политическими интригами французского двора и страстной тайной любовью. Один из самых известных исторических романов Дюма о религиозных войнах во Франции XVI века.'),
('Графиня де Монсоро', 'Александр Дюма', 1846, 800, ARRAY['Классика', 'Исторический роман', 'Приключения', 'Любовный роман'],
 'Благородный дворянин спасает похищенную девушку и влюбляется в неё, не зная, что она уже тайно обвенчана с жестоким и мстительным графом де Монсоро. Продолжение «Королевы Марго» переносит действие во времена правления Генриха III.'),
('Замок Отранто', 'Гораций Уолпол', 1764, 160, ARRAY['Ужасы', 'Готика', 'Мистика', 'Классика'],
 'Таинственный гигантский шлем падает с неба и убивает наследника замка Отранто в день его свадьбы, запуская цепь сверхъестественных событий и древнее родовое проклятие. Первый готический роман в истории литературы, заложивший все основные каноны жанра.'),
('Мельмот Скиталец', 'Чарльз Роберт Метьюрин', 1820, 560, ARRAY['Ужасы', 'Готика', 'Мистика', 'Классика'],
 'Бессмертный Мельмот продал душу дьяволу в обмен на долгую жизнь и теперь скитается по миру в поисках несчастного, который согласится взять на себя его проклятие. Один из самых мрачных и влиятельных готических романов, вдохновивший позднее Оскара Уайльда и Бодлера.'),
('Монах', 'Мэтью Грегори Льюис', 1796, 448, ARRAY['Ужасы', 'Готика', 'Мистика', 'Классика'],
 'Благочестивый испанский монах, прославленный своей добродетелью, поддаётся дьявольскому искушению и скатывается в череду всё более чудовищных преступлений. Один из самых скандальных готических романов XVIII века, сочетающий мистику с откровенным для своего времени натурализмом.'),
('Дом, из рассвета сотворённый', 'Н. Скотт Момадэй', 1968, 224, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Молодой индеец возвращается с войны в родную резервацию и пытается найти равновесие между традициями предков и разрушительным влиянием белого мира. Роман, принёсший автору первую Пулитцеровскую премию, присуждённую писателю коренных народов Америки.'),
('Бесконечная шутка', 'Дэвид Фостер Уоллес', 1996, 1104, ARRAY['Постмодернизм', 'Сатира', 'Психологическая проза'],
 'Действие романа разворачивается между элитной теннисной академией и реабилитационным центром для зависимых неподалёку, а в основе сюжета — легендарный фильм, настолько увлекательный, что зрители умирают, не в силах оторваться от экрана. Один из самых объёмных, сложных и влиятельных американских романов конца XX века.'),
('Корни', 'Алекс Хейли', 1976, 688, ARRAY['Исторический роман', 'Семейная сага', 'Драма'],
 'Автор прослеживает историю собственной семьи на протяжении нескольких поколений — от похищенного из Гамбии предка Кунта Кинте, проданного в рабство, до собственного детства в Америке XX века. Роман, вызвавший огромный общественный резонанс и всплеск интереса к генеалогии афроамериканцев.'),
('Невидимая жизнь Адди Ларю', 'В. Э. Шваб', 2020, 448, ARRAY['Фэнтези', 'Мистика', 'Драма'],
 'Девушка из французской деревни XVIII века заключает сделку с тёмным божеством, чтобы жить вечно и свободно, — но расплатой становится проклятие: все, кого она встречает, мгновенно забывают о её существовании. Современная сказка о памяти, свободе и цене бессмертия.'),
('Свет в августе', 'Уильям Фолкнер', 1932, 480, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Судьбы беременной девушки, ищущей отца своего ребёнка, и мужчины с неясным расовым происхождением, скрывающегося от собственного прошлого, пересекаются в маленьком городке американского Юга. Один из самых значительных романов Фолкнера о расе, вине и насилии южного общества.'),
('Zero to One. Как построить стартап, который изменит будущее', 'Питер Тиль', 2014, 224, ARRAY['Нон-фикшн', 'Бизнес'],
 'Сооснователь PayPal утверждает, что подлинный прогресс заключается не в копировании существующих решений, а в создании чего-то принципиально нового — перехода от нуля к единице. Одна из самых влиятельных книг о технологическом предпринимательстве и монополиях.'),
('Доставляя счастье', 'Тони Шей', 2010, 272, ARRAY['Нон-фикшн', 'Бизнес', 'Биография'],
 'Основатель интернет-магазина обуви Zappos рассказывает, как поставил во главу угла корпоративную культуру и клиентский сервис, превратив небольшой стартап в компанию с миллиардной выручкой. Одна из самых известных бизнес-книг о счастье как основе успешного бизнеса.'),
('Когда дыхание растворяется в воздухе', 'Пол Каланити', 2016, 256, ARRAY['Нон-фикшн', 'Биография', 'Философия'],
 'Молодой нейрохирург, только достигший вершины профессионального мастерства, узнаёт о неизлечимом раке лёгких и пишет книгу о поиске смысла перед лицом неминуемой смерти. Посмертно опубликованные мемуары стали одним из самых пронзительных размышлений о жизни, смертности и врачебном призвании.'),
('Записки из Мёртвого дома', 'Фёдор Достоевский', 1862, 320, ARRAY['Классика', 'Исторический роман', 'Драма'],
 'Полуавтобиографическое повествование описывает годы, проведённые автором на каторге в Сибири, — быт, нравы и человеческие судьбы заключённых самых разных сословий и преступлений. Одно из первых в русской литературе подробных и человечных описаний тюремного мира изнутри.'),
('Униженные и оскорблённые', 'Фёдор Достоевский', 1861, 384, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Молодой писатель становится невольным свидетелем и участником судеб нескольких бедных и униженных петербуржцев, чьи жизни разрушены коварством одного и того же циничного князя. Один из первых больших романов Достоевского о сострадании к «маленьким людям» столицы.'),
('Игрок', 'Фёдор Достоевский', 1866, 160, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Домашний учитель в семье разорившегося русского генерала на немецком курорте постепенно поддаётся азартной одержимости рулеткой, теряя рассудок, деньги и последнюю надежду на любовь. Роман, написанный Достоевским за рекордные двадцать шесть дней под угрозой кабального издательского контракта, во многом основан на его собственной игровой зависимости.'),
('Вечный муж', 'Фёдор Достоевский', 1870, 160, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Вдовец приезжает в Петербург и неожиданно сближается с мужчиной, который когда-то много лет был любовником его покойной жены, — и между ними завязываются странные, болезненно амбивалентные отношения ревности и притяжения. Одна из самых психологически тонких повестей позднего Достоевского.'),
('Подросток', 'Фёдор Достоевский', 1875, 480, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Незаконнорождённый юноша, одержимый идеей разбогатеть и стать «Ротшильдом», приезжает в Петербург к родному, но чужому для него отцу и оказывается втянут в его запутанные денежные и любовные дела. Один из пяти великих романов позднего Достоевского о взрослении, гордыне и поиске отцовской фигуры.'),
('Дама с собачкой', 'Антон Чехов', 1899, 32, ARRAY['Классика', 'Любовный роман', 'Психологическая проза'],
 'Немолодой курортный ловелас заводит очередной мимолётный роман с молодой замужней дамой в Ялте, не ожидая, что эта интрижка перерастёт в единственную настоящую любовь его жизни. Один из самых известных и совершенных рассказов Чехова о позднем, безнадёжном и всё же настоящем чувстве.'),
('Человек в футляре', 'Антон Чехов', 1898, 32, ARRAY['Классика', 'Сатира', 'Психологическая проза'],
 'Учитель греческого языка живёт в постоянном страхе перед любыми переменами и нарушениями привычного порядка, заключив себя в своеобразный футляр из правил и запретов, — и его смерть становится для города настоящим облегчением. Рассказ подарил русскому языку выражение «человек в футляре» для обозначения боязливого консерватора.'),
('Ионыч', 'Антон Чехов', 1898, 32, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Молодой земский врач, полный идеалов и чувств, постепенно, шаг за шагом, превращается в равнодушного и жадного обывателя под давлением скучной провинциальной жизни. Один из самых беспощадных рассказов Чехова о медленном умирании души.'),
('Крыжовник', 'Антон Чехов', 1898, 24, ARRAY['Классика', 'Сатира', 'Философия'],
 'Чиновник всю жизнь копит деньги на мечту — собственное имение с кустами крыжовника, — а добившись своего, превращается в самодовольного и равнодушного к чужим страданиям барина. Короткий рассказ из «маленькой трилогии» Чехова о мелочности человеческого счастья.'),
('Паддингтон', 'Майкл Бонд', 1958, 176, ARRAY['Детская литература', 'Сказка', 'Юмор'],
 'Медвежонок из «дремучего Перу» приезжает в Лондон с биркой «Пожалуйста, позаботьтесь об этом медведе» и поселяется в семье Браун, то и дело попадая в нелепые, но неизменно добрые приключения. Один из самых обаятельных персонажей английской детской литературы.'),
('Доктор Айболит', 'Корней Чуковский', 1929, 96, ARRAY['Сказка', 'Детская литература', 'Юмор'],
 'Добрый доктор, лечащий зверей бесплатно, отправляется в Африку спасать заболевших обезьян, преодолевая по пути акулу Каракулу и злого разбойника Бармалея. Одна из самых любимых советских детских сказок о доброте и самоотверженной помощи.'),
('Мойдодыр', 'Корней Чуковский', 1923, 32, ARRAY['Сказка', 'Детская литература', 'Юмор', 'Поэзия'],
 'От неряшливого мальчика сбегают все его вещи, а умывальник по имени Мойдодыр гонится за ним по улицам города, требуя немедленно вымыться. Одна из самых известных и ритмичных стихотворных сказок Чуковского о пользе чистоты.'),
('Муха-Цокотуха', 'Корней Чуковский', 1924, 32, ARRAY['Сказка', 'Детская литература', 'Юмор', 'Поэзия'],
 'Муха находит на лугу денежку, устраивает весёлые именины для всех насекомых, а затем её похищает злой паук — пока на выручку не прилетает отважный комар. Одна из самых весёлых и музыкальных детских сказок Чуковского в стихах.'),
('Телефон', 'Корней Чуковский', 1926, 32, ARRAY['Сказка', 'Детская литература', 'Юмор', 'Поэзия'],
 'Герою поочерёдно звонят слон, крокодил, зайчата и прочие звери с самыми нелепыми просьбами — от шоколада до вызволения из болота бегемота. Одна из самых забавных стихотворных сказок Чуковского о бесконечной телефонной суете.'),
('Портрет Дориана Грея', 'Оскар Уайльд', 1890, 256, ARRAY['Классика', 'Философия', 'Мистика'],
 'Юноша удивительной красоты желает, чтобы портрет старел вместо него, — и получает свою волшебную просьбу, после чего предаётся распутству и пороку, оставаясь внешне вечно молодым, пока лицо на холсте превращается в отражение его гниющей души. Единственный роман Уайльда об эстетизме, грехе и цене вечной молодости.'),
('Как важно быть серьёзным', 'Оскар Уайльд', 1895, 96, ARRAY['Драма', 'Юмор', 'Сатира', 'Пьесы'],
 'Два лондонских холостяка придумывают себе несуществующих alter ego по имени Эрнест, чтобы иметь повод сбегать от светских обязательств, — а когда обе их невесты заявляют, что готовы выйти замуж только за «Эрнеста», ложь грозит обернуться катастрофой. Самая остроумная комедия Уайльда, доведённая до абсурда искусством каламбура.'),
('Веер леди Уиндермир', 'Оскар Уайльд', 1892, 112, ARRAY['Драма', 'Сатира', 'Пьесы'],
 'Молодая леди, заподозрившая мужа в измене с загадочной дамой из прошлого, едва не совершает непоправимую ошибку, не зная, что эта дама на самом деле жертвует собственной репутацией ради её же счастья. Остроумная комедия нравов Уайльда о лицемерии высшего света и истинной цене добродетели.'),
('Саломея', 'Оскар Уайльд', 1891, 64, ARRAY['Драма', 'Мистика', 'Пьесы'],
 'Иудейская принцесса Саломея, одержимая страстью к пленённому пророку Иоканаану, соглашается исполнить танец семи покрывал перед отчимом-царём в обмен на голову пророка на серебряном блюде. Декадентская одноактная пьеса Уайльда о роковой красоте легла в основу знаменитой оперы Рихарда Штрауса.'),
('Баллада Редингской тюрьмы', 'Оскар Уайльд', 1898, 32, ARRAY['Поэзия', 'Классика', 'Драма'],
 'Поэма, написанная после двух лет тюремного заключения за «непристойное поведение», описывает казнь одного из заключённых и размышляет о вине, милосердии и жестокости системы правосудия. Последнее крупное произведение Уайльда, написанное уже после его общественного и личного краха.'),
('Счастливый принц и другие сказки', 'Оскар Уайльд', 1888, 128, ARRAY['Сказка', 'Детская литература', 'Классика', 'Философия'],
 'Позолоченная статуя принца и ласточка, задержавшаяся в пути на юг, по ночам раздают беднякам города собственное золото и драгоценности, жертвуя ради чужого счастья собственными жизнями. Сборник литературных сказок Уайльда о сострадании, жертвенности и цене настоящей красоты.'),
('Дублинцы', 'Джеймс Джойс', 1914, 256, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Пятнадцать взаимосвязанных рассказов изображают жителей Дублина начала XX века, застрявших в душевном параличе между мечтами о побеге и неспособностью что-либо изменить в собственной жизни. Сборник, завершающийся знаменитой повестью «Мёртвые», заложил стиль, который Джойс позже разовьёт в «Улиссе».'),
('Моллой', 'Сэмюэл Беккет', 1951, 240, ARRAY['Постмодернизм', 'Абсурдизм', 'Психологическая проза'],
 'Безногий бродяга Моллой на велосипеде пробирается через незнакомую страну на поиски собственной матери, а параллельно детектив Моран отправляется на поиски самого Моллоя, постепенно теряя рассудок и идентичность. Первый роман «трилогии» Беккета о распаде языка, тела и смысла.'),
('Конец игры', 'Сэмюэл Беккет', 1957, 48, ARRAY['Драма', 'Абсурдизм', 'Пьесы'],
 'Слепой и неспособный ходить деспот Хамм, его слуга Кловн и родители Хамма, живущие в мусорных баках, коротают, судя по всему, последние часы существования мира в бесконечных перебранках и ритуальных препирательствах. Одна из самых мрачных пьес театра абсурда о медленном угасании всего живого.'),
('Комната Джованни', 'Джеймс Болдуин', 1956, 192, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Американец в Париже, обручённый с женщиной, заводит страстный роман с итальянским барменом Джованни и мучительно разрывается между социально одобряемым будущим и подлинными чувствами, которые боится признать. Один из первых открыто написанных романов о гомосексуальной любви в американской литературе.'),
('Иди, вещай с горы', 'Джеймс Болдуин', 1953, 256, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Подросток из гарлемской пятидесятнической семьи переживает духовный и личный кризис в день собственного четырнадцатилетия, одновременно узнавая темные тайны прошлого своего деспотичного проповедника-отчима. Полуавтобиографический дебютный роман Болдуина о вере, расе и семье в Гарлеме.'),
('Если Бийл-стрит могла бы заговорить', 'Джеймс Болдуин', 1974, 224, ARRAY['Драма', 'Любовный роман', 'Социальная проза'],
 'Беременная темнокожая девушка борется за освобождение жениха, ложно обвинённого в изнасиловании, которого он не совершал, пытаясь доказать его невиновность в системе, заранее настроенной против него. Один из самых пронзительных романов Болдуина о любви, несправедливости и расизме американской судебной системы.'),
('В дороге', 'Джек Керуак', 1957, 320, ARRAY['Классика', 'Приключения', 'Автобиографическая проза'],
 'Писатель Сал Парадайз колесит автостопом по Америке вместе с харизматичным и саморазрушительным Дином Мориарти в поисках джаза, свободы и экстатического опыта настоящего момента. Роман, написанный на одном непрерывном свитке бумаги, стал манифестом поколения битников.'),
('Вопль', 'Аллен Гинзберг', 1956, 32, ARRAY['Поэзия', 'Классика'],
 'Поэма в свободном стихе яростно обрушивается на конформизм, материализм и душевное удушье послевоенной Америки через исповедальные, нарочито необузданные образы. Публикация поэмы привела к суду по обвинению в непристойности, который сборник выиграл, закрепив свободу поэтического слова.'),
('Голый завтрак', 'Уильям Берроуз', 1959, 256, ARRAY['Постмодернизм', 'Сатира', 'Научная фантастика'],
 'Фрагментарное, лишённое линейного сюжета повествование погружает читателя в галлюцинаторный мир наркотической зависимости, паранойи и чёрного юмора, собранный из разрозненных эпизодов и персонажей. Одно из самых скандальных и экспериментальных произведений литературы битников.'),
('Приключения Оги Марча', 'Сол Беллоу', 1953, 608, ARRAY['Классика', 'Художественная проза', 'Юмор'],
 'Чикагский еврей из бедной семьи перебирает десятки профессий и жизненных путей в погоне за собственной самостоятельной идентичностью в послевоенной Америке. Роман, написанный энергичным разговорным языком, принёс Беллоу статус одного из главных американских писателей XX века.'),
('Герцог', 'Сол Беллоу', 1964, 384, ARRAY['Классика', 'Психологическая проза', 'Юмор'],
 'Разведённый университетский профессор Мозес Герцог пишет бесчисленные неотправленные письма — живым, мёртвым и самому себе — пытаясь разобраться в крушении собственного брака и интеллектуальных амбиций. Роман, принёсший Беллоу Национальную книжную премию, о кризисе среднего возраста интеллектуала.'),
('Жалобы Портного', 'Филип Рот', 1969, 320, ARRAY['Классика', 'Сатира', 'Психологическая проза'],
 'Мужчина средних лет на приёме у психоаналитика исповедуется в собственных сексуальных неврозах, виной за которые он винит властную еврейскую мать и религиозное воспитание. Скандальный при выходе роман Рота соединяет исповедальную прозу с едкой сатирой на американский еврейский быт.'),
('Американская пастораль', 'Филип Рот', 1997, 480, ARRAY['Классика', 'Драма', 'Социальная проза'],
 'Образцовый американец, успешный бизнесмен и бывшая школьная звезда спорта видит, как его благополучная жизнь рушится, когда родная дочь становится политической террористкой-подрывницей. Роман, принёсший Роту Пулитцеровскую премию, о крахе американской мечты на фоне общественных потрясений 1960-х.'),
('Враги. История любви', 'Исаак Башевис-Зингер', 1972, 224, ARRAY['Классика', 'Драма', 'Любовный роман'],
 'Переживший Холокост еврей, обосновавшийся в послевоенном Нью-Йорке, оказывается женат сразу на трёх женщинах — спасительнице военных лет, чудом выжившей первой жене и новой возлюбленной. Роман нобелевского лауреата о вине выжившего и невозможности начать жизнь заново после катастрофы.'),
('Шоша', 'Исаак Башевис-Зингер', 1978, 272, ARRAY['Классика', 'Любовный роман', 'Исторический роман'],
 'Молодой варшавский писатель накануне Второй мировой войны влюблён в простодушную соседку детства Шошу, оставшуюся навсегда ребёнком в своём умственном развитии, несмотря на предупреждения всех вокруг о надвигающейся катастрофе. Полуавтобиографический роман Зингера о довоенном еврейском мире Варшавы, обречённом на гибель.'),
('Гитанджали', 'Рабиндранат Тагор', 1910, 160, ARRAY['Поэзия', 'Классика', 'Философия'],
 'Сборник духовных стихов-подношений исследует взаимоотношения человеческой души с божественным через образы индийской природы и повседневной жизни. Сборник принёс Тагору Нобелевскую премию по литературе — первую, присуждённую неевропейскому автору.'),
('Дом и мир', 'Рабиндранат Тагор', 1916, 256, ARRAY['Классика', 'Драма', 'Политическая проза'],
 'Молодая бенгальская женщина, воспитанная мужем в непривычной для своего времени свободе, оказывается разрываема между традиционным семейным долгом и революционным национализмом харизматичного друга семьи. Роман Тагора о столкновении личного и политического в Индии накануне борьбы за независимость.'),
('Книга непокоя', 'Фернандо Пессоа', 1982, 480, ARRAY['Философия', 'Психологическая проза', 'Поэзия'],
 'Фрагментарный дневник вымышленного лиссабонского бухгалтера исследует меланхолию, бездействие и созерцательную тоску человека, наблюдающего жизнь со стороны, не решаясь в неё по-настоящему включиться. Собранная и опубликованная посмертно книга считается одним из величайших произведений португальской литературы XX века.'),
('Дона Флор и два её мужа', 'Жоржи Амаду', 1966, 480, ARRAY['Магический реализм', 'Любовный роман', 'Юмор'],
 'Вдова, снова удачно вышедшая замуж за респектабельного, но скучного аптекаря, обнаруживает, что призрак её первого, обаятельного и распутного покойного мужа начинает являться к ней по ночам с вполне плотскими намерениями. Чувственный магреалистический роман о бразильской душе, разрывающейся между порядком и страстью.'),
('Генералы песчаных карьеров', 'Жоржи Амаду', 1937, 320, ARRAY['Драма', 'Социальная проза', 'Приключения'],
 'Банда беспризорных подростков выживает на улицах и в заброшенных песчаных карьерах Баии, промышляя мелким воровством и отчаянно цепляясь за собственную свободу вопреки всем попыткам государства их «исправить». Один из самых известных ранних романов Амаду о детской нищете и достоинстве изгоев бразильского общества.'),
('Посмертные записки Браса Кубаса', 'Жоакин Мария Машадо де Ассиз', 1881, 256, ARRAY['Классика', 'Сатира', 'Постмодернизм'],
 'Покойный бразильский аристократ сам рассказывает историю собственной бесполезно прожитой жизни, постоянно обращаясь к читателю и обрывая повествование абсурдными отступлениями. Один из первых и самых новаторских романов латиноамериканской литературы, опередивший модернистские приёмы на полвека.'),
('Снег', 'Орхан Памук', 2002, 480, ARRAY['Драма', 'Политическая проза', 'Исторический роман'],
 'Турецкий поэт-эмигрант приезжает в отрезанный снегопадом провинциальный город накануне местных выборов и оказывается в центре столкновения светского национализма, исламизма и личной любовной драмы. Роман нобелевского лауреата о расколотой идентичности современной Турции.'),
('Меня зовут Красный', 'Орхан Памук', 1998, 480, ARRAY['Детектив', 'Исторический роман', 'Философия'],
 'Убийство придворного миниатюриста в Стамбуле XVI века запускает расследование, в котором голос получают сразу несколько рассказчиков — включая саму жертву, убийцу и даже цвет красный. Изощрённый исторический детектив о столкновении исламской и западной художественных традиций.'),
('Вегетарианка', 'Хан Ган', 2007, 224, ARRAY['Драма', 'Психологическая проза'],
 'Обычная южнокорейская домохозяйка внезапно отказывается от мяса после кошмарного сна, а затем и вовсе начинает отрицать собственную человеческую природу, к ужасу и непониманию всей своей семьи. Роман нобелевского лауреата о теле, насилии и отказе соответствовать ожиданиям общества.'),
('Пер Гюнт', 'Генрик Ибсен', 1867, 224, ARRAY['Драма', 'Фэнтези', 'Поэзия', 'Пьесы'],
 'Норвежский мечтатель и лжец Пер Гюнт пускается в полные приключений странствия по миру — от троллиных пещер до марокканских пустынь, — всю жизнь избегая настоящей ответственности за собственные поступки. Эпическая драматическая поэма Ибсена легла в основу знаменитой музыки Эдварда Грига.'),
('Привидения', 'Генрик Ибсен', 1881, 96, ARRAY['Драма', 'Пьесы', 'Социальная проза'],
 'Вдова, годами скрывавшая распутство покойного мужа ради его доброго имени, обнаруживает, что от отца к сыну передалась не только репутация, но и смертельная болезнь. Одна из самых скандальных пьес Ибсена своего времени, открыто заговорившая о венерических заболеваниях и лицемерии буржуазной морали.'),
('Гедда Габлер', 'Генрик Ибсен', 1890, 112, ARRAY['Драма', 'Психологическая проза', 'Пьесы'],
 'Скучающая и эгоистичная генеральская дочь, вышедшая замуж без любви за посредственного учёного, от бессмысленности собственной жизни начинает жестоко манипулировать судьбами окружающих. Одна из самых психологически сложных героинь мировой драматургии.'),
('Фрёкен Жюли', 'Август Стриндберг', 1888, 80, ARRAY['Драма', 'Психологическая проза', 'Пьесы'],
 'Аристократка, пренебрегающая сословными границами в Иванову ночь, заводит роковую связь с собственным лакеем, разрушающую их обоих. Натуралистическая драма Стриндберга о классовой и гендерной борьбе стала одной из самых постановочных пьес скандинавского театра.'),
('Так держать, Дживс!', 'Пелам Гренвилл Вудхаус', 1934, 256, ARRAY['Юмор', 'Классика'],
 'Непутёвый молодой аристократ Берти Вустер в очередной раз ввязывается в нелепую авантюру, из которой его неизменно вытаскивает невозмутимый и безупречно рассудительный камердинер Дживс. Один из лучших образцов классического английского комедийного романа о слуге, превосходящем хозяина умом.'),
('Кодекс чести Вустеров', 'Пелам Гренвилл Вудхаус', 1938, 256, ARRAY['Юмор', 'Классика'],
 'Берти Вустер оказывается втянут в кражу серебряной сливочницы, шантаж и запутанные помолвки друзей, а Дживс в очередной раз элегантно распутывает весь этот клубок нелепостей. Один из самых изобретательных по сюжету романов цикла о Дживсе и Вустере.'),
('Падение дома Ашеров', 'Эдгар Аллан По', 1839, 32, ARRAY['Ужасы', 'Готика', 'Мистика', 'Классика'],
 'Гость приезжает в мрачный фамильный особняк больного друга и становится свидетелем распада не только самого дома, но и всего обречённого рода Ашеров. Одна из самых атмосферных и влиятельных повестей ужасов в истории литературы.'),
('Маска Красной смерти', 'Эдгар Аллан По', 1842, 16, ARRAY['Ужасы', 'Готика', 'Мистика', 'Классика'],
 'Принц со свитой запирается в неприступном замке, устраивая пышный маскарад, пока за стенами свирепствует смертельная чума, — но на бал является незваный гость в костюме самой Красной смерти. Короткая аллегорическая повесть о неотвратимости смерти перед лицом любого богатства и власти.'),
('Колодец и маятник', 'Эдгар Аллан По', 1842, 24, ARRAY['Ужасы', 'Мистика', 'Классика'],
 'Узник испанской инквизиции приходит в себя в полной темноте камеры пыток, постепенно обнаруживая и бездонный колодец в центре, и медленно опускающийся над ним гигантский маятник с лезвием. Одна из самых напряжённых и физиологически достоверных повестей ужасов По.'),
('Убийство на улице Морг', 'Эдгар Аллан По', 1841, 32, ARRAY['Детектив', 'Классика', 'Мистика'],
 'Эксцентричный парижский аналитик Огюст Дюпен раскрывает жестокое двойное убийство в запертой изнутри комнате методом чистой логической дедукции. Рассказ, фактически создавший жанр детективной прозы и вдохновивший позднее Конан Дойла на Шерлока Холмса.'),
('Чёрный кот', 'Эдгар Аллан По', 1843, 24, ARRAY['Ужасы', 'Психологическая проза', 'Классика'],
 'Спившийся рассказчик, когда-то любивший собственного кота, в приступе ярости калечит, а затем и убивает животное — и это преступление начинает мучительно его преследовать. Одна из самых психологически точных повестей По о природе необъяснимого человеческого саморазрушения.'),
('Разумный инвестор', 'Бенджамин Грэм', 1949, 640, ARRAY['Нон-фикшн', 'Бизнес', 'Финансы'],
 'Учитель Уоррена Баффета излагает принципы стоимостного инвестирования — покупки недооценённых активов и долгосрочного терпеливого подхода вместо спекулятивной биржевой игры. Одна из самых авторитетных и цитируемых книг по инвестированию за всю историю фондового рынка.'),
('Случайная прогулка по Уолл-стрит', 'Бёртон Малкиел', 1973, 448, ARRAY['Нон-фикшн', 'Бизнес', 'Финансы'],
 'Экономист доказывает, что движения цен на фондовом рынке в целом непредсказуемы и случайны, а значит, для большинства инвесторов пассивное индексное инвестирование выгоднее попыток обыграть рынок. Одна из самых влиятельных и переиздаваемых книг по личным инвестициям.'),
('Августовские пушки', 'Барбара Такман', 1962, 608, ARRAY['Нон-фикшн', 'История', 'Военная проза'],
 'Книга подробно реконструирует первый месяц Первой мировой войны — от дипломатических просчётов до первых сражений, — показывая, как цепь случайностей и амбиций привела Европу к катастрофе. Книга принесла автору Пулитцеровскую премию и, по слухам, повлияла на решения президента Кеннеди во время Карибского кризиса.'),
('Взлёт и падение Третьего рейха', 'Уильям Ширер', 1960, 1248, ARRAY['Нон-фикшн', 'История', 'Биография'],
 'Американский журналист, лично работавший в Германии в 1930-е годы, детально прослеживает историю нацистского режима от прихода Гитлера к власти до окончательного краха в 1945 году. Один из самых подробных и авторитетных исторических трудов о Третьем рейхе, написанный непосредственным очевидцем событий.'),
('Путь королей', 'Брэндон Сандерсон', 2010, 1008, ARRAY['Фэнтези', 'Приключения', 'Философия'],
 'На раздираемом бурями континенте Рошар разворачивается история опального хирурга, ставшего рабом, разочарованного дворянина-полководца и древнего ордена рыцарей, чья магия давно забыта. Первый том цикла «Архив Буресвета» — одна из самых масштабных современных фэнтези-эпопей.'),
('Пятое время года', 'Нора Джемисин', 2015, 480, ARRAY['Фэнтези', 'Научная фантастика', 'Драма'],
 'На континенте, регулярно опустошаемом катастрофическими геологическими катаклизмами, женщины с опасным даром управления землёй вынуждены скрывать свои способности под угрозой смерти или рабства. Роман, трижды подряд получивший премию «Хьюго», переосмысляет фэнтези через призму угнетения и экологической катастрофы.'),
('Голый среди волков', 'Бруно Апиц', 1958, 384, ARRAY['Военная проза', 'Исторический роман', 'Драма'],
 'Узники концлагеря Бухенвальд тайно прячут от охраны еврейского младенца, рискуя жизнью ради спасения единственного ребёнка среди тысяч заключённых. Роман, основанный на реальных событиях, о солидарности и сопротивлении в условиях нацистского лагеря смерти.'),
('Если это человек', 'Примо Леви', 1947, 224, ARRAY['Нон-фикшн', 'Биография', 'Военная проза'],
 'Итальянский химик описывает год, проведённый в Освенциме, — методичную систему унижения, голода и истощения, низводящую людей до состояния, в котором само понятие человечности оказывается под вопросом. Одно из самых важных и сдержанных свидетельств о Холокосте в мировой литературе.'),
('Шейн', 'Джек Шефер', 1949, 160, ARRAY['Классика', 'Приключения'],
 'Таинственный незнакомец с пистолетом заступается за семью фермеров против жестокого скотовода, претендующего на их землю, а затем так же тихо исчезает, как и появился. Один из самых известных и часто экранизируемых классических романов американского Дикого Запада.'),
('Как говорить, чтобы дети слушали', 'Адель Фабер и Элейн Мазлиш', 1980, 320, ARRAY['Нон-фикшн', 'Психология'],
 'Книга предлагает конкретные практические техники общения с детьми, основанные на признании их чувств вместо критики и наказания. Одна из самых известных и практичных книг по детской психологии и воспитанию.'),
('Ненасильственное общение', 'Маршалл Розенберг', 1999, 320, ARRAY['Нон-фикшн', 'Психология'],
 'Психолог предлагает модель коммуникации, основанную на честном выражении собственных потребностей и эмпатическом слушании чужих, без обвинений и осуждения. Одна из самых влиятельных книг по межличностному общению и разрешению конфликтов.'),
('Осознанность', 'Марк Уильямс и Дэнни Пенман', 2011, 288, ARRAY['Нон-фикшн', 'Психология'],
 'Книга предлагает восьминедельную программу медитативных практик для снижения тревожности и стресса, основанную на клинически проверенной методике когнитивной терапии осознанности. Один из самых популярных практических руководств по медитации для широкого читателя.'),
('Сердца трёх', 'Джек Лондон', 1920, 320, ARRAY['Приключения', 'Любовный роман', 'Юмор'],
 'Американский авантюрист и его друг отправляются в Центральную Америку на поиски сокровищ майя, попутно сражаясь с пиратами и влюбляясь в одну и ту же девушку. Один из самых лёгких и приключенческих поздних романов Джека Лондона, написанный изначально как сценарий для кино.'),
('Чёрная стрела', 'Роберт Льюис Стивенсон', 1888, 304, ARRAY['Приключения', 'Исторический роман', 'Классика'],
 'Молодой рыцарь в разгар войны Алой и Белой розы вступает в тайную шайку мстителей, стреляющих чёрными стрелами в виновников гибели своих близких, и ищет собственную правду среди всеобщего предательства. Исторический приключенческий роман Стивенсона о рыцарстве и мести в средневековой Англии.'),
('Странная история доктора Джекила и мистера Хайда', 'Роберт Льюис Стивенсон', 1886, 128, ARRAY['Ужасы', 'Мистика', 'Психологическая проза', 'Классика'],
 'Респектабельный лондонский врач изобретает зелье, высвобождающее его тёмную, порочную сторону в облике совершенно другого человека, — и постепенно теряет контроль над тем, кто из двоих на самом деле он есть. Повесть подарила языку выражение «доктор Джекил и мистер Хайд» для обозначения раздвоения личности.'),
('Остров доктора Моро', 'Герберт Уэллс', 1896, 192, ARRAY['Научная фантастика', 'Ужасы', 'Философия'],
 'Потерпевший кораблекрушение человек попадает на уединённый остров, где безумный учёный путём чудовищных вивисекций превращает животных в подобие людей. Один из первых романов о биологической этике и границе между человеком и зверем.'),
('Человек-невидимка', 'Герберт Уэллс', 1897, 192, ARRAY['Научная фантастика', 'Классика', 'Триллер'],
 'Учёный, открывший секрет невидимости, не может найти способ стать видимым снова и постепенно, в полной социальной изоляции, скатывается от научного триумфа к безумию и террору. Классический роман о цене научного открытия, вышедшего из-под контроля создателя.'),
('Пища богов', 'Герберт Уэллс', 1904, 256, ARRAY['Научная фантастика', 'Сатира', 'Приключения'],
 'Экспериментальное вещество, ускоряющее рост живых организмов, случайно попадает в дикую природу, порождая гигантских насекомых, растения и в конце концов — новое поколение великанов-людей. Сатирический роман Уэллса о страхе общества перед всем, что превосходит привычный масштаб.'),
('Михаил Строгов', 'Жюль Верн', 1876, 448, ARRAY['Приключения', 'Исторический роман', 'Классика'],
 'Царский курьер отправляется с секретным поручением через охваченную татарским восстанием Сибирь, преодолевая предательство, плен и ослепление раскалённым клинком ради спасения страны. Один из самых популярных приключенческих романов Жюля Верна, действие которого разворачивается в России.'),
('Робур-Завоеватель', 'Жюль Верн', 1886, 288, ARRAY['Научная фантастика', 'Приключения', 'Классика'],
 'Эксцентричный изобретатель похищает скептиков, не веривших в будущее воздухоплавания, и катает их по всему миру на борту гигантского летающего винтового аппарата собственной конструкции. Один из первых романов Верна о покорении неба на аппарате тяжелее воздуха.'),
('Маленькие огни повсюду', 'Селеста Инг', 2017, 384, ARRAY['Драма', 'Семейная сага', 'Социальная проза'],
 'Размеренную жизнь образцового пригорода нарушает появление матери-одиночки с дочерью-подростком, чьё присутствие постепенно обнажает секреты и трещины в идеально устроенных семьях соседей. Роман о материнстве, классовых различиях и цене внешнего благополучия.'),
('Тонкая работа', 'Сара Уотерс', 2002, 480, ARRAY['Детектив', 'Исторический роман', 'Триллер'],
 'Юная карманница из лондонских трущоб виктoрианской эпохи устраивается служанкой к богатой наследнице, чтобы помочь сообщнику обманом жениться на ней и завладеть состоянием, — но план рушится самым неожиданным образом. Изобретательный неовикторианский триллер с несколькими слоями обмана.'),
('Бархатные коготки', 'Сара Уотерс', 1998, 480, ARRAY['Исторический роман', 'Драма', 'Любовный роман'],
 'Устричная девушка из провинциального городка влюбляется в артистку мюзик-холла, переодевающуюся в мужское платье, и вслед за ней отправляется в богемный и порой опасный мир викторианского Лондона. Дебютный роман Уотерс о скрытой queer-культуре и свободе быть собой в консервативную эпоху.'),
('Биология добра и зла', 'Роберт Сапольски', 2017, 800, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология', 'Биология'],
 'Нейробиолог объясняет человеческое поведение — от насилия до альтруизма — через целый каскад причин: от происходящего в мозге за секунду до события до эволюционных процессов, растянутых на миллионы лет. Масштабный научно-популярный труд о биологических корнях морали и агрессии.'),
('Записки нейрохирурга', 'Генри Марш', 2014, 320, ARRAY['Нон-фикшн', 'Биография', 'Научно-популярная'],
 'Британский нейрохирург честно и без прикрас описывает собственную карьеру — триумфы, фатальные ошибки и постоянное балансирование между спасением жизни и её разрушением одним неверным движением скальпеля. Один из самых откровенных медицинских мемуаров о цене врачебной профессии.'),
('Миф о Сизифе', 'Альбер Камю', 1942, 160, ARRAY['Нон-фикшн', 'Философия'],
 'Философское эссе исследует абсурдность человеческого существования через миф о Сизифе, обречённом вечно вкатывать камень на гору, — и приходит к выводу, что единственный выход из абсурда не самоубийство, а бунт и принятие жизни такой, какая она есть. Один из ключевых программных текстов философии абсурда.'),
('Бытие и ничто', 'Жан-Поль Сартр', 1943, 800, ARRAY['Нон-фикшн', 'Философия'],
 'Фундаментальный философский трактат излагает экзистенциалистское учение о свободе, ответственности и фундаментальном различии между бытием вещи и бытием сознающего себя человека. Одна из самых влиятельных и сложных философских работ XX века.'),
('Экзистенциализм — это гуманизм', 'Жан-Поль Сартр', 1946, 96, ARRAY['Нон-фикшн', 'Философия'],
 'Короткая публичная лекция в доступной форме объясняет основные идеи экзистенциализма — то, что существование предшествует сущности и человек сам, своими поступками, создаёт собственную природу. Самое популярное и понятное введение в философию Сартра.'),
('Роковые яйца', 'Михаил Булгаков', 1925, 96, ARRAY['Научная фантастика', 'Сатира', 'Мистика'],
 'Профессор-зоолог случайно открывает луч, ускоряющий рост и размножение живых организмов, а советские чиновники тут же пытаются применить открытие в сельском хозяйстве — с катастрофическими последствиями. Сатирическая повесть Булгакова о слепой вере в технический прогресс без понимания его опасности.'),
('Дьяволиада', 'Михаил Булгаков', 1924, 64, ARRAY['Сатира', 'Мистика', 'Юмор'],
 'Мелкий советский служащий теряет документы и рассудок, пытаясь пробиться сквозь абсурдную бюрократическую машину нового учреждения, раздваивающуюся буквально на глазах. Ранняя сатирическая повесть Булгакова о кафкианском абсурде советской бюрократии.'),
('Оле-Лукойе', 'Ганс Христиан Андерсен', 1841, 32, ARRAY['Сказка', 'Детская литература', 'Классика'],
 'Добрый дух сна Оле-Лукойе каждую ночь приходит к детям с двумя зонтиками — один навевает чудесные сны послушным детям, а другой оставляет непослушных без сновидений вовсе. Цикл сказок Андерсена, рассказанных от лица персонажа, ставшего символом самого детского сна.'),
('Стойкий оловянный солдатик', 'Ганс Христиан Андерсен', 1838, 24, ARRAY['Сказка', 'Детская литература', 'Классика', 'Драма'],
 'Однорукий оловянный солдатик безответно влюблён в бумажную балерину и переживает череду опасных приключений — падение из окна, плавание в бумажном кораблике и путешествие в желудке рыбы, — сохраняя стойкость до самого трагического конца. Одна из самых печальных и трогательных сказок Андерсена о верности вопреки обстоятельствам.'),
('Новое платье короля', 'Ганс Христиан Андерсен', 1837, 16, ARRAY['Сказка', 'Детская литература', 'Сатира', 'Классика'],
 'Тщеславный король нанимает мошенников, обещающих сшить наряд, невидимый для глупцов, — и весь двор, боясь показаться глупым, восхищается несуществующим одеянием, пока один честный ребёнок не произносит очевидное вслух. Одна из самых известных сказок-притч о конформизме и силе непредвзятого детского взгляда.'),
('Дом на Пуховой опушке', 'Алан Александр Милн', 1928, 176, ARRAY['Сказка', 'Детская литература', 'Юмор', 'Классика'],
 'Винни-Пух и его друзья из Стоакрового леса встречают нового обитателя — прыгучего и неугомонного Тигру, а Кристофер Робин постепенно готовится к взрослению и расставанию с волшебным детским миром. Второй и заключительный сборник историй о Винни-Пухе, завершающийся одной из самых трогательных прощальных сцен детской литературы.'),
('Разговоры с друзьями', 'Салли Руни', 2017, 320, ARRAY['Драма', 'Любовный роман', 'Психологическая проза'],
 'Две молодые ирландки, выступающие дуэтом на поэтических вечерах, оказываются втянуты в сложные отношения с состоятельной супружеской парой средних лет. Дебютный роман Руни о дружбе, классовых различиях и неловкости близости в эпоху постоянной переписки.'),
('Прекрасный мир, где же ты', 'Салли Руни', 2021, 352, ARRAY['Драма', 'Любовный роман', 'Психологическая проза'],
 'Успешная, но внутренне опустошённая писательница и её друг детства переписываются о любви, политике и смысле жизни в современном мире, одновременно пытаясь наладить собственные запутанные романтические отношения. Третий роман Салли Руни продолжает её фирменное исследование близости и отчуждения поколения миллениалов.'),
('Ночной цирк', 'Эрин Моргенштерн', 2011, 512, ARRAY['Фэнтези', 'Любовный роман', 'Мистика'],
 'Два юных иллюзиониста с детства обучены тайным соперничающим магическим школам для дуэли, разворачивающейся внутри таинственного цирка, который открывается только по ночам, — но вместо соперничества между ними вспыхивает запретная любовь. Атмосферный роман о магии, судьбе и цирке, существующем на грани реальности и волшебства.'),
('Эссенциализм', 'Грег МакКеон', 2014, 272, ARRAY['Нон-фикшн', 'Бизнес', 'Психология'],
 'Книга призывает сознательно отказываться от большинства возможностей и задач ради сосредоточенной работы над по-настоящему важным, вместо того чтобы распыляться на всё подряд. Один из самых известных бестселлеров о продуктивности через осознанное ограничение.'),
('Гибкое сознание', 'Кэрол Дуэк', 2006, 320, ARRAY['Нон-фикшн', 'Психология', 'Бизнес'],
 'Психолог противопоставляет «фиксированное» мышление, при котором способности считаются врождёнными и неизменными, и «растущее» мышление, при котором усилия и опыт способны развить практически любой навык. Одна из самых влиятельных книг по психологии мотивации и обучения.'),
('Дары волхвов', 'О. Генри', 1905, 16, ARRAY['Классика', 'Любовный роман', 'Драма'],
 'Бедная молодая пара накануне Рождества продаёт каждый своё самое ценное имущество, чтобы купить подарок другому, — и оба подарка оказываются бесполезны из-за этой самой жертвы. Один из самых известных рассказов о бескорыстной любви, завершающийся знаменитым неожиданным финалом О. Генри.'),
('Последний лист', 'О. Генри', 1907, 16, ARRAY['Классика', 'Драма'],
 'Больная пневмонией художница решает, что умрёт, когда с дикого винограда за окном упадёт последний лист, — а старый сосед-неудачник совершает собственный последний в жизни благородный поступок. Один из самых трогательных рассказов О. Генри о жертвенности искусства ради спасения чужой надежды.'),
('Вождь краснокожих', 'О. Генри', 1907, 24, ARRAY['Юмор', 'Классика', 'Приключения'],
 'Двое мелких жуликов похищают сына богатого фермера ради выкупа, но невыносимо энергичный и жестокий ребёнок быстро превращает похитителей в собственных заложников. Один из самых смешных рассказов О. Генри о похищении, обернувшемся против самих похитителей.'),
('Дом о семи фронтонах', 'Натаниель Готорн', 1851, 320, ARRAY['Готика', 'Классика', 'Мистика'],
 'Старинный фамильный особняк в Новой Англии несёт на себе проклятие, наложенное веками ранее за несправедливо отнятую землю, и преследует всех последующих поколений семьи, в нём живущих. Готический роман Готорна о грузе родового греха и неотвратимости расплаты через поколения.'),
('Писец Бартлби', 'Герман Мелвилл', 1853, 64, ARRAY['Классика', 'Психологическая проза', 'Сатира'],
 'Новый клерк в нью-йоркской юридической конторе на любую просьбу работодателя начинает кротко отвечать «я предпочёл бы не», постепенно отказываясь буквально от всего, включая саму жизнь. Одна из самых загадочных и часто интерпретируемых повестей американской литературы об абсолютном, необъяснимом отказе от участия в системе.'),
('Голова профессора Доуэля', 'Александр Беляев', 1925, 224, ARRAY['Научная фантастика', 'Мистика', 'Философия'],
 'Учёный оживляет отделённую от тела голову собственного погибшего коллеги, поддерживая в ней сознание и речь исключительно ради продолжения научных экспериментов. Один из первых советских научно-фантастических романов о границах этики научного эксперимента.'),
('Человек-амфибия', 'Александр Беляев', 1928, 256, ARRAY['Научная фантастика', 'Приключения', 'Любовный роман'],
 'Хирург пересаживает больному мальчику жабры акулы, превращая его в человека-амфибию, способного жить и в воде, и на суше, — а повзрослев, юноша влюбляется и становится жертвой жадных до сенсации и наживы людей. Один из самых популярных советских научно-фантастических романов о цене инаковости.'),
('Аэлита', 'Алексей Толстой', 1923, 224, ARRAY['Научная фантастика', 'Приключения', 'Любовный роман'],
 'Советский инженер строит ракету и отправляется на Марс, где влюбляется в дочь верховного правителя древней марсианской цивилизации Аэлиту, а заодно невольно разжигает на планете революцию. Один из первых советских романов о космических полётах и межпланетной любви.'),
('Гиперболоид инженера Гарина', 'Алексей Толстой', 1927, 320, ARRAY['Научная фантастика', 'Приключения', 'Триллер'],
 'Беспринципный учёный-изобретатель создаёт оружие невиданной разрушительной силы — тепловой луч — и использует его в попытке установить собственную мировую диктатуру. Один из самых известных советских научно-фантастических романов о технологии как инструменте безграничной личной власти.'),
('Старуха Изергиль', 'Максим Горький', 1895, 32, ARRAY['Классика', 'Притча', 'Романтизм'],
 'Старая цыганка рассказывает путнику у моря легенды о гордом Ларре, обречённом на вечное одиночество за презрение к людям, и о Данко, вырвавшем из груди собственное сердце, чтобы осветить племени путь из тьмы. Романтическая повесть-притча раннего Горького о двух полюсах человеческого эгоизма и самопожертвования.'),
('Песня о Буревестнике', 'Максим Горький', 1901, 8, ARRAY['Поэзия', 'Классика', 'Политическая проза'],
 'Короткая поэма в прозе изображает гордого буревестника, с нетерпением зовущего надвигающуюся революционную бурю, в то время как остальные морские птицы в страхе прячутся от грозы. Произведение стало одним из самых известных поэтических символов приближающейся русской революции.'),
('Детство', 'Максим Горький', 1913, 224, ARRAY['Классика', 'Автобиографическая проза', 'Драма'],
 'Маленький Алёша Пешков переживает раннее сиротство и жестокий быт в доме деспотичного деда-красильщика в провинциальном Нижнем Новгороде. Первая часть автобиографической трилогии Горького о тяжёлом детстве среди нищеты и домашнего насилия.'),
('В людях', 'Максим Горький', 1916, 256, ARRAY['Классика', 'Автобиографическая проза', 'Драма'],
 'Подросток Алёша перебивается случайными заработками — от посудомойщика на пароходе до подмастерья в иконописной мастерской, — впервые по-настоящему открывая для себя мир книг и человеческой жестокости одновременно. Вторая часть автобиографической трилогии Горького о взрослении среди тяжёлого труда.'),
('Мои университеты', 'Максим Горький', 1923, 160, ARRAY['Классика', 'Автобиографическая проза', 'Драма'],
 'Юный Алёша приезжает в Казань в надежде поступить в университет, но вместо лекций проходит куда более суровую школу жизни — среди революционеров, босяков и портовых грузчиков. Заключительная часть автобиографической трилогии Горького, давшая название самому понятию «университеты жизни».'),
('Фома Гордеев', 'Максим Горький', 1899, 320, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Сын богатого купца Фома Гордеев не может найти себе места в мире практичного и беспринципного накопительства, к которому его готовили с детства, и постепенно скатывается к бунту и саморазрушению. Один из первых крупных романов Горького о духовном кризисе нарождающейся русской буржуазии.'),
('Мать', 'Максим Горький', 1906, 384, ARRAY['Классика', 'Политическая проза', 'Драма'],
 'Простая неграмотная работница постепенно вовлекается в революционную деятельность сына и сама становится сознательной участницей подпольной борьбы рабочих за свои права. Один из первых программных романов социалистического реализма, оказавший огромное влияние на советскую литературу.'),
('Бесприданница', 'Александр Островский', 1878, 112, ARRAY['Драма', 'Классика', 'Пьесы'],
 'Бедная, но гордая девушка Лариса Огудалова оказывается разменной монетой в руках богатых поклонников, ни один из которых не готов жениться на бесприданнице по-настоящему честно. Одна из самых трагических пьес Островского о цене женской чести в мире, где всё продаётся и покупается.'),
('Лес', 'Александр Островский', 1870, 128, ARRAY['Драма', 'Сатира', 'Пьесы', 'Юмор'],
 'Разорившаяся помещица, тайно продающая лес в своём имении, скрывает собственную скупость за маской благочестия, пока странствующие актёры не вмешиваются в судьбу её бедной племянницы. Одна из самых ярких сатирических комедий Островского о лицемерии провинциального дворянства.'),
('Таланты и поклонники', 'Александр Островский', 1881, 112, ARRAY['Драма', 'Пьесы', 'Социальная проза'],
 'Талантливая провинциальная актриса вынуждена выбирать между искренней бедной любовью и покровительством богатого поклонника, способного обеспечить её театральную карьеру. Пьеса Островского о цене, которую искусство и женская независимость платят за выживание в мире денег.'),
('Снегурочка', 'Александр Островский', 1873, 160, ARRAY['Сказка', 'Драма', 'Поэзия', 'Пьесы'],
 'Дочь Мороза и Весны Снегурочка, неспособная любить из-за ледяного сердца, отчаянно жаждет познать человеческое чувство, даже ценой собственной жизни под первыми лучами весеннего солнца. Поэтическая пьеса-сказка Островского легла в основу знаменитой оперы Римского-Корсакова.'),
('Рассказ Служанки', 'Маргарет Этвуд', 1985, 320, ARRAY['Фэнтези', 'Антиутопия', 'Драма'],
 'В тоталитарном теократическом государстве, возникшем на месте США после экологической катастрофы и резкого падения рождаемости, фертильных женщин превращают в «служанок» — живые сосуды для деторождения, лишённые имени, собственности и права голоса. Одна из самых влиятельных феминистских антиутопий XX века.'),
('Заветы', 'Маргарет Этвуд', 2019, 448, ARRAY['Фэнтези', 'Антиутопия', 'Драма'],
 'Спустя пятнадцать лет после событий «Рассказа Служанки» три женщины — высокопоставленная Тётка режима, девушка, выросшая в Гилеаде, и беглянка из Канады — оказываются втянуты в заговор, способный разрушить теократическое государство изнутри. Продолжение культовой антиутопии принесло Этвуд вторую Букеровскую премию.'),
('Орикс и Коростель', 'Маргарет Этвуд', 2003, 400, ARRAY['Научная фантастика', 'Антиутопия', 'Философия'],
 'Последний, судя по всему, человек на Земле вспоминает, как корпоративная генная инженерия и погоня за совершенством привели цивилизацию к биологическому апокалипсису. Первый роман трилогии «Беззумный Аддам» о гордыне науки и хрупкости человеческого вида.'),
('Слепой убийца', 'Маргарет Этвуд', 2000, 544, ARRAY['Драма', 'Семейная сага', 'Психологическая проза'],
 'Пожилая женщина вспоминает историю собственной семьи и загадочное самоубийство сестры-писательницы, чей посмертно изданный роман о тайном романе любовников постепенно оказывается куда ближе к реальности, чем кажется на первый взгляд. Роман, построенный как книга в книге, принёс Этвуд Букеровскую премию.'),
('2001: Космическая одиссея', 'Артур Кларк', 1968, 304, ARRAY['Научная фантастика', 'Философия', 'Приключения'],
 'Экипаж космического корабля отправляется к Юпитеру вслед за таинственным сигналом древнего монолита, а искусственный интеллект корабля HAL 9000 начинает действовать по собственной, не вполне понятной людям логике. Роман, написанный параллельно со сценарием одноимённого фильма Стэнли Кубрика, стал одной из самых философски насыщенных книг в истории научной фантастики.'),
('Свидание с Рамой', 'Артур Кларк', 1973, 256, ARRAY['Научная фантастика', 'Приключения', 'Философия'],
 'Гигантский цилиндрический космический корабль неизвестного происхождения на огромной скорости влетает в Солнечную систему, и земная экспедиция получает считаные дни, чтобы исследовать его изнутри, прежде чем он покинет пределы системы навсегда. Один из самых известных романов о контакте с абсолютно непостижимым чужим разумом.'),
('Конец детства', 'Артур Кларк', 1953, 240, ARRAY['Научная фантастика', 'Философия'],
 'Загадочные пришельцы устанавливают мирное господство над Землёй, прекращая войны и нищету, но истинная цель их присутствия оказывается связана не с политикой, а со следующим эволюционным шагом самого человечества. Один из самых философски масштабных романов золотого века научной фантастики о цене эволюционного преображения.'),
('Мир-Кольцо', 'Ларри Нивен', 1970, 352, ARRAY['Научная фантастика', 'Приключения', 'Философия'],
 'Экспедиция из людей и инопланетян исследует гигантское искусственное кольцо, опоясывающее звезду наподобие орбиты планеты, — инженерное сооружение настолько огромное, что способно вместить миллионы обитаемых миров. Один из самых известных романов жанра «мегаструктур», получивший сразу премии «Хьюго» и «Небьюла».'),
('Дом для мистера Бисваса', 'Видиадхар Найпол', 1961, 624, ARRAY['Классика', 'Драма', 'Семейная сага'],
 'Индотринидадец Мохун Бисвас всю жизнь мечтает о собственном доме как символе независимости от властной жениной родни, переживая череду неудачных попыток обрести хоть какую-то точку опоры. Эпический трагикомический роман нобелевского лауреата о колониальной идентичности и праве на собственное место в мире.'),
('Излучина реки', 'Видиадхар Найпол', 1979, 320, ARRAY['Классика', 'Политическая проза', 'Драма'],
 'Индиец-мусульманин открывает торговую лавку в только что освободившейся от колониального правления африканской стране, охваченной хаосом постколониальной диктатуры и этнического насилия. Один из самых мрачных романов Найпола о распаде общества на обломках колониальной эпохи.'),
('Омерос', 'Дерек Уолкотт', 1990, 352, ARRAY['Поэзия', 'Классика', 'Исторический роман'],
 'Эпическая поэма переносит мотивы и персонажей гомеровской «Илиады» на карибский остров Сент-Люсия, где рыбаки, туристы и призраки колониального прошлого ведут собственную версию древней истории о гневе и любви. Поэма нобелевского лауреата соединяет карибский фольклор с европейской эпической традицией.'),
('Фосс', 'Патрик Уайт', 1957, 448, ARRAY['Классика', 'Исторический роман', 'Приключения'],
 'Немецкий исследователь возглавляет экспедицию через неисследованные просторы австралийской пустыни, одержимый почти мистической верой в собственное предназначение, пока в Сиднее его ждёт женщина, с которой он связан не меньше мистической духовной связью. Роман нобелевского лауреата, основанный на реальной трагической экспедиции Людвига Лейххардта.'),
('Оскар и Люсинда', 'Питер Кэри', 1988, 512, ARRAY['Классика', 'Исторический роман', 'Любовный роман'],
 'Застенчивый английский священник-игроман и эксцентричная австралийская наследница стекольной фабрики заключают невероятное пари — перевезти целую стеклянную церковь через австралийскую глушь. Роман, принёсший Кэри Букеровскую премию, о вере, азарте и одержимости невозможным.'),
('Истинная история шайки Келли', 'Питер Кэри', 2000, 416, ARRAY['Исторический роман', 'Приключения', 'Драма'],
 'Легендарный австралийский разбойник Нед Келли пишет собственной неграмотной рукой письмо-исповедь для дочери, которую никогда не узнает, — рассказ о бедности, несправедливости и превращении обычного скотокрада в народного героя. Роман, стилизованный под подлинные исторические документы, принёс Кэри вторую Букеровскую премию.'),
('Сид', 'Пьер Корнель', 1636, 128, ARRAY['Драма', 'Исторический роман', 'Пьесы', 'Любовный роман'],
 'Молодой испанский дворянин вынужден убить на дуэли отца собственной возлюбленной, защищая честь своего отца, — и оба влюблённых разрываются между долгом перед семьёй и чувством друг к другу. Пьеса, заложившая каноны французского классицизма, вызвала бурную полемику современников о соотношении чести и любви.'),
('Федра', 'Жан Расин', 1677, 112, ARRAY['Драма', 'Трагедия', 'Пьесы'],
 'Жена афинского царя Тесея воспылала запретной страстью к пасынку Ипполиту и, узнав о ложном слухе о смерти мужа, признаётся в чувствах, — а когда муж неожиданно возвращается, ложь и ревность приводят к трагической гибели невинного юноши. Одна из вершин французского классицистического театра о разрушительной силе неконтролируемой страсти.'),
('Андромаха', 'Жан Расин', 1667, 96, ARRAY['Драма', 'Трагедия', 'Пьесы', 'Любовный роман'],
 'После падения Трои пленная Андромаха вынуждена выбирать между верностью памяти погибшего мужа Гектора и спасением сына от греческого царя, домогающегося её любви под угрозой убийства ребёнка. Трагедия Расина о цепи безответных любовей, в которой каждый герой любит того, кто не любит его самого.'),
('Лига перепуганных мужчин', 'Рекс Стаут', 1935, 256, ARRAY['Детектив', 'Классика'],
 'Группа влиятельных мужчин, объединённых тайной студенческой виной четвертьвековой давности, один за другим получают анонимные угрозы и обращаются за помощью к эксцентричному сыщику-гурману Ниро Вулфу. Один из первых и самых известных романов о детективе-домоседе Ниро Вулфе и его энергичном помощнике Арчи Гудвине.'),
('Прощай, любимая', 'Реймонд Чандлер', 1940, 304, ARRAY['Детектив', 'Нуар', 'Классика'],
 'Частный сыщик Филип Марлоу случайно оказывается втянут в поиски бывшей возлюбленной только что освободившегося из тюрьмы громилы, а дело быстро разрастается в клубок шантажа, контрабанды и убийства. Один из самых атмосферных нуар-романов о Лос-Анджелесе, пропитанном коррупцией.'),
('Глубокий сон', 'Реймонд Чандлер', 1939, 256, ARRAY['Детектив', 'Нуар', 'Классика'],
 'Частный детектив Филип Марлоу, нанятый богатым стариком-генералом разобраться с шантажистом его непутёвой дочери, погружается в клубок порнографии, убийств и семейных тайн настолько запутанный, что сам автор позже признавался, что не до конца понимал, кто кого убил. Дебютный роман о Филипе Марлоу, заложивший канон жанра крутого детектива.'),
('Стеклянный ключ', 'Дэшил Хэммет', 1931, 256, ARRAY['Детектив', 'Нуар', 'Криминальная проза'],
 'Правая рука политического боссы небольшого города расследует убийство сына влиятельного сенатора, пытаясь защитить покровителя от обвинений, несмотря на собственные растущие сомнения в его невиновности. Один из самых мрачных и политически циничных романов Хэммета о коррупции и преданности.'),
('Худой человек', 'Дэшил Хэммет', 1934, 224, ARRAY['Детектив', 'Юмор', 'Нуар'],
 'Отошедший от дел частный детектив и его остроумная богатая жена, навестившие Нью-Йорк на Рождество, невольно оказываются втянуты в расследование исчезновения эксцентричного изобретателя. Последний роман Хэммета, сочетающий детективную интригу с лёгким юмором супружеской пары сыщиков.'),
('Удольфские тайны', 'Анна Радклиф', 1794, 672, ARRAY['Ужасы', 'Готика', 'Мистика', 'Романтизм'],
 'Осиротевшая девушка оказывается заточена опекуном в мрачном итальянском замке, полном таинственных звуков, зловещих портретов и необъяснимых происшествий, которым, впрочем, в финале находится совершенно рациональное объяснение. Один из самых влиятельных готических романов, задавший моду на зловещие замки и доверчивых героинь.'),
('Ватек', 'Уильям Бекфорд', 1786, 160, ARRAY['Ужасы', 'Готика', 'Мистика', 'Фэнтези'],
 'Могущественный багдадский халиф Ватек в погоне за запретным знанием и безграничной властью заключает сделку со злыми силами, ведущую его через вереницу всё более чудовищных преступлений прямо в ад. Один из самых экзотических и мрачных готических романов XVIII века, вдохновлённый арабскими сказками.'),
('Просто христианство', 'Клайв Стейплз Льюис', 1952, 256, ARRAY['Нон-фикшн', 'Философия', 'Религия'],
 'Бывший атеист, обратившийся в христианство уже в зрелом возрасте, излагает доступным и логически выстроенным языком основы христианской веры, общие для всех конфессий. Одна из самых известных и переиздаваемых апологетических книг XX века.'),
('Письма Баламута', 'Клайв Стейплз Льюис', 1942, 160, ARRAY['Нон-фикшн', 'Сатира', 'Религия', 'Юмор'],
 'Старший демон-наставник в письмах учит племянника-беса, как незаметно сбивать с пути одного конкретного человека, превращая духовную борьбу в остроумную сатиру на повседневные человеческие слабости. Одна из самых оригинальных и ироничных религиозных книг XX века.'),
('Чудо', 'Клайв Стейплз Льюис', 1947, 240, ARRAY['Нон-фикшн', 'Философия', 'Религия'],
 'Философ-апологет разбирает возможность сверхъестественного вмешательства в устроенный по законам природы мир, споря с натурализмом и рационалистическим отрицанием чудес. Одна из самых аргументированных попыток примирить веру в чудо с рациональным мышлением.'),
('Капитализм и свобода', 'Милтон Фридман', 1962, 272, ARRAY['Нон-фикшн', 'Экономика', 'Философия'],
 'Экономист отстаивает идею, что экономическая свобода рынка является необходимым условием политической свободы, и предлагает радикальное сокращение роли государства в большинстве сфер жизни. Одна из самых влиятельных книг неолиберальной экономической мысли XX века.'),
('Свободны выбирать', 'Милтон Фридман', 1980, 320, ARRAY['Нон-фикшн', 'Экономика'],
 'Экономист и его жена в доступной форме, на конкретных исторических примерах, объясняют, как свободный рынок эффективнее государственного регулирования решает большинство экономических проблем общества. Книга и сопровождавший её телесериал сделали идеи свободного рынка понятными массовому читателю.'),
('Противостояние', 'Стивен Кинг', 1978, 1200, ARRAY['Постапокалиптика', 'Ужасы', 'Фэнтези'],
 'Сбежавший из секретной лаборатории смертоносный грипп уничтожает почти всё человечество, а немногочисленные выжившие постепенно разделяются на два противоборствующих лагеря добра и зла, готовящихся к финальному столкновению. Одна из самых масштабных и амбициозных книг Стивена Кинга, которую сам автор называет своим любимым романом.'),
('Воспламеняющая взглядом', 'Стивен Кинг', 1980, 400, ARRAY['Научная фантастика', 'Триллер', 'Фэнтези'],
 'Девочка, унаследовавшая от родителей — участников секретного эксперимента — способность воспламенять предметы одной лишь силой мысли, становится объектом охоты правительственного агентства, желающего превратить её в оружие. Один из самых известных триллеров Кинга о сверхспособностях и государственном насилии над детьми.'),
('Куджо', 'Стивен Кинг', 1981, 320, ARRAY['Ужасы', 'Триллер', 'Драма'],
 'Добродушный сенбернар, укушенный бешеной летучей мышью, постепенно превращается в неуправляемое чудовище, запирающее мать с маленьким сыном в заглохшей машине посреди жаркого лета. Один из самых клаустрофобных и реалистичных романов ужасов Кинга без единого намёка на сверхъестественное.'),
('Томминокеры', 'Стивен Кинг', 1987, 560, ARRAY['Научная фантастика', 'Ужасы', 'Мистика'],
 'Писательница натыкается в лесу на край погребённого в земле инопланетного корабля, и раскопки постепенно меняют не только её саму, но и весь городок, одержимый непреодолимым желанием выкопать находку целиком. Один из самых мрачных романов Кинга о технологии, зависимости и утрате человечности.'),
('11/22/63', 'Стивен Кинг', 2011, 850, ARRAY['Научная фантастика', 'Исторический роман', 'Триллер'],
 'Учитель английского находит портал во времени, ведущий в 1958 год, и решает использовать его, чтобы предотвратить убийство президента Кеннеди, — но прошлое оказывается куда более упрямым и опасным, чем он предполагал. Один из самых популярных поздних романов Кинга, соединяющий путешествия во времени с ностальгией по Америке середины XX века.'),
('Стальные пещеры', 'Айзек Азимов', 1954, 256, ARRAY['Научная фантастика', 'Детектив', 'Классика'],
 'Земной детектив, вынужденный раскрывать убийство в паре с человекоподобным роботом, преодолевает собственные предрассудки против искусственного интеллекта на фоне перенаселённого футуристического Нью-Йорка. Один из первых и самых успешных примеров слияния детектива с научной фантастикой.'),
('Обнажённое солнце', 'Айзек Азимов', 1957, 240, ARRAY['Научная фантастика', 'Детектив', 'Классика'],
 'Земной детектив и его напарник-робот расследуют первое убийство за двести лет на планете, населённой людьми, патологически избегающими личного физического контакта друг с другом. Продолжение «Стальных пещёр» исследует общество, доведшее социальную изоляцию до логического предела.'),
('Что-то страшное грядёт', 'Рэй Брэдбери', 1962, 288, ARRAY['Ужасы', 'Мистика', 'Классика'],
 'В маленький американский городок в канун Хэллоуина приезжает зловещий бродячий карнавал, исполняющий самые тайные желания жителей в обмен на их душу и молодость. Поэтичный и тревожный роман Брэдбери о цене исполненных желаний и силе отцовской любви против зла.'),
('Колыбель для кошки', 'Курт Воннегут', 1963, 288, ARRAY['Научная фантастика', 'Сатира', 'Философия'],
 'Писатель, собирающий материал о создателе атомной бомбы, оказывается на крошечном карибском острове, где правит абсурдная религия боконизм, а секретное изобретение льда-девять грозит заморозить всю воду на планете. Один из самых остроумных и мрачных романов Воннегута о науке, религии и апокалипсисе.'),
('Завтрак для чемпионов', 'Курт Воннегут', 1973, 320, ARRAY['Сатира', 'Постмодернизм', 'Юмор'],
 'Неудачливый автор научной фантастики и богатый торговец автомобилями случайно пересекаются на провинциальном литературном фестивале, что приводит продавца к психическому срыву, спровоцированному буквальным восприятием книг как абсолютной истины. Постмодернистский роман Воннегута с собственными авторскими иллюстрациями о природе свободы воли.'),
('Шпиль', 'Уильям Голдинг', 1964, 256, ARRAY['Классика', 'Психологическая проза', 'Философия'],
 'Настоятель собора одержим идеей возвести немыслимо высокий шпиль, несмотря на явную архитектурную невозможность замысла и предупреждения мастеров о неизбежном обрушении. Роман Голдинга о гордыне, одержимости и цене, которую платят окружающие за чужую навязчивую веру в собственную правоту.'),
('Памяти Каталонии', 'Джордж Оруэлл', 1938, 240, ARRAY['Нон-фикшн', 'Военная проза', 'Политическая проза'],
 'Оруэлл описывает собственный опыт добровольца на стороне республиканцев в Гражданской войне в Испании — от восторга революционной солидарности до разочарования в сталинистских репрессиях против собственных же союзников. Одно из самых честных личных свидетельств об идеологических противоречиях антифашистской борьбы.'),
('Дорога на Уиган-Пирс', 'Джордж Оруэлл', 1937, 224, ARRAY['Нон-фикшн', 'Социальная проза', 'Политическая проза'],
 'Оруэлл документирует условия жизни шахтёров и безработных в депрессивных промышленных районах северной Англии, а во второй части книги размышляет о природе социализма и причинах, по которым он отталкивает многих потенциальных сторонников. Одно из самых откровенных социологических исследований британской нищеты 1930-х годов.'),
('Двери восприятия', 'Олдос Хаксли', 1954, 96, ARRAY['Нон-фикшн', 'Философия', 'Психология'],
 'Хаксли описывает собственный опыт приёма мескалина и размышляет о природе сознания, восприятия и возможности химического расширения границ обычного человеческого опыта. Одна из самых влиятельных книг о психоделиках, давшая название рок-группе The Doors.'),
('Падение', 'Альбер Камю', 1956, 160, ARRAY['Классика', 'Философия', 'Психологическая проза'],
 'Бывший успешный парижский адвокат в амстердамском баре исповедуется случайному собеседнику в давнем моральном падении — отказе спасти тонущую женщину, — превратившем всю его последующую жизнь в циничный самосуд. Последний завершённый роман Камю, построенный как монолог-исповедь без единой реплики слушателя.'),
('Первый человек', 'Альбер Камю', 1994, 320, ARRAY['Классика', 'Автобиографическая проза', 'Драма'],
 'Незавершённый автобиографический роман воссоздаёт детство Камю в бедной французской семье в колониальном Алжире — без отца, погибшего на войне, рядом с глухой неграмотной матерью. Рукопись была найдена в разбившейся машине автора и опубликована спустя три десятилетия после его смерти.'),
('Мухи', 'Жан-Поль Сартр', 1943, 96, ARRAY['Драма', 'Философия', 'Пьесы'],
 'Орест возвращается в родной город, одолеваемый роем мух — символом коллективной вины за убийство отца, — чтобы отомстить за него и тем самым принять на себя абсолютную экзистенциальную свободу и ответственность. Пьеса Сартра переосмысляет древнегреческий миф об Оресте как манифест экзистенциалистской философии.'),
('За запертой дверью', 'Жан-Поль Сартр', 1944, 64, ARRAY['Драма', 'Философия', 'Пьесы'],
 'Трое грешников попадают после смерти в комнату без зеркал, окон и пыточных инструментов — и обнаруживают, что настоящим адом оказываются не муки, а вечное присутствие друг друга. Пьеса подарила философии знаменитую фразу «ад — это другие».'),
('Голубая точка', 'Карл Саган', 1994, 384, ARRAY['Нон-фикшн', 'Научно-популярная', 'Философия'],
 'Отталкиваясь от знаменитой фотографии Земли, снятой с окраин Солнечной системы, где планета выглядит едва заметной голубой точкой, астроном размышляет о месте человечества во Вселенной и необходимости космической экспансии. Одна из самых философски поэтичных научно-популярных книг о масштабе мироздания.'),
('Космос', 'Карл Саган', 1980, 384, ARRAY['Нон-фикшн', 'Научно-популярная', 'История'],
 'Книга, написанная на основе знаменитого телесериала, увлекательно рассказывает об устройстве Вселенной, истории астрономии и месте науки в человеческой культуре. Одна из самых успешных научно-популярных книг в истории, воспитавшая целое поколение будущих учёных.'),
('Мир, полный демонов', 'Карл Саган', 1995, 480, ARRAY['Нон-фикшн', 'Научно-популярная', 'Философия'],
 'Астроном защищает научное мышление и скептицизм от псевдонауки, суеверий и лженауки, предлагая читателю практический «набор инструментов для выявления чуши». Одна из самых страстных и актуальных книг в защиту рационального мышления.'),
('Слепой часовщик', 'Ричард Докинз', 1986, 496, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биология'],
 'Биолог доказывает, что сложность и кажущаяся продуманность живых организмов объясняется исключительно слепым, нецеленаправленным процессом естественного отбора, без всякого разумного замысла. Одна из самых аргументированных научно-популярных защит теории эволюции.'),
('Язык как инстинкт', 'Стивен Пинкер', 1994, 480, ARRAY['Нон-фикшн', 'Научно-популярная', 'Лингвистика'],
 'Психолингвист доказывает, что способность к языку — врождённый биологический инстинкт человеческого мозга, а не просто выученный культурный навык. Одна из самых влиятельных научно-популярных книг о природе человеческого языка.'),
('Чистый лист', 'Стивен Пинкер', 2002, 528, ARRAY['Нон-фикшн', 'Научно-популярная', 'Психология'],
 'Психолог оспаривает идею о том, что человеческий разум при рождении представляет собой «чистый лист», полностью формируемый средой и воспитанием, доказывая значительную роль врождённой человеческой природы. Одна из самых спорных и обсуждаемых книг о природе и воспитании.'),
('Клеопатра', 'Генри Райдер Хаггард', 1889, 320, ARRAY['Исторический роман', 'Приключения', 'Мистика'],
 'Потомок древних фараонов вынашивает заговор по свержению египетской царицы Клеопатры, но сам оказывается пленён её роковыми чарами. Исторический приключенческий роман Хаггарда о древнем Египте, написанный с той же мистической атмосферой, что и его африканские романы.'),
('Она', 'Генри Райдер Хаггард', 1887, 320, ARRAY['Приключения', 'Мистика', 'Фэнтези'],
 'Экспедиция в затерянное африканское королевство обнаруживает бессмертную белую царицу Айешу, правящую племенем уже два тысячелетия в ожидании реинкарнации своего погибшего возлюбленного. Один из самых влиятельных романов о затерянных цивилизациях и женщине, обладающей абсолютной властью.'),
('Вещи, которые они несли', 'Тим О’Брайен', 1990, 256, ARRAY['Военная проза', 'Психологическая проза', 'Драма'],
 'Сборник взаимосвязанных рассказов о солдатах американской роты во Вьетнаме исследует не столько сами боевые действия, сколько груз — буквальный и метафорический, — который они несут с собой: письма, амулеты, вину и невозможность забыть. Один из самых важных и формально новаторских романов об опыте войны во Вьетнаме.'),
('Опасные связи', 'Шодерло де Лакло', 1782, 416, ARRAY['Классика', 'Любовный роман', 'Психологическая проза'],
 'Двое аристократов-либертенов заключают циничное пари о соблазнении добродетельной замужней женщины и невинной юной девушки, превращая чужие судьбы в изощрённую светскую игру. Эпистолярный роман о манипуляции и разврате французской аристократии накануне революции остаётся одним из самых психологически точных произведений о власти и желании.'),
('Манон Леско', 'Антуан Франсуа Прево', 1731, 192, ARRAY['Классика', 'Любовный роман', 'Драма'],
 'Благородный юноша без памяти влюбляется в легкомысленную красавицу Манон и ради неё жертвует карьерой, честью и в итоге собственным будущим, следуя за ней даже в ссылку в колонии. Один из первых психологически достоверных романов о разрушительной, нерациональной природе страсти.'),
('Чёрный корсар', 'Эмилио Сальгари', 1898, 320, ARRAY['Приключения', 'Классика'],
 'Итальянский дворянин-пират мстит испанскому губернатору Карибских островов за гибель братьев, попутно влюбляясь в дочь своего врага. Один из самых популярных европейских пиратских романов конца XIX века, подаривший жанру образ благородного мстителя морей.'),
('4-часовая рабочая неделя', 'Тимоти Феррис', 2007, 416, ARRAY['Нон-фикшн', 'Бизнес'],
 'Книга предлагает радикально пересмотреть традиционное представление о карьере через аутсорсинг, автоматизацию и отказ от бессмысленной занятости ради жизни, построенной вокруг путешествий и свободного времени уже сейчас, а не после выхода на пенсию. Один из самых известных манифестов «образа жизни удалённого предпринимателя».'),
('Хорошая стратегия, плохая стратегия', 'Ричард Румельт', 2011, 384, ARRAY['Нон-фикшн', 'Бизнес'],
 'Консультант объясняет, почему большинство корпоративных «стратегий» на самом деле являются лишь списком благих пожеланий без чёткого диагноза проблемы и плана конкретных действий. Одна из самых практичных и честных книг о стратегическом менеджменте.'),
('Как привести дела в порядок', 'Дэвид Аллен', 2001, 352, ARRAY['Нон-фикшн', 'Бизнес', 'Психология'],
 'Консультант по продуктивности предлагает систему GTD — фиксации всех задач вне головы в надёжную внешнюю систему, что освобождает сознание для сосредоточенной работы вместо постоянного удержания в памяти незавершённых дел. Одна из самых влиятельных методик персональной организации труда.'),
('Комната с видом', 'Эдвард Морган Форстер', 1908, 256, ARRAY['Классика', 'Любовный роман', 'Сатира'],
 'Молодая англичанка во время путешествия по Италии влюбляется в свободомыслящего юношу, что ставит под угрозу её благопристойную помолвку с чопорным и манерным женихом на родине. Остроумный роман Форстера о классовых условностях эдвардианской Англии и праве следовать собственным чувствам.'),
('Говардс-Энд', 'Эдвард Морган Форстер', 1910, 320, ARRAY['Классика', 'Драма', 'Социальная проза'],
 'Судьбы интеллигентной, но небогатой семьи, состоятельных буржуа и бедного банковского клерка переплетаются вокруг загородного дома Говардс-Энд, символизирующего саму душу старой Англии. Один из самых значимых романов Форстера о классовом разрыве под девизом «только соединяйте».'),
('Орландо', 'Вирджиния Вулф', 1928, 256, ARRAY['Фэнтези', 'Исторический роман', 'Сатира'],
 'Молодой английский аристократ живёт на протяжении четырёх столетий, в середине повествования безо всякого объяснения превращаясь из мужчины в женщину и продолжая жить дальше. Игривая и смелая для своего времени фантазия Вулф о гендере, времени и литературной традиции, посвящённая её возлюбленной Вите Сэквилл-Уэст.'),
('Волны', 'Вирджиния Вулф', 1931, 256, ARRAY['Модернизм', 'Психологическая проза', 'Поэзия'],
 'Шестеро друзей детства от рождения до старости делятся внутренними монологами, перемежающимися поэтичными описаниями смены дня и моря, как единым потоком сознания на шестерых. Самый формально радикальный роман Вулф, почти полностью отказавшийся от традиционного сюжета ради чистого потока мысли.'),
('Вечеринка в саду', 'Кэтрин Мэнсфилд', 1922, 192, ARRAY['Классика', 'Психологическая проза'],
 'Беззаботный праздник в саду состоятельной семьи омрачается известием о внезапной смерти бедного соседа, и юная героиня впервые по-настоящему сталкивается с несправедливым соседством роскоши и нищеты, жизни и смерти. Заглавный рассказ сборника — одна из вершин короткой прозы модернизма.'),
('Радуга', 'Дэвид Герберт Лоуренс', 1915, 480, ARRAY['Классика', 'Драма', 'Семейная сага'],
 'Три поколения семьи Брэнгуэн на английской ферме переживают смену эпох — от патриархального аграрного уклада до индустриализации, — и вместе с ней меняются и представления о любви, браке и женской независимости. Роман Лоуренса был запрещён за непристойность сразу после публикации.'),
('Влюблённые женщины', 'Дэвид Герберт Лоуренс', 1920, 480, ARRAY['Классика', 'Психологическая проза', 'Любовный роман'],
 'Две сестры из рабочего йоркширского городка вступают в отношения с двумя очень разными мужчинами, исследуя пределы страсти, власти и подлинной близости между полами. Прямое продолжение «Радуги» — один из самых психологически смелых романов Лоуренса о природе любви.'),
('Конец одного романа', 'Грэм Грин', 1951, 256, ARRAY['Драма', 'Любовный роман', 'Религия'],
 'Писатель вспоминает оборванный войной роман с замужней женщиной, которая внезапно покинула его без объяснений, — а личный дневник умершей возлюбленной открывает, что причиной разрыва стала тайная данная ею богу клятва. Один из самых личных романов Грина о границе между земной страстью и религиозной верой.'),
('Суть дела', 'Грэм Грин', 1948, 320, ARRAY['Драма', 'Религия', 'Психологическая проза'],
 'Британский полицейский чиновник в колониальной Западной Африке, разрываясь между состраданием к людям вокруг и собственной католической совестью, запутывается в череде моральных компромиссов, ведущих к трагическому финалу. Один из самых мрачных романов Грина о милосердии, грехе и невозможности спасти всех сразу.'),
('Кролик, беги', 'Джон Апдайк', 1960, 320, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Бывшая школьная звезда баскетбола, ощущающий себя запертым в скучном браке и бессмысленной работе, внезапно бросает семью, пускаясь в бесцельные поиски утраченного юношеского чувства свободы. Первый роман знаменитого тетралогического цикла Апдайка о типичном американце и кризисе мужской идентичности.'),
('Людское клеймо', 'Филип Рот', 2000, 400, ARRAY['Драма', 'Психологическая проза', 'Социальная проза'],
 'Уважаемый университетский профессор классической филологии лишается карьеры из-за случайно оброненного слова, истолкованного как расистское, — а тайна, которую он скрывал всю жизнь, оказывается куда масштабнее этого скандала. Роман Рота об идентичности, политкорректности и невозможности полностью сбежать от собственного прошлого.'),
('Смоляное чучелко', 'Тони Моррисон', 1981, 320, ARRAY['Драма', 'Любовный роман', 'Социальная проза'],
 'Богатая чернокожая модель, выросшая и воспитанная в белом светском мире, заводит страстные и мучительные отношения с чернокожим беглецом, не признающим никаких компромиссов с белой культурой. Роман Моррисон исследует конфликт ассимиляции и расовой идентичности через призму невозможной любви.'),
('Слишком много счастья', 'Элис Манро', 2009, 320, ARRAY['Психологическая проза', 'Драма'],
 'Сборник рассказов исследует неожиданные повороты обычных женских судеб — от случайной встречи до давней трагедии, — раскрывающиеся через характерную для Манро недосказанность и точность бытовой детали. Один из поздних сборников нобелевского лауреата, мастера короткой формы.'),
('Жизни девочек и женщин', 'Элис Манро', 1971, 256, ARRAY['Психологическая проза', 'Драма', 'Автобиографическая проза'],
 'Взаимосвязанные рассказы прослеживают взросление девочки в провинциальном канадском городке — от детских фантазий до первого сексуального опыта и попыток стать писательницей. Единственный формально роман в творчестве Манро, фактически представляющий собой цикл рассказов о женском взрослении.'),
('Сайлес Марнер', 'Джордж Элиот', 1861, 224, ARRAY['Классика', 'Драма', 'Притча'],
 'Ткач-отшельник, несправедливо изгнанный из родной общины и ожесточившийся в одиночестве среди накопленного золота, обретает смысл жизни заново, когда у его порога появляется осиротевшая маленькая девочка. Одна из самых трогательных притч Джордж Элиот об искуплении через родительскую любовь.'),
('Мельница на Флоссе', 'Джордж Элиот', 1860, 384, ARRAY['Классика', 'Драма', 'Семейная сага'],
 'Своевольная и начитанная Мэгги Талливер на протяжении всего детства и юности сталкивается с непониманием семьи и общества, не готового принять женщину, не вписывающуюся в привычные рамки. Полуавтобиографический роман Джордж Элиот о конфликте личных стремлений и семейного долга.'),
('Просто сказки', 'Редьярд Киплинг', 1902, 256, ARRAY['Сказка', 'Детская литература', 'Юмор', 'Классика'],
 'Сборник шутливых сказок-небылиц в стиле «как это было на самом деле» объясняет детям, откуда у слона взялся хобот, откуда у леопарда пятна, а у верблюда горб. Одна из самых весёлых и ритмически изобретательных книг Киплинга, написанная специально для маленьких читателей.'),
('Сказка про кролика Питера', 'Беатрис Поттер', 1902, 64, ARRAY['Сказка', 'Детская литература', 'Классика'],
 'Непослушный крольчонок Питер пробирается в огород строгого фермера Макгрегора вопреки маминому запрету и чудом избегает попадания в кроличье рагу. Одна из самых издаваемых и любимых иллюстрированных детских книг в истории английской литературы.'),
('Энн из Зелёных Мезонинов', 'Люси Мод Монтгомери', 1908, 320, ARRAY['Детская литература', 'Классика', 'Юмор'],
 'Рыжая сирота с неукротимым воображением по ошибке попадает в семью, мечтавшую усыновить мальчика для работы на ферме, — и постепенно покоряет сердца всего маленького канадского острова. Один из самых любимых романов о взрослении девочки, ставший символом острова Принца Эдуарда.'),
('Маленькие мужчины', 'Луиза Мэй Олкотт', 1871, 352, ARRAY['Классика', 'Драма', 'Детская литература'],
 'Повзрослевшая Джо Марч вместе с мужем открывает школу для мальчиков в фамильном поместье, принимая под крыло самых разных воспитанников — от избалованных богачей до беспризорников с улицы. Продолжение «Маленьких женщин» о воспитании и семье, построенной не только на кровном родстве.'),
('Легенда о Сонной Лощине', 'Вашингтон Ирвинг', 1820, 64, ARRAY['Ужасы', 'Мистика', 'Классика', 'Юмор'],
 'Робкий школьный учитель в тихой голландской деревушке штата Нью-Йорк соперничает за руку местной красавицы с грубоватым силачом — и однажды ночью сталкивается на дороге с легендарным всадником без головы. Одна из первых американских историй о привидениях, ставшая классикой хэллоуинского фольклора.'),
('Рип Ван Винкль', 'Вашингтон Ирвинг', 1819, 32, ARRAY['Сказка', 'Мистика', 'Классика', 'Юмор'],
 'Ленивый голландский поселенец засыпает в горах после встречи со странными духами, играющими в кегли, а проснувшись спустя двадцать лет, обнаруживает, что проспал всю Американскую революцию. Одна из первых и самых известных американских сказок, подарившая языку идиому о человеке не от мира сего.'),
('Мост короля Людовика Святого', 'Торнтон Уайлдер', 1927, 160, ARRAY['Классика', 'Философия', 'Драма'],
 'Монах, ставший свидетелем обрушения старинного перуанского моста, уносящего жизни пятерых случайных путников, пытается понять, была ли их гибель божественным замыслом или чистой случайностью, изучая судьбы каждого из погибших. Роман, принёсший Уайлдеру Пулитцеровскую премию, о случайности, судьбе и смысле, который мы ищем в трагедии.'),
('Моя Антония', 'Уилла Кэсер', 1918, 272, ARRAY['Классика', 'Семейная сага', 'Природа'],
 'Рассказчик вспоминает детскую дружбу с дочерью чешских иммигрантов Антонией, выросшей на суровых прериях Небраски, и её стойкость перед лицом нищеты, утраты и тяжёлого труда освоения новых земель. Один из самых значительных романов о жизни первых переселенцев американского фронтира.'),
('Эпоха невинности', 'Эдит Уортон', 1920, 320, ARRAY['Классика', 'Любовный роман', 'Драма', 'Сатира'],
 'Молодой нью-йоркский аристократ накануне собственной свадьбы влюбляется в кузину невесты, скандальную разведённую графиню, бросающую вызов строгим условностям высшего света 1870-х годов. Роман, принёсший Уортон первую Пулитцеровскую премию, присуждённую женщине-автору, о цене социального конформизма.'),
('Дом радости', 'Эдит Уортон', 1905, 384, ARRAY['Классика', 'Драма', 'Сатира'],
 'Красивая, но небогатая светская барышня Лили Барт балансирует между расчётливым замужеством и подлинными чувствами, постепенно теряя место в высшем обществе из-за собственной нерешительности и чужих интриг. Один из самых беспощадных романов Уортон о цене, которую платит женщина за малейшее отклонение от светских приличий.'),
('Главная улица', 'Синклер Льюис', 1920, 480, ARRAY['Классика', 'Сатира', 'Драма'],
 'Образованная городская девушка выходит замуж за провинциального врача и переезжает в маленький городок Миннесоты, задыхаясь от его самодовольной ограниченности и тщетно пытаясь привнести в него культуру и прогресс. Сатирический роман Синклера Льюиса о конформизме и душевной узости американской провинции.'),
('Бэббит', 'Синклер Льюис', 1922, 432, ARRAY['Классика', 'Сатира', 'Драма'],
 'Преуспевающий и всем довольный агент по недвижимости среднего возраста внезапно осознаёт пустоту собственной конформистской жизни, построенной исключительно на статусе и общественном одобрении, и пытается — безуспешно — вырваться за её рамки. Роман подарил английскому языку слово «бэббит» для обозначения самодовольного обывателя.'),
('Джунгли', 'Эптон Синклер', 1906, 400, ARRAY['Классика', 'Социальная проза', 'Драма'],
 'Литовский иммигрант устраивается на чикагские мясокомбинаты и становится свидетелем чудовищной эксплуатации рабочих и антисанитарии пищевого производства. Роман, задуманный как социалистический манифест, вызвал такой общественный резонанс, что привёл к принятию в США законов о контроле качества продуктов питания.'),
('Лорд Джим', 'Джозеф Конрад', 1900, 352, ARRAY['Классика', 'Приключения', 'Психологическая проза'],
 'Молодой офицер торгового флота, в момент паники покинувший тонущий корабль с сотнями паломников на борту, проводит остаток жизни в попытках искупить этот единственный миг трусости. Один из самых психологически глубоких романов Конрада о чести, вине и невозможности убежать от собственного прошлого.'),
('Алый знак доблести', 'Стивен Крейн', 1895, 192, ARRAY['Классика', 'Военная проза', 'Психологическая проза'],
 'Молодой солдат армии северян во время Гражданской войны в США в первом же бою охвачен паническим страхом и бежит с поля боя, а затем мучительно пытается обрести собственное представление о подлинном мужестве. Один из первых психологически достоверных романов о войне, написанный автором, который сам никогда не участвовал в сражениях.'),
('Сестра Керри', 'Теодор Драйзер', 1900, 480, ARRAY['Классика', 'Драма', 'Социальная проза'],
 'Провинциальная девушка приезжает покорять Чикаго и, последовательно сходясь то с одним, то с другим состоятельным мужчиной, поднимается по социальной лестнице, в то время как один из её покровителей столь же стремительно катится на самое дно. Один из первых американских романов, честно показавших, что порок порой остаётся безнаказанным, а добродетель — невознаграждённой.'),
('Американская трагедия', 'Теодор Драйзер', 1925, 896, ARRAY['Классика', 'Драма', 'Психологическая проза', 'Детектив'],
 'Амбициозный бедный юноша, одержимый мечтой о богатстве и социальном статусе, оказывается загнан в ловушку между беременной фабричной работницей и перспективой выгодного брака с богатой невестой — и выбирает убийство. Монументальный роман Драйзера о том, как американская мечта превращается в кошмар.'),
('Домой возврата нет', 'Томас Вулф', 1940, 560, ARRAY['Классика', 'Автобиографическая проза', 'Драма'],
 'Писатель, прославившийся романом о родном городке, обнаруживает, что земляки восприняли правдивое изображение как предательство, и вынужден заново определить своё место в Америке, переживающей Великую депрессию. Посмертно изданный роман Вулфа о невозможности вернуться туда, откуда начал, не изменившись самому.'),
('Взгляни на дом свой, ангел', 'Томас Вулф', 1929, 640, ARRAY['Классика', 'Автобиографическая проза', 'Семейная сага'],
 'Юноша из шумной и неблагополучной семьи южного городка взрослеет среди скандалов, бедности и поэтической жажды вырваться за пределы собственного тесного мира. Дебютный, во многом автобиографический роман Вулфа, написанный плотным, почти захлёбывающимся лирическим языком.'),
('Возвращение в Брайдсхед', 'Ивлин Во', 1945, 400, ARRAY['Классика', 'Драма', 'Исторический роман'],
 'Офицер британской армии, расквартированный во время войны в старинном поместье Брайдсхед, вспоминает собственную юношескую дружбу с аристократическим католическим семейством, владевшим этим домом, и крушение всех его членов одного за другим. Один из самых ностальгических романов Ивлина Во об уходящей эпохе английской аристократии.'),
('Пригоршня праха', 'Ивлин Во', 1934, 288, ARRAY['Сатира', 'Драма', 'Классика'],
 'Благополучный английский джентльмен из старинного рода раз за разом сталкивается с изменой жены, крушением брака и собственной наивной верой в незыблемость традиционных ценностей высшего общества. Один из самых едких и одновременно трагичных романов Ивлина Во о гибели старой доброй Англии.'),
('Упадок и разрушение', 'Ивлин Во', 1928, 256, ARRAY['Сатира', 'Юмор', 'Классика'],
 'Безобидного студента богословия несправедливо исключают из Оксфорда за чужой проступок, и он отправляется учительствовать в эксцентричную частную школу, где абсурд следует за абсурдом. Дебютный сатирический роман Ивлина Во о нелепости английской классовой системы и образовательных институтов.'),
('Страх и трепет', 'Сёрен Кьеркегор', 1843, 192, ARRAY['Нон-фикшн', 'Философия', 'Религия'],
 'Философ исследует библейскую историю Авраама, готового по Божьему велению принести в жертву собственного сына, как предельный пример «рыцаря веры», чей поступок невозможно оправдать никакой этической логикой. Один из ключевых текстов экзистенциалистской философии о вере, парадоксе и абсолютном одиночестве перед Богом.'),
('Или — или', 'Сёрен Кьеркегор', 1843, 640, ARRAY['Нон-фикшн', 'Философия'],
 'Книга противопоставляет два способа существования — эстетический, посвящённый сиюминутному наслаждению, и этический, построенный на долге и постоянстве выбора, — предлагая читателю самому определить, какой путь вести собственную жизнь. Одно из первых и самых влиятельных произведений Кьеркегора, заложивших основы экзистенциализма.'),
('Перси Джексон и похититель молний', 'Рик Риордан', 2005, 384, ARRAY['Фэнтези', 'Детская литература', 'Приключения', 'Мифология'],
 'Двенадцатилетний школьник с дислексией узнаёт, что он сын древнегреческого бога морей Посейдона, и отправляется в опасный квест, чтобы вернуть украденную молнию Зевса и предотвратить войну между олимпийцами. Первая книга серии, переносящей греческую мифологию в современную Америку.'),
('Перси Джексон и море чудовищ', 'Рик Риордан', 2006, 320, ARRAY['Фэнтези', 'Детская литература', 'Приключения', 'Мифология'],
 'Перси и его друзья отправляются на поиски Золотого руна сквозь Бермудский треугольник, чтобы спасти отравленное магическое дерево, защищающее лагерь полукровок от чудовищ. Вторая книга серии о современных приключениях детей греческих богов.'),
('Новолуние', 'Стефани Майер', 2006, 560, ARRAY['Фэнтези', 'Любовный роман', 'Мистика'],
 'Эдвард покидает Беллу ради её же безопасности, и девушка сближается с оборотнем Джейкобом, пока семья вампиров Калленов не оказывается под угрозой из-за роковой ошибки. Второй роман саги «Сумерки» вводит в историю оборотней и расширяет мир сверхъестественного противостояния.'),
('Затмение', 'Стефани Майер', 2007, 640, ARRAY['Фэнтези', 'Любовный роман', 'Мистика'],
 'Белла оказывается в центре любовного треугольника между Эдвардом и Джейкобом как раз в тот момент, когда городу угрожает армия новообращённых вампиров, жаждущих её крови. Третий роман саги «Сумерки» ведёт героиню к окончательному выбору между двумя мирами.'),
('Рассвет', 'Стефани Майер', 2008, 752, ARRAY['Фэнтези', 'Любовный роман', 'Мистика'],
 'Белла и Эдвард наконец женятся, а рождение их наполовину человеческого, наполовину вампирского ребёнка ставит под угрозу хрупкий мир между вампирами и оборотнями. Заключительный роман саги «Сумерки» завершает историю окончательным превращением героини.'),
('И вспыхнет пламя', 'Сьюзен Коллинз', 2009, 400, ARRAY['Фэнтези', 'Антиутопия', 'Приключения'],
 'Победа Китнисс и Пита в Голодных играх невольно разжигает искру восстания по всему Панему, а Капитолий организует для них особые юбилейные игры, призванные раз и навсегда сломить дух победителей. Второй роман трилогии «Голодные игры» о зарождающейся революции.'),
('Сойка-пересмешница', 'Сьюзен Коллинз', 2010, 400, ARRAY['Фэнтези', 'Антиутопия', 'Военная проза'],
 'Спасённая повстанцами Китнисс становится живым символом восстания против Капитолия, но обнаруживает, что подполье способно на такую же манипуляцию людьми, как и прежний режим. Заключительный роман трилогии «Голодные игры» о цене войны и пропаганды с обеих сторон конфликта.'),
('Паула', 'Исабель Альенде', 1994, 416, ARRAY['Нон-фикшн', 'Биография', 'Драма'],
 'Пока дочь писательницы лежит в коме, Альенде пишет ей письмо-воспоминание о собственной жизни, семье и родной Чили, пытаясь удержать дочь в сознании силой рассказанной истории. Один из самых личных и пронзительных мемуаров Альенде о материнской любви и неотвратимой утрате.'),
('Шоколад на крутом кипятке', 'Лаура Эскивель', 1989, 256, ARRAY['Магический реализм', 'Любовный роман', 'Юмор'],
 'Младшая дочь мексиканской семьи, которой по семейной традиции запрещено выходить замуж, выражает подавленные чувства через кулинарию — и её блюда начинают магическим образом передавать едокам те самые эмоции, что она вложила в готовку. Роман, построенный как поваренная книга с рецептами, стал одним из самых известных образцов магического реализма в женской прозе.'),
('Убийца без лица', 'Хеннинг Манкелль', 1991, 480, ARRAY['Детектив', 'Триллер', 'Криминальная проза'],
 'Пожилую пару жестоко убивают на уединённой шведской ферме, а единственная зацепка — предсмертное слово жертвы, которое может указывать на иностранное происхождение убийц, грозящее разжечь расовую ненависть в маленьком городке. Роман, открывший знаменитую серию о детективе Курте Валландере и жанр скандинавского нуара.'),
('Спеши любить', 'Николас Спаркс', 1999, 256, ARRAY['Любовный роман', 'Драма'],
 'Бунтарь-старшеклассник из богатой семьи неожиданно для себя влюбляется в скромную и набожную дочь пастора, чья тайна — смертельная болезнь — меняет его самого куда сильнее, чем он мог представить. Один из самых известных романов Спаркса о взрослении через любовь и потерю.'),
('Полночь в саду добра и зла', 'Джон Беренд', 1994, 416, ARRAY['Нон-фикшн', 'Детектив', 'Юмор'],
 'Журналист, переехавший в эксцентричный южный город Саванну, оказывается втянут в реальное судебное дело об убийстве, попутно знакомя читателя с целой галереей колоритных местных чудаков. Документальный роман, сочетающий true crime с портретом странного и обаятельного американского Юга.'),
('Часы', 'Агата Кристи', 1963, 288, ARRAY['Детектив', 'Классика'],
 'В доме слепой учительницы машинописи обнаруживают труп незнакомца, а комнату заполняют многочисленные часы, остановленные на одном и том же времени, — ни одни из которых не принадлежат хозяйке дома. Один из поздних и самых загадочных романов о расследованиях Эркюля Пуаро.'),
('Вечеринка в Хэллоуин', 'Агата Кристи', 1969, 256, ARRAY['Детектив', 'Классика'],
 'Девочка на детской хэллоуинской вечеринке хвастается, что когда-то видела настоящее убийство, — а спустя несколько часов её саму находят утопленной в бадье для яблок. Эркюль Пуаро и писательница детективов Ариадна Оливер распутывают дело, в котором мало кто говорит правду.'),
('Трагедия в трёх актах', 'Агата Кристи', 1935, 256, ARRAY['Детектив', 'Классика'],
 'Безобидный с виду священник неожиданно умирает за коктейлем на званом ужине, устроенном актёром на покое, — и когда похожая смерть повторяется на точно такой же вечеринке, Эркюль Пуаро понимает, что имеет дело с тщательно спланированным планом. Один из самых театральных по структуре романов Агаты Кристи, разделённый на три акта, как настоящая пьеса.'),
('Кремлёвский кардинал', 'Том Клэнси', 1988, 672, ARRAY['Триллер', 'Военная проза', 'Политическая проза'],
 'Высокопоставленный источник ЦРУ в советском военном руководстве оказывается под угрозой разоблачения как раз в разгар гонки за создание противоракетного щита. Один из самых масштабных техно-триллеров Клэнси о шпионаже на излёте холодной войны.'),
('Патриот', 'Том Клэнси', 1987, 592, ARRAY['Триллер', 'Приключения', 'Политическая проза'],
 'Аналитик ЦРУ Джек Райан случайно срывает покушение террористов на членов британской королевской семьи и становится личной целью мести уцелевших заговорщиков. Роман, впервые по-настоящему раскрывший Джека Райана как главного героя целого цикла техно-триллеров Клэнси.'),
('Клиент', 'Джон Гришэм', 1993, 480, ARRAY['Триллер', 'Детектив', 'Криминальная проза'],
 'Одиннадцатилетний мальчик случайно становится свидетелем самоубийства адвоката мафии, успевшего рассказать ему местонахождение спрятанного трупа, — и теперь за жизнью ребёнка охотятся и мафия, и федеральное правительство. Один из самых напряжённых юридических триллеров Гришэма с ребёнком в центре смертельно опасной тайны.'),
('Камера', 'Джон Гришэм', 1994, 512, ARRAY['Драма', 'Детектив', 'Социальная проза'],
 'Молодой адвокат берётся бесплатно защищать своего деда, бывшего члена ку-клукс-клана, приговорённого к смертной казни за давний теракт, пытаясь успеть остановить казнь и одновременно примириться с семейным прошлым. Один из самых эмоционально тяжёлых романов Гришэма о расизме, вине и праве на искупление.'),
('Психология масс и анализ человеческого Я', 'Зигмунд Фрейд', 1921, 128, ARRAY['Нон-фикшн', 'Психология', 'Философия'],
 'Основатель психоанализа исследует, как индивидуальная психика растворяется в коллективном поведении толпы, а лидер группы занимает место идеализированного родительского образа в психике её членов. Одна из первых психоаналитических попыток объяснить природу массовых движений и подчинения авторитету.'),
('Толкование сновидений', 'Зигмунд Фрейд', 1899, 480, ARRAY['Нон-фикшн', 'Психология'],
 'Фрейд излагает теорию о том, что сновидения представляют собой зашифрованное исполнение подавленных бессознательных желаний, и предлагает метод их психоаналитической расшифровки. Фундаментальный труд, заложивший основы психоанализа как научной дисциплины.'),
('Недовольство культурой', 'Зигмунд Фрейд', 1930, 160, ARRAY['Нон-фикшн', 'Философия', 'Психология'],
 'Фрейд утверждает, что сама цивилизация построена на вечном подавлении природных инстинктов человека, что неизбежно порождает коллективное чувство вины и тревоги. Одна из самых мрачных поздних работ Фрейда о неразрешимом конфликте между личной свободой и требованиями общества.'),
('Человек и его символы', 'Карл Густав Юнг', 1964, 320, ARRAY['Нон-фикшн', 'Психология', 'Философия'],
 'Последняя работа Юнга, написанная в доступной для широкого читателя форме, объясняет его ключевые идеи о символах, сновидениях и архетипах коллективного бессознательного. Одно из самых понятных введений в аналитическую психологию Юнга.'),
('Архетипы и коллективное бессознательное', 'Карл Густав Юнг', 1959, 352, ARRAY['Нон-фикшн', 'Психология', 'Философия'],
 'Сборник эссе излагает центральную идею юнгианской психологии — существование унаследованных всем человечеством универсальных первообразов, проявляющихся в мифах, снах и культуре разных народов независимо друг от друга. Одна из фундаментальных работ аналитической психологии.'),
('Вечерний альбом', 'Марина Цветаева', 1910, 128, ARRAY['Поэзия', 'Классика'],
 'Дебютный сборник восемнадцатилетней поэтессы, изданный на собственные средства, подкупил современников искренностью и почти дневниковой непосредственностью юношеских переживаний. Сборник, с которого началось признание Цветаевой в литературных кругах Серебряного века.'),
('Стихи к Блоку', 'Марина Цветаева', 1922, 48, ARRAY['Поэзия', 'Классика'],
 'Цикл стихотворений, посвящённых Александру Блоку, которого Цветаева боготворила, но с которым лично почти не была знакома, передаёт почти мистическое поэтическое преклонение перед собратом по цеху. Один из самых проникновенных образцов поэтического посвящения в русской лирике XX века.'),
('Тристия', 'Осип Мандельштам', 1922, 96, ARRAY['Поэзия', 'Классика'],
 'Второй сборник поэта, написанный на фоне революционных потрясений, соединяет темы изгнания, памяти античности и предчувствия надвигающейся катастрофы. Один из самых зрелых и музыкальных сборников Мандельштама, упрочивших его репутацию мастера акмеизма.'),
('Чётки', 'Анна Ахматова', 1914, 160, ARRAY['Поэзия', 'Классика', 'Любовный роман'],
 'Второй сборник Ахматовой закрепил за ней славу главного поэта любовной лирики своего времени благодаря предельно точным и сдержанным образам женских переживаний. Один из самых переиздаваемых поэтических сборников Серебряного века.'),
('Поэма без героя', 'Анна Ахматова', 1962, 96, ARRAY['Поэзия', 'Классика', 'Исторический роман'],
 'Поэма, которую Ахматова писала и переписывала более двадцати лет, воссоздаёт призрачный Петербург Серебряного века, пронизанный предчувствием грядущих катастроф XX века. Одно из самых сложных и зашифрованных поздних произведений Ахматовой.'),
('Чёрный человек', 'Сергей Есенин', 1925, 32, ARRAY['Поэзия', 'Классика', 'Психологическая проза'],
 'Поэт ведёт мучительный ночной диалог с собственным зловещим двойником, явившимся обличить его пьянство, растраченный талант и духовное падение. Одна из последних и самых мрачных поэм Есенина, написанная незадолго до его трагической гибели.'),
('Анна Снегина', 'Сергей Есенин', 1925, 64, ARRAY['Поэзия', 'Классика', 'Любовный роман', 'Исторический роман'],
 'Поэт возвращается в родное село после революции и встречает бывшую возлюбленную, ставшую помещицей, — а личная история неразделённой любви разворачивается на фоне крестьянских бунтов и Гражданской войны. Одна из последних и самых лиричных поэм Есенина о прощании с дореволюционной Россией.'),
('Про это', 'Владимир Маяковский', 1923, 64, ARRAY['Поэзия', 'Классика', 'Любовный роман'],
 'Поэма исследует личную, почти исповедальную драму неразделённой и мучительной любви, которую поэт пытается преодолеть через революционную веру в будущее переустройство самой человеческой природы. Одно из самых лиричных и личных произведений Маяковского, обычно ассоциирующегося с агитационной поэзией.'),
('Хорошо!', 'Владимир Маяковский', 1927, 96, ARRAY['Поэзия', 'Классика', 'Исторический роман', 'Политическая проза'],
 'Поэма, написанная к десятилетию Октябрьской революции, хронологически прослеживает события от Февральской революции до строительства нового советского государства глазами непосредственного участника и свидетеля. Одна из самых масштабных агитационных поэм Маяковского.'),
('Дом, где разбиваются сердца', 'Бернард Шоу', 1919, 160, ARRAY['Драма', 'Сатира', 'Пьесы'],
 'Гости эксцентричного английского дома накануне Первой мировой войны ведут бесконечные разговоры о любви и деньгах, не замечая надвигающейся катастрофы, разрушающей их беспечный мир. Пьеса Шоу, написанная под явным влиянием чеховской драматургии, о духовном крахе европейского общества.'),
('Святая Иоанна', 'Бернард Шоу', 1923, 192, ARRAY['Драма', 'Исторический роман', 'Пьесы'],
 'Пьеса прослеживает путь Жанны д’Арк от крестьянской девушки, услышавшей голоса святых, до национальной героини, преданной собственными союзниками и сожжённой на костре инквизицией. Историческая драма Шоу о столкновении искреннего религиозного вдохновения с политическим прагматизмом.'),
('Строитель Сольнес', 'Генрик Ибсен', 1892, 128, ARRAY['Драма', 'Психологическая проза', 'Пьесы'],
 'Стареющий и мучимый страхом перед молодым поколением архитектор встречает восторженную юную поклонницу, убеждающую его совершить последний, невозможно рискованный творческий подвиг. Одна из самых символистских и психологически насыщенных поздних пьес Ибсена о страхе старости и творческой гордыне.'),
('Враг народа', 'Генрик Ибсен', 1882, 160, ARRAY['Драма', 'Политическая проза', 'Пьесы'],
 'Врач курортного городка обнаруживает, что местные целебные воды заражены и опасны для здоровья, но вместо благодарности город, боящийся экономических потерь, объявляет его врагом народа. Одна из самых актуальных пьес Ибсена о цене правды и тирании общественного мнения большинства.'),
('Сирены Титана', 'Курт Воннегут', 1959, 320, ARRAY['Научная фантастика', 'Сатира', 'Философия'],
 'Богатейший человек Земли оказывается невольным участником грандиозного межпланетного плана, управляемого инопланетной цивилизацией, которая веками манипулировала всей человеческой историей ради доставки одной крошечной детали для застрявшего на Титане корабля. Один из самых абсурдистски смешных и одновременно философски мрачных ранних романов Воннегута о бессмысленности человеческой истории.'),
('Галапагосы', 'Курт Воннегут', 1985, 320, ARRAY['Научная фантастика', 'Сатира', 'Философия'],
 'Рассказчик-призрак повествует миллион лет спустя, как случайное кораблекрушение забросило горстку людей на Галапагосские острова как раз накануне краха цивилизации — и их потомки, в отличие от погибшего остального человечества, в итоге эволюционировали в нечто куда более простое и счастливое. Поздний сатирический роман Воннегута о человеческом интеллекте как эволюционной ошибке.'),
('И грянул гром', 'Рэй Брэдбери', 1952, 32, ARRAY['Научная фантастика', 'Приключения', 'Философия'],
 'Участник сафари-экспедиции в эпоху динозавров случайно сходит с предписанной тропы и раздавливает бабочку — крошечное изменение, которое, вернувшись в настоящее, оказывается необратимо исказило весь дальнейший ход истории. Один из самых известных рассказов о путешествиях во времени, подаривший культуре само понятие «эффект бабочки».'),
('Человек в картинках', 'Рэй Брэдбери', 1951, 288, ARRAY['Научная фантастика', 'Философия', 'Мистика'],
 'Странник встречает покрытого движущимися татуировками человека, каждая из которых оживает ночью и рассказывает отдельную историю о будущем человечества. Сборник рассказов Брэдбери, объединённых причудливой рамочной конструкцией живых картин на коже.'),
('Конец Вечности', 'Айзек Азимов', 1955, 256, ARRAY['Научная фантастика', 'Философия', 'Любовный роман'],
 'Тайная организация Вечность управляет историей человечества, внося точечные корректировки времени ради предотвращения катастроф, — пока один из её сотрудников не влюбляется в женщину из будущего и не начинает сомневаться в праве кого-либо распоряжаться судьбой всего человечества. Один из самых философски насыщенных романов Азимова о времени и цене абсолютной безопасности.'),
('Приход ночи', 'Айзек Азимов', 1941, 64, ARRAY['Научная фантастика', 'Философия'],
 'На планете с шестью солнцами, где никогда не бывает по-настоящему темно, учёные предсказывают первое за две тысячи лет наступление ночи — и общество, не готовое к встрече со звёздами, обречено сойти с ума от ужаса перед неизвестным. Один из самых знаменитых рассказов золотого века научной фантастики о страхе перед темнотой в буквальном и философском смысле.'),
('Психология денег', 'Морган Хаузел', 2020, 256, ARRAY['Нон-фикшн', 'Бизнес', 'Финансы', 'Психология'],
 'Книга доказывает, что успех в личных финансах определяется не столько знанием математики и экономики, сколько психологией, терпением и умением управлять собственным поведением. Один из самых популярных современных бестселлеров о финансах, написанный через истории, а не формулы.'),
('Невероятное путешествие по внутренним органам', 'Джулия Эндерс', 2014, 288, ARRAY['Нон-фикшн', 'Научно-популярная', 'Биология'],
 'Молодая исследовательница увлекательно и с юмором рассказывает об устройстве пищеварительной системы и её неожиданном влиянии на иммунитет, настроение и даже психическое здоровье. Один из самых неожиданно популярных научпоп-бестселлеров о кишечнике и микробиоме.'),
('Размышления', 'Марк Аврелий', 180, 256, ARRAY['Нон-фикшн', 'Философия'],
 'Римский император ведёт личный дневник стоических размышлений о добродетели, смирении перед судьбой и исполнении долга, никогда не предназначавшийся для публикации. Одна из самых практичных и до сих пор актуальных книг античной философии о внутреннем спокойствии перед лицом бремени власти.'),
('Нравственные письма к Луцилию', 'Луций Анней Сенека', 65, 480, ARRAY['Нон-фикшн', 'Философия'],
 'Философ в серии писем молодому другу излагает практическую стоическую философию — о страхе смерти, богатстве, дружбе и правильном использовании времени. Один из самых доступных и человечных текстов античного стоицизма.'),
('Утешение философией', 'Боэций', 524, 192, ARRAY['Нон-фикшн', 'Философия', 'Поэзия'],
 'Осуждённый на казнь философ в тюремной камере ведёт диалог с явившейся ему Философией, которая утешает его размышлениями о переменчивости Фортуны, подлинном благе и божественном провидении. Один из самых влиятельных философских текстов, написанных на границе Античности и Средневековья.'),
('Дар', 'Владимир Набоков', 1938, 400, ARRAY['Классика', 'Психологическая проза', 'Модернизм'],
 'Молодой русский эмигрант-писатель в Берлине работает над биографией Чернышевского, одновременно переживая собственное творческое становление и несбывшуюся любовь. Последний и самый сложный роман Набокова, написанный по-русски, — своеобразное прощание с родным языком перед переходом на английский.'),
('Защита Лужина', 'Владимир Набоков', 1930, 256, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Гениальный, но социально беспомощный шахматист настолько полностью растворяется в шахматной логике, что перестаёт отличать реальную жизнь от шахматной партии, разыгрываемой против него самой судьбой. Один из самых известных ранних русскоязычных романов Набокова о гениальности и безумии.'),
('Машенька', 'Владимир Набоков', 1926, 112, ARRAY['Классика', 'Любовный роман', 'Психологическая проза'],
 'Русский эмигрант в берлинском пансионе узнаёт, что к соседу должна приехать жена, оказывающаяся его собственной первой любовью, оставшейся в дореволюционной России, — и несколько дней ожидания превращаются в путешествие по памяти. Дебютный роман Набокова о ностальгии по безвозвратно утраченной юности и родине.'),
('Зависть', 'Юрий Олеша', 1927, 160, ARRAY['Классика', 'Сатира', 'Психологическая проза'],
 'Неудачник и завистник Николай Кавалеров противопоставляет собственную поэтическую, но бесполезную натуру практичному и успешному советскому функционеру, приютившему его из жалости. Один из самых стилистически изощрённых романов о человеке, не нашедшем себе места в новом советском мире.'),
('Три толстяка', 'Юрий Олеша', 1924, 192, ARRAY['Сказка', 'Детская литература', 'Приключения'],
 'В вымышленной стране три жестоких толстяка-тирана правят, подавляя восстание бедняков, пока отважная гимнастка Суок и доктор Гаспар не помогают спасти схваченного вождя восставших. Одна из самых известных советских сказок-притч о восстании против тирании, написанная ярким и образным языком.'),
('Раковый корпус', 'Александр Солженицын', 1966, 480, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Пациенты онкологического отделения провинциальной больницы — от бывшего лагерного заключённого до партийного функционера — равны перед лицом общей смертельной болезни, которая обнажает истинную цену их прежних убеждений и статуса. Полуавтобиографический роман Солженицына, основанный на его собственном опыте борьбы с раком.'),
('В круге первом', 'Александр Солженицын', 1968, 768, ARRAY['Классика', 'Исторический роман', 'Драма'],
 'Учёные-заключённые особой секретной тюремной лаборатории — «шарашки» — работают на сталинскую спецслужбу, разрабатывая технологии слежки, пока один из них не решается на отчаянный акт морального сопротивления. Масштабный роман Солженицына о компромиссе совести в условиях тоталитарного принуждения к интеллектуальному труду.'),
('Жизнь Арсеньева', 'Иван Бунин', 1933, 320, ARRAY['Классика', 'Автобиографическая проза', 'Поэзия'],
 'Полуавтобиографический роман прослеживает детство, юность и творческое становление дворянского мальчика на фоне угасающей усадебной России рубежа веков. Роман, принёсший Бунину первую в истории русской литературы Нобелевскую премию.'),
('Тёмные аллеи', 'Иван Бунин', 1946, 320, ARRAY['Классика', 'Любовный роман', 'Психологическая проза'],
 'Сборник рассказов, написанных уже в эмиграции, исследует десятки вариаций любовной страсти — мимолётной, трагической, запретной — всегда на грани утраты и невозвратности. Один из самых чувственных и совершенных по стилю сборников русской прозы XX века.'),
('Деревня', 'Иван Бунин', 1910, 192, ARRAY['Классика', 'Социальная проза', 'Драма'],
 'Два брата из крестьянской семьи — предприимчивый лавочник и спившийся неудачник — по-разному проживают беспросветную нищету и жестокость русской деревни накануне революции. Беспощадно реалистичная повесть Бунина, лишённая какой-либо идеализации крестьянского быта.'),
('Господин из Сан-Франциско', 'Иван Бунин', 1915, 32, ARRAY['Классика', 'Философия', 'Драма'],
 'Богатый американец, всю жизнь копивший состояние ради будущих удовольствий, внезапно умирает во время роскошного круиза, а его смерть мгновенно обнажает всю ничтожность прежнего поклонения перед его деньгами. Одна из самых знаменитых философских притч Бунина о тщете богатства перед лицом смерти.'),
('Гранатовый браслет', 'Александр Куприн', 1911, 64, ARRAY['Классика', 'Любовный роман', 'Драма'],
 'Мелкий чиновник годами безнадёжно и безответно любит светскую замужнюю даму, присылая ей анонимные письма и скромные подарки, — а узнав, что его чувство раскрыто и осмеяно её роднёй, принимает единственное доступное ему решение. Одна из самых пронзительных повестей русской литературы о бескорыстной, почти священной любви.'),
('Олеся', 'Александр Куприн', 1898, 96, ARRAY['Классика', 'Любовный роман', 'Драма', 'Мистика'],
 'Городской интеллигент, оказавшийся в глухой полесской деревне, влюбляется в девушку, живущую с бабушкой-колдуньей на болотах и слывущую у местных ведьмой, — а предрассудки суеверной деревни обрекают их любовь на трагический финал. Один из самых лиричных ранних рассказов Куприна о естественной, не испорченной цивилизацией любви.'),
('Поединок', 'Александр Куприн', 1905, 320, ARRAY['Классика', 'Военная проза', 'Психологическая проза'],
 'Молодой армейский подпоручик, разочаровавшийся в бессмысленной жестокости и пошлости провинциального гарнизонного быта, оказывается втянут в дуэль, спровоцированную интригой офицерской жены. Один из самых известных антивоенных романов дореволюционной русской литературы о разложении армейской среды.'),
('Иуда Искариот', 'Леонид Андреев', 1907, 96, ARRAY['Классика', 'Философия', 'Психологическая проза'],
 'Повесть переосмысляет библейского предателя как самого преданного и глубоко любящего Христа ученика, чьё предательство становится извращённой формой доказательства этой любви. Одно из самых провокационных и психологически смелых переосмыслений евангельского сюжета в русской литературе.'),
('Красный смех', 'Леонид Андреев', 1904, 96, ARRAY['Классика', 'Военная проза', 'Психологическая проза'],
 'Фрагментарные записки двух братьев, один из которых сходит с ума на поле боя Русско-японской войны, передают абсолютный, лишённый всякого героизма ужас и безумие современной войны. Один из первых и самых экспрессионистских антивоенных текстов русской литературы начала XX века.'),
('Голубая книга', 'Михаил Зощенко', 1935, 320, ARRAY['Сатира', 'Юмор', 'Классика'],
 'Сборник коротких сатирических новелл, написанных нарочито неправильным языком малообразованного рассказчика, высмеивает мещанство, бюрократию и нелепости повседневного советского быта. Одно из самых известных сатирических произведений советской литературы 1930-х годов.'),
('Чудесное путешествие Нильса с дикими гусями', 'Сельма Лагерлёф', 1906, 400, ARRAY['Сказка', 'Детская литература', 'Приключения', 'Природа'],
 'Непослушного мальчика, издевавшегося над домашними животными, волшебный гном превращает в крошечное существо, и Нильс отправляется в путешествие на спине дикого гуся через всю Швецию, попутно узнавая географию родной страны и учась состраданию. Книга была написана как школьный учебник географии и стала классикой скандинавской детской литературы.'),
('Бременские музыканты', 'Братья Гримм', 1819, 24, ARRAY['Сказка', 'Детская литература', 'Классика', 'Юмор'],
 'Четверо состарившихся и ненужных больше хозяевам домашних животных — осёл, пёс, кот и петух — отправляются в Бремен, чтобы стать уличными музыкантами, а по пути хитростью прогоняют разбойников из их лесного дома. Одна из самых известных сказок братьев Гримм о дружбе, не теряющей ценности с возрастом.'),
('Гензель и Гретель', 'Братья Гримм', 1812, 24, ARRAY['Сказка', 'Детская литература', 'Классика', 'Ужасы'],
 'Брат и сестра, брошенные в лесу обедневшими родителями, набредают на пряничный домик, где их поджидает людоедка-ведьма, — но находчивость детей оказывается сильнее колдовства. Одна из самых мрачных и самых известных сказок братьев Гримм о голоде, предательстве и детской смекалке.'),
('Румпельштильцхен', 'Братья Гримм', 1812, 16, ARRAY['Сказка', 'Детская литература', 'Классика', 'Мистика'],
 'Дочь мельника, вынужденная под угрозой казни прясть золото из соломы, принимает помощь загадочного карлика в обмен на будущего первенца, — а единственный способ избежать расплаты состоит в том, чтобы угадать его настоящее имя. Одна из самых загадочных сказок братьев Гримм о силе имени и цене заключённой второпях сделки.'),
('Антихрупкость', 'Нассим Николас Талеб', 2012, 640, ARRAY['Нон-фикшн', 'Философия', 'Экономика'],
 'Автор «Чёрного лебедя» вводит понятие «антихрупкости» — свойства систем не просто выдерживать потрясения, подобно устойчивости, а становиться от них только сильнее. Книга предлагает принципы построения систем, экономик и собственной жизни, устойчивых к непредсказуемым потрясениям.'),
('Одураченные случайностью', 'Нассим Николас Талеб', 2001, 320, ARRAY['Нон-фикшн', 'Экономика', 'Философия'],
 'Бывший трейдер доказывает, что люди систематически недооценивают роль чистой случайности в успехе и неудаче, принимая везение за собственный талант и мастерство. Первая книга Талеба на тему непредсказуемости, задавшая тон всей его последующей работе о риске и случайности.'),
('Как перестать беспокоиться и начать жить', 'Дейл Карнеги', 1948, 320, ARRAY['Нон-фикшн', 'Психология'],
 'Классическое руководство предлагает практические техники борьбы с тревогой — от жизни в границах «сегодняшнего отсека» до анализа наихудшего возможного исхода, после которого тревога теряет силу. Один из самых продаваемых самоучителей по управлению стрессом и беспокойством XX века.'),
('Логико-философский трактат', 'Людвиг Витгенштейн', 1921, 160, ARRAY['Нон-фикшн', 'Философия'],
 'Философ в предельно сжатой, пронумерованной форме афоризмов очерчивает границы того, что вообще может быть осмысленно высказано языком, — и завершает книгу знаменитым выводом, что о том, о чём нельзя говорить, следует молчать. Одна из самых влиятельных и загадочных философских книг XX века, заложившая основы аналитической философии языка.'),
('Записки у изголовья', 'Сэй-Сёнагон', 1002, 320, ARRAY['Нон-фикшн', 'Классика', 'Поэзия'],
 'Придворная дама японского императорского двора ведёт дневник наблюдений, списков и коротких зарисовок придворной жизни эпохи Хэйан — от того, что раздражает, до того, что трогательно и прекрасно. Один из первых и самых изящных образцов японской эссеистической прозы.'),
('Повесть о Гэндзи', 'Мурасаки Сикибу', 1008, 1200, ARRAY['Классика', 'Любовный роман', 'Драма', 'Поэзия'],
 'Роман прослеживает жизнь и многочисленные любовные связи придворного принца Гэндзи при императорском дворе средневековой Японии, а во второй части — судьбу его потомков. Один из первых психологических романов в истории мировой литературы, написанный придворной дамой более тысячи лет назад.'),
('Исповедь неполноценного человека', 'Осаму Дадзай', 1948, 176, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Мужчина, неспособный понять и повторить простейшие социальные ритуалы окружающих его людей, с юности скрывает собственную внутреннюю пустоту за маской шута, пока саморазрушение не становится для него единственным честным способом существования. Полуавтобиографический роман Дадзая о тотальном отчуждении от человеческого общества.'),
('Заходящее солнце', 'Осаму Дадзай', 1947, 192, ARRAY['Классика', 'Драма', 'Психологическая проза'],
 'Аристократическая японская семья медленно беднеет и распадается на фоне послевоенного краха традиционного уклада, а дочь ищет собственный, пусть и скандальный, путь к новой жизни. Роман Дадзая, давший название целому литературному явлению «людей заходящего солнца» — поколению, потерявшему довоенный мир.'),
('Подлинная история А-Кью', 'Лу Синь', 1921, 96, ARRAY['Сатира', 'Классика', 'Психологическая проза'],
 'Безземельный деревенский батрак А-Кью превращает каждое собственное унижение в воображаемую моральную победу, пока революция, которую он толком не понимает, не приводит его к нелепой и бессмысленной гибели. Самая известная сатирическая повесть основоположника современной китайской литературы о национальном самообмане.'),
('Дневник сумасшедшего', 'Лу Синь', 1918, 32, ARRAY['Сатира', 'Классика', 'Психологическая проза'],
 'Параноидальный рассказчик постепенно убеждается, что все окружающие его люди — тайные каннибалы, поедающие друг друга под прикрытием традиционной конфуцианской морали. Первый современный рассказ, написанный на разговорном китайском языке, положивший начало новой китайской литературе.'),
('Стрела бога', 'Чинуа Ачебе', 1964, 288, ARRAY['Классика', 'Исторический роман', 'Драма'],
 'Верховный жрец нигерийской деревни оказывается разрываем между традиционными религиозными обязанностями, колониальной британской администрацией и собственными амбициозными сыновьями. Третий роман африканской трилогии Ачебе о распаде традиционного уклада под натиском колониализма.'),
('Лев и жемчужина', 'Воле Шойинка', 1963, 96, ARRAY['Драма', 'Юмор', 'Пьесы'],
 'Деревенская красавица выбирает между молодым прогрессивным учителем и пожилым, но хитрым и могущественным старостой деревни, претендующим на её руку. Комедия нобелевского лауреата Шойинка о столкновении традиции и западной современности в нигерийской деревне.'),
('Продавец обуви', 'Фил Найт', 2016, 400, ARRAY['Нон-фикшн', 'Биография', 'Бизнес'],
 'Основатель Nike откровенно рассказывает историю создания компании — от торговли кроссовками из багажника машины до превращения в глобальную спортивную империю, не скрывая ни сомнений, ни провалов на этом пути. Один из самых честных и захватывающих предпринимательских мемуаров последних лет.'),
('Исповедь', 'Лев Толстой', 1882, 112, ARRAY['Нон-фикшн', 'Философия', 'Религия', 'Автобиографическая проза'],
 'Знаменитый на весь мир писатель описывает собственный духовный кризис середины жизни, поставивший под сомнение смысл всего, чего он достиг, и мучительный поиск веры, способной этот смысл вернуть. Одно из самых откровенных автобиографических свидетельств о религиозном перевороте в жизни Толстого.'),
('О жизни', 'Лев Толстой', 1887, 192, ARRAY['Нон-фикшн', 'Философия'],
 'Толстой излагает собственное понимание истинной жизни как жизни не для личного эгоистического блага, а для блага других людей через любовь, противопоставляя эту позицию животному, чисто биологическому существованию. Один из ключевых философских трактатов позднего Толстого.'),
('Царство Божие внутри вас', 'Лев Толстой', 1894, 400, ARRAY['Нон-фикшн', 'Философия', 'Религия'],
 'Толстой излагает учение о непротивлении злу насилием как единственно подлинно христианском пути, резко критикуя государство, церковь и сам институт войны. Трактат оказал прямое влияние на философию ненасильственного сопротивления Махатмы Ганди.'),
('Воскресение', 'Лев Толстой', 1899, 448, ARRAY['Классика', 'Драма', 'Социальная проза'],
 'Аристократ оказывается присяжным на суде над проституткой, обвинённой в убийстве, и узнаёт в подсудимой девушку, которую сам когда-то соблазнил и бросил, — после чего отправляется вслед за ней в сибирскую ссылку в попытке искупить давнюю вину. Последний большой роман Толстого — беспощадная социальная критика судебной системы, церкви и всего общественного устройства Российской империи.'),
('Севастопольские рассказы', 'Лев Толстой', 1855, 192, ARRAY['Военная проза', 'Классика', 'Исторический роман'],
 'Молодой офицер-артиллерист описывает собственный опыт обороны Севастополя во время Крымской войны, подчёркнуто избегая ложного героического пафоса ради честного изображения страха, грязи и абсурдности войны. Ранние военные очерки Толстого, принёсшие ему первую литературную известность.'),
('Борис Годунов', 'Александр Пушкин', 1825, 160, ARRAY['Драма', 'Исторический роман', 'Пьесы', 'Поэзия'],
 'Царь Борис Годунов мучительно страдает от подозрений в убийстве законного наследника престола, пока на политической арене не появляется самозванец Лжедмитрий, выдающий себя за чудом спасённого царевича. Историческая драма Пушкина в стихах, написанная под явным влиянием Шекспира, о легитимности власти и народном суде над правителями.'),
('Полтава', 'Александр Пушкин', 1829, 96, ARRAY['Поэзия', 'Классика', 'Исторический роман', 'Военная проза'],
 'Поэма рассказывает о Полтавской битве Петра Великого со шведским королём Карлом XII на фоне личной драмы гетмана Мазепы и его роковой любви к юной Марии. Эпическая историческая поэма Пушкина о столкновении личной страсти и государственной судьбы.'),
('Цыганы', 'Александр Пушкин', 1824, 48, ARRAY['Поэзия', 'Классика', 'Любовный роман'],
 'Разочарованный в цивилизации аристократ Алеко уходит жить к вольному цыганскому табору и влюбляется в цыганку Земфиру, но, узнав о её измене, совершает поступок, несовместимый с той самой свободой, которую он искал среди цыган. Романтическая поэма Пушкина о иллюзорности бегства от самого себя.'),
('Белые ночи', 'Фёдор Достоевский', 1848, 96, ARRAY['Классика', 'Любовный роман', 'Психологическая проза'],
 'Одинокий петербургский мечтатель за четыре белые ночи переживает короткую, но ослепительную историю любви к девушке, ожидающей возвращения своего жениха, — и готов довольствоваться одним лишь мигом её благодарности взамен на разбитое сердце. Одна из самых светлых и лиричных повестей раннего Достоевского.'),
('Неточка Незванова', 'Фёдор Достоевский', 1849, 192, ARRAY['Классика', 'Психологическая проза', 'Драма'],
 'Девочка-сирота вспоминает тяжёлое детство рядом с отчимом — спившимся гениальным музыкантом, так и не реализовавшим собственный талант, — и последующие годы в богатой опекунской семье. Незавершённый роман молодого Достоевского, прерванный его арестом по делу петрашевцев.'),
('Бедные люди', 'Фёдор Достоевский', 1846, 160, ARRAY['Классика', 'Художественная проза', 'Психологическая проза'],
 'Пожилой мелкий чиновник и его молодая дальняя родственница ведут трогательную переписку о собственной беспросветной бедности, одиночестве и редких проблесках взаимной заботы. Дебютный роман Достоевского в письмах, сразу признанный Белинским гениальным явлением «натуральной школы».'),
('Село Степанчиково и его обитатели', 'Фёдор Достоевский', 1859, 256, ARRAY['Классика', 'Сатира', 'Психологическая проза'],
 'Деспотичный приживал Фома Опискин полностью подчинил своей воле добродушного помещика и всю его усадьбу, прикрываясь показным смирением и мнимой добродетелью. Одна из самых смешных и одновременно язвительных повестей Достоевского о домашней тирании и лицемерии.'),
('Крокодил', 'Фёдор Достоевский', 1865, 48, ARRAY['Сатира', 'Классика', 'Юмор'],
 'Чиновника по собственной неосторожности заживо проглатывает выставленный на ярмарке крокодил, а он изнутри зверя как ни в чём не бывало продолжает философствовать о собственной новой жизненной позиции. Короткая гротескная сатира Достоевского на российскую бюрократию и слепую веру в прогресс.'),
('Школа злословия', 'Ричард Бринсли Шеридан', 1777, 160, ARRAY['Драма', 'Сатира', 'Юмор', 'Пьесы'],
 'Лондонское высшее общество с наслаждением плетёт сплетни и интриги вокруг двух братьев — показного добродетельного лицемера и подлинно благородного повесы, — пока правда о каждом из них не выходит наружу самым неожиданным образом. Одна из самых остроумных комедий нравов английского театра XVIII века.'),
('Соперники', 'Ричард Бринсли Шеридан', 1775, 144, ARRAY['Драма', 'Юмор', 'Любовный роман', 'Пьесы'],
 'Богатый поклонник выдаёт себя за бедного офицера, чтобы завоевать сердце романтичной барышни, мечтающей исключительно о бедном возлюбленном, — а путаница личностей и соперников только усугубляется с каждым актом. Комедия положений Шеридана подарила английскому языку выражение «мэлапропизм» по имени одной из её героинь.'),
('Сорочинская ярмарка', 'Николай Гоголь', 1831, 64, ARRAY['Сказка', 'Юмор', 'Мистика', 'Классика'],
 'Крестьянская девушка и парубок мечтают пожениться вопреки воле мачехи, а суета украинской ярмарки неожиданно переплетается с мистической легендой о красной свитке, которую носит сам чёрт. Первая повесть цикла «Вечера на хуторе близ Диканьки», открывшая миру украинский колорит молодого Гоголя.');
